INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(287602, 'ژ', '<span class=\"hlight\">ژ.</span> (حرف ) ژی یا زاء معقوده و یا زاء فارسی . نشانه ٔ حرف چهاردهم از حروف تهجّی است و در حساب جُمَّل نماینده ٔ عدد نیست (مگر اینکه قائم مقام زاء باشد) و در حساب ترتیبی نشانه ٔ عدد چهارده (<span class=\"hlight\" dir=\"rtl\">١٤</span>) است .<br />ابدالها:<br />> این حرف به «ت » بدل شود:<br />ارژنگ = ارتنگ <span class=\"hlight\">:</span> <br />به قصر دولتم مانی و ارژنگ <br />طراز سحر می بستند بر سنگ .<br /> <font color=\"Red\">امیرخسرو.</font><br />اگر مانی شود زنده چو بیند نقش توقیعش <br />بمیرد باز از شرم نگارستان ارتنگش .<br /> <font color=\"Red\">سیف اسفرنگی .</font><br />> وبه «ج » تبدیل گردد:<br />ژدوار = جدوار.<br />لاژورد = لاجورد.<br />موژان = موجان .<br />نوژ = نوج . <br />کژ = کج . <br />هژده = هجده . <br />هژیر = خجیر و هجیر <span class=\"hlight\">:</span> <br />به شاه جهان گفت زردشت پیر<br />که در دین ما این نباشد هجیر.<br /> <font color=\"Red\">فردوسی .</font><br />نوروز فرخ آمد و نغز آمد و هژیر<br />با طالع سعادت و با کوکب منیر.<br /> <font color=\"Red\">منوچهری .</font><br />دست به می شاه را و دل به هژیران <br />دیده به روی نکو و گوش به قوّال .<br /> <font color=\"Red\">منوچهری .</font><br />لژن و لژند = لجن <span class=\"hlight\">:</span> <br />کردم تهی دو دیده ٔ خود را ز خون دل <br />تا شد ز اشکم آن زمی خشک چون لژن .<br /> <font color=\"Red\">عسجدی .</font><br />خصمانش گر به زور چو شیران نر شوند<br />چون خوک خشت خورده بمیرند در لژند.<br /> <font color=\"Red\">اثیرالدین اخسیکتی .</font><br />پیش دست تو مگر لاف صفا زد ورنه <br />بحر را بهر چه در حلق نهادند لجن .<br /> <font color=\"Red\">رفیعالدین لنبانی .</font><br />دانژه = دانجه . <br />منیژه = منیجه . <br />کاژ = کاج <span class=\"hlight\">:</span> <br />ای تیغ زبان آخته بر قافله ٔ ژاژ<br />چشمت به طمع مانده سوی نان کسان کاژ.<br /> <font color=\"Red\">ناصرخسرو.</font><br />غرض چمیدن و حمل است اگرنه بتراشد<br />ز کاژ و نوژ به یک روزه ده شتر نجار.<br /> <font color=\"Red\">اثیرالدین اخسیکتی .</font><br />اخ اخی برداشتی ای گیج کاج <br />تا که کالای بدت یابد رواج .<br /> <font color=\"Red\">مولوی .</font><br />سرو و شمشاد و صنوبر بید و کاج و نارون <br />درنمی بایدکنون چیزی بجز داروی دن .<br /> <font color=\"Red\">؟</font><br />باژ = باج <span class=\"hlight\">:</span> <br />به بیچارگی باژ و ساوگران <br />پذیرفت با هدیه ٔ بی کران .<br /> <font color=\"Red\">فردوسی .</font><br />رسولان رسیدند با ساو و باج <br />همایون کنان شاه را تخت و تاج .<br /> <font color=\"Red\">نظامی .</font><br />فاژه = فاجه (به معنی دهن دره )<span class=\"hlight\">:</span> <br />ساقی به شیشه ریز ز ساغر شراب ناب <br />خصم نشاط، فاجه و خمیازه شد مرا.<br /> <font color=\"Red\">ابونصر نصیرای بدخشانی .</font><br />اگر ندانی بندیش تا چگونه بود<br />که سبزه خورده به فاژه بهارگه اشتر.<br /> <font color=\"Red\">لبیبی .</font><br />کژک = کجک <span class=\"hlight\">:</span> <br />آن کژک بر تارک فیل از شکوه <br />بود تیغ کوه بر بالای کوه .<br /> <font color=\"Red\">امیرخسرو.</font><br />داد از پی ضبط فیل مستش <br />از قوس قزح کجک به دستش .<br /> <font color=\"Red\">هاتفی .</font><br />نوژ = نوج <span class=\"hlight\">:</span> <br />چو طوطی گشت شاخ بید و شاخ سرو و نوژ وگل <br />نشستند ارغنون سازان بزیر سایه ٔ طوبی .<br /> <font color=\"Red\">منوچهری .</font><br />زیب زمانه باد ز تاج و سریر تو<br />تا هست زیب بستان از سرو و بید و نوج .<br /> <font color=\"Red\">مجد همگر.</font><br />نژند =نجند <span class=\"hlight\">:</span> <br />پیاده ٔ سپه آرای او دویست هزار<br />چو پیل مست و پلنگ نژندو ببر بیان .<br /> <font color=\"Red\">فرخی .</font><br />ناژو = ناجو <span class=\"hlight\">:</span> <br />چو بر ناژو سرایان گشت نارو<br />به صحرا شد گرازان گور و آهو.<br /> <font color=\"Red\">عبدالمجید (از آنندراج ).</font><br />ناجوی این باغ به وجد و خروش <br />بوده چو سکان فلک سبزپوش .<br /> <font color=\"Red\">نظامی (از آنندراج ).</font><br />> به «ر» بدل شود: <br />واژون = وارون . <br />> به «ز» تبدیل گردد: <br />کوژ = کوز <span class=\"hlight\">:</span> <br />بدو گفت کای پشت بخت تو کوز<br />کسی از شما زنده مانده ست نوز.<br /> <font color=\"Red\">اسدی .</font><br />ژُکیدن = زُکیدن . <br />آژخ = آزخ . <br />ژیره = زیره . <br />> به «س » مبدّل گردد: <br />تکژ = تکس .<br />> به «ش » مبدل شود: <br />باژگونه = باشگونه . <br />دُژ = دُش . <br />دُژخدای = دُش خدای . <br />لژن = لَشن . <br />خاکژی = خاکشی .<br />> به «ن » ابدال پذیرد: <br />ژاپن = نی پن . <br />> به «ی » بدل شود: <br />ژاپن = یابان .<br />> حرف «ژ» در تعریب به «ق » بدل شود:<br />قنذفیل و قندویل = ژنده پیل .<br />> و به «غ » بدل گردد:<br />اسطاژیرا = اسطاغیرا .<br />حرف «ژ» با «ز» قافیه آید، مانند:<br />جهان از بدان ویژه او داشتی <br />به رزم اندرون نیزه او داشتی .<br /> <font color=\"Red\">دقیقی .</font><br />و چون «نوز» و «سوز». رجوع به نوز شود.<br /></font></div>'),
(287603, 'ژآن', '<span class=\"hlight\">ژآن .</span> <font color=\"DarkGreen\"><b>[ ژِ ]</font></b> (اِخ ) سلسله ٔ جبال واقعه در شمال بوهم منشعب از الب . نام این کوه به آلمانی ریزن گبیرگ و به زبان چک کرکنوشه است .<br /></font></div>'),
(287604, 'ژابس', '<span class=\"hlight\">ژابس .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) ژابش . همان یابیش جلعاد است که شهری بوددر مشرق اردن که اسرائیلیان آن را خراب کردند... و ناحاش عمونی بقصد فتح آن برآمد لیکن شاؤل آن را مستخلص ساخت ... و چون شاؤل و اولادش در جلبوع کشته شدنداهالی یابیش رفته نعش ایشان را از بیت شان به یابیش آورده سوزانیدند و استخوانها را در زیر درخت گزی در یابیش دفن کردند... و داود ایشان را بدین واسطه تبریک کرد... و از آن پس استخوانهای مذکور را به صیلعبن یامین نقل کرده و در قبر قیس پدر خود دفن کردند... روبنسون گمان دارد که یابیش جلعاد در نزدیک دیر است که به مسافت <span class=\"hlight\" dir=\"rtl\">٢٣</span> میل به جنوب شرقی دریای جلیل بطرف جنوبی وادی یابیش واقع است، امّا مورل گمان میکند که آن نزدیک خرابه ای است که به مسافت هفت میل از فحل بطرف شمال وادی یابیش واقع میباشد. (قاموس کتاب مقدس ).<br /></font></div>'),
(287605, 'ژابش', '<span class=\"hlight\">ژابش .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) رجوع به ژابس شود.<br /></font></div>'),
(287606, 'ژابلشکف', '<span class=\"hlight\">ژابلشکف .</span> <font color=\"DarkGreen\"><b>[ ل ُ ک ُ ]</font></b> (اِخ ) پُل . نام فیزیک دان روسی متولد در سردوبسک که به مطالعات و آثارخود در مبحث الکتریک معروف است (<span class=\"hlight\" dir=\"rtl\">١٨٤٧</span> - <span class=\"hlight\" dir=\"rtl\">١٨٩٤</span> م .).<br /></font></div>'),
(287607, 'ژابلنسکی', '<span class=\"hlight\">ژابلنسکی .</span> <font color=\"DarkGreen\"><b>[ ل ُ ]</font></b> (اِخ ) پُل اِرنست . نام متألّه و زبانشناس آلمانی که بسال <span class=\"hlight\" dir=\"rtl\">١٦٩٣</span> م . در برلن متولد شد و بسال <span class=\"hlight\" dir=\"rtl\">١٧٥٧</span> در فرانکفرت سورلُدر درگذشت . وی از استادان معروف دانشگاه فرانکفرت سورلُدر است . (از لاروس ).<br /></font></div>'),
(287608, 'ژابلنک', '<span class=\"hlight\">ژابلنک .</span> <font color=\"DarkGreen\"><b>[ ل ُ ن ِ ]</font></b> (اِخ ) رجوع به یابلنک شود.<br /></font></div>'),
(287609, 'ژابوراندی', '<span class=\"hlight\">ژابوراندی .</span> <font color=\"DarkGreen\"><b>[ ب ُ ]</font></b> (فرانسوی، اِ) گیاهی است از طایفه ٔ سداب و بومی برزیل، معرق و مدر لعاب . (ناظم الاطباء).<br /></font></div>'),
(287610, 'ژابیز', '<span class=\"hlight\">ژابیز.</span> (اِ) رجوع به ژابیژ شود.<br /></font></div>'),
(287611, 'ژابیژ', '<span class=\"hlight\">ژابیژ.</span> (اِ) داروئی است که آن را بوی مادران گویند. (برهان ). رجوع به بوی مادران شود. <BR><font color=\"Blue\">◄</font> سرشک آتش و آن قطره های آب است که از هیزم تر در وقت سوختن می چکد. شراره ٔ آتش . ابیز. (برهان ).<br /></font></div>'),
(287612, 'ژاتیوا', '<span class=\"hlight\">ژاتیوا.</span> <font color=\"DarkGreen\"><b>[ تی ]</font></b> (اِخ ) نام شهری است به اسپانیا بر مصب مونت سا و در طرف راست ژوکار . این شهر را سان فلیپ دوژاتیوا نیز گویند.<br /></font></div>'),
(287613, 'ژاد', '<span class=\"hlight\">ژاد.</span> (اِخ ) نام خلیجی از خلیجهای آلمان در دریای شمال که بندر ویلهلمشافن بر ساحل آن است .<br /></font></div>'),
(287614, 'ژادوس', '<span class=\"hlight\">ژادوس .</span> (اِخ ) یدوع . پسر یوناتان از قبیله ٔ لاوی . رجوع به یدوع شود.<br /></font></div>'),
(287615, 'ژارتیر', '<span class=\"hlight\">ژارتیر.</span> <font color=\"DarkGreen\"><b>[ رِ ی ِ ]</font></b> (اِخ ) نام طبقه ای از سواران که بسال <span class=\"hlight\" dir=\"rtl\">١٣٤٨</span> م . در انگلستان تأسیس شد بدین کیفیت که ادوارد سوم با کنتس سالیس بوری رقص میکرد، بند جوراب کنتس بیفتاد، شاه آن را برگرفت و به وی داد. درباریان از آن به خنده افتادند. شاه گفت : لعنت بر بداندیش باد! آنکه امروز بدین بند می خندد فردا به نشان آن مباهی نخواهد بود. و پس ازآن بر فور طبقه ٔ ژارتیر را تأسیس کرد. سواران که عده ٔ ایشان <span class=\"hlight\" dir=\"rtl\">٢٦</span> تن است آن بند را بر زانوی چپ بندند و ملکه بر دست . خود شاه پیشوای آنان است . (از لاروس ).<br /></font></div>'),
(287616, 'ژارسلو', '<span class=\"hlight\">ژارسلو.</span> <font color=\"DarkGreen\"><b>[ رُ ل َ ]</font></b> (اِخ ) نام شهری به «گالیسی » واقع بر ساحل نهر سان شعبه ٔ یمین رود ویستول دارای قریب <span class=\"hlight\" dir=\"rtl\">١٨٠٦٥</span> تن سکنه .<br /></font></div>'),
(287617, 'ژارناژ', '<span class=\"hlight\">ژارناژ.</span> (اِخ ) نام کرسی بخش در ایالت «کروز» از شهرستان گِرِه که قریب <span class=\"hlight\" dir=\"rtl\">٦٠٥</span> تن سکنه دارد.<br /></font></div>'),
(287618, 'ژارناک', '<span class=\"hlight\">ژارناک .</span> (اِخ ) فیلیپ فردینان اگوست دو روهان شابو، کنت دو. نام سیاستمدار فرانسوی متولد در ایرلند بسال <span class=\"hlight\" dir=\"rtl\">١٨١٥</span> م . و متوفی در لندن بسال <span class=\"hlight\" dir=\"rtl\">١٨٧٥</span> م . (از لاروس ).<br /></font></div>'),
(287619, 'ژارناک', '<span class=\"hlight\">ژارناک .</span> (اِخ ) گی شابو، کنت دو. نام کاپیتن فرانسوی متوفی بعد از سنه ٔ <span class=\"hlight\" dir=\"rtl\">١٥٧٢</span> م . وی همان است که شاتینیره را بسال <span class=\"hlight\" dir=\"rtl\">١٥٤٧</span> در جنگ تن بتن بکشت . (از لاروس ).<br /></font></div>'),
(287620, 'ژارناک', '<span class=\"hlight\">ژارناک .</span> (اِخ ) کرسی بخش در ایالت شارنت از شهرستان کُنیاک بر ساحل راست رود شارنت، دارای <span class=\"hlight\" dir=\"rtl\">٣٧٩٦</span> تن سکنه . آنجا مرکز عمده ٔ دستگاههای تقطیر عرق و کنیاک است . فیروزی کاتولیکها به قیادت دوک آنژو (هانری سوم ) بر پروتستانها بسال <span class=\"hlight\" dir=\"rtl\">١٥٦٩</span> م . در این شهر بود.<br /></font></div>'),
(287621, 'ژارو', '<span class=\"hlight\">ژارو.</span> <font color=\"DarkGreen\"><b>[ رُ ]</font></b> (اِخ ) نام شهری به انگلستان (دورهام ) بر ساحل رود تاین دارای قریب به <span class=\"hlight\" dir=\"rtl\">٣٣٧٠٠</span> تن سکنه .<br /></font></div>'),
(287622, 'ژارویل', '<span class=\"hlight\">ژارویل .</span> <font color=\"DarkGreen\"><b>[ ژارْ ]</font></b> (اِخ ) نام دهستان مورت و موزل از ایالت نانسی دارای راه آهن و <span class=\"hlight\" dir=\"rtl\">٥٢٧٠</span> تن سکنه . بدانجا کوره های مرتفعی برای ذوب فلزات هست .<br /></font></div>'),
(287623, 'ژارژو', '<span class=\"hlight\">ژارژو.</span> <font color=\"DarkGreen\"><b>[ ژُ ]</font></b> (اِخ ) نام کرسی بخش در ایالت «لوآره » از شهرستان اورلئان بر ساحل چپ رود لوآر دارای <span class=\"hlight\" dir=\"rtl\">١٨٥٥</span> تن سکنه . ژاندارک در سال <span class=\"hlight\" dir=\"rtl\">١٤٢٩</span> م . بدانجا بر انگلیسها غلبه کرد.<br /></font></div>'),
(287624, 'ژاری', '<span class=\"hlight\">ژاری .</span> (اِخ ) کرسی بخش در ایالت شارانت ماری تیم از شهرستان لارشل، دارای راه آهن و قریب <span class=\"hlight\" dir=\"rtl\">٧١١</span> تن سکنه .<br /></font></div>'),
(287625, 'ژازن', '<span class=\"hlight\">ژازن .</span> <font color=\"DarkGreen\"><b>[ زُ ]</font></b> (اِخ ) پسر اِزُن پادشاه یلکس . وی بیاری سانتور شیرون رفعت و مقام یافت و سپس به دست پلیاس از تخت سلطنت که از پدر بمیراث برده بود خلع شد. او آرگونوت ها را به گشادن گنج های کلشید راهنمائی کرد و از این ممالک دور مدئه را همراه آورد و او را بزنی گرفت، سپس وی را طلاق گفت و با کروز دختر سی زیف ازدواج کرد. کروز از ژازن دو فرزند آورد. ژازُن سرانجام تخت سلطنت یلکس را مجدداً به دست آوردو پس از حادثه ٔ دیگری در سرگردانی و بدبختی بمرد.<br /></font></div>'),
(287626, 'ژازن', '<span class=\"hlight\">ژازن .</span> <font color=\"DarkGreen\"><b>[ زُ ]</font></b> (اِخ ) بقول پلوتارک نام بازیگری بود از مردم شهر ترال که در پیشگاه اُرُد اشک سیزدهم اشکانی در جشنی که این پادشاه برای عروسی پسرش پاکروس با خواهر پادشاه ارمنستان برپا کرده بود بازی آگاوه را موسوم به باکانت از تصنیفات اری پید نمایش میداد و حضار با لذت و اعجابی هرچه تمامتر به سخنان او گوش فراداده بودند که ناگاه سر کراسوس سردار رومی را که به دست سورنا سردارایرانی کشته شده بود سیلاس به مجلس آورده به پای شاهنشاه ایران انداخت . ژازن برای اینکه شاهنشاه را در این پیروزی بزرگ تهنیتی گفته باشد سر کراسوس را برداشته و بالمناسبة این اشعار را از زبان آگاوه بخواند: «از بلندی کوهستانهایمان این بچه شیر را که آفت دشتهای ماست به اینجا آورده ایم، از این صید که باعث سعادت است فاتح را مفتخر میدانیم ». از این مناسب خوانی همه ٔ حضار لذت بردند و نمایش دهندگان دنباله ٔ شعر مزبوررا بخواندند، یعنی آنجائی را که آوازه خوانان میپرسند: «چه دستی او را زد؟» و آگاوه جواب میدهد: «دست من شرف این کار را داشت ». ارد را این مناسب خوانی خوش آمد و او را یک تالان که تقریباً معادل بیست و هشت هزار ریال بود ارزانی داشت . (ایران باستان ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٢٣٢٥</span>).<br /></font></div>'),
(287627, 'ژاسمن', '<span class=\"hlight\">ژاسمن .</span><font color=\"DarkGreen\"><b>[ م َ ]</font></b> (اِخ ) ژاک بوئه . نام شاعری از مردم گاسکنی، متولد و متوفی در آژان (<span class=\"hlight\" dir=\"rtl\">١٧٩٨</span> - <span class=\"hlight\" dir=\"rtl\">١٨٦٤</span> م .). وی پسر خیاطی بود و چندی در مدرسه ٔ علوم روحانی و مذهبی گذرانید و سپس دکه ٔ حلاّقی و مزینی باز کرد و مشغول کار شد، از این جهت او را «پروکیه » گویند. وی پس از بیست وچهار سال اولین منظومه ٔ خود را به لهجه ٔ گاسکنی بنام «مرا باید مرد» انتشارداد و بسال <span class=\"hlight\" dir=\"rtl\">١٨٣٥</span> م . بهترین آثار خود را که به لهجه ٔمحلی سروده شده بود فراهم آورده در مجلّدی بنام «لاس پاپی یوتس » منتشر ساخت .<br /></font></div>'),
(287628, 'ژاسی', '<span class=\"hlight\">ژاسی .</span> (اِخ ) رجوع به یاشی شود.<br /></font></div>'),
(287629, 'ژاشت', '<span class=\"hlight\">ژاشت .</span> (اِخ ) ناحیتی است از حدود ماوراءالنهر اندر کوهها و شکستگی ها و اندر میان بتمان و ختلان نهاده، با روستاها و کشت و برز بسیار و مهتران این ناحیت را دهقان ژاشت خوانند. (حدود العالم چ طهران ص <span class=\"hlight\" dir=\"rtl\">٧٢</span>). از اقلیم پنجم است . (التفهیم ص <span class=\"hlight\" dir=\"rtl\">١٩٩</span>).<br /></font></div>'),
(287630, 'ژاعو', '<span class=\"hlight\">ژاعو.</span> (اِ) ژاغو. صاحب ذخیره گوید: چون علت رجا که زنان را پدید آید و آن گوشت پاره ای باشد بی روح که اندر جسم تولید کند و چون ژاعو که اندر فرغانه و بعض نواحی خوارزم همی باشد. (ذخیره ٔ خوارزمشاهی نسخه ٔ خطّی مؤلف ورق <span class=\"hlight\" dir=\"rtl\">٤٣</span> صفحه ٔ دست چپ سطر ده ). و ظاهراً این همان چیزی است که مثل بادنجان بزرگ از گلو آویزد. <br /></font></div>'),
(287631, 'ژاغر', '<span class=\"hlight\">ژاغر.</span> <font color=\"DarkGreen\"><b>[ غ َ ]</font></b> (اِ) چینه دان . به تازی آن را حوصله خوانند. کژار. چینه دان مرغ <span class=\"hlight\">:</span> <br />خورنداز آنچه بماند ز من ملوک زمین <br />تو از پلیدی و مردار پر کنی ژاغر.<br /> <font color=\"Red\">عنصری (خطاب باز سپید به زاغ ).</font><br />وگر مرغکی کوچک آید فراز<br />دهدش آب و چینه بروز دراز<br />چو از بس چنه پر شود ژاغرش <br />گرد زورمندی تن لاغرش .<br /> <font color=\"Red\">اسدی .</font><br />از خون دلیران بدشت، شیران <br />از نیزه ٔ او پر کنند ژاغر.<br /> <font color=\"Red\">قطران .</font><br />از کشتگان هنوز طیور و سباع را<br />پر گوشت ژاغر است و پر از استخوان شکم .<br /> <font color=\"Red\">معزی .</font><br />کبوتری است که بر چنگ و مخلب شاهین <br />براه دیده ز ژاغر برافکند ارزن .<br /> <font color=\"Red\">ازرقی .</font><br />مرغ توام مرا پر فرمان ده و بپران <br />که الاّ سزای دانه ٔ تو ژاغری ندارم .<br /> <font color=\"Red\">خاقانی .</font><br />از دل و رخسارشان خوردند چندان کرکسان <br />کز شبه منقار و از زرنیخ ژاغر ساختند.<br /> <font color=\"Red\">خاقانی .</font><br />دائم از چینه های انعامش <br />پر بود مرغ آز را ژاغر.<br /><font color=\"Red\">لطیفی (از شعوری ).</font><br /></font></div>'),
(287632, 'ژاغو', '<span class=\"hlight\">ژاغو.</span> (اِ) رجوع به ژاعو شود.<br /></font></div>'),
(287633, 'ژافا', '<span class=\"hlight\">ژافا.</span>(اِخ ) نام پرده ای بزرگ در موزه ٔ لوور که مبتلاشدگان به مرض طاعون را در شهر یافا در حالی که بناپارت با ژنرال های خود در بیمارستانی به عیادت ایشان رفته است نشان میدهد (<span class=\"hlight\" dir=\"rtl\">١٨٠٤</span> م .).<br /></font></div>'),
(287634, 'ژافا', '<span class=\"hlight\">ژافا.</span> (اِخ ) در تداول مردم اروپا یافا را گویند. رجوع به یافا شود.<br /></font></div>'),
(287635, 'ژافنا', '<span class=\"hlight\">ژافنا.</span> (اِخ ) نام شهر و بندر سیلان و آن دارای <span class=\"hlight\" dir=\"rtl\">٤٥٠٠٠</span> سکنه است .<br /></font></div>'),
(287636, 'ژافه', '<span class=\"hlight\">ژافه .</span> <font color=\"DarkGreen\"><b>[ ف ِ ]</font></b> (اِخ ) پسر سوم نوح . یافث . رجوع به یافث شود.<br /></font></div>'),
(287637, 'ژافه', '<span class=\"hlight\">ژافه .</span> <font color=\"DarkGreen\"><b>[ ف َ <span class=\"hlight\" dir=\"rtl\">/</span> ف ِ ]</font></b> (اِ) نوعی گیاه بدبو. <BR><font color=\"Blue\">◄</font> خارپشت . (آنندراج ). رجوع به زافه شود.<br /></font></div>'),
(287638, 'ژال', '<span class=\"hlight\">ژال .</span> (اِخ ) اگوستن . دانشمند فرانسوی نویسنده ٔ لغت نامه ٔ انتقادی و قاموسی در اصطلاحات کشتی رانی متولد به لیون (<span class=\"hlight\" dir=\"rtl\">١٧٩٥</span>-<span class=\"hlight\" dir=\"rtl\">١٨٧٣</span> م .).<br /></font></div>'),
(287639, 'ژال', '<span class=\"hlight\">ژال .</span> (اِ) ژاله . رجوع به ژاله شود <span class=\"hlight\">:</span> <br />بر ایشان ببارید چون ژال میغ<br />چه تیر از کمان و چه پولاد تیغ.<br /> <font color=\"Red\">فردوسی .</font><br />در بعض فرهنگها این صورت و شاهد از بیت مذکور آمده است ولی ظاهراً بر اساسی نیست .<br /></font></div>'),
(287640, 'ژالابر', '<span class=\"hlight\">ژالابر.</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) شارل فرانسوا. نام نقاش فرانسوی متولد در نیم بسال <span class=\"hlight\" dir=\"rtl\">١٨١٩</span> و متوفی بسال <span class=\"hlight\" dir=\"rtl\">١٩٠١</span> م .<br /></font></div>'),
(287641, 'ژالاپا', '<span class=\"hlight\">ژالاپا.</span> (اِخ ) نام شهری از مکزیک دارای <span class=\"hlight\" dir=\"rtl\">٢٨٠٠٠</span> تن سکنه، واقع در شمال وراکروز .<br /></font></div>'),
(287642, 'ژالق', '<span class=\"hlight\">ژالق .</span> <font color=\"DarkGreen\"><b>[ ل َ ]</font></b> (اِخ ) نام حصنی به سیستان .زالق، جالق، صالق، جالقان و صالقان نیز ضبط کرده اند. رجوع به زالق شود. (تاریخ سیستان ص <span class=\"hlight\" dir=\"rtl\">٢٩</span>).<br /></font></div>'),
(287643, 'ژاله', '<span class=\"hlight\">ژاله .</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (اِخ ) ژان لوئی نیکلا. مجسمه ساز فرانسوی متولد در پاریس بسال <span class=\"hlight\" dir=\"rtl\">١٨٠٢</span> و متوفی بسال <span class=\"hlight\" dir=\"rtl\">١٨٦٦</span> م .<br /></font></div>'),
(287644, 'ژاله', '<span class=\"hlight\">ژاله .</span> <font color=\"DarkGreen\"><b>[ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ل ِ ]</font></b> (اِ) تگرگ را گویند و سبب آن چنان است که چون بخار بهوا رود و سرمادر او اثر کند غلیظ شود و قطره ٔ باران گردد و در محل فرودآمدن فعل برودت در او زیاده تأثیر کند او را بفشرد و یخ بندد. (برهان ). ژاله را بتازی برد گویند.(ذخیره ٔ خوارزمشاهی ). (کذا در لغت نامه ٔ مقامات حمیدی ). حب الغمام . سنگچه . یخچه . سنگک . (حاشیه ٔ نسخه ٔ اسدی نخجوانی ). تگرگ را نیز گویند. (اسدی ) <span class=\"hlight\">:</span> <br />چون ژاله به سردی اندرون موصوف <br />چون غوره به خامی اندرون محکم .<br /> <font color=\"Red\">منجیک .</font><br />پدید آمدی منجنیق از برش <br />چو ژاله همی کوفتی بر سرش .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> باران . سرشک هوا. <BR><font color=\"Blue\">◄</font> شؤبوب . (زمخشری ) (دهار). سرشک صافی و شبنم که بر کشت افتد. (نسخه ٔ اسدی نخجوانی ). شبنم و آن چون قطره ٔ باران باشد که بامدادان از خنکی بر چیزها نشیند. (صحاح الفرس ). شبنم را نیز گویند و سبب آن چنان باشد که که شدت سرما هوای صافی را غلیظ کند و بخار سازد و از زمین اندکی بلند شود و بر برگهای نباتات نشیند و از آن قطره ها پدید گردد. (برهان ). رطوبتی که در هوای صحو بر گیاه و درخت نشیند و بسته نباشد خلاف شبنم . قطره ٔ آب که از سردی صبح بر برگ نشیند. <BR><font color=\"Blue\">◄</font> قطره ٔ آب که بر برگ گل و جز آن پیدا آید که روان و سیال است و بمعنی صقیع و پشک نیست <span class=\"hlight\">:</span> <br />زمانی برق پرخنده زمانی باد پرناله <br />چنان مادر ابر سوک عروس سیزده ساله <br />و گشته زین پرند سرخ شاخ بیدبن ساله <br />چنان چون اشک مهجوران نشسته ژاله بر ژاله .<br /> <font color=\"Red\">رودکی .</font><br />یاقوت وار لاله، بر برگ لاله ژاله <br />کرده بر او حواله، غواص در دریا.<br /> <font color=\"Red\">کسائی .</font><br /> <br />گل شنبلیدش پر از ژاله گشت <br />زبان و روانش پر از ناله گشت .<br /> <font color=\"Red\">فردوسی .</font><br />سرشک سر ابر چون ژاله گشت <br />همه کوه و هامون پر از لاله گشت .<br /> <font color=\"Red\">فردوسی .</font><br />شده ژاله در گل چو می در قدح <br />همی تافت از چرخ قوس قزح .<br /> <font color=\"Red\">فردوسی .</font><br />زبس کو همی شیون و ناله کرد<br />همه خلق را چشم پرژاله کرد.<br /> <font color=\"Red\">فردوسی .</font><br />پدید آمدی منجنیق از برش <br />چو ژاله همی کوفتی بر سرش .<br /> <font color=\"Red\">فردوسی .</font><br />بدرّید آواز گوش هزبر<br />تو گفتی همی ژاله بارید ابر.<br /> <font color=\"Red\">فردوسی .</font><br />ز دیوارها خشت و از بام سنگ <br />به کوی اندرون تیغ و تیر خدنگ <br />ببارید چون ژاله ز ابر سیاه <br />کسی را نبد بر زمین جایگاه .<br /> <font color=\"Red\">فردوسی .</font><br />بر ایشان ببارید چون ژاله میغ<br />چه تیر از کمان و چه پولاد تیغ.<br /> <font color=\"Red\">فردوسی .</font><br />ز بس نیزه و گرز و کوپال و تیغ<br />تو گفتی هوا ژاله بارد ز میغ.<br /> <font color=\"Red\">فردوسی .</font><br />به گرد اندرون نیزه چون ژاله بود<br />همه دشت از آن خستگان ناله بود.<br /> <font color=\"Red\">فردوسی .</font><br />تو گفتی هوا ژاله بارد همی <br />به سنگ اندرون لاله کارد همی .<br /> <font color=\"Red\">فردوسی .</font><br />همه شهر پر زاری و ناله گشت <br />به چشم اندرون آب چون ژاله گشت .<br /> <font color=\"Red\">فردوسی .</font><br />همه شهر ایران پر از ناله بود<br />به چشم اندرون آب چون ژاله بود.<br /> <font color=\"Red\">فردوسی .</font><br />بشست آسمان روی گیتی به قیر<br />ببارید چون ژاله از قیر تیر.<br /> <font color=\"Red\">فردوسی .</font><br />کوه پرلاله و لاله همه پرژاله <br />دشت پرسنبل و سنبل همه پرسوسن .<br /> <font color=\"Red\">فرخی .</font><br />وز سر بالا چون ژاله روان کردی تیر<br />هرکه را گفتی بر دیده برم تیر بکار.<br /> <font color=\"Red\">فرخی .</font><br />ژاله باران زده بر لاله ٔ نعمان نقط<br />لاله ٔ نعمان شده از ژاله ٔ باران نگار.<br /> <font color=\"Red\">منوچهری .</font><br />هر قمریکی قصد به باغی دارد<br />هر لاله گرفته ژاله ای در بر تنگ .<br /> <font color=\"Red\">منوچهری .</font><br />لاله به شمشاد برآمیختند<br />ژاله به گلنار درآویختند.<br /> <font color=\"Red\">منوچهری .</font><br />چون بردرید بر کف صحرا قباله ها<br />بارانها چکید و ببارید ژاله ها.<br /> <font color=\"Red\">منوچهری .</font><br />ژاله بر رخ فتاده چون عرقی <br />که به رخسار یار من باشد.<br /> <font color=\"Red\">بهرامی .</font><br />بگفت این و گل برگ پرژاله کرد<br />ز خونین سرشک آتشین لاله کرد.<br /> <font color=\"Red\">اسدی .</font><br />دلش گشت دریای درد و دریغ<br />شدش دیدگان ژاله بارنده میغ.<br /> <font color=\"Red\">اسدی .</font><br />کمان آزفنداک شد ژاله تیر<br />گل غنچه پیکان زره آبگیر.<br /> <font color=\"Red\">اسدی .</font><br />دیوستان شد زمین و خاک خراسان <br />زانکه همی ز ابر جهل بارد ژاله .<br /> <font color=\"Red\">ناصرخسرو.</font><br />تو سحاب سخا و مکرمتی <br />جود تو ژاله کز سحاب آید<br />زر و سیم است ژاله ٔ تو سحاب <br />آنچه در وزن و در حساب آید.<br /> <font color=\"Red\">سوزنی .</font><br />کف ّ جواد تو چون ابر بهار است راست <br />زو زده بر شوره زار ژاله چو بر کشتمند.<br /> <font color=\"Red\">سوزنی .</font><br />سعد ملک ای وزیر دریادل <br />کف راد تو ابر پرژاله <br />روید از ژاله ٔ کف رادت <br />بر رخ سائلان تو لاله .<br /> <font color=\"Red\">سوزنی .</font><br />ژاله خورشید شعله بارد اگر<br />درجهد برق خاطرش به غمام .<br /> <font color=\"Red\">انوری .</font><br />چون نم ژاله ز خایه از تف خورشید<br />جان حسود از تف حسام برآمد.<br /> <font color=\"Red\">خاقانی .</font><br />مائده سالار صبح، نزل سحرگه فکند<br />از پی جلاب خاص، ریخت ز ژاله گلاب .<br /> <font color=\"Red\">خاقانی .</font><br />ژاله به آن شمع ریخت روغن طلق از هوا<br />تا نرسد شمع را زآتش لاله عذاب .<br /> <font color=\"Red\">خاقانی .</font><br />تا شکل حباب از مدد ژاله نماید<br />چون خرگه بی روزن و بی در بشمر بر.<br /> <font color=\"Red\">سیف اسفرنگ .</font><br />ژاله بر لاله فرودآمد هنگام سحر<br />راست چون عارض گلبوی عرق کرده ٔ یار.<br /> <font color=\"Red\">سعدی .</font><br />اگر ژاله هر قطره ای دُر شدی <br />چو خرمهره بازار از او پُر شدی .<br /> <font color=\"Red\">سعدی .</font><br />فراقت کُشت خسرو را که بیمش بد ز روز بد<br />ملخ زد کشت دهقان را که می ترسید از ژاله .<br /> <font color=\"Red\">امیرخسرو.</font><br />خوی کرده میخرامد و بر عارض چمن <br />از شرم روی او عرق ژاله میرود.<br /> <font color=\"Red\">حافظ.</font><br />باد بهار میوزد از بوستان شاه <br />وز ژاله آب در قدح لاله میرود.<br /> <font color=\"Red\">حافظ.</font><br />بهار شدچه بجا خشک مانده ای، ای ابر<br />سزای خرقه ٔ تقوی بسنگ ژاله بده .<br /> <font color=\"Red\">صائب .</font><br /> <BR><font color=\"Blue\">◄</font> خیکی پرباد که بدو از آب بگذرند. (لغت نامه ٔ اسدی نسخه ٔ نخجوانی ). خیک باددمیده باشد که بدان از آبهای بزرگ عبره کنند. (صحاح الفرس ). بمعنی جاله و آن چیزی باشد که از چوب و علف سازند و مشکهای پرباد بر آن بندند و بر آن نشسته از آب گذرند و بعضی آن مشکهای پرباد را و مشکی را که شناوران بر پشت بندند ژاله گویند. (برهان قاطع).<br />چنانکه در فوق گذشت یکی از معانی که به ژاله میدهند (و پیش از همه ظاهراً در لغت اسدی آمده است ) خیکی است که پرباد کنند و بر آب بدان بگذرند، ولی شاهد آن تنها دو شعر فرخی است در یک قصیده و اولی بضبط نسخه ٔ اسدی نخجوانی این شعر است <span class=\"hlight\">:</span> <br />سرملوک عجم چون بنزد کوه رسید<br />صف سپاه عدو دید با سکون و قرار<br />ز ریدکان سرائی چوژاله بر سر آب <br />بدان کنار فرستاد ریدکی سه چهار.<br />در اینجا فرخی ریدک شناور را به ژاله تشبیه میکند و ظاهراً کلمه معنی حباب میدهد. و شاهد دوم آن بیت دیگر فرخی است در این شعر <span class=\"hlight\">:</span> <br />بدان ره اندر بگذشت ز آبهای بزرگ <br />چه آبهائی تا گنگ رفته از کهسار<br />چو آب سیلی کز ژاله برگرفتی مرد<br />چو آب جوئی کزپیل درربودی بار.<br />و چنانکه مشهود است این شعر به این صورت معنی ندارد و در نسخه ٔ چاپی عبدالرسولی بیت دوم این است <span class=\"hlight\">:</span> <br />چه آب گوئی از پیل برگرفتی سر<br />چه آب گوئی کز ژاله برفکندی بار.<br />و نسخه بدل «برگرفتن بار» است . ولی چون نسخه ٔ اسدی نخجوانی اقدم می باشد باید شعر را بحدس و تصحیح قیاسی اینطورخواند <span class=\"hlight\">:</span> <br />چو آب سیلی گر ژاله برگرفتی مرد<br />چو آب جوئی گر پیل واربردی بار.<br />آن وقت باز ژاله بمعنی حباب میشود و فاعل برگرفتی آب سیل و مفعول مرد است ؛ یعنی اگر آب سیل ژاله اش مردی بودی چنانکه در مصراع ثانی فاعل بردی آب جوی و مفعول بار پیل وار میباشد.<br />بنابر آنچه در بالا گذشت اگر شاهد این دو شعر فرخی است تنها آن برای این معنی یعنی خیک باداندردمیده کافی نیست زیرا بطوری که گفتم کلمه ٔ ژاله در آن دو شاهد اقرب به معنی کوهله و حباب است تا به خیک باداندردمیده .<br /></font></div>'),
(287645, 'ژالو', '<span class=\"hlight\">ژالو.</span> (اِخ ) اِدمُن . نام داستان نویس و نقاد فرانسوی، متولد به مارسی به سال <span class=\"hlight\" dir=\"rtl\">١٨٧٨</span> م . وی عضو فرهنگستان فرانسه و نویسنده ٔ کتاب «بقیه خاموشی است » است .<br /></font></div>'),
(287646, 'ژالکه', '<span class=\"hlight\">ژالکه .</span> <font color=\"DarkGreen\"><b>[ ک َ <span class=\"hlight\" dir=\"rtl\">/</span> ک ِ ]</font></b> (اِ) نام گیاهی است دوائی شبیه به انگشتان چلپاسه و زغن . (برهان ).<br /></font></div>'),
(287647, 'ژالیسکو', '<span class=\"hlight\">ژالیسکو.</span> <font color=\"DarkGreen\"><b>[ ک ُ ]</font></b> (اِخ ) نام شهری در مکزیک که آن را اکسالیسکو نیز خوانند. در این شهر آثار سفالین و اشیاء عتیق و بقایای ابنیه ٔ قدیمه یافت شده است که مربوط به تمدن باستانی بومیان اصلی مکزیک است .<br /></font></div>'),
(287648, 'ژالین یی', '<span class=\"hlight\">ژالین یی .</span> (اِخ ) نام کرسی حکومت از ایالت آلیر درشهرستان ویشی واقع بر ساحل رود ببر دارای <span class=\"hlight\" dir=\"rtl\">٩٥٤</span> تن سکنه . و بدانجا معدن مرمر سفید و کوره های آهک است .<br /></font></div>'),
(287649, 'ژالیو', '<span class=\"hlight\">ژالیو.</span> <font color=\"DarkGreen\"><b>[ ی ُ ]</font></b> (اِخ ) نام دهستانی از ایالت ایزر در شهرستان لاتوردوپن دارای <span class=\"hlight\" dir=\"rtl\">٥٣٧٧</span> تن سکنه . آنجا مرکز مقواسازی است .<br /></font></div>'),
(287650, 'ژامبلیک', '<span class=\"hlight\">ژامبلیک .</span> (اِخ ) نام فیلسوفی از طریقه ٔ افلاطونیون جدید در قرن چهارم میلادی .<br /></font></div>'),
(287651, 'ژامبلیک', '<span class=\"hlight\">ژامبلیک .</span> (اِخ ) نام داستان نویس یونانی متولد به شام در قرن دوم میلادی .<br /></font></div>'),
(287652, 'ژامن', '<span class=\"hlight\">ژامن .</span> <font color=\"DarkGreen\"><b>[ م َ ]</font></b> (اِخ ) ژول سلستن . نام طبیعی دان فرانسوی، متولد به ترم آردن (<span class=\"hlight\" dir=\"rtl\">١٨١٨</span>-<span class=\"hlight\" dir=\"rtl\">١٨٨٦</span> م .).<br /></font></div>'),
(287653, 'ژامن', '<span class=\"hlight\">ژامن .</span> <font color=\"DarkGreen\"><b>[م َ ]</font></b> (اِخ ) آمادیس . نام شاعر فرانسوی، متولد به شاورس (اوب ) شاگرد گزیده ٔ رونسار (<span class=\"hlight\" dir=\"rtl\">١٥٣٨</span>-<span class=\"hlight\" dir=\"rtl\">١٥٨٥</span> م .).<br /></font></div>'),
(287654, 'ژان', '<span class=\"hlight\">ژان .</span> (اِخ ) نپوموسن ماری ژزف . پادشاه ساکس متولد در <span class=\"hlight\" dir=\"rtl\">١٨٠١</span> و متوفی در <span class=\"hlight\" dir=\"rtl\">١٨٧٣</span> م .<br /></font></div>'),
(287655, 'ژان', '<span class=\"hlight\">ژان .</span> (اِخ ) او را کاتولیکوس می نامند. مورخ ارمنی متوفی در <span class=\"hlight\" dir=\"rtl\">٩٢٥</span> م . او تاریخ ارمنستان را به روایت موسی خورنی و الیزه و دیگر مورخان ارمنی نوشته است .<br /></font></div>'),
(287656, 'ژان', '<span class=\"hlight\">ژان .</span> (اِخ ) فردریک لوئی . نویسنده ٔ وطن خواه آلمانی متولددر لانز . وی در <span class=\"hlight\" dir=\"rtl\">١٨١٣</span> م . آلمانها را بر فرانسویان بشورانید. (<span class=\"hlight\" dir=\"rtl\">١٧٧٨</span>-<span class=\"hlight\" dir=\"rtl\">١٨٥٢</span> م .).<br /></font></div>'),
(287657, 'ژان', '<span class=\"hlight\">ژان .</span> (اِخ ) شارل ماری ایزیدر. نام شاهزاده ٔ بوربونی (<span class=\"hlight\" dir=\"rtl\">١٨٢٤</span>-<span class=\"hlight\" dir=\"rtl\">١٨٨٧</span> م .).<br /></font></div>'),
(287658, 'ژان', '<span class=\"hlight\">ژان .</span> (اِخ ) باتیست ژزف فابیان سه باستیان . آرشیدوک اطریش متولد در <span class=\"hlight\" dir=\"rtl\">١٧٨٢</span> و متوفی در <span class=\"hlight\" dir=\"rtl\">١٨٥٩</span> م .<br /></font></div>'),
(287659, 'ژان', '<span class=\"hlight\">ژان .</span> (اِخ ) اتو. عالم فقه اللغه و باستان شناس و مورخ آلمانی (<span class=\"hlight\" dir=\"rtl\">١٨١٣</span> - <span class=\"hlight\" dir=\"rtl\">١٨٦٩</span> م .).<br /></font></div>'),
(287660, 'ژان', '<span class=\"hlight\">ژان .</span> (اِخ ) او را پره مونتره نامند. نام رئیس طرفداران عقاید مذهبی در پراگ (<span class=\"hlight\" dir=\"rtl\">١٣٧٠</span>-<span class=\"hlight\" dir=\"rtl\">١٤٢١</span> م .).<br /></font></div>'),
(287661, 'ژان', '<span class=\"hlight\">ژان .</span> (اِخ ) کنتس فلاندر و هنو دختر بودوآن نهم کنت فلاندر و امپراطور قسطنطنیه، متوفی در <span class=\"hlight\" dir=\"rtl\">١٢٤٩</span> م .<br /></font></div>'),
(287662, 'ژان', '<span class=\"hlight\">ژان .</span> (اِخ ) ملکه ٔ فرانسه (<span class=\"hlight\" dir=\"rtl\">١٣٢٦</span>-<span class=\"hlight\" dir=\"rtl\">١٣٦٠</span> م .). دختر گیوم سیزدهم کنت دُوِرنی و بولنی .<br /></font></div>'),
(287663, 'ژان', '<span class=\"hlight\">ژان .</span> (اِخ ) یا ژان گری . رجوع به گری شود.<br /></font></div>'),
(287664, 'ژان', '<span class=\"hlight\">ژان .</span> (اِخ ) مورخ فرانسوی در قرن دوازدهم میلادی . او را آثار بسیاری به زبان لاتین است .<br /></font></div>'),
(287665, 'ژان', '<span class=\"hlight\">ژان .</span> (اِخ ) کنت آرمانیاک . رجوع به آرمانیاک شود.<br /></font></div>'),
(287666, 'ژان', '<span class=\"hlight\">ژان .</span> (اِخ ) نام پادشاه دانمارک و سوئد و نروژ (<span class=\"hlight\" dir=\"rtl\">١٤٥٥</span>-<span class=\"hlight\" dir=\"rtl\">١٥١٣</span> م .).<br /></font></div>'),
(287667, 'ژان', '<span class=\"hlight\">ژان .</span> (اِخ ) دوک دآلنسن . متولد در <span class=\"hlight\" dir=\"rtl\">١٤٠٩</span> و متوفی در پاریس بسال <span class=\"hlight\" dir=\"rtl\">١٤٧٦</span> م .<br /></font></div>'),
(287668, 'ژان', '<span class=\"hlight\">ژان .</span> (اِخ ) کنت انگولم . امیر و ادیب فرانسوی متولد در اورلئان بسال <span class=\"hlight\" dir=\"rtl\">١٤٠٤</span> و متوفی در کنیاک بسال <span class=\"hlight\" dir=\"rtl\">١٤٦٧</span> م .<br /></font></div>'),
(287669, 'ژان', '<span class=\"hlight\">ژان .</span> (اِخ ) امپراطور حبشه . اورا دجه کاسائی گویند. وی در حدود سال <span class=\"hlight\" dir=\"rtl\">١٨٣٢</span> متولد شد و بسال <span class=\"hlight\" dir=\"rtl\">١٨٨٩</span> م . درگذشت .<br /></font></div>'),
(287670, 'ژان اول', '<span class=\"hlight\">ژان اول .</span> <font color=\"DarkGreen\"><b>[ ن ِ اَوْ وَ ]</font></b> (اِخ ) لورو. دوک برتانی از <span class=\"hlight\" dir=\"rtl\">١٢٣٧</span> تا <span class=\"hlight\" dir=\"rtl\">١٢٨٦</span> م .<br /></font></div>'),
(287671, 'ژان اول', '<span class=\"hlight\">ژان اول .</span> <font color=\"DarkGreen\"><b>[ ن ِ اَوْ وَ ]</font></b> (اِخ ) لوپستم . پادشاه فرانسه . متولد در پاریس بسال <span class=\"hlight\" dir=\"rtl\">١٣١٦</span> م . وی بعد از مردن پدرش لوئی دهم لوهوتن زائیده شده و چند روز بیش نزیست .<br /></font></div>'),
(287672, 'ژان اول', '<span class=\"hlight\">ژان اول .</span> <font color=\"DarkGreen\"><b>[ ن ِ اَوْ وَ ]</font></b> (اِخ ) تزیمیسس . پادشاه یونان . متولد در ارمنستان بسال <span class=\"hlight\" dir=\"rtl\">٩٢٥</span> م . وی از سال <span class=\"hlight\" dir=\"rtl\">٩٦٩</span> تا <span class=\"hlight\" dir=\"rtl\">٩٧٦</span> م . در یونان پادشاهی کرده است .<br /></font></div>'),
(287673, 'ژان اول', '<span class=\"hlight\">ژان اول .</span> <font color=\"DarkGreen\"><b>[ ن ِ اَوْ وَ ]</font></b> (اِخ ) (قدیس ) پاپ مسیحی از سال <span class=\"hlight\" dir=\"rtl\">٥٢٣</span> تا <span class=\"hlight\" dir=\"rtl\">٥٢٦</span> م .<br /></font></div>'),
(287674, 'ژان اول', '<span class=\"hlight\">ژان اول .</span> <font color=\"DarkGreen\"><b>[ ن ِ اَوْ وَ ]</font></b> (اِخ ) دوک لورن متولد در <span class=\"hlight\" dir=\"rtl\">١٣٣٩</span> و متوفی در <span class=\"hlight\" dir=\"rtl\">١٣٩٠</span> م .<br /></font></div>'),
(287675, 'ژان اول', '<span class=\"hlight\">ژان اول .</span> <font color=\"DarkGreen\"><b>[ ن ِ اَوْ وَ ]</font></b> (اِخ ) یا ژان البرت . پادشاه لهستان (<span class=\"hlight\" dir=\"rtl\">١٤٥٩</span>-<span class=\"hlight\" dir=\"rtl\">١٥٠١</span> م .).<br /></font></div>'),
(287676, 'ژان اول', '<span class=\"hlight\">ژان اول .</span> <font color=\"DarkGreen\"><b>[ ن ِ اَوْ وَ ]</font></b> (اِخ ) ملکه ٔ ناپل از سال <span class=\"hlight\" dir=\"rtl\">١٣٤٣</span> تا <span class=\"hlight\" dir=\"rtl\">١٣٨٢</span> م . (<span class=\"hlight\" dir=\"rtl\">١٣٢٦</span> - <span class=\"hlight\" dir=\"rtl\">١٣٨٢</span> م .).<br /></font></div>'),
(287677, 'ژان اول', '<span class=\"hlight\">ژان اول .</span> <font color=\"DarkGreen\"><b>[ ن ِ اَوْ وَ ]</font></b> (اِخ ) پادشاه سوئد (<span class=\"hlight\" dir=\"rtl\">١٢٠١</span> - <span class=\"hlight\" dir=\"rtl\">١٢٢٢</span> م .).<br /></font></div>'),
(287678, 'ژان اول', '<span class=\"hlight\">ژان اول .</span> <font color=\"DarkGreen\"><b>[ ن ِ اَوْ وَ ]</font></b> (اِخ ) پادشاه پرتقال از <span class=\"hlight\" dir=\"rtl\">١٣٨٥</span> تا <span class=\"hlight\" dir=\"rtl\">١٤٣٣</span> م . و مؤسس سلسله ٔ آویز . مولد بسال <span class=\"hlight\" dir=\"rtl\">١٣٥٧</span> در لیسبن و وفات <span class=\"hlight\" dir=\"rtl\">١٤٣٣</span> م .<br /></font></div>'),
(287679, 'ژان اول', '<span class=\"hlight\">ژان اول .</span> <font color=\"DarkGreen\"><b>[ ن ِ اَوْ وَ ]</font></b> (اِخ ) نام پادشاه کاستیل (<span class=\"hlight\" dir=\"rtl\">١٣٥٨</span>-<span class=\"hlight\" dir=\"rtl\">١٣٩٠</span> م .).<br /></font></div>'),
(287680, 'ژان اول', '<span class=\"hlight\">ژان اول .</span> <font color=\"DarkGreen\"><b>[ ن ِ اَوْ وَ ]</font></b> (اِخ ) پادشاه آراگون متولد در <span class=\"hlight\" dir=\"rtl\">١٣٥٠</span> و متوفی در <span class=\"hlight\" dir=\"rtl\">١٣٩٥</span> م .<br /></font></div>'),
(287681, 'ژان ایتالس', '<span class=\"hlight\">ژان ایتالس .</span> <font color=\"DarkGreen\"><b>[ ل ُ ]</font></b> (اِخ ) نام فیلسوف یونانی در قرن یازدهم میلادی . وی در ایتالیا متولد شد و در قسطنطنیه نشو و نما یافت . فلسفه و آثار افلاطون و ارسطو و فرفوریوس و ژامبلیک و پرکلوس را شرح کرد ولی متهم به بددینی گشت و تکفیر شد.<br /></font></div>'),
(287682, 'ژان باتیست', '<span class=\"hlight\">ژان باتیست .</span> <font color=\"DarkGreen\"><b>[ ژام ْ ]</font></b> (اِخ ) رجوع به یحیی تعمیددهنده شود.<br /></font></div>'),
(287683, 'ژان بن سنت آندره', '<span class=\"hlight\">ژان بن سنت آندره .</span> <font color=\"DarkGreen\"><b>[ ژام ْ ب ُ س َ رِ ]</font></b> (اِخ ) یا آندره ژان بون . او را بارون نیز میگفتند. وی عضو مجلس کنوانسیون فرانسه بود (<span class=\"hlight\" dir=\"rtl\">١٧٤٩</span>-<span class=\"hlight\" dir=\"rtl\">١٨١٣</span> م .).<br /></font></div>'),
(287684, 'ژان بیست ودوم', '<span class=\"hlight\">ژان بیست ودوم .</span><font color=\"DarkGreen\"><b>[ ن ِ ت ُ دُوْ وُ ]</font></b> (اِخ ) ژاک دوئز . پاپ مسیحی از <span class=\"hlight\" dir=\"rtl\">١٣١٦</span> تا <span class=\"hlight\" dir=\"rtl\">١٣٣٤</span> م . در زمان این پاپ الملک الناصر پادشاه مصر که معاصر با ابوسعید بهادر مغول بود در سال <span class=\"hlight\" dir=\"rtl\">٧٢٠</span>هَ . ق . جمعی از سرداران خود را امر به هجوم به ارمنستان صغیر و غارت شهر سیس پایتخت کیلیکیه داد و آنان از نیمه ٔ ربیعالاَّخر این سال به بعد آن شهر را غارت کردند و از نهر جیحان گذشتند و سراسر ارمنستان را به باد غارت دادند. پادشاه صغیر آن مملکت لئون پنجم که ده سال بیش نداشت و اتابک ارمنی او چاره ای ندیدند جز آنکه از پاپ ژان بیست ودوم استمداد کنند و عالم عیسویت را به کمک بطلبند. پاپ در جواب نوشت که سلاطین اروپا گرفتار جنگ با یکدیگرند و نمیتوانند به مدد او بیایند، ولی خود او قشونی به کمک ارمنستان میفرستد. رسیدن این خبر الملک الناصر را بر ارمنستان خشمناک کرد و بار دیگر آن مملکت را به باد غارت داد و به بلاد عیسوی نشین تاخت و شهر ادانه به دست مصریان بسوخت و قریب بیست هزار تن از ارامنه به اسیری گرفتار شدند. از شنیدن این اخبار پاپ بار دیگر به خیال یاری ارمنستان افتاد و این بار علاوه بر اعانه ای که جهت پادشاه آن مملکت جمعآوری کرد و فرستاد مراسله ای به تاریخ <span class=\"hlight\" dir=\"rtl\">١٣</span> ژویه ٔ <span class=\"hlight\" dir=\"rtl\">١٣٢٢</span> م . <span class=\"hlight\" dir=\"rtl\">٢٧/</span> جمادی الثانی <span class=\"hlight\" dir=\"rtl\">٧٢٢</span> هَ . ق .) از شهر آوین یون به ابوسعید پادشاه مغول در ایران نوشت و سیاست سابق ایلخانان ایران واجداد او را به یاد او آورد و او را به کمک ارمنستان دعوت کرد و نامه ای دیگر خصوصاً به ایلخان نوشت و او را به قبول مذهب مسیح خواند. چند سال بعد از بنای شهر سلطانیه یعنی در تاریخ <span class=\"hlight\" dir=\"rtl\">٧١٨</span> پاپ بموجب فرمانی در آن شهر کنیسه ای دایر کرد و یکی از روحانیون عیسوی راکه فرانسوا دوپروز نام داشت به ریاست و خلیفگی عیسویان رعیت ایران و ممالک مجاور آن فرستاد و این روحانی تا سال <span class=\"hlight\" dir=\"rtl\">٧٢٤</span> این مقام رادارا بود، ولی چون ایلخانان ایران قبول اسلام کرده بودند دیگر عیسویان به آن درجه از نفوذ و اقتدار که در عهد هولاکو و اباقا و ارغون داشتند نرسیدند. لئون پادشاه ارمنستان هم در این تاریخ از ابوسعید مدد خواست و ابوسعید با وجود معاهده ای که با سلطان مصر داشت <span class=\"hlight\" dir=\"rtl\">٢٠٠٠٠</span> سپاهی بمدد او روانه کرد و ضمناً سلطان مصر رابه عقد صلح با پادشاه ارمنستان خواند اما قبل از آنکه سپاهیان ابوسعید برسند قشون مصریان چنان ارامنه را از پا درآورده بودند که خلیفه ٔ ارمنستان به ملاقات الملک الناصر رفت و با او معاهده ای بمدت پانزده سال در ترک جنگ با ارمنستان بست و لئون در سال <span class=\"hlight\" dir=\"rtl\">٧٢٩</span> رسماً قبول تبعیت از الملک الناصر کرده خلعت و تشریف او بپوشید و ارامنه با قبول این خواری از آزار قشون مصری رهائی یافتند. (از تاریخ مغول اقبال صص <span class=\"hlight\" dir=\"rtl\">٣٤٧</span> - <span class=\"hlight\" dir=\"rtl\">٣٤٨</span>).<br /></font></div>'),
(287685, 'ژان بیست وسوم', '<span class=\"hlight\">ژان بیست وسوم .</span> <font color=\"DarkGreen\"><b>[ ن ِ ت ُ س ِوْ وُ ]</font></b> (اِخ ) (بالتازار کسا) پاپ مسیحی . وی در سال <span class=\"hlight\" dir=\"rtl\">١٤١٠</span> م . به مقام پاپی رسید و در <span class=\"hlight\" dir=\"rtl\">١٤١٥</span> م . از آن مقام خلع شد و بسال <span class=\"hlight\" dir=\"rtl\">١٤١٩</span> درگذشت .<br /></font></div>'),
(287686, 'ژان بیست ویکم', '<span class=\"hlight\">ژان بیست ویکم .</span> <font color=\"DarkGreen\"><b>[ ن ِ ت ُ ی ِ ک ُ ]</font></b> (اِخ ) (پیر ژولیانی ) پاپ مسیحی از سال <span class=\"hlight\" dir=\"rtl\">١٢٧٦</span> تا <span class=\"hlight\" dir=\"rtl\">١٢٧٧</span> م . در عهد وی دو تن نماینده از طرف دربار اباقا پادشاه مغول در ایران عازم شهر رم شدند و عیسویان را به پس گرفتن بیت المقدس و فلسطین از دست مسلمین دعوت کردند و از جانب اباقا به ایشان وعده ٔ مساعدت شد و پاپ آنان را نزد سلاطین فرانسه و انگلیس فرستاد و دو نماینده ٔ مزبور که ازعیسویان گرجی بودند از طرف آباقا اظهار داشتند که او و قوبیلای قاآن مائلند که قبول دیانت عیسوی کنند. پاپ برای تحقیق مطلب و تبلیغ آئین مسیح تصمیم گرفت که پنج تن از روحانیون را به دیار مشرق فرستد، ولی چون در همان اوان یعنی سال <span class=\"hlight\" dir=\"rtl\">٦٧٦</span> هَ . ق . بمرد تصمیم او عملی نشد، فقط نیکلای سوم پاپ جدید سال بعد نامه ای به اباقا و قوبیلای نوشت و از مساعدت ایشان درباره ٔ عیسویان اظهار مسرّت کرد. (از تاریخ مغول اقبال ص <span class=\"hlight\" dir=\"rtl\">٢٠٤</span>).<br /></font></div>'),
(287687, 'ژان بیستم', '<span class=\"hlight\">ژان بیستم .</span> <font color=\"DarkGreen\"><b>[ ن ِ ت ُ ]</font></b> (اِخ ) وی چند ماهی در سال <span class=\"hlight\" dir=\"rtl\">١٠٤٤</span> م . پاپ غیرقانونی بود.<br /></font></div>'),
(287688, 'ژان بیوگر', '<span class=\"hlight\">ژان بیوگر.</span> <font color=\"DarkGreen\"><b>[ یُگ ْ ]</font></b> (اِخ ) رجوع به ایوان شود.<br /></font></div>'),
(287689, 'ژان داراس', '<span class=\"hlight\">ژان داراس .</span> (اِخ ) مشهور به کارون . نثرنویس فرانسوی در قرن پانزدهم میلادی .<br /></font></div>'),
(287690, 'ژان داراس', '<span class=\"hlight\">ژان داراس .</span> (اِخ ) نام نثرنویس فرانسوی در قرن چهاردهم میلادی و دبیر ژان دوک دوبری برادر شارل پنجم .<br /></font></div>'),
(287691, 'ژان داراگن', '<span class=\"hlight\">ژان داراگن .</span> <font color=\"DarkGreen\"><b>[ گ ُ ]</font></b> (اِخ ) پسر صلبی فردینان اول پادشاه ناپل . متوفی در <span class=\"hlight\" dir=\"rtl\">١٥٧٧</span> م . رفائیل نقاش را از او تصویری است در موزه ٔ لوور.<br /></font></div>'),
(287692, 'ژان دالبره', '<span class=\"hlight\">ژان دالبره .</span> <font color=\"DarkGreen\"><b>[ رِ ]</font></b> (اِخ ) نام ملکه ٔ ناوار . وی زوجه ٔ آنتوان دوبوربون و مادر هانری چهارم است . بسال <span class=\"hlight\" dir=\"rtl\">١٥٢٨</span> درپاریس متولد شد و در <span class=\"hlight\" dir=\"rtl\">١٥٧٢</span> م . در همان شهر درگذشت .<br /></font></div>'),
(287693, 'ژان داماسن', '<span class=\"hlight\">ژان داماسن .</span> <font color=\"DarkGreen\"><b>[ س ِ ]</font></b> (اِخ ) (قدیس ) عالم روحانی کلیسای یونانی متولد در دمشق و متوفی بعد از سال <span class=\"hlight\" dir=\"rtl\">٧٥٤</span> م . وی با بدعت تصویرپرستی مبارزه میکرد. ذکران او ششم مارس است .<br /></font></div>'),
(287694, 'ژان دانتیوش', '<span class=\"hlight\">ژان دانتیوش .</span> <font color=\"DarkGreen\"><b>[ یُش ْ ]</font></b> (اِخ ) وقایعنگار و مورخ بیزانسی که به احتمال برخی در اوائل قرن هفتم میلادی میزیسته است . او را تاریخی است عمومی که در آن وقایع تاریخ را از اول خلقت تا سال <span class=\"hlight\" dir=\"rtl\">٦١٠</span> م . به رشته ٔ تحریر آورده است .<br /></font></div>'),
(287695, 'ژان دانتیوش', '<span class=\"hlight\">ژان دانتیوش .</span> <font color=\"DarkGreen\"><b>[ یُش ْ ]</font></b> (اِخ ) ملقب به اسکلاستیک بطریق قسطنطنیه از <span class=\"hlight\" dir=\"rtl\">٥٦٤</span> تا <span class=\"hlight\" dir=\"rtl\">٥٧٨</span> م .<br /></font></div>'),
(287696, 'ژان دبرگام', '<span class=\"hlight\">ژان دبرگام .</span> <font color=\"DarkGreen\"><b>[ دُ ب ِ ]</font></b> (اِخ ) (قدیس ) اسقف برگام (<span class=\"hlight\" dir=\"rtl\">٦٥٦</span> - <span class=\"hlight\" dir=\"rtl\">٦٨٣</span> م .).<br /></font></div>'),
(287697, 'ژان دبوربن', '<span class=\"hlight\">ژان دبوربن .</span> <font color=\"DarkGreen\"><b>[ دُ ب ُ ]</font></b> (اِخ ) ملکه ٔ فرانسه دختر پیر اول متولد بسال <span class=\"hlight\" dir=\"rtl\">١٣٣٨</span> و متوفی بسال <span class=\"hlight\" dir=\"rtl\">١٣٧٨</span> م .<br /></font></div>'),
(287698, 'ژان دبورگنی', '<span class=\"hlight\">ژان دبورگنی .</span> <font color=\"DarkGreen\"><b>[ دُ گ ُن ْی ْ ]</font></b> (اِخ ) ملکه ٔ فرانسه و زوجه ٔ فیلیپ پنجم متوفی بسال <span class=\"hlight\" dir=\"rtl\">١٣٢٥</span> م .<br /></font></div>'),
(287699, 'ژان دبورگنی', '<span class=\"hlight\">ژان دبورگنی .</span> <font color=\"DarkGreen\"><b>[ دُ گ ُن ْی ْ ]</font></b> (اِخ ) دختر روبرت دوم دوک بورگنی . (<span class=\"hlight\" dir=\"rtl\">١٢٩٣</span> - <span class=\"hlight\" dir=\"rtl\">١٣٤٨</span> م .).<br /></font></div>'),
(287700, 'ژان دتری', '<span class=\"hlight\">ژان دتری .</span> <font color=\"DarkGreen\"><b>[ دُ رُ ]</font></b> (اِخ ) مورخ فرانسوی در قرن پانزدهم میلادی .<br /></font></div>'),
(287701, 'ژان ددیو', '<span class=\"hlight\">ژان ددیو.</span> <font color=\"DarkGreen\"><b>[ دُ ی ُ ]</font></b> (اِخ ) (قدیس )مؤسس طریقه ٔ شاریته (برادران سن ژان دودیو) است . مولد او پرتقال (<span class=\"hlight\" dir=\"rtl\">١٤٩٥</span> م .) وذکران وی در هشتم مارس است (متوفی بسال <span class=\"hlight\" dir=\"rtl\">١٥٥٠</span> م .).<br /></font></div>'),
(287702, 'ژان دزانتمر', '<span class=\"hlight\">ژان دزانتمر.</span> <font color=\"DarkGreen\"><b>[ دِ ت ُ م ُ ]</font></b> (اِخ ) نام یکی از اشخاص مذکور در کتاب رابله . راهبی بزم آرای و رزمجوی بود و او همان است که گارگانتوآ دستور داد برای وی معبد تلم را بنا کنند.<br /></font></div>'),
(287703, 'ژان دسالیسبوری', '<span class=\"hlight\">ژان دسالیسبوری .</span> <font color=\"DarkGreen\"><b>[ دُ ]</font></b> (اِخ ) نام فیلسوف اسکولاستیک انگلیسی، بطریق شارتر و دوست سن توماس بکه (<span class=\"hlight\" dir=\"rtl\">١١١٠</span> - <span class=\"hlight\" dir=\"rtl\">١١٨٠</span> م .).<br /></font></div>'),
(287704, 'ژان دسوآب', '<span class=\"hlight\">ژان دسوآب .</span> <font color=\"DarkGreen\"><b>[ دُ ]</font></b> (اِخ ) او را لوپاریسید (پدرکش ) گویند. وی شاهزاده ٔ خانواده ٔ اطریش است و بسال <span class=\"hlight\" dir=\"rtl\">١٢٩٠</span> م . متولد شده است اما تاریخ وفات او معلوم نیست .<br /></font></div>'),
(287705, 'ژان دفرانس', '<span class=\"hlight\">ژان دفرانس .</span> <font color=\"DarkGreen\"><b>[ دُ ]</font></b> (اِخ ) دوشس داورلئان دختر لوئی یازدهم پادشاه فرانسه و مارگریت دساووآ (<span class=\"hlight\" dir=\"rtl\">١٤٦٤</span> - <span class=\"hlight\" dir=\"rtl\">١٥٠٥</span> م .).<br /></font></div>'),
(287706, 'ژان دفز', '<span class=\"hlight\">ژان دفز.</span> <font color=\"DarkGreen\"><b>[ دِف ِ ]</font></b> (اِخ ) او را ژان دازیر نیز گویند. مورخ سریانی در قرن ششم میلادی، متولد در حدود سنه ٔ <span class=\"hlight\" dir=\"rtl\">٥٠٦</span> م . وی نخست در شهر آمد راهب بود و امپراطور ژوستی نین و تئودرا او را محترم میداشتند. او از مونوفیزیت ها یعنی از پیروان فلسفه ٔ اتحاد لاهوت و ناسوت در وجود عیسی مسیح بشمار میرفت . در زمان ژوستین دوم به امر وی به زندان افتاد و در حدود سال <span class=\"hlight\" dir=\"rtl\">٥٨٥</span> م . جهان را بدرود گفت . او راست : تاریخ کلیسائی در وقایع عالم که در آن از خلقت تا <span class=\"hlight\" dir=\"rtl\">٥٨٤</span> م . را به رشته ٔ تحریر درآورده است .<br /></font></div>'),
(287707, 'ژان دفلاندر', '<span class=\"hlight\">ژان دفلاندر.</span> <font color=\"DarkGreen\"><b>[ دُ ]</font></b> (اِخ ) زن ژان چهارم کنت دُمونت فرت و دوک برتانی .<br /></font></div>'),
(287708, 'ژان دلاتران', '<span class=\"hlight\">ژان دلاتران .</span> <font color=\"DarkGreen\"><b>[ دُ ]</font></b> (اِخ ) رجوع به لاتران شود.<br /></font></div>'),
(287709, 'ژان دلارشل', '<span class=\"hlight\">ژان دلارشل .</span> <font color=\"DarkGreen\"><b>[ دُ رُ ش ِ ]</font></b> (اِخ ) عالم کلامی فرانسوی که در حدود سنه ٔ <span class=\"hlight\" dir=\"rtl\">١٢٠٥</span> در رشل متولد شد و در <span class=\"hlight\" dir=\"rtl\">١٢٤٥</span> م . به پاریس درگذشت .<br /></font></div>'),
(287710, 'ژان دلاکروا', '<span class=\"hlight\">ژان دلاکروا.</span> <font color=\"DarkGreen\"><b>[ دُ ]</font></b> (اِخ ) (قدیس ) رجوع به کروآ شود.<br /></font></div>'),
(287711, 'ژان دلوکزامبورگ', '<span class=\"hlight\">ژان دلوکزامبورگ .</span> <font color=\"DarkGreen\"><b>[ دُ ]</font></b> (اِخ ) پادشاه بوهم متولد بسال <span class=\"hlight\" dir=\"rtl\">١٢٩٦</span> و متوفی بسال <span class=\"hlight\" dir=\"rtl\">١٣٤٦</span> م .<br /></font></div>'),
(287712, 'ژان دلید', '<span class=\"hlight\">ژان دلید.</span> <font color=\"DarkGreen\"><b>[ دُ ل َ ]</font></b> (اِخ ) او را ژان بوکلس زون نیز گویند. وی رئیس تعمیدنایافتگان مونستر بود و به طرز فجیعی در <span class=\"hlight\" dir=\"rtl\">١٥٣٦</span> م . مثله و کشته گردید.<br /></font></div>'),
(287713, 'ژان دماتا', '<span class=\"hlight\">ژان دماتا.</span> <font color=\"DarkGreen\"><b>[ دُ ]</font></b> (اِخ ) (قدیس ) مؤسس نظام تثلیثیون که ملتزم بازخرید اسیران بودند. مولد او در فکن (<span class=\"hlight\" dir=\"rtl\">١١٦٠</span>-<span class=\"hlight\" dir=\"rtl\">١٢١٣</span> م .) و ذکران وی هشتم فوریه است .<br /></font></div>'),
(287714, 'ژان دمدا', '<span class=\"hlight\">ژان دمدا.</span> <font color=\"DarkGreen\"><b>[ دُ م ِ ]</font></b> (اِخ ) (قدیس ) مولد او مدا نزدیک میلان . در اواخر قرن یازدهم میلادی متولد شد و بسال <span class=\"hlight\" dir=\"rtl\">١١٥٩</span> م . به همان شهر درگذشت و ذکران او بیست وششم سپتامبر است .<br /></font></div>'),
(287715, 'ژان دمن', '<span class=\"hlight\">ژان دمن .</span> <font color=\"DarkGreen\"><b>[ دُ م ُ ]</font></b> (اِخ ) ژان کلوپینل . نویسنده ٔ فرانسوی متولد در حدود <span class=\"hlight\" dir=\"rtl\">١٢٤٠</span> و متوفی پیش از سنه ٔ <span class=\"hlight\" dir=\"rtl\">١٣٠٥</span> م .<br /></font></div>'),
(287716, 'ژان دناوار', '<span class=\"hlight\">ژان دناوار.</span> <font color=\"DarkGreen\"><b>[ دُ ]</font></b> (اِخ ) ملکه ٔ فرانسه و ناوار، زن فیلیپ لوبل (<span class=\"hlight\" dir=\"rtl\">١٢٧٣</span> - <span class=\"hlight\" dir=\"rtl\">١٣٠٥</span> م .).<br /></font></div>'),
(287717, 'ژان دنیول', '<span class=\"hlight\">ژان دنیول .</span> <font color=\"DarkGreen\"><b>[ دُ نی وِ ]</font></b> (اِخ ) پسر بزرگ ژان دوم، ملقب به دُمونت مورنسی .<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(287718, 'ژان دنیکین', '<span class=\"hlight\">ژان دنیکین .</span> <font color=\"DarkGreen\"><b>[ دُ یُن ْ ]</font></b> (اِخ ) مورخ بیزانسی در نیمه ٔ دوم قرن هفتم میلادی . او را تاریخی است که در آن وقایع عالم را از اول خلقت تا اواسط قرن هفتم میلادی به یونانی نوشته و نیز از تاریخ مصر در قرن هفتم و فتح آن کشور بدست عرب بحث کرده است .<br /></font></div>'),
(287719, 'ژان دهته سی', '<span class=\"hlight\">ژان دهته سی .</span> <font color=\"DarkGreen\"><b>[ دُ هَُ ت ِ س ِی ی ]</font></b> (اِخ ) نویسنده ٔ لاتینی در قرن دوازدهم میلادی، راهب هوته سی وُژ .<br /></font></div>'),
(287720, 'ژان دهتویل', '<span class=\"hlight\">ژان دهتویل .</span> <font color=\"DarkGreen\"><b>[ دُ هَُ ت ِ ]</font></b> (اِخ ) یا هانتویل . نام شاعر نورماندی در اواخر قرن دوازدهم میلادی .<br /></font></div>'),
(287721, 'ژان دهلیوود', '<span class=\"hlight\">ژان دهلیوود.</span> <font color=\"DarkGreen\"><b>[ دُ هَُ لی ]</font></b> (اِخ ) در لاتین او را ژن دساکرو-بسکو گویند. نام راهب و ریاضی دان انگلیسی متولد به هولیوود در حدود سنه ٔ <span class=\"hlight\" dir=\"rtl\">١١٩٠</span> و متوفی در حدود سال <span class=\"hlight\" dir=\"rtl\">١٢٥٠</span> م .<br /></font></div>'),
(287722, 'ژان دهم', '<span class=\"hlight\">ژان دهم .</span> <font color=\"DarkGreen\"><b>[ ن ِ دَ هَُ ]</font></b> (اِخ ) پاپ مسیحی از سال <span class=\"hlight\" dir=\"rtl\">٩١٤</span> تا <span class=\"hlight\" dir=\"rtl\">٩٢٨</span> م .<br /></font></div>'),
(287723, 'ژان دوازدهم', '<span class=\"hlight\">ژان دوازدهم .</span> <font color=\"DarkGreen\"><b>[ ن ِ دَ دَ هَُ ]</font></b> (اِخ ) پاپ مسیحی از سال <span class=\"hlight\" dir=\"rtl\">٩٥٥</span> تا <span class=\"hlight\" dir=\"rtl\">٩٦٤</span> م .<br /></font></div>'),
(287724, 'ژان دودین', '<span class=\"hlight\">ژان دودین .</span> (اِخ ) نام نقاش ایتالیائی که در <span class=\"hlight\" dir=\"rtl\">١٤٩٤</span> در اودین متولد شد و در <span class=\"hlight\" dir=\"rtl\">١٥٦٤</span> م . به روم درگذشت .<br /></font></div>'),
(287725, 'ژان دوم', '<span class=\"hlight\">ژان دوم .</span> <font color=\"DarkGreen\"><b>[ ن ِ دُوْ وُ ]</font></b> (اِخ ) کمنن . امپراطور یونان از <span class=\"hlight\" dir=\"rtl\">١١١٨</span> تا <span class=\"hlight\" dir=\"rtl\">١١٤٣</span> م .<br /></font></div>'),
(287726, 'ژان دوم', '<span class=\"hlight\">ژان دوم .</span> <font color=\"DarkGreen\"><b>[ ن ِ دُوْ وُ ]</font></b> (اِخ ) کازیمیر پنجم . پادشاه لهستان پسر سی ژیسموند سوم (<span class=\"hlight\" dir=\"rtl\">١٦٠٩</span>-<span class=\"hlight\" dir=\"rtl\">١٦٧٢</span> م .).<br /></font></div>'),
(287727, 'ژان دوم', '<span class=\"hlight\">ژان دوم .</span> <font color=\"DarkGreen\"><b>[ ن ِ دُوْ وُ ]</font></b> (اِخ ) او را لوبن میگفتند که به اصطلاح زمان وی بمعنی مرد دلیر باشد. از <span class=\"hlight\" dir=\"rtl\">١٣٥٠</span> تا <span class=\"hlight\" dir=\"rtl\">١٣٦٤</span> م . پس از فیلیپ ششم دووالوآ پادشاه فرانسه بود. مولد او قصرِ گه دملوئی نزدیک مانس بوده است .<br /></font></div>'),
(287728, 'ژان دوم', '<span class=\"hlight\">ژان دوم .</span> <font color=\"DarkGreen\"><b>[ ن ِ دُوْ وُ ]</font></b> (اِخ ) پادشاه کاستیل متولد در <span class=\"hlight\" dir=\"rtl\">١٤٠٥</span> و متوفی در <span class=\"hlight\" dir=\"rtl\">١٤٥٤</span> م .<br /></font></div>'),
(287729, 'ژان دوم', '<span class=\"hlight\">ژان دوم .</span> <font color=\"DarkGreen\"><b>[ ن ِ دُوْ وُ ]</font></b> (اِخ ) او را ژانل نیز گویند. ملکه ٔ ناپل (<span class=\"hlight\" dir=\"rtl\">١٣٧١</span>-<span class=\"hlight\" dir=\"rtl\">١٤٣٥</span> م .).<br /></font></div>'),
(287730, 'ژان دوم', '<span class=\"hlight\">ژان دوم .</span> <font color=\"DarkGreen\"><b>[ ن ِ دُوْ وُ ]</font></b> (اِخ ) پاپ مسیحی از سال <span class=\"hlight\" dir=\"rtl\">٥٣٢</span> تا <span class=\"hlight\" dir=\"rtl\">٥٣٥</span> م .<br /></font></div>'),
(287731, 'ژان دوم', '<span class=\"hlight\">ژان دوم .</span> <font color=\"DarkGreen\"><b>[ ن ِ دُوْ وُ]</font></b> (اِخ ) پادشاه آراگن (<span class=\"hlight\" dir=\"rtl\">١٣٩٧</span>-<span class=\"hlight\" dir=\"rtl\">١٤٧٩</span> م .). او را نیز عنوان پادشاهی ناوار بود.<br /></font></div>'),
(287732, 'ژان دوم', '<span class=\"hlight\">ژان دوم .</span> <font color=\"DarkGreen\"><b>[ ن ِ دُوْ وُ ]</font></b> (اِخ ) نام کنت ریشمونت از <span class=\"hlight\" dir=\"rtl\">١٢٣٩</span> تا <span class=\"hlight\" dir=\"rtl\">١٢٨٦</span> م . و دوک برتانی از <span class=\"hlight\" dir=\"rtl\">١٢٨٦</span> تا <span class=\"hlight\" dir=\"rtl\">١٣٠٥</span> م .<br /></font></div>'),
(287733, 'ژان دوم', '<span class=\"hlight\">ژان دوم .</span> <font color=\"DarkGreen\"><b>[ن ِ دُوْ وُ ]</font></b> (اِخ ) پادشاه پرتقال از سال <span class=\"hlight\" dir=\"rtl\">١٤٨١</span> تا <span class=\"hlight\" dir=\"rtl\">١٤٩٥</span> م . (<span class=\"hlight\" dir=\"rtl\">١٤٥٥</span>-<span class=\"hlight\" dir=\"rtl\">١٤٩٥</span> م .).<br /></font></div>'),
(287734, 'ژان دپاری', '<span class=\"hlight\">ژان دپاری .</span> <font color=\"DarkGreen\"><b>[ دُ ]</font></b> (اِخ ) نام شخصی اساطیری پسر یکی از پادشاهان فرانسه که در رهگذار خویش زر و سیم میریخت .<br /></font></div>'),
(287735, 'ژان دپاری', '<span class=\"hlight\">ژان دپاری .</span> <font color=\"DarkGreen\"><b>[ دُ ]</font></b> (اِخ ) یکی از افراد دمینیکن و دکتر دانشگاه پاریس .<br /></font></div>'),
(287736, 'ژان دپانتیور', '<span class=\"hlight\">ژان دپانتیور.</span> <font color=\"DarkGreen\"><b>[ دُ ی ِوْرْ ]</font></b> (اِخ ) برادرزاده ٔ ژان سوم دوک برتانی و زن شارل دوبوآ. <br /></font></div>'),
(287737, 'ژان دپراگ', '<span class=\"hlight\">ژان دپراگ .</span> <font color=\"DarkGreen\"><b>[ دُ پْرا <span class=\"hlight\" dir=\"rtl\">/</span> پ ِ ]</font></b> (اِخ ) نام اسقف الموتز (مراوی ) متولد بسال <span class=\"hlight\" dir=\"rtl\">١٣٦٠</span> و متوفی بسال <span class=\"hlight\" dir=\"rtl\">١٤٣٠</span> م .<br /></font></div>'),
(287738, 'ژان دپرتوگال', '<span class=\"hlight\">ژان دپرتوگال .</span> <font color=\"DarkGreen\"><b>[ دُ پ ُ ]</font></b> (اِخ ) ملکه ٔ کاستیل دختر ادوار پادشاه پرتقال، متولد بسال <span class=\"hlight\" dir=\"rtl\">١٤٣٨</span> و متوفی به <span class=\"hlight\" dir=\"rtl\">١٤٧٥</span> م .<br /></font></div>'),
(287739, 'ژان دپیفانی', '<span class=\"hlight\">ژان دپیفانی .</span> <font color=\"DarkGreen\"><b>[ دِ ]</font></b> (اِخ ) مورخ بیزانسی در نیمه ٔ دوم قرن ششم میلادی . او تاریخی در حوادث سال <span class=\"hlight\" dir=\"rtl\">٥٧١</span> - <span class=\"hlight\" dir=\"rtl\">٥٧٢</span> تا حوادث سال <span class=\"hlight\" dir=\"rtl\">٥٩٢</span> - <span class=\"hlight\" dir=\"rtl\">٥٩٣</span> م . گرد آورده ودر آن از جنگهای روم شرقی با ایران بحث کرده است .<br /></font></div>'),
(287740, 'ژان دکاستیل', '<span class=\"hlight\">ژان دکاستیل .</span> <font color=\"DarkGreen\"><b>[ دُ ]</font></b> (اِخ ) دختر ژان پرتقال . او ملقبه به لابلترانژا است (<span class=\"hlight\" dir=\"rtl\">١٤٦٢</span> - <span class=\"hlight\" dir=\"rtl\">١٥٣٠</span> م .).<br /></font></div>'),
(287741, 'ژان دکاپادس', '<span class=\"hlight\">ژان دکاپادس .</span> <font color=\"DarkGreen\"><b>[ دُ دُ ]</font></b> (اِخ ) نام رئیس دادگاه ژوستی نی ین . وی مردی باهوش و جاه طلب و حریص بود و امپراطور او را گرامی میداشت . و از جهت سؤرفتار خود منفور مردمان بود.<br /></font></div>'),
(287742, 'ژان دکاپو', '<span class=\"hlight\">ژان دکاپو.</span> <font color=\"DarkGreen\"><b>[ دُ ]</font></b> (اِخ ) نام مترجم ایطالیائی است که او را به زبان لاتین ژنس دکاپوا میگفتند.وی در قرن سیزدهم میلادی میزیست و در بدایت حال یهودی بود و سپس به دین مسیح درآمد. اثر مهم او ترجمه ٔ کتاب کلیله و دمنه است که آن را از ترجمه ٔ عبری ربان جوعل به زبان لاتین درآورد. ربان جوعل آن کتاب را از متن سانسکریت به زبان عبری ترجمه کرده بود. ترجمه ٔلاتینی مزبور در حدود سال <span class=\"hlight\" dir=\"rtl\">١٤٠٨</span> م . بطبع رسیده است .<br /></font></div>'),
(287743, 'ژان دگیسکالا', '<span class=\"hlight\">ژان دگیسکالا.</span> <font color=\"DarkGreen\"><b>[ دُ ]</font></b> (اِخ ) نام یکی از شجعان یهود متوفی در <span class=\"hlight\" dir=\"rtl\">٧٥</span> م .<br /></font></div>'),
(287744, 'ژان سان تر', '<span class=\"hlight\">ژان سان تر.</span> <font color=\"DarkGreen\"><b>[ ت ِ ]</font></b> (اِخ ) چهارمین پسر هانری دوم و اِله اونر داکیتن . او به استظهار فیلیپ اگوست پادشاه فرانسه درشورشی که بر ضد پدر او برپا شده بود شرکت کرد و بعداز مرگ برادر خود ریشارد کُردُلیُن (ریشارد شیردل ) برادرزاده ٔ وی آرتور دوبرتانی را برای به دست آوردن سلطنت به قتل رسانید (<span class=\"hlight\" dir=\"rtl\">١٢٠٢</span> م .) و از سال <span class=\"hlight\" dir=\"rtl\">١١٩٩</span> تا <span class=\"hlight\" dir=\"rtl\">١٢١٦</span> م . در انگلستان پادشاهی کرد (<span class=\"hlight\" dir=\"rtl\">١١٦٧</span> - <span class=\"hlight\" dir=\"rtl\">١٢١٦</span> م .).<br /></font></div>'),
(287745, 'ژان سان پور', '<span class=\"hlight\">ژان سان پور.</span> <font color=\"DarkGreen\"><b>[ سام ْ پُرْ ]</font></b> (اِخ ) دوک دُبورگنی مولدبسال <span class=\"hlight\" dir=\"rtl\">١٣٧١</span> در دیژن پسر فیلیپ لوهاردی و نوه ٔ ژان لوبون مقتول در <span class=\"hlight\" dir=\"rtl\">١٤١٩</span> م .<br /></font></div>'),
(287746, 'ژان سوم', '<span class=\"hlight\">ژان سوم .</span> <font color=\"DarkGreen\"><b>[ ن ِ س ِوْ وُ ]</font></b> (اِخ ) واتاتزس . امپراطور یونان . وی از مردم نیسه بود و از سال <span class=\"hlight\" dir=\"rtl\">١٢٢٢</span> تا <span class=\"hlight\" dir=\"rtl\">١٢٥٤</span> م . سلطنت راند.<br /></font></div>'),
(287747, 'ژان سوم', '<span class=\"hlight\">ژان سوم .</span> <font color=\"DarkGreen\"><b>[ ن ِ س ِوْ وُ ]</font></b> (اِخ ) لوبُن . دوک دُبرتانی از سال <span class=\"hlight\" dir=\"rtl\">١٣١٢</span> تا <span class=\"hlight\" dir=\"rtl\">١٣٤١</span> م .<br /></font></div>'),
(287748, 'ژان سوم', '<span class=\"hlight\">ژان سوم .</span> <font color=\"DarkGreen\"><b>[ ن ِ س ِوْ وُ ]</font></b> (اِخ ) پادشاه پرتقال (<span class=\"hlight\" dir=\"rtl\">١٥٢١</span> - <span class=\"hlight\" dir=\"rtl\">١٥٥٧</span> م .). متولد بسال <span class=\"hlight\" dir=\"rtl\">١٥٠٢</span> م .<br /></font></div>'),
(287749, 'ژان سوم', '<span class=\"hlight\">ژان سوم .</span> <font color=\"DarkGreen\"><b>[ ن ِ س ِوْ وُ ]</font></b> (اِخ ) پادشاه سوئد پسرگوستاو وازا متولد در قصر استژبرگ و متوفی در استکهلم (<span class=\"hlight\" dir=\"rtl\">١٥٣٧</span> - <span class=\"hlight\" dir=\"rtl\">١٥٩٢</span> م .).<br /></font></div>'),
(287750, 'ژان سوم', '<span class=\"hlight\">ژان سوم .</span> <font color=\"DarkGreen\"><b>[ ن ِ س ِوْ وُ ]</font></b> (اِخ ) وی نخست امارت آلبره داشت و سپس پادشاه ناوار شد و در <span class=\"hlight\" dir=\"rtl\">١٤٨٤</span> م . کاترین دوفوآ دخترعم لوئی دوازدهم را به زنی گرفت . وفات او بسال <span class=\"hlight\" dir=\"rtl\">١٥١٦</span> م . است .<br /></font></div>'),
(287751, 'ژان سوم', '<span class=\"hlight\">ژان سوم .</span> <font color=\"DarkGreen\"><b>[ ن ِ س ِوْ وُ ]</font></b> (اِخ ) نام پاپ مسیحی از سال <span class=\"hlight\" dir=\"rtl\">٥٥٩</span> تا <span class=\"hlight\" dir=\"rtl\">٥٧٣</span> م .<br /></font></div>'),
(287752, 'ژان سیزدهم', '<span class=\"hlight\">ژان سیزدهم .</span> <font color=\"DarkGreen\"><b>[ ن ِ دَ هَُ ]</font></b> (اِخ ) پاپ از سال <span class=\"hlight\" dir=\"rtl\">٩٦٥</span> تا <span class=\"hlight\" dir=\"rtl\">٩٧٢</span> م .<br /></font></div>'),
(287753, 'ژان سیمور', '<span class=\"hlight\">ژان سیمور.</span> (اِخ ) ملکه ٔ انگلستان . سومین زن هانری هشتم، تولد او در حدود سال <span class=\"hlight\" dir=\"rtl\">١٥٠٩</span> و وفات در <span class=\"hlight\" dir=\"rtl\">١٥٣٧</span> م .<br /></font></div>'),
(287754, 'ژان شانزدهم', '<span class=\"hlight\">ژان شانزدهم .</span> <font color=\"DarkGreen\"><b>[ ن ِ شا دَ هَُ ]</font></b> (اِخ ) پاپ مسیحیان از سال <span class=\"hlight\" dir=\"rtl\">٩٨٥</span> تا <span class=\"hlight\" dir=\"rtl\">٩٩٦</span> م .<br /></font></div>'),
(287755, 'ژان ششم', '<span class=\"hlight\">ژان ششم .</span> <font color=\"DarkGreen\"><b>[ ن ِ ش ِش ُ ]</font></b> (اِخ ) لوساژ . دوک برتانی متوفی در <span class=\"hlight\" dir=\"rtl\">١٤٤٢</span> م .<br /></font></div>'),
(287756, 'ژان ششم', '<span class=\"hlight\">ژان ششم .</span> <font color=\"DarkGreen\"><b>[ ن ِ ش ِ ش ُ ]</font></b> (اِخ ) کانتاکوزن . امپراطور بیزانس از سال <span class=\"hlight\" dir=\"rtl\">١٣٤١</span> تا <span class=\"hlight\" dir=\"rtl\">١٣٥٥</span> م .<br /></font></div>'),
(287757, 'ژان ششم', '<span class=\"hlight\">ژان ششم .</span> <font color=\"DarkGreen\"><b>[ن ِ ش ِ ش ُ ]</font></b> (اِخ ) پاپ مسیحی از سال <span class=\"hlight\" dir=\"rtl\">٧٠١</span> تا <span class=\"hlight\" dir=\"rtl\">٧٠٥</span> م .<br /></font></div>'),
(287758, 'ژان ششم', '<span class=\"hlight\">ژان ششم .</span> <font color=\"DarkGreen\"><b>[ ن ِ ش ِ ش ُ ]</font></b> (اِخ ) ماری ژزف لوئی . پادشاه پرتقال . وی نخست در زمان جنون مادر، نایب السلطنه ٔ پرتقال بود و در سال <span class=\"hlight\" dir=\"rtl\">١٨٠٧</span> م . کشور وی به دست فرانسویان افتاد و پس از آن واقعه به برزیل رفت و در <span class=\"hlight\" dir=\"rtl\">١٨٢١</span> بازگشت و اساس حکومت مشروطه را در پرتقال بنا نهاد (<span class=\"hlight\" dir=\"rtl\">١٧٦٩</span> - <span class=\"hlight\" dir=\"rtl\">١٨٢٦</span> م .).<br /></font></div>'),
(287759, 'ژان فردریک اول', '<span class=\"hlight\">ژان فردریک اول .</span> <font color=\"DarkGreen\"><b>[ فْرِ <span class=\"hlight\" dir=\"rtl\">/</span> ف ِ رِ دِ ک ِ اَوْ وَ ]</font></b> (اِخ ) لومانیانیم . الکتر ساکس متولد بسال <span class=\"hlight\" dir=\"rtl\">١٥٠٣</span> و متوفی به <span class=\"hlight\" dir=\"rtl\">١٥٥٤</span> م .<br /></font></div>'),
(287760, 'ژان فردریک دوم', '<span class=\"hlight\">ژان فردریک دوم .</span> <font color=\"DarkGreen\"><b>[ فْرِ <span class=\"hlight\" dir=\"rtl\">/</span> ف ِ رِ دِ ک ِ دُوْ وُ ]</font></b> (اِخ ) دوک ساکس متولد بسال <span class=\"hlight\" dir=\"rtl\">١٥٢٩</span> و متوفی بسال <span class=\"hlight\" dir=\"rtl\">١٥٩٥</span> م .<br /></font></div>'),
(287761, 'ژان فیلوپونس', '<span class=\"hlight\">ژان فیلوپونس .</span> <font color=\"DarkGreen\"><b>[ ل ُ پ ُن ُ ]</font></b> (اِخ ) عالم صرف و نحو و فیلسوف یونانی در قرن ششم میلادی به اسکندریه .<br /></font></div>'),
(287762, 'ژان لافل', '<span class=\"hlight\">ژان لافل .</span> <font color=\"DarkGreen\"><b>[ ف ُ ]</font></b> (اِخ ) ملکه ٔ کاستیل از <span class=\"hlight\" dir=\"rtl\">١٥٠٤</span> تا <span class=\"hlight\" dir=\"rtl\">١٥٥٥</span> م . متولد در طُلیطلة (<span class=\"hlight\" dir=\"rtl\">١٤٧٩</span> م .) و متوفی در تردزیلاس (<span class=\"hlight\" dir=\"rtl\">١٥٥٥</span> م .).<br /></font></div>'),
(287763, 'ژان لوانژلیست', '<span class=\"hlight\">ژان لوانژلیست .</span> <font color=\"DarkGreen\"><b>[ ل ِ ژِ ]</font></b> (اِخ ) (قدیس ) یوحنّا القدیس . نام یکی از دوازده حواری عیسی و شاگرد محبوب آن حضرت . در جلیله ٔ بیت سعید تولد یافت و از جوانی به عیسی مسیح پیوست و ظاهراً پیش از آن درک محضر یحیی تعمیددهنده کرده بود و از شاگردان او بشمار میرفت . وی نویسنده ٔ انجیل یوحنّا است . رجوع به یوحنّا شود.<br /></font></div>'),
(287764, 'ژان لوسیلانسیو', '<span class=\"hlight\">ژان لوسیلانسیو.</span> <font color=\"DarkGreen\"><b>[ ل ُ لا ی ُ ]</font></b> (اِخ ) (قدیس ) اسقف کلنی متولد به نیکوپولیس (ارمنستان ) در حدود سال <span class=\"hlight\" dir=\"rtl\">٤٥٤</span> و متوفی به سال <span class=\"hlight\" dir=\"rtl\">٥٥٨</span> م .<br /></font></div>'),
(287765, 'ژان لومنیه', '<span class=\"hlight\">ژان لومنیه .</span> <font color=\"DarkGreen\"><b>[ م ُ ی ِ ]</font></b> (اِخ ) (قدیس ) بطریق اسکندریه . مولد او قبرس و وفاتش بسال <span class=\"hlight\" dir=\"rtl\">٦١٧</span> م . بوده است .<br /></font></div>'),
(287766, 'ژان لوکنستانت', '<span class=\"hlight\">ژان لوکنستانت .</span> <font color=\"DarkGreen\"><b>[ ل ُ ک ُ ]</font></b> (اِخ ) الکتر ساکس (<span class=\"hlight\" dir=\"rtl\">١٤٦٨</span> - <span class=\"hlight\" dir=\"rtl\">١٥٣٢</span> م .).<br /></font></div>'),
(287767, 'ژان لژنر', '<span class=\"hlight\">ژان لژنر.</span> <font color=\"DarkGreen\"><b>[ ل ُ ژُ ن ُ ]</font></b> (اِخ ) بطریق قسطنطنیه (<span class=\"hlight\" dir=\"rtl\">٥٨٢</span> - <span class=\"hlight\" dir=\"rtl\">٥٩٥</span> م .). این بطریق را در امپراطور موریس نفوذ کلمه بسیار بود.<br /></font></div>'),
(287768, 'ژان مامی گنین', '<span class=\"hlight\">ژان مامی گنین .</span> <font color=\"DarkGreen\"><b>[ گ ُ ی َ ]</font></b> (اِخ ) مورخی ارمنی در قرن هفتم میلادی . وی سالنامه های مورخ دیگری را بنام زِنوب گِلاگی دنبال کرده است، از این نظر کتاب او هم به تاریخ دارون که نام نوشته های مورخ مزبور است موسوم میباشد. وی در کتاب خود اشاراتی به دوره ٔ ساسانی و تاریخ آن سلسله میکند ولی نوشته های او چندان مورد توجه و اعتماد نیست زیرا گذشته از اینکه دارای اشتباهات بسیاری است کاتبان قرون بعد مطالبی در کتاب او داخل کرده اند. (ایران باستان ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٩٧</span> و ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٦٠٣</span>).<br /></font></div>'),
(287769, 'ژان ماین', '<span class=\"hlight\">ژان ماین .</span> <font color=\"DarkGreen\"><b>[ ی ِ ]</font></b> (اِخ ) نام جزیره ٔ آتشفشانی قطبی در اقیانوس منجمد شمالی، دارای <span class=\"hlight\" dir=\"rtl\">٥٥٠</span> کیلومتر مساحت . آن را هلندیها در اوایل قرن هفدهم کشف کردند.<br /></font></div>'),
(287770, 'ژان نهم', '<span class=\"hlight\">ژان نهم .</span> <font color=\"DarkGreen\"><b>[ ن ِ ن ُ هَُ ]</font></b> (اِخ ) پاپ مسیحی از سال <span class=\"hlight\" dir=\"rtl\">٨٩٨</span> تا <span class=\"hlight\" dir=\"rtl\">٩٠٠</span> م .<br /></font></div>'),
(287771, 'ژان نوزدهم', '<span class=\"hlight\">ژان نوزدهم .</span> <font color=\"DarkGreen\"><b>[ ن ِدَ هَُ ]</font></b> (اِخ ) پاپ مسیحی از سال <span class=\"hlight\" dir=\"rtl\">١٠٢٤</span> تا <span class=\"hlight\" dir=\"rtl\">١٠٣٣</span> م .<br /></font></div>'),
(287772, 'ژان هانریکز', '<span class=\"hlight\">ژان هانریکز.</span> <font color=\"DarkGreen\"><b>[ک ِ ]</font></b> (اِخ ) ملکه ٔ ناوار و آراگُن . مولد حدود سال <span class=\"hlight\" dir=\"rtl\">١٤٢٥</span> و وفات بسال <span class=\"hlight\" dir=\"rtl\">١٤٦٨</span> م .<br /></font></div>'),
(287773, 'ژان هجدهم', '<span class=\"hlight\">ژان هجدهم .</span> <font color=\"DarkGreen\"><b>[ ن ِهَِ دَ هَُ ]</font></b> (اِخ ) پاپ مسیحی متوفی بسال <span class=\"hlight\" dir=\"rtl\">١٠٠٩</span> م .<br /></font></div>'),
(287774, 'ژان هشتم', '<span class=\"hlight\">ژان هشتم .</span> <font color=\"DarkGreen\"><b>[ ن ِ هََ ت ُ ]</font></b> (اِخ )پالئولگ . امپراطور مشرق (<span class=\"hlight\" dir=\"rtl\">١٤٢٥</span> - <span class=\"hlight\" dir=\"rtl\">١٤٤٨</span> م .)، متولد بسال <span class=\"hlight\" dir=\"rtl\">١٣٩٠</span> م . پسر مانوئل .<br /></font></div>'),
(287775, 'ژان هشتم', '<span class=\"hlight\">ژان هشتم .</span> <font color=\"DarkGreen\"><b>[ ن ِ هََ ت ُ ]</font></b> (اِخ )پاپ مسیحی . مولد حدود سال <span class=\"hlight\" dir=\"rtl\">٨٢٠</span> و وفات بسال <span class=\"hlight\" dir=\"rtl\">٨٨٢</span> م .<br /></font></div>'),
(287776, 'ژان هفتم', '<span class=\"hlight\">ژان هفتم .</span> <font color=\"DarkGreen\"><b>[ ن ِهََ ت ُ ]</font></b> (اِخ ) امپراطور بیزانس . مولد بسال <span class=\"hlight\" dir=\"rtl\">١٣٦٠</span> و وفات بسال <span class=\"hlight\" dir=\"rtl\">١٤١٠</span> م . پسر آندرُنیک و نبسه ٔ ژان پنجم .<br /></font></div>'),
(287777, 'ژان هفتم', '<span class=\"hlight\">ژان هفتم .</span> <font color=\"DarkGreen\"><b>[ ن ِ هََ ت ُ ]</font></b> (اِخ ) پاپ مسیحی از سال <span class=\"hlight\" dir=\"rtl\">٧٠٥</span> تا <span class=\"hlight\" dir=\"rtl\">٧٠٧</span> م .<br /></font></div>'),
(287778, 'ژان هفدهم', '<span class=\"hlight\">ژان هفدهم .</span> <font color=\"DarkGreen\"><b>[ ن ِ هَِ دَ هَُ]</font></b> (اِخ ) مردی یونانی فیلاگات نام . وی از مخالفین پاپ بشمار میرفت و بسال <span class=\"hlight\" dir=\"rtl\">٩٩٧</span> م . دعوی پاپی کرد و خویشتن را ژان هفدهم خواند و سرانجام او را مُثله و محبوس کردند و در زندان درگذشت .<br /></font></div>'),
(287779, 'ژان هفدهم', '<span class=\"hlight\">ژان هفدهم .</span> <font color=\"DarkGreen\"><b>[ ن ِهَِ دَ هَُ ]</font></b> (اِخ ) پاپ مسیحی . وفات بسال <span class=\"hlight\" dir=\"rtl\">١٠٠٣</span> م .<br /></font></div>'),
(287780, 'ژان هوس', '<span class=\"hlight\">ژان هوس .</span> (اِخ ) نام یکی از روحانیون چک مولد هوزی نتز (بوهم ). وی در باب تعلیمات ویکلیف مبنی بر اصلاح مذهب مسیح و اعتراض بر پاره ای از پاپها خطابه هائی بسال <span class=\"hlight\" dir=\"rtl\">١٣٩٨</span> م . در دارالفنون پراگ انشاد کردو پیروانی بسیار یافت، بدین مناسبت پاپ به تشکیل شورائی در شهر کنستانس فرمان داد و اعضاء این شوری که از سال <span class=\"hlight\" dir=\"rtl\">١٤١٤</span> تا <span class=\"hlight\" dir=\"rtl\">١٤١٨</span> م . طول کشید ژان هوس را به محاکمه دعوت کردند و در سال <span class=\"hlight\" dir=\"rtl\">١٤١٥</span> زنده بسوختند و برای دفع پیروان او حکم جهاد دادند. نیز رجوع به هوس شود.<br /></font></div>'),
(287781, 'ژان هیرکانوس', '<span class=\"hlight\">ژان هیرکانوس .</span> (اِخ ) نام سردار لشکری از یهود که بیاری آنتیوخُس سلوکی به جنگ فرهاد دوم اشکانی شتافت . (ایران باستان ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٢٢٣٨</span>).<br /></font></div>'),
(287782, 'ژان پانزدهم', '<span class=\"hlight\">ژان پانزدهم .</span> <font color=\"DarkGreen\"><b>[ ن ِ دَ هَُ ]</font></b> (اِخ ) پاپ مسیحی از سال <span class=\"hlight\" dir=\"rtl\">٩٨٥</span> تا <span class=\"hlight\" dir=\"rtl\">٩٩٦</span> م .<br /></font></div>'),
(287783, 'ژان پلانتاژنه', '<span class=\"hlight\">ژان پلانتاژنه .</span><font color=\"DarkGreen\"><b>[ ن ِ پ ِ ژِ ن ِ ]</font></b> (اِخ ) نام ملکه ٔ سیسیل و کنتس تولوز متوفی در سال <span class=\"hlight\" dir=\"rtl\">١٢٠٠</span> م .<br /></font></div>'),
(287784, 'ژان پنجم', '<span class=\"hlight\">ژان پنجم .</span> <font color=\"DarkGreen\"><b>[ ن ِ پ َ ج ُ ]</font></b> (اِخ ) ل ُویان . نام دوک برتانی متولد در <span class=\"hlight\" dir=\"rtl\">١٣٣٨</span> و متوفی در <span class=\"hlight\" dir=\"rtl\">١٣٩٩</span> م .<br /></font></div>'),
(287785, 'ژان پنجم', '<span class=\"hlight\">ژان پنجم .</span> <font color=\"DarkGreen\"><b>[ ن ِ پ َ ج ُ ]</font></b> (اِخ ) پاله الگ . نام امپراطور بیزانس از <span class=\"hlight\" dir=\"rtl\">١٣٤١</span> تا <span class=\"hlight\" dir=\"rtl\">١٣٧٦</span> و از <span class=\"hlight\" dir=\"rtl\">١٣٧٩</span> تا <span class=\"hlight\" dir=\"rtl\">١٣٩٠</span> م .<br /></font></div>'),
(287786, 'ژان پنجم', '<span class=\"hlight\">ژان پنجم .</span> <font color=\"DarkGreen\"><b>[ن ِ پ َ ج ُ ]</font></b> (اِخ ) پاپ مسیحی از سال <span class=\"hlight\" dir=\"rtl\">٦٨٥</span> تا <span class=\"hlight\" dir=\"rtl\">٦٨٦</span> م .<br /></font></div>'),
(287787, 'ژان پنجم', '<span class=\"hlight\">ژان پنجم .</span><font color=\"DarkGreen\"><b>[ ن ِ پ َ ج ُ ]</font></b> (اِخ ) پادشاه پرتقال از <span class=\"hlight\" dir=\"rtl\">١٧٠٧</span> تا <span class=\"hlight\" dir=\"rtl\">١٧٥٠</span> م . متولد در لیسبن بسال <span class=\"hlight\" dir=\"rtl\">١٦٨٩</span> و متوفی بسال <span class=\"hlight\" dir=\"rtl\">١٧٥٠</span> م .<br /></font></div>'),
(287788, 'ژان چهاردهم', '<span class=\"hlight\">ژان چهاردهم .</span> <font color=\"DarkGreen\"><b>[ ن ِ چ َ دَ هَُ ]</font></b> (اِخ ) پاپ مسیحی از سال <span class=\"hlight\" dir=\"rtl\">٩٨٣</span> تا <span class=\"hlight\" dir=\"rtl\">٩٨٤</span> م .<br /></font></div>'),
(287789, 'ژان چهارم', '<span class=\"hlight\">ژان چهارم .</span> <font color=\"DarkGreen\"><b>[ ن ِ چ َ رُ]</font></b> (اِخ ) لاسکاریس . امپراطور یونان از <span class=\"hlight\" dir=\"rtl\">١٢٥٨</span> تا <span class=\"hlight\" dir=\"rtl\">١٢٥٩</span> م . وی از مردم نیسه بود.<br /></font></div>'),
(287790, 'ژان چهارم', '<span class=\"hlight\">ژان چهارم .</span> <font color=\"DarkGreen\"><b>[ ن ِ چ َ رُ ]</font></b> (اِخ ) دومونت فر . دوک برتانی . وی پس از مرگ برادر خود ژان سوم در سال <span class=\"hlight\" dir=\"rtl\">١٣٤١</span> م . به دوکی نشست و در <span class=\"hlight\" dir=\"rtl\">١٣٤٥</span> وفات یافت .<br /></font></div>'),
(287791, 'ژان ژاک روسو', '<span class=\"hlight\">ژان ژاک روسو.</span> <font color=\"DarkGreen\"><b>[ س ُ ]</font></b> (اِخ ) رجوع به روسو شود.<br /></font></div>'),
(287792, 'ژان ژرژ اول', '<span class=\"hlight\">ژان ژرژ اول .</span> <font color=\"DarkGreen\"><b>[ ژُ ژِ اَوْ وَ ]</font></b> (اِخ ) الکتور ساکس . متولد بسال <span class=\"hlight\" dir=\"rtl\">١٥٨٥</span> و متوفی بسال <span class=\"hlight\" dir=\"rtl\">١٦٥٦</span> م .<br /></font></div>'),
(287793, 'ژان ژرژ دوم', '<span class=\"hlight\">ژان ژرژ دوم .</span> <font color=\"DarkGreen\"><b>[ ژُ ژِ دُوْ وُ ]</font></b> (اِخ ) الکتور ساکس . متولد بسال <span class=\"hlight\" dir=\"rtl\">١٦١٣</span> و متوفی بسال <span class=\"hlight\" dir=\"rtl\">١٦٨٠</span> م .<br /></font></div>'),
(287794, 'ژان ژرژ سوم', '<span class=\"hlight\">ژان ژرژ سوم .</span> <font color=\"DarkGreen\"><b>[ژُ ژِ س ِوْ وُ ]</font></b> (اِخ ) الکتور ساکس . متولد بسال <span class=\"hlight\" dir=\"rtl\">١٦٤٧</span> و متوفی بسال <span class=\"hlight\" dir=\"rtl\">١٦٩١</span> م .<br /></font></div>'),
(287795, 'ژان ژرژ چهارم', '<span class=\"hlight\">ژان ژرژ چهارم .</span><font color=\"DarkGreen\"><b>[ ژُ ژِ چ َ رُ ]</font></b> (اِخ ) الکتور ساکس . متولد بسال <span class=\"hlight\" dir=\"rtl\">١٦٦٨</span> و متوفی بسال <span class=\"hlight\" dir=\"rtl\">١٦٩٤</span> م .<br /></font></div>'),
(287796, 'ژان کازیمیر', '<span class=\"hlight\">ژان کازیمیر.</span> (اِخ ) کنت پالاتن . پسر الکترفردریک سوم متولد بسال <span class=\"hlight\" dir=\"rtl\">١٥٤٣</span> و متوفی بسال <span class=\"hlight\" dir=\"rtl\">١٥٩٢</span> م .<br /></font></div>'),
(287797, 'ژان کریزستم', '<span class=\"hlight\">ژان کریزستم .</span> <font color=\"DarkGreen\"><b>[ کْری <span class=\"hlight\" dir=\"rtl\">/</span> ک ِ زُ ت ُ ]</font></b> (اِخ ) (بوش دُر) (قدیس ) یکی از آباء کلیسا و بطریق قسطنطنیه (<span class=\"hlight\" dir=\"rtl\">٣٤٧</span> - <span class=\"hlight\" dir=\"rtl\">٤٠٧</span> م .). وی به شکنجه وجفای امپراطریس اودکسی گرفتار گشت . ژان به فصاحت و بلاغت مشتهر و مواعظ وی مورد اعجاب و تحسین است . ذکران وی در <span class=\"hlight\" dir=\"rtl\">٢٧</span> ژانویه است .<br /></font></div>'),
(287798, 'ژان گالبرت', '<span class=\"hlight\">ژان گالبرت .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) یکی از قدّیسین در فلورانس . وی بسال <span class=\"hlight\" dir=\"rtl\">٩٩٩</span> تولد یافت و بسال <span class=\"hlight\" dir=\"rtl\">١٠٧٣</span> م . رحلت کرد. ذکران وی روز دوازدهم ژوئیه است .<br /></font></div>'),
(287799, 'ژان یازدهم', '<span class=\"hlight\">ژان یازدهم .</span> <font color=\"DarkGreen\"><b>[ ن ِ دَ هَُ ]</font></b> (اِخ ) پاپ مسیحی متولد بسال <span class=\"hlight\" dir=\"rtl\">٩٠٦</span> و متوفی بسال <span class=\"hlight\" dir=\"rtl\">٩٣٦</span> م . به رُم .<br /></font></div>'),
(287800, 'ژانتس', '<span class=\"hlight\">ژانتس .</span> (اِخ ) فردریک . نام نویسنده ٔ سیاسی و عالم سیاست پروسی (<span class=\"hlight\" dir=\"rtl\">١٧٦٤</span>-<span class=\"hlight\" dir=\"rtl\">١٨٣٢</span> م .).<br /></font></div>'),
(287801, 'ژانتی یی', '<span class=\"hlight\">ژانتی یی .</span> (اِخ ) مرکز تجارتی لاسن در ایالت سو در ساحل رود بیور، دارای <span class=\"hlight\" dir=\"rtl\">١٥٦٢٣</span> تن سکنه و راه آهن . در آنجا دباغخانه های بسیار است .<br /></font></div>'),
(287802, 'ژاندارم', '<span class=\"hlight\">ژاندارم .</span> (فرانسوی، اِ) کلمه ای است فرانسوی مستعمل در زبان فارسی اخیر که در اصطلاح امروز بمعنی فردی از امنیه و پلیس خارج شهر است .<br /></font></div>'),
(287803, 'ژاندارمری', '<span class=\"hlight\">ژاندارمری .</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (فرانسوی، اِ) کلمه ای است فرانسوی که در زبان فارسی اخیر بمعنی اداره ٔ امور وظایف ژاندارمها بکار میرود.<br /></font></div>'),
(287804, 'ژاندارک', '<span class=\"hlight\">ژاندارک .</span> (اِخ ) (قدّیسه ) او را دارک یا آرک و دوشیزه ٔ ارلئانی نیزنامند و ژان اسم اوست . وی قهرمان ملی فرانسه است و بسال <span class=\"hlight\" dir=\"rtl\">١٤١٢</span> م . در دمرمی پای به عرصه ٔ وجود گذارد. زنی بغایت دیندار و متقی و اهل مکاشفه و مراقبه و مدعی نوعی وحی بود و میگفت که الهاماتی غیبی از جانب قدیس میشل و کاترین به او میشود که وی را به قیام برای نجات فرانسه از سلطه ٔ انگلیسیان میخوانند. وی به وساطت ربر دوبدریکور کاپیتن دوکولر در هنگام محاصره ٔارلئان (<span class=\"hlight\" dir=\"rtl\">١٤٢٩</span> م .) در شینن بین درباریان به حضور شارل هفتم پادشاه فرانسه رسید و او را به اصرار بسیار راضی کرد که وی را بر گروهی از لشکریان خود سردار کند. ژاندارک با این عده ٔ قلیل انگلیسیان را مجبور به ترک محاصره ٔ ارلئان کرد و در جائی بنام پاتی بر ایشان ظفر یافت . و در ریمس تشریفات تاجگذاری شارل هفتم را بجای آورد. سپس قصد تسخیر پاریس کرد ولی بعد از مجروح شدن در نبردی که به دروازه ٔ سن هنره روی داد به امر پادشاه از این قصد بازایستاد. ظاهراً وی بعلت خیانت بعضی از حواشی و اطرافیان خود در ظاهر شهر کمپین به دست بورگینیون ها افتاد و سپس کنت لوکزامبورگ او را به انگلیسیان فروخت و آنان وی را در محکمه ٔ کلیسائی که بریاست اسقف بوه بنام پیر کوشن تشکیل شد محاکمه کردند. ژاندارک با کمال سادگی و شجاعت و جسارت از خود دفاع کرد. سرانجام محکمه او را تکفیر و به الحاد و ارتداد و فساد عقیدت متهم و به زنده سوختن محکوم ساخت . او را در میدان ویومارشه واقع در روئن زنده بسوختند (<span class=\"hlight\" dir=\"rtl\">١٤٣١</span> م .).<br /></font></div>'),
(287805, 'ژاندره', '<span class=\"hlight\">ژاندره .</span> <font color=\"DarkGreen\"><b>[ رِ ]</font></b> (اِخ ) کرسی دهستان ژورا از ایالت دُل دارای راه آهن و قریب <span class=\"hlight\" dir=\"rtl\">٣٨٧</span> تن سکنه .<br /></font></div>'),
(287806, 'ژانرن', '<span class=\"hlight\">ژانرن .</span> <font color=\"DarkGreen\"><b>[ رُ ]</font></b> (اِخ ) فیلیپ اگوست . نقاش فرانسوی (<span class=\"hlight\" dir=\"rtl\">١٨١٠</span> - <span class=\"hlight\" dir=\"rtl\">١٨٧٧</span> م .).<br /></font></div>'),
(287807, 'ژانزه', '<span class=\"hlight\">ژانزه .</span> <font color=\"DarkGreen\"><b>[ زِ ]</font></b> (اِخ ) نام کرسی بخش ایل -اِ-ویلن از شهرستان رن دارای قریب <span class=\"hlight\" dir=\"rtl\">٤٠٨٧</span> تن سکنه و راه آهن از آن گذرد.<br /></font></div>'),
(287808, 'ژانسن', '<span class=\"hlight\">ژانسن .</span> <font color=\"DarkGreen\"><b>[ س ِ ]</font></b> (اِخ ) ژول . عالم طبیعی و ستاره شناس فرانسوی (<span class=\"hlight\" dir=\"rtl\">١٨٢٤</span> - <span class=\"hlight\" dir=\"rtl\">١٩٠٧</span> م .).<br /></font></div>'),
(287809, 'ژانسن', '<span class=\"hlight\">ژانسن .</span> <font color=\"DarkGreen\"><b>[ س ِ ]</font></b> (اِخ ) ژان . مورخ کاتولیک آلمانی . مولد وی کسانتن و مؤلف تاریخ ملت آلمان است (<span class=\"hlight\" dir=\"rtl\">١٨٢٩</span> - <span class=\"hlight\" dir=\"rtl\">١٨٩١</span> م .).<br /></font></div>'),
(287810, 'ژانسن', '<span class=\"hlight\">ژانسن .</span> <font color=\"DarkGreen\"><b>[ س ِ ]</font></b>(اِخ ) آبراهام . نقاش فلاماندی (<span class=\"hlight\" dir=\"rtl\">١٥٧٥</span> - <span class=\"hlight\" dir=\"rtl\">١٦٣٢</span> م .).<br /></font></div>'),
(287811, 'ژانسنیوس', '<span class=\"hlight\">ژانسنیوس .</span> <font color=\"DarkGreen\"><b>[ س ِ ]</font></b> (اِخ ) کرنه لیوس ژانسن . نام عالم کلامی هلندی بطریق ایپرس . مولد او له اردام . اثر مهم وی اگوستینوس است که در آن نظریه ٔ غفران سنت اگوستن را مطابق رأی و نظر خود در امر عفو و غفران و اختیار و قدر شرح داده است و همین نظریه ٔ اوست که بنام وی به ژانسه نیسم معروف است (<span class=\"hlight\" dir=\"rtl\">١٥٨٥</span> - <span class=\"hlight\" dir=\"rtl\">١٦٣٨</span> م .).<br /></font></div>'),
(287812, 'ژانسه', '<span class=\"hlight\">ژانسه .</span> <font color=\"DarkGreen\"><b>[ س ِ ]</font></b> (اِخ ) نام کرسی بخش «وین » از شهرستان مونت مریین دارای قریب <span class=\"hlight\" dir=\"rtl\">١٠٦٥٠</span> تن سکنه .<br /></font></div>'),
(287813, 'ژانسه نیسم', '<span class=\"hlight\">ژانسه نیسم .</span> <font color=\"DarkGreen\"><b>[ س ِ ]</font></b> (اِخ ) رجوع به ژانسنیوس شود.<br /></font></div>'),
(287814, 'ژانسیو', '<span class=\"hlight\">ژانسیو.</span> (اِخ ) نام کرسی بخش «کروز» از ایالت ابوسن واقع در پلاتو دژانسیو دارای <span class=\"hlight\" dir=\"rtl\">٨٨٥</span> تن سکنه .<br /></font></div>'),
(287815, 'ژانطیوس', '<span class=\"hlight\">ژانطیوس .</span> (اِخ ) پادشاه ایلیری و این آن کس است «که گویند که اول بار خواص جنطیانا را بشناخت ونام خود بدین گیاه داد». و نام او را در کتب مفردات، جنطین الملک می نویسند.<br /></font></div>'),
(287816, 'ژانلیس', '<span class=\"hlight\">ژانلیس .</span> (اِخ ) مادمازل استفانی فلیسیته . نام معلمه ٔ اطفال دوک دأرلئان و فیلیپ اِگالیته مؤلف تألیفات مشهور راجع به تعلیم و تربیت . مولد در حوالی اتن (<span class=\"hlight\" dir=\"rtl\">١٧٤٦</span> -<span class=\"hlight\" dir=\"rtl\">١٨٣٠</span> م .).<br /></font></div>'),
(287817, 'ژانلیس', '<span class=\"hlight\">ژانلیس .</span> (اِخ ) نام کرسی بخش «کت در» از شهرستان دیژن دارای راه آهن و قریب <span class=\"hlight\" dir=\"rtl\">١٢٧٦</span> تن سکنه .<br /></font></div>'),
(287818, 'ژانن', '<span class=\"hlight\">ژانن .</span> <font color=\"DarkGreen\"><b>[ ن َ ]</font></b> (اِخ ) ژول گابریل . نام ادیب و نویسنده و نقاد فرانسوی . مولد سن -اتین (لوآر) و وفات در پاریس (<span class=\"hlight\" dir=\"rtl\">١٨٠٤</span> - <span class=\"hlight\" dir=\"rtl\">١٨٧٤</span> م .).<br /></font></div>'),
(287819, 'ژانه', '<span class=\"hlight\">ژانه .</span> <font color=\"DarkGreen\"><b>[ ن ِ ]</font></b> (اِخ ) پُل . نام فیلسوف فرانسوی (<span class=\"hlight\" dir=\"rtl\">١٨٢٣</span>-<span class=\"hlight\" dir=\"rtl\">١٨٩٩</span> م .).<br /></font></div>'),
(287820, 'ژانوس', '<span class=\"hlight\">ژانوس .</span> (اِخ ) بر طبق اساطیر کهن، وی اولین پادشاه شهر ژانی کولوس واقع بر ساحل رود تیبر مقابل شهر رم بوده است . رومیان او را چون خدائی پرستش میکردند و گمان داشتند که مراسم دینی را او بنیان نهاده است . (ترجمه ٔ تمدن قدیم فوستل دکولانژ ص <span class=\"hlight\" dir=\"rtl\">٤٨٠</span>).<br /></font></div>'),
(287821, 'ژانویل', '<span class=\"hlight\">ژانویل .</span> <font color=\"DarkGreen\"><b>[ ژان ْ ]</font></b> (اِخ ) نام کرسی بخش اور-اِ-لوار ولایت شارتر دارای راه آهن و <span class=\"hlight\" dir=\"rtl\">١١٩٢</span> تن سکنه .<br /></font></div>'),
(287822, 'ژانویه', '<span class=\"hlight\">ژانویه .</span> <font color=\"DarkGreen\"><b>[ ژان ْ ی ِ ]</font></b> (اِخ ) (قدیس ) نام اسقف بنه وان مولد حدود سنه ٔ <span class=\"hlight\" dir=\"rtl\">٢٥٠</span> م . و شهادت در سال <span class=\"hlight\" dir=\"rtl\">٣٠٥</span> م . ذکران وی روز <span class=\"hlight\" dir=\"rtl\">١٩</span> سپتامبر است .<br /></font></div>'),
(287823, 'ژانویه', '<span class=\"hlight\">ژانویه .</span> <font color=\"DarkGreen\"><b>[ ژان ْ ی ِ ]</font></b> (اِخ ) (بُن اُم ) نام شخص اساطیری که بنا به افسانه های کودکانه برای اطفال در شب اول سال میلادی بازیچه ها آرد. وی به هیئت سن نیکلا، پیرمردی با ریش سپید که با خود بازیچه ٔ بسیار دارد تصویر میشود.<br /></font></div>'),
(287824, 'ژانویه', '<span class=\"hlight\">ژانویه .</span> <font color=\"DarkGreen\"><b>[ ژان ْ ی ِ ]</font></b> (اِخ ) فرمانی که در تاریخ <span class=\"hlight\" dir=\"rtl\">١٧</span> ژانویه ٔ <span class=\"hlight\" dir=\"rtl\">١٥٦٢</span> م . کاترین دمدیسی به پرتستانها داده و امتیازاتی به آنان اعطا کرد.<br /></font></div>'),
(287825, 'ژانویه', '<span class=\"hlight\">ژانویه .</span><font color=\"DarkGreen\"><b>[ ژان ْ ی ِ ]</font></b> (فرانسوی، اِ) نام اولین ماه سال گریگوری یا نخستین ماه سال میلادی فرنگی که آغاز آن تقریباً برابر هفدهم دیماه جلالی است و سی ویک روز دارد.<br /></font></div>'),
(287826, 'ژانی سر', '<span class=\"hlight\">ژانی سر.</span> <font color=\"DarkGreen\"><b>[ س ِ ]</font></b> (اِ) مصحف ینی چری عثمانیان . رجوع به ینی چری شود.<br /></font></div>'),
(287827, 'ژانی کول', '<span class=\"hlight\">ژانی کول .</span> (اِخ ) نام یکی از تپه های هفتگانه ٔ رم بساحل رود تیبر.<br /></font></div>'),
(287828, 'ژانین', '<span class=\"hlight\">ژانین .</span> (اِخ ) نام دریاچه ای به اپیر یونان .در قدیم پئوم بوتی نیز میگفته اند. (ایران باستان ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٢١٢</span>).<br /></font></div>'),
(287829, 'ژانینا', '<span class=\"hlight\">ژانینا.</span> (اِخ ) رجوع به یانینا شود.<br /></font></div>'),
(287830, 'ژاهل', '<span class=\"hlight\">ژاهل .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ژائیل . یاعیل . نام زوجه ٔ حابرقینی (سِفْرِ داوران <span class=\"hlight\" dir=\"rtl\">٤</span>:<span class=\"hlight\" dir=\"rtl\">١٧</span>). زنی که میخی در شقیقه ٔ سیسرا که به چادر وی پناهنده شده بود کوفت بدانگونه که از جانب دیگر به زمین نشست و سیسرا را بکشت . نیز رجوع به یاعیل شود.<br /></font></div>'),
(287831, 'ژاو', '<span class=\"hlight\">ژاو.</span> (ص، اِ) خالص و خلاصه ٔ هر چیز را گویند. (برهان ).<br /></font></div>'),
(287832, 'ژاوا', '<span class=\"hlight\">ژاوا.</span> (اِخ ) (جزیره ٔ...) جاوه . جاوه در تداول اروپائیان . رجوع به جاوه شود.<br /></font></div>'),
(287833, 'ژاوا', '<span class=\"hlight\">ژاوا.</span> (اِخ ) (دریای ...) دریای جاوه . نام قسمتی از اقیانوس هند میان جزیره ٔ جاوه و سوماترا و برنئو. رجوع به جاوه شود.<br /></font></div>'),
(287834, 'ژاور', '<span class=\"hlight\">ژاور.</span> <font color=\"DarkGreen\"><b>[ وَ ]</font></b> (ص ) زفت و بخیل باشد <span class=\"hlight\">:</span> <br />کمربستگانند و بیچارگان <br />ابی شکانند و بی ژاوران .<br /><font color=\"Red\">رودکی (از فرهنگ اوبهی ).</font><br /></font></div>'),
(287835, 'ژاوژا', '<span class=\"hlight\">ژاوژا.</span> <font color=\"DarkGreen\"><b>[ وَ ]</font></b> (اِ) خارپشت . ژَاُوژا <span class=\"hlight\">:</span> <br />گر سایه ٔ عمود تو افتد بفرق او<br />سر درکشد به سینه عدویت چو ژاوَژا.<br /><font color=\"Red\">عمادالدین یوسف (از فرهنگ نظام ).</font><br /></font></div>'),
(287836, 'ژاوی', '<span class=\"hlight\">ژاوی .</span> (اِخ ) نام کرسی بخش باس -آلپ از ولایت دینی دارای قریب <span class=\"hlight\" dir=\"rtl\">٣٢١</span> تن سکنه .<br /></font></div>'),
(287837, 'ژاویدن', '<span class=\"hlight\">ژاویدن .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (مص ) جاویدن . نشخوار کردن . <BR><font color=\"Blue\">◄</font> ژاژیدن (؟). (آنندراج ). <BR><font color=\"Blue\">◄</font> زاریدن . زنوبیدن . (معانی این کلمه از شعوری نقل شده و ظاهراً بر اساسی نیست ).<br /></font></div>'),
(287838, 'ژاپن', '<span class=\"hlight\">ژاپن .</span> <font color=\"DarkGreen\"><b>[ پ ُ ]</font></b> (اِخ ) نام دریائی منشعب از اقیانوس کبیر که محدود است به سیبری و منچوری و کره و جزایر ژاپن .<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(287839, 'ژاپن', '<span class=\"hlight\">ژاپن .</span> <font color=\"DarkGreen\"><b>[ پ ُ ]</font></b> (اِخ ) کشور امپراطوری ژاپن یا دائی نیپون که بمعنی مملکت شمس طالع است شامل چهار هزار جزیره ٔ خرد و بزرگ است که از شبه جزیره ٔ کامچاتکا تا سواحل جنوب شرقی چین امتداد داردو قریب به <span class=\"hlight\" dir=\"rtl\">٣٨٢٤٤٧</span> کیلومتر مربع سطح آن است . مهمترین جزایر ژاپن جزایر بزرگ سه گانه ٔ مرکزی است که بنامهای نی پون یا هندو یا «اراضی اصلی » و شی ککو یا «نواحی چهارگانه » و کیوشو یا «نواحی نه گانه » معروف است . در شمال جزایر مرکزی نیز جزیره ٔ هوکائیدو یا یزو یعنی «سرزمین وحشیان » و نصف جنوبی جزیره ٔ کارافوتو یا ساخالین و مجمعالجزایر ریوکیو واقع شده و در جنوب مجمعالجزایر کوریل و جزیره ٔ بزرگ تائی وان یا فرمز است که در <span class=\"hlight\" dir=\"rtl\">١٨٩٥</span> م . از چین منتزع شده است ولی در حال حاضر جزء ژاپن نیست . <br />حدود آن : جزایر ژاپن از مشرق متصل به اقیانوس کبیر و دریاهای غربی آن بحر اختسک و دریای ژاپن و دریای چین و تنگه ٔ کره است . <br />وضع طبیعی جزایر ژاپن : از جزایر ژاپن در ساحل غربی اقیانوس کبیر سه قوس بزرگ پدید آمده که از شمال به جنوب سواحل شرقی آسیا را احاطه کرده است . اول قوس جزایر کوریل در شمال میان شبه جزیره ٔ کامچاتکا و جزیره ٔ هوکائیدو. دوم قوس مرکزی میان جزیره ٔ کارافوتو و جزیره ٔ کیوشو. سوم قوس ریوکیو در جنوب میان جزایر کیوشو و تائی وان . در میان این سه قوس بین سواحل آسیا و ژاپن دریاهای بزرگ سه گانه ٔ اختسک و ژاپن و چین شرقی قرار دارد.<br />پستی و بلندی : جزایر ژاپن بطور کلی صخره ای و کوهستانی است و فقط یک هشتم از اراضی آن جلگه می باشد. وسیعترین جلگه های شرقی درجزیره ٔ هندو است که شهر توکیو در آن واقع شده است . کوههای ژاپن بیشتر از آثار دوره ٔ سوم معرفةالارضی است . و در آن کشور دو رشته ٔ جبال عمده است : رشته ٔ اول از جنوب به شمال در جزیره ٔ هندو ممتد می باشد که سلسله های آئیچی و آبوکوما و کاتاکامی از مهمترین آنها بشمار میرود. رشته ٔ دیگر از شمال شرقی به جنوب غربی امتداد دارد و دنباله ٔ آن به جزایر کوریل و کامچاتکا منتهی میشود. مرتفعترین قلل جبال ژاپن در جزیره ٔ فرمز قله ٔ موریسن است که <span class=\"hlight\" dir=\"rtl\">٤١٤٥</span> متر ارتفاع دارد. در مرکز جزیره ٔ هندو میان سلسله ٔجبال شمالی و جنوبی زمینهای پستی است که از دریای ژاپن تا اقیانوس کبیر امتداد داشته و در حقیقت جزیره ٔمزبور را به دو نیم کرده است و در این قسمت آتشفشانهای بسیار وجود دارد که از آنجمله یکی آتشفشان فوجی یاما است . این آتشفشان از سال <span class=\"hlight\" dir=\"rtl\">١٧٠٧</span> خاموش شده و <span class=\"hlight\" dir=\"rtl\">٣٧٥٠</span> متر ارتفاع دارد و همیشه مستور از برف است . فوجی یاما را مردم ژاپن مقدس میشمرند. بواسطه ٔ وجود کوههای آتشفشان زلزله در جزایر ژاپن بسیار روی میدهد، چنانکه در سال <span class=\"hlight\" dir=\"rtl\">١٨٨٨</span> بسبب آتشفشانی کوه باندائی سان دوازده قریه بکلی ویران شد. در مدت چهارده سال از <span class=\"hlight\" dir=\"rtl\">١٨٩٤</span> تا <span class=\"hlight\" dir=\"rtl\">١٩٠٧</span> قریب <span class=\"hlight\" dir=\"rtl\">٢٣٣٤٠</span> زلزله در این کشور روی داد. قبل از آن نیز در سال <span class=\"hlight\" dir=\"rtl\">١٨٩١</span> زلزله ٔ سهمناکی باعث هلاک <span class=\"hlight\" dir=\"rtl\">٧٠٠٠</span> تن از اهالی و ویرانی <span class=\"hlight\" dir=\"rtl\">١٩٧٠٠٠</span> خانه گردید و در <span class=\"hlight\" dir=\"rtl\">١٨٩٦</span> بر اثر زلزله ای دیگر قریب <span class=\"hlight\" dir=\"rtl\">٢٢٠٠٠</span> تن هلاک شدند. سخت ترین بلای مهیب، زلزله و طوفان سختی بود که در ماه سپتامبر <span class=\"hlight\" dir=\"rtl\">١٩٢٣</span> در حوالی شهر یوکوهاما روی داد. در این حادثه قریب <span class=\"hlight\" dir=\"rtl\">١٤٢٠٠٠</span> تن معدوم و مفقود شدند.<br />سواحل و جزایر ژاپن : جزایر ژاپن بسبب وجود کوههای ساحلی و مجاورت با ژرف ترین اعماق اقیانوس کبیر که در اطراف قوس کوریل <span class=\"hlight\" dir=\"rtl\">٨٥١٣</span> متر و در نزدیکی جزیره ٔ گوام در گودال معروف به نرو <span class=\"hlight\" dir=\"rtl\">٩٦٣٥</span> متر عمق دارد دارای خلیجها و دماغه های فراوان است .بهمین سبب طول سواحل آن به یازده هزار کیلومتر میرسد. جزایر کوریل مشتمل بر شانزده جزیره ٔ کوچک میباشد ولی ژاپنی ها آن را فسیسیما یعنی جزایر هزارگانه مینامند. جزیره ٔ بیزو بتوسط باب لاپروز از ساخالین جدا شده و با جزیره ٔ هندو بواسطه ٔ تنگه ٔ فزوگار ارتباط دارد و در جنوب غربی آن خلیج هاکودات واقع شده است .تضاریس سواحل جزیره ٔ هندو از جزایر دیگر بیشتر است و مهمترین خلیج این جزیره خلیجی است که بنام پایتخت کشور به خلیج توکیو معروف شده و بندر یوکوهاما هم در کنار این خلیج واقع است .بریدگی های جزیره ٔ شی ککو کمتر و بین آن و جزیره ٔ کیوشو تنگه ٔ بوناگو فاصله میباشد و تنگه ٔ سیمونوزکی بین جزیره ٔ هندو و کیوشو واقع است . جزیره ٔ کیوشو تضاریس بسیار دارد و در جنوب آن خلیج و بندر ناکازاکی واقع و خلیج کاکوشیما قرار دارد. جزایر ریوکیو نیز بشکل قوسی از جزیره ٔ کیوشو به جزیره ٔ فرمزا ممتد است و در مغرب جزیره ٔ اخیر جزایر پسکادرس به ژاپن تعلق دارد.<br />رودهای ژاپن : از جهت کمی وسعت اراضی ژاپن رودهای آن کشور کوتاه و بی اهمیت است و طویل ترین آنها <span class=\"hlight\" dir=\"rtl\">٣٥٠</span> کیلومتر طول دارد و عموماً جریان آنها تند و سیلابی است . رودهای بزرگ آن یکی رود ایشی کاری درجزیره ٔ هوکائیدو و رودهای شی نانوگاوا (<span class=\"hlight\" dir=\"rtl\">٣٥٠</span> کیلومتر) و تونه گاوا (<span class=\"hlight\" dir=\"rtl\">٣٠٠</span> کیلومتر) و سومیداگاوا (<span class=\"hlight\" dir=\"rtl\">١٧٠</span> کیلومتر) در جزیره ٔ هندو و ازرودهای سه گانه ٔ اخیر دو رود اول قابل کشتی رانی است .<br />آب و هوای ژاپن : کلیةً آب وهوای ژاپن بحری است و اختلاف درجه ٔ حرارات آن کم و چون بین <span class=\"hlight\" dir=\"rtl\">٢٢</span> و <span class=\"hlight\" dir=\"rtl\">٥٠</span> درجه ٔ عرض شمالی واقع شده و طول آن <span class=\"hlight\" dir=\"rtl\">٢٨</span> درجه است از اینرو آب و هوای مختلف در جزایر آن مشاهده میشود و اختلاف بین درجه ٔ حرارت جزایر شمالی و جنوبی آن بسیار است . با وجود این جریان کوروشیو و بادهای موسمی زمستانی هوای آن را معتدل کرده است . بادهای موسمی زمستانی از آغاز مهرماه (اواخر سپتامبر) در شمال غربی و شمال بر جزایر ژاپن میوزد. این بادها اصولاً خشک است ولی چون از دریای ژاپن میگذرد اندکی رطوبت می پذیرد و در سواحل غربی تولید باران میکند. وزش بادهای موسمی تابستانی ازنیمه ٔ فروردین آغاز میشود و باد از طرف جنوب شرقی میوزد و چون از اقیانوس کبیر عبور میکند رطوبت فراوان دارد و در سواحل ژاپن بارانهای شدید فرومی بارد. مهمترین جریان دریائی اقیانوس کبیر جریان گرم کوروشیو «رود سیاه » است . این جریان شعبه ای از جریان بزرگ اقیانوس کبیر است که در شمال خط استوا در سواحل شبه جزیره ٔ کالیفرنیا تولید میشود و بجانب فیلی پین می آید و درآنجا به دو شعبه منقسم میگردد، شعبه ٔ بزرگ آن همان کوروشیو است . سرعت این جریان در زمستان در <span class=\"hlight\" dir=\"rtl\">٢٤</span> ساعت از <span class=\"hlight\" dir=\"rtl\">٢٤</span> تا <span class=\"hlight\" dir=\"rtl\">٣٦</span> میل بحری نمیگذرد زیرا در این فصل وزش بادهای موسمی شمال غربی مانع سرعت جریان آن است، ولی در تابستان سرعت آن بواسطه ٔ مساعدت بادهای موسمی جنوب شرقی در <span class=\"hlight\" dir=\"rtl\">٢٤</span> ساعت به <span class=\"hlight\" dir=\"rtl\">٤٢</span> میل میرسد. کوروشیو از سواحل جزایر تائی وان و جزایر ریوکیو و ساحل شرقی جزایر ژاپن میگذرد و در نواحی شمالی ژاپن با جریان آب سردی که از دریای برینگ می آید بنام جریان اویاشیو تلاقی میکند و در برابر جزایر آله ئوسی ین بسوی آمریکای شمالی متوجه میشود.<br />نباتات ژاپن : کشور ژاپن بسبب بارندگی بسیار سبز و خرم است . در نواحی مرتفع جزایر بزرگ مرکزی خاصه در هوکائیدو جنگلهای سرو و کاج بسیار دیده میشود و در سایر نواحی جزایر مزبور جنگلهای بلوط و زیرفون و آزاد فراوان است . در جزیره ٔ تائی وان نیز جنگلهائی از نوع درختهای مناطق حاره مانند خیزران و کافور و سرخس و امثال آن وجود دارد. از جمله اشجار ژاپن دو درخت را اهمیت مخصوص است : یکی درخت معروف به هی نوکی یا «درخت آفتاب » که در نظر مردم آن کشور مقدس است و چوب آن فقط در ساختن معابد و برخی از بناهای خاص بکار میرود. دیگر درخت سوقی است که آن را کُنار ژاپنی خوانند و بسیار بلند و انبوه میشود و طول آن به <span class=\"hlight\" dir=\"rtl\">٣٥</span> تا <span class=\"hlight\" dir=\"rtl\">٥٠</span> متر میرسد. دامنه ٔ جبال ژاپن را جلگه های سبز و خرم که بزبان ژاپنی «هارا»میخوانند فراگرفته . در این جلگه ها انواع گلهای رنگارنگ مانند گل داودی که گل ملی ژاپن است و شقایق نعمان و زنبق و گلهای دیگر میروید که بوی عطر آن از دور به مشام مسافرین میرسد.<br />حیوانات ژاپن : حیوانات برّی ژاپن مانند نباتات آن بسیار و متنوع نیست، عمده ٔ آن گرگ و روباه و بوزینه و گراز است که در جنگلهای هندو یافت میشود.<br />جغرافیای سیاسی ژاپن <br />ملت ژاپن : درباره ٔ نژاد اصلی ملت ژاپن اطلاع درستی در دست نیست و آنچه مورخان ژاپنی در این خصوص نوشته اند مبتنی بر افسانه های ملی است . ظاهراً چندین قرن پیش از میلاد دسته ای از مهاجرین چین و کره به جزایر ژاپن رفته و آداب و اصول تمدن را به مردم آن جزایر آموخته اند. طوایف بومی و اصلی ژاپن آی نوس ها بودند که از مائه ٔ هفتم پیش از مسیح تا مائه ٔ دوم میلادی در آنجا بحال توحش بسر میبردند. بعدها در مائه ٔ دوم میلادی عده ای از مهاجرین چینی به آن جزایر هجوم آورده و بومیان را به نقاط و جزایر دوردست شمالی رانده و خود در جزایر هندو و اطراف آن اقامت گزیدند و ممالک ژاپن را تشکیل دادند. امروز جزایر ژاپن گذشته از وحشیان جزیره ٔ تائی وان و اقوام معروف به آی نوس که در نواحی غیرحاصلخیز هوکائیدو (یزو) مسکن دارند و از تمدن کمتر بهره مند شده اند مسکن ملت ژاپن است که قطعاً در آغاز امر از قاره ٔ آسیا به این جزایر رفته و بر بومیان دست یافته اند. ژاپنی ها به اغلب احتمال از نژاد مغول هستند و به مردم کره بیش از اهالی چین بستگی و ارتباط نژادی دارند. نخستین میکادوی ژاپن بنا به روایات ژاپنی جیموتنو است که در <span class=\"hlight\" dir=\"rtl\">٦٦٠</span> ق .م . میزیسته و امروز روان او مورد پرستش ژاپنی هااست . تاریخ ژاپن در قرون قبل از میلاد تاریک و آمیخته به افسانه میباشد. ملت ژاپن از دو طبقه ٔ مشخص تشکیل شده است : یکی طبقات عالیه که قد بلند و چهره ٔ کشیده و بینی باریک دارند و چشمان ایشان در جنس ذکور عادی و در جنس اناث پیچیده است . دیگر طبقات پست که کوتاه قد و درشت پیکرند و صورت و بینی پهن و چشمان پیچیده و دهان فراخ دارند و از تمدن کمتر بهره مند شده اند. نخستین مسافر اروپائی که از ژاپن در سفرنامه ٔ خود نام میبرد مارکوپولو از مردم ونیز است که در قرن هفتم هجری سفری به چین کرد و به دربار قوبیلای قاآن خان مغول رفت . مارکوپولو ژاپن راسی پانگو نامیده است . باید دانست که محاط بودن به دریا ژاپن را از هجوم تاتارها نجات داد. از ملل اروپائی نخستین قومی که به ژاپن راه یافتند تجار پرتقالی بودند که در اواسط قرن شانزدهم (<span class=\"hlight\" dir=\"rtl\">١٥٤٣</span>) به آن جزیره رفتند و پس از ایشان جمعی از مبلغان مسیحی نیز به ژاپن سفر کرده و به تبلیغات دینی پرداختند و کم کم در امور سیاسی نیز مداخله کردند. بهمین سبب دولت ژاپن در آغاز قرن هفدهم اروپائیان را از سرزمین خود بیرون کرد و ورود بیگانگان را به ژاپن ممنوع ساخت . از آن پس فقط دسته ای از تجار هندی وچینی میتوانستند به جزیره ٔ کوچکی مقابل بندر ناکازاکی آمده امتعه و محصولات ژاپن را بخرند. از سال <span class=\"hlight\" dir=\"rtl\">١٨٥٤</span> بسبب مداخله و سختگیری کشورهای متحده ٔ آمریکا باب تجارت ژاپن به دولت مزبور و دول بزرگ اروپائی مانند انگلستان و فرانسه و روسیه باز شد و دولت ژاپن ورود تجار این دولت را به جزایر خود آزاد کرد، ولی این امر میان سرداران ژاپن اختلافی پدید آورد و به جنگ داخلی کشید (<span class=\"hlight\" dir=\"rtl\">١٨٦٤</span>). ژاپنی ها از مائه ٔ ششم تا مائه ٔ هفتم تمدن چینی را اتخاذ کرده و مؤدّب به آداب و رسوم چینی گردیدند. پادشاهان ژاپن از قدیم ملقب به میکادو بودند و در سابق قدرت مطلقه داشتند. در <span class=\"hlight\" dir=\"rtl\">٧٩٤</span> م . میکادو کوامو، کیوتو را پایتخت قرار داد. در مائه ٔ دوازدهم رفته رفته از جهت سستی و ضعف امپراطوران قدرت و تسلط آنان را اعیان مخصوص خود کرده و صاحب اختیار مطلق گردیدند. و قدرت و حکومت میکادو اسمی بلارسم گردید و عنان امور کشور به دست سئی ای توئی شگون یعنی «سردار مأمور تسخیر کشور وحشیها» و شاهزادگان یا «دائی میوس » ها بود و همه ٔ قشون دولتی که موسوم به سامورائی بودند اطاعت از شگون و طبقات عالی نظامیان میکردند. سامورائیها از طفولیت شمشیر دوسر بکار برده و در زمره ٔ طبقات نظامی و ادب دوست ژاپن بشمار می آمدند و این دو شغل را مختص به خود میدانستند. در سال <span class=\"hlight\" dir=\"rtl\">١٨٦٨</span> مردم کشور مخصوصاً سامورائیها و دائی میوسها از بیداد و ستم شگون به تنگ آمده و به استظهار میکادو موتسوهیتو امپراطور ژاپن بر او شوریده و بفرمان امپراطور سپهسالار کل شگون از مقام خود خلع و میکادو مجدداً صاحب اختیارات مطلق گردید. از این تاریخ اصلاحات در ژاپن شروع گشته و به فرمان میکادو پایتخت از شهر کیوتو اقامتگاه قدیم امپراطوران قدیم به شهر یدو و مقر سپهسالار کل منتقل شد و آن را توکیو یعنی «پایتخت شرقی » خواندند. موتسوهیتو در بدو اصلاحات خود ترتیب ملوک الطوایفی را که تا آن زمان در ژاپن معمول بود متروک کرده و امتیازات سامورائیها را از ایشان انتزاع کرد. وی برای اصلاح امور کشوری و لشکری و سیاسی مملکت مستشارانی ازممالک اروپا طلب کرد و جمعی از طلاب ژاپنی را به اروپا فرستاد و در سراسر ژاپن دبستانها و دبیرستانها و دانشکده ها تأسیس کرد و از سال <span class=\"hlight\" dir=\"rtl\">١٨٧٠</span> به کشیدن خطوط آهن و تلگراف و ساختن سفاین جنگی همت گماشت و خدمت نظام را اجباری کرد و در اندک زمانی <span class=\"hlight\" dir=\"rtl\">٤٠٠٠٠٠</span> سپاهی آماده ساخت . در سال <span class=\"hlight\" dir=\"rtl\">١٨٨٩</span> نیز قانون اساسی تازه ای وضع کردو قوه ٔ مقننه ٔ کشور را به دو مجلس اعیان و مبعوثان سپرد و قوه ٔ مجریه را خویشتن در دست گرفت . این دوره ٔدرخشان در تاریخ ژاپن به عصر میجی معروف است . جنگ سال <span class=\"hlight\" dir=\"rtl\">١٩٠٠</span> بین ژاپن و چین و فتح ژاپن ترقی و برتری نظامی ژاپن را ظاهر ساخت و باعث عقد اتحاد بین انگلیس وآن کشور در <span class=\"hlight\" dir=\"rtl\">١٩٠٢</span> گردید. در نتیجه ٔ این جنگ جزیره ٔ فرمز به دست ژاپنیها افتاد. پس از آن مهمترین جنگ ژاپن نبرد آن کشور در سال <span class=\"hlight\" dir=\"rtl\">١٩٠٤</span> - <span class=\"hlight\" dir=\"rtl\">١٩٠٥</span> با دولت تزاری روس است که بالاخره به فتح ژاپن و شکست روس منتهی گشت . در این جنگ شبه جزیره ٔ کره را ژاپن ضمیمه ٔ خود ساخت ودولت ژاپن بر اثر این پیروزی در ردیف دول معظمه ٔ جهان محسوب شد. در جنگ بزرگ <span class=\"hlight\" dir=\"rtl\">١٩١٤</span> - <span class=\"hlight\" dir=\"rtl\">١٩١٨</span> برخلاف جنگ اخیر از کشورهای متفق و از مخالفین آلمان بود و از غراماتی که بر آلمان تعلق گرفت برخوردار شد و کیااوچو راتصرف کرد و بعدها بر منچوری و مغولستان دست یافت و آن را در دسامبر <span class=\"hlight\" dir=\"rtl\">١٩٤١</span> از کشور چین مجزا ساخت .<br />ژاپن در جنگ اخیر از دول محور و مخالفین آمریکا و انگلیس و متفقین آنها بود و با حمله ٔ ناگهانی در پیرل هاربور بر سفاین آمریکا مخالفت خود را با متفقین علنی ساخت و تا <span class=\"hlight\" dir=\"rtl\">١٩٤٢</span> فتوحات وی در مشرق آسیا به منتهای عظمت خود رسید ولی پس از شکست آلمان قوای او رو به ضعف نهاد و سرانجام بر اثر افکندن بمب اتمی در دو شهر هیروشیما و ناکازاکی و کشتن تمامی مردم بی گناه آن از صغیر و کبیر در <span class=\"hlight\" dir=\"rtl\">١٩٤٥</span> مجبور به تسلیم بلاشرط گردید و سرزمین هائی را که از کشور چین تصرف کرده بود دولت چین بازگرفت و از جمله جزیره ٔ فرمز را که پنجاه سال پیش از چین گرفته بود و همچنین منچوری را مجدداً دولت اخیر متصرف شد.<br />وضع حکومت ژاپن : حکومت ژاپن از سال <span class=\"hlight\" dir=\"rtl\">١٨٨٩</span> مشروطه شده و قوه ٔ مجریه در دست امپراطور یا میکادو است و اعلان جنگ و عقد معاهدات صلح و انتخاب وزراء و انحلال مجلس مبعوثان و تعیین جلسات مجلس اعیان از جمله ٔ اختیارات اوست . امپراطور را در مواقع رسمی میکادو خوانده و ملت او را پسر آسمان خطاب می کنند. وی بموجب قانون اساسی، غیرقابل عزل و دارای قدرت مطلقه می باشد و وزراء ژاپن مسئول امپراطور میباشند و در مقابل پارلمان مسئولیتی ندارند. دی یت ژاپن مرکب از دو مجلس است : یکی مجلس اعیان و دیگری مجلس مبعوثان . مجلس اعیان مرکب از شاهزادگان و اعضاءارشد خانواده ٔ سلطنتی و عده ای از اعیان و رجال بزرگ کشور است که قسمتی از جانب شخص امپراطور و قسمتی ازطرف مردم انتخاب میشوند و عده ٔ ایشان در حدود چهارصد تن است و باید لااقل سی سال داشته باشند. دوره ٔ وکالت برخی از اعضاء این مجلس تمام عمر و دوره ٔ وکالت بعض دیگر هفت سال است . وکلای مجلس مبعوثان از جانب عامه ٔ مردم انتخاب میشوند و باید لااقل سی سال داشته باشند. مدت وکالت نمایندگان این مجلس چهار سال است . امروز عده ٔ نمایندگان مجلس مبعوثان ژاپن در حدود چهارصدو شصت تن (یک نماینده از طرف <span class=\"hlight\" dir=\"rtl\">١٢٨٢٠٠</span> تن ) است . آزادی مذهب و مطبوعات و اجتماعات و عدم عزل قضاة از اصول قوانین اساسی ژاپن میباشد. در ژاپن مذهب رسمی وجود ندارد و همه ٔ مذاهب آزاد است ولی مردم بیشتر پیرو یکی از سه دین شنتوئی و بودائی و کنفوسیوسی هستند. دین بودائی و کنفوسیوسی از راه چین به ژاپن داخل شده است، ولی مذهب شنتوئی دین ملی ژاپنی هاست و زمانی دین بودائی و کنفوسیوسی بر آن مذهب غلبه کرده بود ولی در عهد تجدید قدرت میکادوهای ژاپن این مذهب باز حیات و قوت خود را در آن کشور از سر گرفت . اصول این مذهب پرستش ارواح نیاکان و قوای طبیعت است .<br />جمعیت ژاپن : جمعیت ژاپن خاص بنا به احصائیه ٔ رسمی سال <span class=\"hlight\" dir=\"rtl\">١٩٣٠</span>، <span class=\"hlight\" dir=\"rtl\">٦٤٤٥٠٠٠٠</span> تن بوده است و چون مساحت ژاپن بدون متصرفات آن دولت <span class=\"hlight\" dir=\"rtl\">٣٨٢٣٠٠</span> کیلومتر مربع است پس در هر کیلومتر مربعی قریب <span class=\"hlight\" dir=\"rtl\">١٦٩</span> تن زندگی میکنند. از سال <span class=\"hlight\" dir=\"rtl\">١٩٢٥</span> تا <span class=\"hlight\" dir=\"rtl\">١٩٣٠</span> یعنی در ظرف پنج سال قریب <span class=\"hlight\" dir=\"rtl\">٤٧١٠٩٠٠</span> تن بر جمعیت ژاپن افزوده شده و احصائیه ٔ سال <span class=\"hlight\" dir=\"rtl\">١٩٣٢</span> نیز جمعیت ژاپن خاص را قریب <span class=\"hlight\" dir=\"rtl\">٦٦٣١٧٠٠٠</span> تن تعیین کرده است . احصائیه ٔ جمعیت ژاپن تا <span class=\"hlight\" dir=\"rtl\">١٩٤٦</span> قریب به <span class=\"hlight\" dir=\"rtl\">٧٣٠٠٠٠٠٠</span> تن بوده است . علت افزایش جمعیت ژاپن فزونی عده ٔ متولدین بر متوفیات است . بهمین سبب مردم ژاپن ناگزیرند که یا به سایر نواحی عالم مهاجرت کنند و یا با تصرف اراضی تازه و توسعه ٔ تجارت مملکت وسائل زندگانی و آسایش خود را فراهم سازند.<br />شهرهای ژاپن : از جمعیت ژاپن جمع کثیری روستائی و زارعند که در دهکده ها و مزارع و شهرهای کوچک بسر میبرند. از سال <span class=\"hlight\" dir=\"rtl\">١٨٦٨</span> که ژاپن راه ترقی و تمدن پیش گرفت کم کم شهرهای صنعتی بزرگ نظیر شهرهای صنعتی اروپا و آمریکا در آن کشور پدید آمد. نخستین شهر بزرگ ژاپن توکیو است که در کنار خلیج بزرگی بهمین نام قرار دارد. بنا به احصائیه ٔ سال <span class=\"hlight\" dir=\"rtl\">١٩٣٠</span> جمعیت این شهر در حدود <span class=\"hlight\" dir=\"rtl\">٢٠٧٠٥٠٠</span> تن (با توابع <span class=\"hlight\" dir=\"rtl\">٥٣١١٠٠٠</span> تن ) بوده و وسعت آن <span class=\"hlight\" dir=\"rtl\">٢٤٠٠٩</span> هکتار است . در جنوب خلیج توکیو بندر بزرگ یوکوهاما واقع شده و فاصله ٔ آن از پایتخت سی کیلومتر است . شهر کیوتو هم که مدت یازده قرن پایتخت ژاپن بود با آنکه جمعیت فراوانی ندارد از لحاظ صنعت خالی از اهمیت نیست . بندر اُزاکا یگانه شهری است که صورت قدیمی خود را کاملاً محفوظ داشته . کوچه های این شهر بیشتر تنگ و عمارات آن گذشته از کارخانه ها و مراکز صنایع، قدیمی است و چون در اطراف دلتائی بنا شده و ترعه های متعدد از میان آن میگذرد آن را نظیر شهر ونیز شمرده اند. این بندربزرگترین مرکز صنایع ژاپن است . در کنار خلیج ازاکا بندر معروف دیگری است بنام کبه که در مغرب ازاکا واقع شده و مرکز ورود امتعه ٔخارجی به ژاپن است . در جنوب غربی جزیره ٔ کیوشو بندربزرگ ناکازاکی مرکز روابط تجارتی ژاپن با ممالک آسیائی مخصوصاً چین و چزن (کُره ) و هند است . بندر هاکوداته در جنوب جزیره ٔ هوکائیدو (یزو) نیز از بنادر مهم ماهی گیری است .<br />شهرهای بزرگ ژاپن که جمعیت آنها از <span class=\"hlight\" dir=\"rtl\">١٥٠</span> هزار متجاوز است بقرار ذیل میباشد:<br />بندر توکیو <span class=\"hlight\" dir=\"rtl\">٢٠٧٠٥٠٠</span> تن پایتخت کشور.<br />بندر ازاکا <span class=\"hlight\" dir=\"rtl\">٢٤٥٣٥٠٠</span> \" در جنوب هندو.<br />بندر ناگویا <span class=\"hlight\" dir=\"rtl\">٩٠٧٤٠٠</span> \" در جنوب هندو.<br />بندر کبه <span class=\"hlight\" dir=\"rtl\">٧٨٧٥٠٠</span> \" در کنار خلیج ازاکا.<br />شهرکیوتو <span class=\"hlight\" dir=\"rtl\">٧٦٥٠٠٠</span> \" در جنوب دریاچه ٔ بیوا.<br />بندر یوکوهاما <span class=\"hlight\" dir=\"rtl\">٦٢٠٢٠٠</span>\" در کنار خلیج توکیو.<br />بندر هیروشیما <span class=\"hlight\" dir=\"rtl\">٢٧٠٠٠٠</span> \" در جنوب هندو.<br />بندر فوکواوکا <span class=\"hlight\" dir=\"rtl\">٢٢٨٢٠٠</span> \" در شمال غربی کیوشو.<br />بندر ناکازاکی <span class=\"hlight\" dir=\"rtl\">٢٠٤٠٠٠</span> \" درمغرب کیوشو.<br />بندر هاکوداته <span class=\"hlight\" dir=\"rtl\">١٩٧٢٠٠</span>\" در جنوب هوکائیدو.<br />بندر کوره <span class=\"hlight\" dir=\"rtl\">١٩٠٢٠٠</span> \" در جنوب بندر هیروشیما.<br />بندر سن دائی <span class=\"hlight\" dir=\"rtl\">١٩٠٠٠٠</span> \" در ساحل شرقی هندو.<br />شهر ساپورو <span class=\"hlight\" dir=\"rtl\">١٦٨٥٠٠</span> \" در جزیره ٔ هوکائیدو.<br />شهر یاواتا <span class=\"hlight\" dir=\"rtl\">١٦٨٢٠٠</span>\" در شمال کیوشو.<br />شهر کوماموتو <span class=\"hlight\" dir=\"rtl\">١٦٤٤٠٠</span> \" در مغرب کیوشو.<br />بندر کانازاوا <span class=\"hlight\" dir=\"rtl\">١٥٧٣٠٠</span> \" در ساحل غربی هندو.<br />علاوه بر این، جمعیت دوازده شهر دیگر بیش از صد هزار و جمعیت <span class=\"hlight\" dir=\"rtl\">٧٩</span> شهر از سی تا صد هزار است .<br />جغرافیای اقتصادی ژاپن <br />فلاحت چندی یگانه وسیله ٔ امرار معاش مردم ژاپن بود، چنانکه امروز هم از وسائل مهم زندگانی ایشان بشمار میرود. در ژاپن دوسوم از اهالی در مزارع بسر میبرند، معهذا در جزایر ژاپن اراضی قابل کشت و زرع نسبت به مساحت جزایر مزبور کم است و فقط شش ملیون هکتار زمین یعنی صدی پانزده از اراضی آن مملکت قابل زراعت است و تقریباً عموم خانواده ها مالک زمینی هستند و کمتر خانواده ای است که لااقل یک هکتار زمین نداشته باشد و قریب پنج ملیون هکتار مخصوص کشت غلات است و از این مقدار درسه ملیون هکتار تنها برنج میکارند. غیر از جزیره ٔ هوکائیدو که از جهت سرمای شدید قابل کشت برنج نیست، در سایر جزایر بزرگ عموماً کشت این محصول رائج است و محصول سالیانه ٔ آن به یازده ملیون تن میرسد. غیر از ناحیه ٔ جنوبی جزیره ٔ شی ککو که در سال دوبار حاصل میدهد، در سایر نواحی فقط سالی یک مرتبه برنج میکارند، ولی پس از آنکه در ماه آبان (نوامبر) محصول برنج برداشته شد بیدرنگ نیمی از مزارع گود برنج را از خاک نیم دیگر انباشته در کشت غلات دیگر یا شلغمهای بزرگی که غالباً طول آن به یک متر میرسد و بزبان ژاپنی دائی کن نام دارد بکار میبرند. گذشته از برنج سایر غلات و حبوبی که در ژاپن کاشته میشود جو و گندم و ارزن و لوبیای قرمز است . جو و گندم را در نواحی کوهستانی مخصوصاً در جلگه های مرکزی جزیره ٔ هندو میکارند. کشت چای که مخصوص نواحی گرمسیر و مرطوب است تا سی و شش درجه ٔ عرض شمالی متداول میباشد.کشت توتون هم که از قرن شانزدهم بتوسط تجار پرتقالی در ژاپن معمول شده جز در جزایر شمالی در سایر نواحی رونقی ندارد. ژاپنی ها در توسعه ٔ زراعت پنبه کوشش بسیار کرده اند ولی باز محصول آن برای مصرف کارخانه های مملکت کافی نیست . نیشکر در جزایر جنوبی مانند شی ککو و کیوشو و مخصوصاً تائی وان کاشته میشود. تربیت کرم ابریشم در ژاپن بسیار رائج است و <span class=\"hlight\" dir=\"rtl\">٩٥</span> درصد از ابریشم ژاپن از جزیره ٔ هندو حاصل میشود. محصول سالیانه ٔ ابریشم ژاپن قریب <span class=\"hlight\" dir=\"rtl\">٣٠٠</span> ملیون کیلوگرم پیله است . بهای صادرات ابریشم ژاپن در سال <span class=\"hlight\" dir=\"rtl\">١٩٣٢</span> قریب <span class=\"hlight\" dir=\"rtl\">٣٨٢٣٦٦٠٠٠</span> ین یا <span class=\"hlight\" dir=\"rtl\">١٠٧٤٨٣٠٠٠</span> دلار بوده است و از این مقدار معادل <span class=\"hlight\" dir=\"rtl\">١٠٦١٨٨٠٠٠</span> دلار به آمریکا صادر شده است .<br />گله داری : گله داری در ژاپن رونقی ندارد، چه مردم غالباً بنابر عقاید دینی خویش از خوردن گوشت احتراز میکنند و فقط گوشت خوک و طیوربکار میرود. عده ٔ اسبانی که در سال تربیت می کنند درحدود یک ملیون و نیم است و عده ٔ گاوانی که در امور فلاحتی بکار میبرند نیز از این مقدار بیشتر نیست .<br />ماهیگیری : در ژاپن ماهیگیری اهمیت بسیار دارد زیرا خوراک مردم آن بیشتر برنج و ماهی است . دریاهای اطراف ژاپن نیز بکثرت ماهی مشهور عالم است، چنانکه در هیچیک از نقاط دنیا ماهیگیری به پایه ٔ سواحل جزیره ٔ کارافوتو (ساخالین ) نمیرسد. در مقابل جزیره ٔ هوکائیدو چون محل تلاقی جریانهای دریائی سرد و گرم است انواع ماهیها مانند ماهی روغنی و ماهی آزاد و غیره به آسانی گرفته میشود.<br />صنایع ژاپن <br />با آنکه در ژاپن امور فلاحتی در ترقی است باز محصولات فلاحتی برای تغذیه ٔ اهالی کافی نیست و ژاپن ناگزیر است که مقداری ماهی و برنج از هندوستان و هندوچین بخرد. پس برای جبران این امر و نیز برای اینکه حتی الامکان خود را از نفوذ اقتصادی ممالک اروپائی و آمریکائی محفوظ دارد ناچار به امور صنعتی متوجه شده و در ترویج و توسعه ٔ آن کوشش فراوان کرده است . صنایع ژاپن بر دو گونه است : یکی صنایع ملی قدیمی و دیگر صنایع تازه ٔ اروپایی . مقصود از صنایع ملی قدیمی صنایعی است که در ژاپن پیش از آنکه این کشور به تمدن اروپائی آشنا شود نیز متداول بوده است، مانند بافتن پارچه های ابریشمین بسیار لطیف و قالی و حصیرهای زیبا و ساختن ظروف چینی و بدل چینی با نقش و نگارهای دلپسند و بادبزنها و پرده های منقش و اشیاء دیگری از چوب هی نوکی یا از مینا یا از برنج و امثال آن . اینگونه صنایع هنوز هم در زندگانی اقتصادی ژاپن اهمیت و مقام خاص دارد و تا سال <span class=\"hlight\" dir=\"rtl\">١٩١٤</span> سی و پنج درصد از جمع مصنوعات کشور از اینگونه بود. صنایع تازه ٔ اروپائی از اواخر قرن نوزدهم در ژاپن رواج یافت و چنان بسرعت ترقی کرد که امروز ژاپن از جمله ٔ ممالک صنعتی بزرگ دنیا بشمار است . سبب ترقی فوق العاده ٔ اینگونه صنایع کمی مزد کارگران و مداخله ٔ دولت و ترویج صنایع و کمک به مؤسسات صنعتی و ایجاد وسائل حمل و نقل و تلگراف و تلفن و امثال آن است .علاوه بر این دولت ژاپن از جنگ بین المللی اول نیز استفاده کرد و چون در جنگ مداخله ٔ مستقیم مؤثری نداشت از لحاظ اقتصادی سود فراوان برد (برخلاف جنگ اخیر).<br />محصولات معدنی ژاپن به پایه ٔ چین و هند نمیرسد. معادن زغال سنگ در غالب جزایر موجود است، مخصوصاً در جزایر هندو و هوکائیدو و کیوشو که سه چهارم از محصولات زغال سنگ ژاپن از آنجاست، ولی چون زغال معادن داخلی برای کارخانه ها کافی نیست همه ساله مقداری زغال و کک از چین میخرند. معادن گوگرد ژاپن بسبب وجود کوههای آتشفشان بسیار است و از اینجهت پس از ایتالیا و آمریکا در مرتبه ٔ سوم قرار دارد. محصول طلا و نقره ٔ ژاپن در قرون جدید معروف عالم بود و تجار پرتقالی از آن سرزمین طلای فراوان بردند، ولی امروز مهم نیست . در محصول مس نیز سرزمین ژاپن پس از ممالک متحده ٔ آمریکا و شیلی و کنگوی بلژیک و کانادا در مرتبه ٔ پنجم است . ولی آهن قابلی ندارد. منگنز از معادن اطراف کیوتو و جزیره ٔ هوکائیدو بسیار استخراج میشود. محصول نفت ژاپن بسیار نیست و در حدود دوصدم از محصول نفت تمام دنیاست . در ژاپن از آبشارها استفاده ٔ بسیار میکنند و پس از ممالک متحده ٔ آمریکا و کانادا هیچ کشوری در استفاده ٔ از قوه ٔآب به پای ژاپن نمیرسد. از جمله مهمترین صنایع تازه ٔ ژاپن نساجی است که از زمان جنگ بین المللی اول ترقی بسیار کرده و مخصوصاً بافتن پارچه های ابریشمی و پشمی و پنبه ای چنان رونق یافت که ژاپن در ممالک آسیای شرقی و حتی در هندوستان از جمله ٔ رقیبان بزرگ انگلیس گشت . ژاپن پشم خام را از استرالیا وارد کرده و در کارخانه های داخلی برای بافتن مهیا می سازد و همه ساله مقدار کثیری آهن و فلزات دیگر از ممالک بیگانه وارد میکند و در نواحی مرکزی هندو در شهرهای ازاکا و یوکوهاما، موروران کارخانه های پولادکاری بزرگ برپاست و در بنادر ناکازاکی و کوبه و یوکوهاما و ازاکا کارخانه های کشتی سازی بسیار است . شهرازاکا و نواحی اطراف آن مرکز صنایع تازه ٔ ژاپن است .در این شهر کارخانه های پارچه بافی و نخ تابی بقدری است که آن را منچستر ژاپن خوانده اند. علاوه بر این شهر مزبور دارای ضرابخانه و قورخانه و کارخانه های بزرگ شیشه سازی و کاغذسازی و کبریت سازی و امثال آن است . شهرتوکیو نیز مرکز بافتن پارچه های ابریشمین و شهر ساکائی (در جنوب ازاکا) محل بافتن فرشهای کنفی و پارچه های پنبه ای است . گذشته از کارخانه های سابق الذکر کارخانه های بزرگی نیز برای کاغذسازی و ساختن اسباب بازیهای گوناگون و مواد شیمیائی وجود دارد و اجناس مزبور از جمله ٔ صادرات ژاپن میباشد. از زمانی که صنایع ژاپن رو به ترقی نهاد دایره ٔ روابط تجارتی آن کشور نیز با ممالک دیگر توسعه یافت و در سال <span class=\"hlight\" dir=\"rtl\">١٨٨٦</span> جمع واردات و صادرات ژاپن فقط <span class=\"hlight\" dir=\"rtl\">٣٠٠</span> ملیون فرانک فرانسه بود، ولی تا سال <span class=\"hlight\" dir=\"rtl\">١٩٢٧</span> حد متوسط تجارت سالیانه ٔ آن به ده هزار ملیون فرانک طلا رسید. از اینروی میتوان به ترقی فوق العاده ٔ تجارت آن مملکت پی برد. روابط تجارتی ژاپن با ممالک متحده ٔ آمریکا بیش ازسایر دول عالم است، چه از ممالک مزبور همه ساله مقدار کثیری پنبه و مصنوعات فلزی میخرد و مقدار بسیاری از ابریشم و چای خود را به آن ممالک می فروشد. ژاپن قسمت مهمی از تجارت چین و هند و ممالک شرقی آسیا را پیش از جنگ اخیر به خود منحصر کرده بود، چنانکه همیشه مقدار کثیری زغال سنگ و آهن و چدن و فولاد و پنبه ٔ خام از چین و هند میخرید و مصنوعات کارخانه های خود مانند ماشینهای گوناگون و کاغذ و کبریت و پارچه های پنبه ای را در آن ممالک و هندوچین بفروش میرسانید. توسعه ٔ تجارت ژاپن در چین و هند و استرالیا موجب شکست فاحش تجارت انگلستان و ممالک متحده ٔ آمریکا گردید. برای تسهیل امر تجارت دولت ژاپن در ساختن خطوط آهن و توسعه ٔ نیروی دریائی تجارتی کوشش بسیار کرده است . امروز طول مجموع خطوط آهن ژاپن متجاوز از <span class=\"hlight\" dir=\"rtl\">٢٧٤٠٠</span> کیلومتر است و عده ٔ کشتیهای تجارتی آن در سال <span class=\"hlight\" dir=\"rtl\">١٩٣٢</span>، <span class=\"hlight\" dir=\"rtl\">٣٣٣٨</span> کشتی با گنجایش <span class=\"hlight\" dir=\"rtl\">٣٨٩٤٨١٩</span> تن بوده . امروز کشتیهای شرکتهای بزرگ کشتیرانی ژاپن مانند توگوکیزن کائیشا و نی پون یوشن کائیشا و ازاکاچزن کائیشا مرتباً در اقیانوس کبیر و اقیانوس هند و حتی در دریاهای اروپائی سیر میکنند، چنانکه پیش از جنگ اخیر ازجمع واردات ژاپن شصت درصد و از جمع صادرات آن هفتادو سه درصد توسط کشتیهای ژاپنی حمل و نقل میشد.<br />نیروی دریائی ژاپن بموجب احصائیه ٔ سال <span class=\"hlight\" dir=\"rtl\">١٩٣٦</span> بقرار ذیل بوده است :<br />نوع کشتی عده گنجایش <br />زره دار <span class=\"hlight\" dir=\"rtl\">١١</span> <span class=\"hlight\" dir=\"rtl\">٣٠٧٠٧٠</span> تن <br />حامل هواپیما <span class=\"hlight\" dir=\"rtl\">٦</span> <span class=\"hlight\" dir=\"rtl\">٨٨٤٧٠</span> تن <br />رزم ناو (طبقه ٔ <span class=\"hlight\" dir=\"rtl\">١</span>) <span class=\"hlight\" dir=\"rtl\">١٣</span> <span class=\"hlight\" dir=\"rtl\">١١٦٤٤٠</span> تن <br />رزم ناو (طبقه ٔ <span class=\"hlight\" dir=\"rtl\">٢</span>) <span class=\"hlight\" dir=\"rtl\">٢٦</span> <span class=\"hlight\" dir=\"rtl\">١٤٤٣٢٥</span> تن <br />ناوشکن <span class=\"hlight\" dir=\"rtl\">١١٥</span> <span class=\"hlight\" dir=\"rtl\">١٤٥٥٨٣</span> تن <br />زیردریائی <span class=\"hlight\" dir=\"rtl\">٦٢</span> <span class=\"hlight\" dir=\"rtl\">٨٠٢٨٤</span> تن <br />که جمعاً <span class=\"hlight\" dir=\"rtl\">٢٣٣</span> کشتی بظرفیت <span class=\"hlight\" dir=\"rtl\">٨٨٢١٧٢</span> تن میباشد.<br />جمع واردات ژاپن در سال <span class=\"hlight\" dir=\"rtl\">١٩٣٣</span>، <span class=\"hlight\" dir=\"rtl\">١٨٦١٠٤٦٠٠٠</span> تن و جمع صادرات آن کشور در همان سال <span class=\"hlight\" dir=\"rtl\">١٩١٧٢٢٠٠٠٠</span> تن بوده است .<br />متصرفات ژاپن پیش از جنگ جهانی اول : ترقی ناگهانی ژاپن و افزایش دائمی جمعیت آن کشور دولت </font></div>'),
(287840, 'ژاپه', '<span class=\"hlight\">ژاپه .</span> <font color=\"DarkGreen\"><b>[ پ ِ ]</font></b> (اِخ ) نام یکی از تیتان ها پسراُرانوس و گ ِآ برادر کرونوس و پدر پرومته و اطلس و اپی مته و منتیوس .<br /></font></div>'),
(287841, 'ژاپون', '<span class=\"hlight\">ژاپون .</span> (اِخ ) ژاپن . رجوع به ژاپن شود.<br /></font></div>'),
(287842, 'ژاژ', '<span class=\"hlight\">ژاژ.</span> (اِ) گیاهی بود که آن را کنگر گویند و تره ٔ دوغ کنند. (نسخه ای از لغت نامه ٔ اسدی ). گیاهی باشد که اندر تره ٔ دوغ کنند. (لغت نامه ٔ اسدی ). گیاهی است که تره ٔ دوغ از وی سازند یعنی ریچال . (صحاح الفرس ). از تعریف های فوق خوب پیداست که ژاژ، کاکوتی (ککلیک اوتی ) معروف است که آن را نتوان جویدن، چه آب به خود نگیرد و آن گیاهی خرد است در صحرا چون خارهای خرد و با شاخهای خرد و معطر که برای عطر در دوغ و ماست کنند و هیچ مصرف دیگر جز این ندارد.<br />صاحب آنندراج گوید: گیاهی است شبیه به درمنه در نهایت بیمزگی و ناگواری که هرچند شتر آن را بخاید نرم نشود و بجهت بیمزگی فرونبردو آن را به تازی غلیص خوانند. صاحب برهان گوید: بوته ٔ گیاهی باشد بغایت سپید و شبیه به درمنه در نهایت بیمزگی و هرچند شتر آن را بخاید نرم نشود و بسبب بیمزگی فرونبرد و بعضی مطلق تره ٔ دوغ را گفته اند یعنی آنچه از رستنی که در دوغ و ماست کنند و علفی را نیز گویند خاردار که در ماست کنند و آن را کنگر خوانند و جمعی گویند علفی است که بی تخم میروید و آن نوعی از درمنه است که بدان آتش افروزند و این بمعنی اول نزدیک است و بعضی گویند هر علفی که بی تخم روید و بعضی گفته اند علفی است که آن را شتر خورد و بعربی غلیص خوانند -انتهی . گیاهی است سفید و خاردار و سخت بدمزه که اشتر چندانکه بخاید به حلق فروبردن نتواند. (غیاث ). غلیص . (مهذب الاسماء) <span class=\"hlight\">:</span> ملک بوقت بهار هر سال به دشت بیرون شدی با خاصگان خویش و آنجا خیمه زدی وتا گرم نشدی آنجا بودی و از آن چیزها که از زمین روید چون گیاهها و ژاژها از مفارج (؟) و مجه همی چیدندی و همی خوردندی . (ترجمه ٔ طبری بلعمی ).<br />ژاژ میخایم و ژاژم شده خشک <br />خار دارد همه چون نوک بغاز.<br /><font color=\"Red\">ابوالعباس .</font><br />ای میر شاعرانت همه آنک <br />من ژاژ نی ولیکن فرغستم .<br /> <font color=\"Red\">لمعانی عباسی .</font><br />ژاژ داری تو و هستند بسی ژاژخوران <br />وین عجب نیست که یازند سوی ژاژ خران .<br /> <font color=\"Red\">عسجدی .</font><br /> <BR><font color=\"Blue\">◄</font> کنایه از سخنان هرزه و یاوه و بی مزه و هذیان هم هست . (برهان ). مجازاً بمعنی سخن بیهوده و گفته ٔ باطل و بیفایده و هرزه . اسدی در لغت نامه ذیل لغت یافه گوید: یافه و خله و ژاژ و لک، سخنان بیهوده بود. هرزه . هذیان . بیهده . بیهوده از سخن و غیر آن <span class=\"hlight\">:</span> <br />پس ار ژاژ و خوهل آوری پیش من <br />همت خوهل پاسخ دهد پیرزن (کذا).<br /> <font color=\"Red\">ابوشکور.</font><br />چو برسم بدید اندرآمد به باژ<br />نه گاه سخن بود و گفتار ژاژ.<br /> <font color=\"Red\">فردوسی .</font><br />ایا ز بیم زبانم نژند گشته و هاژ<br />کجا شد آنهمه دعوی کجا شد آنهمه ژاژ.<br /> <font color=\"Red\">لبیبی .</font><br />نامه ٔ مانی با نامه ٔ تو ژاژ است <br />شعر خوارزمی با شعر تو لامانی .<br /> <font color=\"Red\">فرخی .</font><br />من اینهمه ز طریق مطایبت گفتم <br />مگر نگوئی کاین ژاژ باشد و هذیان .<br /> <font color=\"Red\">فرخی .</font><br />شعر ژاژ از دهان من شکر است <br />شعر نیک از دهان تو پینو.<br /> <font color=\"Red\">طیان .</font><br />این مُشتی ژاژ است که بوالحسن و دیگران نبشته اند. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٦٦١</span>).<br />صدگونه ژاژ و بیخردی کرد و نیز گفت <br />بر هر کسی نثار و برو بند و گیر و دار.<br /> <font color=\"Red\">سوزنی .</font><br />غرر سحر ستانید که خاقانی راست <br />ژاژ منحول به دزدان غرربازدهید.<br /> <font color=\"Red\">خاقانی .</font><br />شعر استادان فرود ژاژهای خود نهم <br />سخت سخت آمدخرد را اینکه منکر منکرم .<br /> <font color=\"Red\">خاقانی .</font><br />بر دشمن تو خندد گردون چو مرد عاقل <br />بر هزلهای جحی بر ژاژهای طیان .<br /> <font color=\"Red\">پیغوملک .</font><br />وین چه ژاژ است دگرباره که ابیات مدیح <br />گر بود هفت فرستی به تقاضا هفتاد.<br /> <font color=\"Red\">اثیر اومانی .</font><br />این چه ژاژ است و چه هرزه ای فلان <br />من حقیقت یافتم چبودنشان .<br /> <font color=\"Red\">مولوی .</font><br />این چه ژاژ است این چه کفر است و فشار<br />پنبه ای اندر دهان خود فشار.<br /> <font color=\"Red\">مولوی .</font><br />شهوتی ّ است او و بس شهوت پرست <br />زان شراب زهرناک ژاژ مست .<br /> <font color=\"Red\">مولوی .</font><br />خادع دردند درمانهای ژاژ<br />ره زنند و زرستانان رسم باژ.<br /> <font color=\"Red\">مولوی .</font><br /><BR><font color=\"Blue\">◄</font> قسمی از هیزم باشد که آتش بدان افروزند و برفور شعله اش فرونشیندو فروزینه هم گویند. (از فرهنگی خطی ).<br /></font></div>'),
(287843, 'ژاژ گفتن', '<span class=\"hlight\">ژاژ گفتن .</span> <font color=\"DarkGreen\"><b>[ گ ُ ت َ ]</font></b> (مص مرکب ) بیهوده و هزل گفتن . رجوع به ژاژ خائیدن شود <span class=\"hlight\">:</span> <br />همه گوینده ٔ فسق و فجوریم <br />ز هزل و ژاژ گفتن ابکمی کو.<br /><font color=\"Red\">سنائی .</font><br /></font></div>'),
(287844, 'ژاژخا', '<span class=\"hlight\">ژاژخا.</span> (اِخ ) ژاژخای . لقب طَیّان شاعر. رجوع به طیّان شود <span class=\"hlight\">:</span> <br />صبح حَسّان مصطفائی کو<br />تا ثناهای غم زدا آرد<br />زانکه مقبول مصطفی نشود<br />آنچه طیان ژاژخا آرد.<br /><font color=\"Red\">انوری .</font><br /></font></div>'),
(287845, 'ژاژخا', '<span class=\"hlight\">ژاژخا.</span> (نف مرکب ) ژاژخای . بیهوده گوی . بیهده گوی . ول گوی . هرزه درای . هرزه گوی . هرزه سرای . هرزه لای . لک درای . خام درای . کسی که سخن بی معنی و بی فایده گوید. یافه گو. یاوه سرای . یاوه گو. <BR><font color=\"Blue\">◄</font> مِهْذار. هَذر. پرگوی . پرچانه . درازنفس . پُرنفس . مِکْثار. ورّاج (در تداول عوام ) <span class=\"hlight\">:</span> <br />گفت ریمن مرد خام لک درای <br />پیش آن فرتوت پیر ژاژخای .<br /> <font color=\"Red\">لبیبی .</font><br /> <br />وی از خشم برآشفت و مردکی پُرمنش و ژاژخای و بادگرفته بود. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٣٣٧</span>).<br />گاو خاموش نزد مرد خرد<br />به از آن ژاژخای صد بار است .<br /><font color=\"Red\">ناصرخسرو.</font><br />ز بهر چیز بیحاصل نرنجی به بود ایرا<br />بسی بهتر سوی دانا ز مردژاژخا ابکم .<br /> <font color=\"Red\">ناصرخسرو.</font><br />پاک مردان چو ماهیندخموش <br />ژاژخایان خلق چون عصفور.<br /> <font color=\"Red\">ناصرخسرو.</font><br />ز خوشه چینی کشت نیاز هست عدوت <br />خمیده پشت و شکم خوار و ژاژخای چو داس .<br /> <font color=\"Red\">کمال اسماعیل .</font><br />این سیاه اسرار تن اسپید را<br />بت پرستانه بگیر ای ژاژخا.<br /> <font color=\"Red\">مولوی .</font><br />جمع آمد صدهزاران ژاژخا<br />حلقه کرده پشت پا بر پشت پا.<br /> <font color=\"Red\">مولوی .</font><br />تأمل کنان در خطا و صواب <br />به از ژاژخایان حاضرجواب .<br /> <font color=\"Red\">سعدی (بوستان ).</font><br />روشن درون و تفته دل و گرم و ژاژخای <br />آتش نهاد و خاکی و معمور دودمان .<br /><font color=\"Red\">خواجو (در وصف حمام ).</font><br /></font></div>'),
(287846, 'ژاژخای', '<span class=\"hlight\">ژاژخای .</span> (اِخ ) لقب طیان شاعر. رجوع به ژاژخا و طیان شود.<br /></font></div>'),
(287847, 'ژاژخای', '<span class=\"hlight\">ژاژخای .</span> (نف مرکب ) رجوع به ژاژخا شود <span class=\"hlight\">:</span> <br />دل به بیهوده ای مکن مشغول <br />که فلان ژاژخای می خاید.<br /><font color=\"Red\">ناصرخسرو.</font><br /></font></div>'),
(287848, 'ژاژخوار', '<span class=\"hlight\">ژاژخوار.</span> <font color=\"DarkGreen\"><b>[ خوا <span class=\"hlight\" dir=\"rtl\">/</span> خا ]</font></b> (نف مرکب ) بیهوده گو. یاوه گو. ژاژخای در همه ٔ معانی <span class=\"hlight\">:</span> <br />کارهای شیرمردان کردی و ازرشک تو<br />حاسدانت یاوه گو هستند و جمله ژاژخوار.<br /><font color=\"Red\">فرخی .</font><br /></font></div>'),
(287849, 'ژاژدرای', '<span class=\"hlight\">ژاژدرای .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (نف مرکب ) بیهوده گو. یاوه گوی . ژاژخای <span class=\"hlight\">:</span> <br />کسی که گوید من چون توام بفضل و هنر<br />سبک خرد بود و یاوه گوی و ژاژدرای .<br /><font color=\"Red\">فرخی .</font><br /></font></div>'),
(287850, 'ژاژلن', '<span class=\"hlight\">ژاژلن .</span> <font color=\"DarkGreen\"><b>[ ژِل ْ ل ُ ]</font></b> (اِخ ) نام خانواده ای از مردم لیتوانی که بر لهستان (از <span class=\"hlight\" dir=\"rtl\">١٣٨٦</span> تا <span class=\"hlight\" dir=\"rtl\">١٥٧٢</span> م .) و بوهم و هنگری سلطنت کردند و مؤسس آن لادیسلاس ژاژلن بود.<br /></font></div>'),
(287851, 'ژاژمک', '<span class=\"hlight\">ژاژمک .</span> <font color=\"DarkGreen\"><b>[ ژُ م َ ]</font></b> (اِ) دانه ٔ لوبیا را گویند. و آن مخفف ژاژومک است .<br /></font></div>'),
(287852, 'ژاژه', '<span class=\"hlight\">ژاژه .</span> <font color=\"DarkGreen\"><b>[ ژَ <span class=\"hlight\" dir=\"rtl\">/</span> ژِ ]</font></b> (اِ) ژاژ. علف بیمزه . <BR><font color=\"Blue\">◄</font> سخنان هرزه . (برهان ).<br /></font></div>'),
(287853, 'ژاژومک', '<span class=\"hlight\">ژاژومک .</span> <font color=\"DarkGreen\"><b>[ م َ ]</font></b> (اِ) لوبیا را گویند و آن تخمی است که بعربی لیاء خوانند. (برهان ). رجوع به لوبیا شود.<br /></font></div>'),
(287854, 'ژاژوک', '<span class=\"hlight\">ژاژوک .</span>(اِ) در بعض فرهنگها بدان معنی لوبیا داده اند و آن ظاهراً غلط و صحیح ژاژومک باشد چنانکه در فرهنگ جهانگیری، سروری، برهان، سراج و غیاث اللغات آمده است .<br /></font></div>'),
(287855, 'ژاژک', '<span class=\"hlight\">ژاژک .</span> <font color=\"DarkGreen\"><b>[ ژُ ]</font></b> (اِ) در بعض لغت نامه ها آن را به لوبیا ترجمه کرده اند. (حاشیه ٔ لغت نامه ٔ اسدی ). و بیت زیرین در ذیل کلمه ٔ کوم در فرهنگ اسدی آمده است و معنی کلمه چنانکه معنی تمام شعر معلوم نیست <span class=\"hlight\">:</span> <br />ماه کانون است ژاژک نتوانی بستن <br />هم از این کومک بر خشک و همی بند آن را.<br /> <font color=\"Red\">ابوالعباس .</font><br />رجوع به ژاژمک و ژاژومک شود.<br /></font></div>'),
(287856, 'ژاژیدن', '<span class=\"hlight\">ژاژیدن .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (مص ) ژاژ خائیدن . هرزه گفتن . (کذا فی تحفة السعادة) <span class=\"hlight\">:</span> <br />خواری از او بس بود آن کت کند<br />رنجه به ژاژیدن بسیار خویش .<br /> <font color=\"Red\">ناصرخسرو.</font><br />شعر ژاژیدن لهاشم تست <br />علک خائیدن لهاشم خر.<br /> <font color=\"Red\">سوزنی .</font><br /><BR><font color=\"Blue\">◄</font> نشخوار کردن . <BR><font color=\"Blue\">◄</font> عوعو کردن مثل سگ . (آنندراج ).<br /></font></div>'),
(287857, 'ژاک', '<span class=\"hlight\">ژاک .</span> (اِخ ) یا جیم سوم . پادشاه اسمی میورقه (<span class=\"hlight\" dir=\"rtl\">١٣٣٦</span> - <span class=\"hlight\" dir=\"rtl\">١٣٧٥</span> م .).<br /></font></div>'),
(287858, 'ژاک', '<span class=\"hlight\">ژاک .</span> (اِخ ) یا جیم دوم . پادشاه میورقه، پسر کوچک ژاک جیم اول (<span class=\"hlight\" dir=\"rtl\">١٣١٥</span> - <span class=\"hlight\" dir=\"rtl\">١٣٤٩</span> م .).<br /></font></div>'),
(287859, 'ژاک', '<span class=\"hlight\">ژاک .</span> (اِخ ) یا جیم اول . پادشاه میورقه (<span class=\"hlight\" dir=\"rtl\">١٢٤٣</span> - <span class=\"hlight\" dir=\"rtl\">١٣١١</span> م .). وی پسر ژاک اول پادشاه آراگون بود.<br /></font></div>'),
(287860, 'ژاک', '<span class=\"hlight\">ژاک .</span> (اِخ ) (قدیس ) نام اسقف نصیبین از علمای عالیقدر کلیسای سریانی (<span class=\"hlight\" dir=\"rtl\">٢٧٠</span> - <span class=\"hlight\" dir=\"rtl\">٣٥٠</span> م .).<br /></font></div>'),
(287861, 'ژاک', '<span class=\"hlight\">ژاک .</span> (اِخ ) ملقب به شهید، معاصر بهرام پنجم ساسانی . وی از عیسویانی است که از انکار دیانت خود امتناع کردند و بفرمان شاهنشاه ساسانی به مجازات «نُه مرگ » محکوم شدند زیرادر مقابل محکمه ٔ شاهی جسورانه تذکر داده بودند که یزدگرد اول نیز چون از رفتار نیک خود نسبت به عیسویان دست کشید در حالی مرد که همه از او کناره کرده بودند و بعد از مرگ نیز جسد او را در مدفن قرار ندادند. (ایران در زمان ساسانیان ترجمه ٔ رشیدیاسمی ص <span class=\"hlight\" dir=\"rtl\">٢١٧</span>).<br /></font></div>'),
(287862, 'ژاک', '<span class=\"hlight\">ژاک .</span> (اِخ ) (قدیس ) او را ژاک لوماژور نیز گویند. از حواریون مسیح، پسر زبده و برادر یوحنای انجیلی متولد به بیت سعید (جلیله ) مقارن سال <span class=\"hlight\" dir=\"rtl\">١٢</span> ق .م . او در سال <span class=\"hlight\" dir=\"rtl\">٤٤</span> م . در شهر اورشلیم به شهادت رسید. ذکران و یادکرد او در بیست وپنجم ژوئیه است .<br /></font></div>'),
(287863, 'ژاک', '<span class=\"hlight\">ژاک .</span> (اِخ ) شارل امیل . نقاش و گراورساز فرانسوی، متولد و متوفی به پاریس (<span class=\"hlight\" dir=\"rtl\">١٨١٣</span> - <span class=\"hlight\" dir=\"rtl\">١٨٩٤</span> م .). وی را بهترین نقاشی های آب ورنگی هست و موضوع آنها غالباً زندگانی روستائی است .<br /></font></div>'),
(287864, 'ژاک اول', '<span class=\"hlight\">ژاک اول .</span> <font color=\"DarkGreen\"><b>[ ک ِ اَوْ وَ ]</font></b> (اِخ ) متولد بسال <span class=\"hlight\" dir=\"rtl\">١٢٠٨</span> م . او را جیم اول و فاتح نیز نامند. وی پادشاه آراگون بود (از <span class=\"hlight\" dir=\"rtl\">١٢٣١</span> تا <span class=\"hlight\" dir=\"rtl\">١٢٧٦</span> م .).<br /></font></div>'),
(287865, 'ژاک اول', '<span class=\"hlight\">ژاک اول .</span> <font color=\"DarkGreen\"><b>[ ک ِ اَوْ وَ ]</font></b> (اِخ ) استوارت . متولد بسال <span class=\"hlight\" dir=\"rtl\">١٤٠٦</span> م . پادشاه اکُس از <span class=\"hlight\" dir=\"rtl\">١٤٢٣</span> تا <span class=\"hlight\" dir=\"rtl\">١٤٣٧</span> م .<br /></font></div>'),
(287866, 'ژاک بنم', '<span class=\"hlight\">ژاک بنم .</span> <font color=\"DarkGreen\"><b>[ ب ُ ن ُ ]</font></b> (فرانسوی، اِ مرکب ) نامی که گاهی در مقام تحقیر دهقان فرانسوی را دهند و غرض از آن کسی است که تن به هر بندگی و بیگاری و حقارت دهد.<br /></font></div>'),
(287867, 'ژاک دولپه', '<span class=\"hlight\">ژاک دولپه .</span> <font color=\"DarkGreen\"><b>[ دُ ل ِ پ ِ ]</font></b> (اِخ ) رجوع به سنت ژاک دولپه شود.<br /></font></div>'),
(287868, 'ژاک دوم', '<span class=\"hlight\">ژاک دوم .</span> <font color=\"DarkGreen\"><b>[ ک ِ دُوْ وُ ]</font></b> (اِخ ) پسر شارل اول . متولد در قصر سن جیمز بسال <span class=\"hlight\" dir=\"rtl\">١٦٣٣</span> و متوفی در سن ژرمن بسال <span class=\"hlight\" dir=\"rtl\">١٧٠١</span> م . وی بسال <span class=\"hlight\" dir=\"rtl\">١٦٨٥</span>پادشاه انگلیس شد. او سلطانی مستبد و جبار بود و بااحساسات ملی انگلیسیان . او با موافقت کردن با کاتولیکها و عقد اتحاد با لوئی چهاردهم مخالف بود. وی به دست گیوم ناسو شاهزاده ٔ ارانژ از تخت سلطنت خلع گردید و زندگانی خود را در فرانسه در قصر سن ژرمن واقع در لی به پایان رسانید.<br /></font></div>'),
(287869, 'ژاک دوم', '<span class=\"hlight\">ژاک دوم .</span> <font color=\"DarkGreen\"><b>[ ک ِ دُوْ وُ ]</font></b> (اِخ ) پادشاه اِکُس از <span class=\"hlight\" dir=\"rtl\">١٤٣٧</span> تا <span class=\"hlight\" dir=\"rtl\">١٤٦٠</span> م . متولد بسال <span class=\"hlight\" dir=\"rtl\">١٤٣٠</span> و متوفی بسال <span class=\"hlight\" dir=\"rtl\">١٤٦٠</span>.<br /></font></div>'),
(287870, 'ژاک دوم', '<span class=\"hlight\">ژاک دوم .</span> <font color=\"DarkGreen\"><b>[ ک ِ دُوْ وُ ]</font></b> (اِخ ) ملقب به عادل . پادشاه آراگون (<span class=\"hlight\" dir=\"rtl\">١٢٦٠</span> - <span class=\"hlight\" dir=\"rtl\">١٣٢٧</span> م .).<br /></font></div>'),
(287871, 'ژاک دووراژین', '<span class=\"hlight\">ژاک دووراژین .</span> <font color=\"DarkGreen\"><b>[ دُ وُ ]</font></b> (اِخ ) ملقب به سعید. مؤلف احوال اولیاء ایتالیائی . متولد در وراژین نزدیک ژن . نویسنده ٔ داستانهای طلائی (<span class=\"hlight\" dir=\"rtl\">١٢٢٨</span>-<span class=\"hlight\" dir=\"rtl\">١٢٩٨</span> م .).<br /></font></div>'),
(287872, 'ژاک دوویتری', '<span class=\"hlight\">ژاک دوویتری .</span> <font color=\"DarkGreen\"><b>[ دُ ]</font></b> (اِخ ) اُسقف و مورّخ و خطیب فرانسوی (<span class=\"hlight\" dir=\"rtl\">١١٨٠</span> - <span class=\"hlight\" dir=\"rtl\">١٢٤٠</span> م .).<br /></font></div>'),
(287873, 'ژاک سوم', '<span class=\"hlight\">ژاک سوم .</span> <font color=\"DarkGreen\"><b>[ ک ِ س ِوْ وُ ]</font></b> (اِخ ) یا ژاک فرانسیس ادوارد استوارت . یا شوالیه دسن ژرژ . پسر ژاک دوم انگلیسی، متولد در لندن بسال <span class=\"hlight\" dir=\"rtl\">١٦٨٨</span> و متوفی در آلبانو بسال <span class=\"hlight\" dir=\"rtl\">١٧٦٦</span> م . وی برای به دست آوردن تخت سلطنت مشقات بسیار متحمل شد و سرانجام نیز به مقصود نائل نگردید.<br /></font></div>'),
(287874, 'ژاک سوم', '<span class=\"hlight\">ژاک سوم .</span><font color=\"DarkGreen\"><b>[ ک ِ س ِوْ وُ ]</font></b> (اِخ ) پادشاه اِکُس از <span class=\"hlight\" dir=\"rtl\">١٤٦٠</span> تا <span class=\"hlight\" dir=\"rtl\">١٤٨٨</span>م . تولد وی بسال <span class=\"hlight\" dir=\"rtl\">١٤٥١</span> و مرگش بسال <span class=\"hlight\" dir=\"rtl\">١٤٨٨</span> بوده است .<br /></font></div>'),
(287875, 'ژاک ششم', '<span class=\"hlight\">ژاک ششم .</span> <font color=\"DarkGreen\"><b>[ ک ِ ش ِ ش ُ ]</font></b> (اِخ ) پسر ماری استوارت . متولد بسال <span class=\"hlight\" dir=\"rtl\">١٥٦٦</span> در ادیمبورگ و متوفی بسال <span class=\"hlight\" dir=\"rtl\">١٦٢٥</span> م . پادشاه اِکُس در <span class=\"hlight\" dir=\"rtl\">١٥٦٧</span> و پادشاه بریتانی کبیر از <span class=\"hlight\" dir=\"rtl\">١٦٠٣</span> تا <span class=\"hlight\" dir=\"rtl\">١٦٢٥</span>. این پادشاه در انگلستان به ژاک اول موسوم است . وی با سلطه و نفوذ مذهبی خود فرمان به آزار و تعقیب انقلابیون و آزادیخواهان انگلیس داد.<br /></font></div>'),
(287876, 'ژاک پنجم', '<span class=\"hlight\">ژاک پنجم .</span> <font color=\"DarkGreen\"><b>[ ک ِ پ َ ج ُ ]</font></b> (اِخ ) پادشاه اِکُس از <span class=\"hlight\" dir=\"rtl\">١٥١٣</span> تا <span class=\"hlight\" dir=\"rtl\">١٥٤٢</span> م . متولد بسال <span class=\"hlight\" dir=\"rtl\">١٥١٢</span> و متوفی بسال <span class=\"hlight\" dir=\"rtl\">١٥٤٢</span>. وی اتحاد با فرانسه را اعلام کرد. و اوپدر ماری استوارت است .<br /></font></div>'),
(287877, 'ژاک چهارم', '<span class=\"hlight\">ژاک چهارم .</span> <font color=\"DarkGreen\"><b>[ ک ِ چ َ رُ ]</font></b> (اِخ ) پادشاه اِکُس از <span class=\"hlight\" dir=\"rtl\">١٤٨٨</span> تا <span class=\"hlight\" dir=\"rtl\">١٥١٣</span> م . متولد بسال <span class=\"hlight\" dir=\"rtl\">١٤٧٣</span> و متوفی بسال <span class=\"hlight\" dir=\"rtl\">١٥١٣</span>.<br /></font></div>'),
(287878, 'ژاکا', '<span class=\"hlight\">ژاکا.</span> (اِخ ) شهر و قلعه ٔ اسپانیا (آراگون ) دارای <span class=\"hlight\" dir=\"rtl\">٥٠٠٠</span> تن سکنه . پایتخت قدیم کشور سوبرارب .<br /></font></div>'),
(287879, 'ژاکارد', '<span class=\"hlight\">ژاکارد.</span> (اِخ ) ژُزف ماری .مکانیسین فرانسوی، متولد در لیون . مخترع دستگاه بافندگی که باعث شهرت نام او گردید (<span class=\"hlight\" dir=\"rtl\">١٧٥٢</span> - <span class=\"hlight\" dir=\"rtl\">١٨٣٤</span> م .).<br /></font></div>'),
(287880, 'ژاکاند', '<span class=\"hlight\">ژاکاند.</span> (اِخ ) کلودیوس . نام نقاش فرانسوی، متولد به لیون و متوفی به پاریس (<span class=\"hlight\" dir=\"rtl\">١٨٠٥</span> - <span class=\"hlight\" dir=\"rtl\">١٨٧٨</span> م .).<br /></font></div>'),
(287881, 'ژاکب', '<span class=\"hlight\">ژاکب .</span> <font color=\"DarkGreen\"><b>[ ک ُ ]</font></b> (اِخ ) ماکس . نویسنده ٔ فرانسوی، متولد در کیمپر، متوفی در درانسی (<span class=\"hlight\" dir=\"rtl\">١٨٧٦</span>-<span class=\"hlight\" dir=\"rtl\">١٩٤٤</span> م .).<br /></font></div>'),
(287882, 'ژاکب', '<span class=\"hlight\">ژاکب .</span> <font color=\"DarkGreen\"><b>[ ک ُ ]</font></b> (اِخ ) کرتین . نام زبانشناس آلمانی، متولد در گتا (<span class=\"hlight\" dir=\"rtl\">١٧٦٤</span>-<span class=\"hlight\" dir=\"rtl\">١٨٤٧</span> م .). او مؤلف کتاب «منتخبات یونانی » است .<br /></font></div>'),
(287883, 'ژاکبی', '<span class=\"hlight\">ژاکبی .</span> <font color=\"DarkGreen\"><b>[ ک ُ ]</font></b> (اِخ ) شارل گوستاو ژاکب . ریاضی دان آلمانی، متولد در پوتسدام (<span class=\"hlight\" dir=\"rtl\">١٨٠٤</span>-<span class=\"hlight\" dir=\"rtl\">١٨٥١</span> م .).<br /></font></div>'),
(287884, 'ژاکبیت', '<span class=\"hlight\">ژاکبیت .</span> <font color=\"DarkGreen\"><b>[ ک ُ ]</font></b> (اِخ ) نامی است که پس ازانقلاب <span class=\"hlight\" dir=\"rtl\">١٦٨٨</span> م . در انگلستان به طرفداران ژاک دوم و خانواده ٔ استوارت دادند.<br /></font></div>'),
(287885, 'ژاکبیت', '<span class=\"hlight\">ژاکبیت .</span> <font color=\"DarkGreen\"><b>[ ک ُ ]</font></b> (اِخ ) یعقوبیه . رجوع به یعقوبیه و یعقوبیان شود.<br /></font></div>'),
(287886, 'ژاکبین', '<span class=\"hlight\">ژاکبین .</span> <font color=\"DarkGreen\"><b>[ ک ُ ]</font></b> (اِخ ) نام یکی از معروفترین انجمن های سیاسی انقلاب فرانسه . این انجمن متشکل بود از دسته ای از انقلابیون که جلسات خود را در صومعه ٔ قدیمی ژاکوبین واقع در کوچه ٔ سنت هونره در شهر پاریس منعقد میساختند و آن در اکتبر سال <span class=\"hlight\" dir=\"rtl\">١٧٨٩</span> م . به دست عده ای از انقلابیون پرشور تأسیس شد و تا سال <span class=\"hlight\" dir=\"rtl\">١٧٩٤</span> برپا بود.<br /></font></div>'),
(287887, 'ژاکت', '<span class=\"hlight\">ژاکت .</span> <font color=\"DarkGreen\"><b>[ ک ِ ]</font></b> (فرانسوی، اِ) نام نوعی از لباس مردانه که در مواقع رسمی پوشند. <BR><font color=\"Blue\">◄</font> نام قسمی از لباس زنانه .<br /></font></div>'),
(287888, 'ژاکتت', '<span class=\"hlight\">ژاکتت .</span> <font color=\"DarkGreen\"><b>[ ک ُ ت ُ ]</font></b> (اِخ ) ژان ژُزِف . عالم تعلیم و تربیت فرانسوی، متولد در دیژن . او موجد روش تعلیمات عمومی است . (<span class=\"hlight\" dir=\"rtl\">١٧٧٠</span>-<span class=\"hlight\" dir=\"rtl\">١٨٤٠</span> م .).<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(287889, 'ژاکسن', '<span class=\"hlight\">ژاکسن .</span> <font color=\"DarkGreen\"><b>[ س ُ ]</font></b> (اِخ ) اندریو. نام مردی از مردم ممالک متحده ٔ آمریکای شمالی، متولد در واکس هاو کارولین شمالی بسال <span class=\"hlight\" dir=\"rtl\">١٧٦٧</span> و متوفی بسال <span class=\"hlight\" dir=\"rtl\">١٨٤٥</span> م . وی از <span class=\"hlight\" dir=\"rtl\">١٨٢٩</span> تا <span class=\"hlight\" dir=\"rtl\">١٨٣٧</span> رئیس جمهور آمریکا بوده است .<br /></font></div>'),
(287890, 'ژاکسن ویل', '<span class=\"hlight\">ژاکسن ویل .</span> <font color=\"DarkGreen\"><b>[ س ُ ]</font></b> (اِخ ) نام شهری از ممالک متحده ٔ آمریکای شمالی در فلورید بر ساحل رود سنت جون، دارای <span class=\"hlight\" dir=\"rtl\">١٧٣٠٠٠</span> تن سکنه .<br /></font></div>'),
(287891, 'ژاکلین', '<span class=\"hlight\">ژاکلین .</span> <font color=\"DarkGreen\"><b>[ ک ِ ]</font></b> (اِخ ) کنتس هِنوت و هلند و زلاند متولد به لاهه (<span class=\"hlight\" dir=\"rtl\">١٤٠١</span>-<span class=\"hlight\" dir=\"rtl\">١٤٣٦</span> م .).<br /></font></div>'),
(287892, 'ژاکلیو', '<span class=\"hlight\">ژاکلیو.</span> <font color=\"DarkGreen\"><b>[ ک ُ ی ُ ]</font></b> (اِخ ) لوئی . نویسنده ٔ فرانسوی، متولد در کارُل (سائون اِلوآر) بسال <span class=\"hlight\" dir=\"rtl\">١٨٣٧</span> و متوفی بسال <span class=\"hlight\" dir=\"rtl\">١٨٩٠</span> م .<br /></font></div>'),
(287893, 'ژاکلیو', '<span class=\"hlight\">ژاکلیو.</span> <font color=\"DarkGreen\"><b>[ ک ُ ی ُ ]</font></b> (اِخ ) متولد بسال <span class=\"hlight\" dir=\"rtl\">١٨٤٣</span> در سنت -ژان -سولی میو (لوآر) و متوفی در پاریس بسال <span class=\"hlight\" dir=\"rtl\">١٨٨٦</span> م .او راست کتاب «سه ماه در کنار گنگ و برهماپوترا».<br /></font></div>'),
(287894, 'ژاکمار', '<span class=\"hlight\">ژاکمار.</span> <font color=\"DarkGreen\"><b>[ ک ِ ]</font></b> (اِخ ) ژول فردینان . گراورساز فرانسوی، متولد در پاریس بسال <span class=\"hlight\" dir=\"rtl\">١٨٣٧</span> و متوفی بسال <span class=\"hlight\" dir=\"rtl\">١٨٨٠</span> م .<br /></font></div>'),
(287895, 'ژاکمل', '<span class=\"hlight\">ژاکمل .</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (اِخ ) نام بندر جمهوری هائیتی دارای <span class=\"hlight\" dir=\"rtl\">١٠٠٠٠</span> تن سکنه .<br /></font></div>'),
(287896, 'ژاکمن', '<span class=\"hlight\">ژاکمن .</span> <font color=\"DarkGreen\"><b>[ م ُ ]</font></b> (اِخ ) ویکتور.رحاله و طبیعی دان فرانسوی . وی بجهت اکتشافات خود درهندوستان انگلیس و تبت مشهور است (<span class=\"hlight\" dir=\"rtl\">١٨٠١</span>-<span class=\"hlight\" dir=\"rtl\">١٨٣٢</span> م .).<br /></font></div>'),
(287897, 'ژاکو', '<span class=\"hlight\">ژاکو.</span> (اِخ ) فرانسوا سیژیسموند. طبیب فرانسوی، متولد به ژنو (<span class=\"hlight\" dir=\"rtl\">١٨٣٠</span>-<span class=\"hlight\" dir=\"rtl\">١٩١٣</span> م .).<br /></font></div>'),
(287898, 'ژاکو', '<span class=\"hlight\">ژاکو.</span> <font color=\"DarkGreen\"><b>[ ک ُ ]</font></b> (اِخ ) ژرژ. نام مجسمه ساز فرانسوی از مردم نانسی (<span class=\"hlight\" dir=\"rtl\">١٧٩٤</span>-<span class=\"hlight\" dir=\"rtl\">١٨٧٤</span> م .).<br /></font></div>'),
(287899, 'ژاکپن داتدی', '<span class=\"hlight\">ژاکپن داتدی .</span> <font color=\"DarkGreen\"><b>[ ک ُ پ ُ ت ُ ]</font></b> (اِخ ) نام عارف و شاعر ایتالیائی، متولد به تُدی (<span class=\"hlight\" dir=\"rtl\">١٢٣٠</span>-<span class=\"hlight\" dir=\"rtl\">١٣٠٦</span> م .).<br /></font></div>'),
(287900, 'ژب', '<span class=\"hlight\">ژب .</span> <font color=\"DarkGreen\"><b>[ ژِ ]</font></b> (اِخ ) ریچارد کلاورهوز. نام دانشمند انگلیسی عالم زبان و ادبیات یونان (<span class=\"hlight\" dir=\"rtl\">١٨٤١</span> - <span class=\"hlight\" dir=\"rtl\">١٩٠٥</span> م .).<br /></font></div>'),
(287901, 'ژبا', '<span class=\"hlight\">ژبا.</span> <font color=\"DarkGreen\"><b>[ ژِ ]</font></b> (اِخ ) نام رودخانه ای به افریقای غربی در گینه ٔ پرتقال که به اقیانوس اطلس ریزد.<br /></font></div>'),
(287902, 'ژبر', '<span class=\"hlight\">ژبر.</span> <font color=\"DarkGreen\"><b>[ ژُ ب ِ ]</font></b> (اِخ ) پیر آمده امیلین پرب . نام خاورشناس رحاله ٔ فرانسوی و عالم فاضل جغرافیا (<span class=\"hlight\" dir=\"rtl\">١٧٧٩</span> - <span class=\"hlight\" dir=\"rtl\">١٨٤٧</span> م .). وی جغرافیای ادریسی را به زبان فرانسه در دو جلد ترجمه کرد ودر پاریس به چاپ رسانید. و نیز تاریخ فرغانه را ترجمه کرده و مقالات بسیاری درباره ٔ مشرق در مجله ٔ آسیائی نشر داده است . کتابی هم به عنوان سفر ارمنستان و ایران دارد که در پاریس بسال <span class=\"hlight\" dir=\"rtl\">١٨٢١</span> م . بچاپ رسیده است . او مدتی رئیس دانشکده ٔ السنه ٔ شرقی پاریس بود و شاگرد سیلوستر دوساسی است .<br /></font></div>'),
(287903, 'ژبهارت', '<span class=\"hlight\">ژبهارت .</span> <font color=\"DarkGreen\"><b>[ ژِ ]</font></b> (اِخ ) اِمیل . ادیب فرانسوی . مولد نانسی بسال <span class=\"hlight\" dir=\"rtl\">١٨٣٩</span> و وفات بسال <span class=\"hlight\" dir=\"rtl\">١٩٠٨</span> م . مؤلف آثاری نیکو راجع به ایتالیای عهد تجدّد .<br /></font></div>'),
(287904, 'ژبون', '<span class=\"hlight\">ژبون .</span> <font color=\"DarkGreen\"><b>[ ژُ ]</font></b> (اِ) نفع. سود. رباخواری (از مجعولات شعوری است و صحیح کلمه ربون است ).<br /></font></div>'),
(287905, 'ژت', '<span class=\"hlight\">ژت .</span> <font color=\"DarkGreen\"><b>[ ژِ ]</font></b> (اِخ ) طائفه ای از سیتهای اروپا. مسکن ایشان نخست در ساحل یمین رود دانوب بود. داریوش کبیر پادشاه ایران با آنان حرب و اسکندر مقدونی با ایشان اتحاد کرد. سرزمینی که سابقاً مسکن ژتها بود امروز به ترانسیلوانی و والاشی و مُلداوی و بسارابی معروف است . (ترجمه ٔ تمدن قدیم فوستل دوکولانژ ص <span class=\"hlight\" dir=\"rtl\">٤٨٠</span>).<br /></font></div>'),
(287906, 'ژتا', '<span class=\"hlight\">ژتا.</span> <font color=\"DarkGreen\"><b>[ ژِ ]</font></b> (اِخ ) نام امپراطور روم پسر سِپتیم ِ سِوِر . مولد میلان بسال <span class=\"hlight\" dir=\"rtl\">١٨٩</span> م . وی برادر کاراکالا و شریک سلطنت وی بود و سرانجام بسال <span class=\"hlight\" dir=\"rtl\">٢١٢</span> م . به دست وی کشته شد.<br /></font></div>'),
(287907, 'ژتسمانی', '<span class=\"hlight\">ژتسمانی .</span> <font color=\"DarkGreen\"><b>[ ژِ س ِ ]</font></b> (اِخ ) نام قریه ای نزدیک اورشلیم و بدانجا باغهای زیتون بسیار بوده است . رجوع به جتسیمانی شود.<br /></font></div>'),
(287908, 'ژتن', '<span class=\"hlight\">ژتن .</span> <font color=\"DarkGreen\"><b>[ ژِ ت ُ ]</font></b> (فرانسوی، اِ) قطعه ٔ عاجین یا فلزین یا کائوچوکی و غیره که بجای پول در قمارها یا کافه ها بکار دارند.<br /></font></div>'),
(287909, 'ژتول', '<span class=\"hlight\">ژتول .</span> <font color=\"DarkGreen\"><b>[ ژِ ]</font></b> (اِخ ) نام طایفه ای از بربرهای افریقای باستانی . کابیل های کنونی شاید از نژاد آنان باشند.<br /></font></div>'),
(287910, 'ژتولی', '<span class=\"hlight\">ژتولی .</span> <font color=\"DarkGreen\"><b>[ ژِ ]</font></b> (اِخ ) نام سرزمینی مسکن قوم ژِتول به افریقا در جنوب اقیانوس اطلس بروزگار قدیم .<br /></font></div>'),
(287911, 'ژخ', '<span class=\"hlight\">ژخ .</span> <font color=\"DarkGreen\"><b>[ ژَ ]</font></b> (اِ) ناله ٔ زار و حزین . (لغت نامه ٔ اسدی ). آواز حزین و آهسته . زاری و ناله . (برهان ). <BR><font color=\"Blue\">◄</font> بانگ و آواز. (صحاح الفرس ). هیاهو. هیابانگ . هلالوش <span class=\"hlight\">:</span> <br />بوی برانگیخت گل چو عنبر اشهب <br />بانگ برآورد مرغ با ژخ طنبور.<br /> <font color=\"Red\">منجیک .</font><br />شاید اینجا ژخ صورتی از زخ مخفف زخم بمعنی ضرب باشد. <BR><font color=\"Blue\">◄</font> طعن . گواژه <span class=\"hlight\">:</span> <br />چون کشف انبوه غوغایی بدید<br />بانگ و ژخ مردمان خشم آورید.<br /> <font color=\"Red\">رودکی .</font><br /> <br /><BR><font color=\"Blue\">◄</font> مخفف آژخ، دانه ای باشد سخت و بی درد که در اعضای آدمی بهم میرسد و آن را به عربی ثؤلول گویند. (برهان ). زگیل . پالو. (جهانگیری ). کار. گوجَه .<br /></font></div>'),
(287912, 'ژخار', '<span class=\"hlight\">ژخار.</span> <font color=\"DarkGreen\"><b>[ ژِ ]</font></b> (اِ) بانگ و نعره . <BR><font color=\"Blue\">◄</font> سختی . (برهان ). رجوع به ژغار شود.<br /></font></div>'),
(287913, 'ژخش', '<span class=\"hlight\">ژخش .</span> <font color=\"DarkGreen\"><b>[ ژَ ]</font></b> (اِ) برق . درخش . (آنندراج ). <BR><font color=\"Blue\">◄</font> قوس قُزَح . آژفنداک . (این کلمه با دو معنی آن از مجعولات شعوری و شمس فخری است و مصحف درخش و رخش است ).<br /></font></div>'),
(287914, 'ژد', '<span class=\"hlight\">ژد.</span> <font color=\"DarkGreen\"><b>[ ژَ ]</font></b> (اِ) صمغ و آن چیزی است چسبنده که از ساق درخت برمی آید. (برهان ). اَنگم . کتیرا.<br /></font></div>'),
(287915, 'ژداغا', '<span class=\"hlight\">ژداغا.</span> <font color=\"DarkGreen\"><b>[ ژَ ]</font></b> (اِ) بت پرست .<br /></font></div>'),
(287916, 'ژدرزی', '<span class=\"hlight\">ژدرزی .</span> <font color=\"DarkGreen\"><b>[ ژِ رُ ]</font></b> (اِخ ) نام ناحیتی از ایران باستان میان فارس و بلوچستان که امروز مکران نامیده میشود. آمین مارسلن اغلب ولایاتی را که بروزگار وی تحت حکمرانی بیدخش ها و پادشاهان جزء و ساتراپ ها اداره میشد نام برده است و منجمله ژدرُزی را از ایالات ایران شمرده است . (ترجمه ٔ ایران در زمان ساسانیان ص <span class=\"hlight\" dir=\"rtl\">٨٥</span>).<br /></font></div>'),
(287917, 'ژدس', '<span class=\"hlight\">ژدس .</span> <font color=\"DarkGreen\"><b>[ ژِ دِ ]</font></b> (اِخ ) نام شهری به ممالک متحده ٔ امریکای شمالی (نیویورک ) (در قلمرو اُنندُگا)، دارای چهارهزار تن سکنه .<br /></font></div>'),
(287918, 'ژدل', '<span class=\"hlight\">ژدل .</span><font color=\"DarkGreen\"><b>[ ژُ دِ ]</font></b> (اِخ ) اتین . نام شاعر درام نویس فرانسوی عضو پله ایاد و معاصر هانری دوم (<span class=\"hlight\" dir=\"rtl\">١٥٣٢</span> - <span class=\"hlight\" dir=\"rtl\">١٥٧٣</span> م .).<br /></font></div>'),
(287919, 'ژدله', '<span class=\"hlight\">ژدله .</span> <font color=\"DarkGreen\"><b>[ ژُ دِ ل ِ ]</font></b> (اِخ ) ژولین بدو. نام هنرپیشه ٔ فرانسوی متولد بسال <span class=\"hlight\" dir=\"rtl\">١٥٩٠</span> و متوفی بسال <span class=\"hlight\" dir=\"rtl\">١٦٦٠</span> م .<br /></font></div>'),
(287920, 'ژدلین', '<span class=\"hlight\">ژدلین .</span> <font color=\"DarkGreen\"><b>[ ژِ ]</font></b> (اِخ ) نام ناحیتی به انگلستان (در قلمرو نوتینگهام )، دارای <span class=\"hlight\" dir=\"rtl\">٣٣٥٠</span> تن سکنه .<br /></font></div>'),
(287921, 'ژدن', '<span class=\"hlight\">ژدن .</span> <font color=\"DarkGreen\"><b>[ ژِ دَ ]</font></b> (مص ) مخفف آژدن <span class=\"hlight\">:</span> <br />بنزدیک آن گرگ باید شدن <br />همه چرم او را به پیکان ژدن .<br /> <font color=\"Red\">فردوسی (از جهانگیری ).</font><br />(در لغت نامه ٔ ولف این کلمه نیامده و ظاهراً اصل آن، به تیر آژدن بوده ).<br /></font></div>'),
(287922, 'ژدنی', '<span class=\"hlight\">ژدنی .</span> <font color=\"DarkGreen\"><b>[ ژِ ]</font></b> (اِخ ) نام دهستانی به انگلستان (در قلمرو لینکلن )، دارای <span class=\"hlight\" dir=\"rtl\">٢٤٨٠</span> تن سکنه .<br /></font></div>'),
(287923, 'ژده', '<span class=\"hlight\">ژده .</span> <font color=\"DarkGreen\"><b>[ ژِ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف ) نعت مفعولی از ژدن، از مصدر آژدن . مخفف آژده است . (برهان ). سوزن زده و آژینه بسنگ آسیا زده .<br /></font></div>'),
(287924, 'ژدوار', '<span class=\"hlight\">ژدوار.</span> <font color=\"DarkGreen\"><b>[ ژَدْ <span class=\"hlight\" dir=\"rtl\">/</span> ژُدْ ]</font></b> (اِ) جدوار است که ماه پروین باشد و آن داروئی است مشهور و جدوار معرّب آن است . (برهان ). جدوار. (مخزن الادویه ). رجوع به جدوار شود.<br /></font></div>'),
(287925, 'ژدپم', '<span class=\"hlight\">ژدپم .</span> <font color=\"DarkGreen\"><b>[ ژُ دُ پ ُ ]</font></b> (اِخ ) (سرمان دو...) نام سوگندی است که در بیستم ژوئن <span class=\"hlight\" dir=\"rtl\">١٧٨٩</span> م . وکلاء طبقه ٔ سوم خوردند که تا قانون اساسی را به تصویب نرسانند از یکدیگر جدا نشوند. چون ایشان را از دخول در تالار منو که معمولاً در آنجا به مذاکره میپرداختند منع کرده بودند آنان ناگزیر به تالاری در جوار آن موسوم به ژدپم که آنجا بازی پم میشد رفتند و مذاکرات خود را درباره ٔ قانون اساسی ادامه دادند. این واقعه موضوع تابلوی معروف نقاش مشهور فرانسوی داوید (<span class=\"hlight\" dir=\"rtl\">١٧٩٢</span>) است .<br /></font></div>'),
(287926, 'ژدیمن', '<span class=\"hlight\">ژدیمن .</span> <font color=\"DarkGreen\"><b>[ ژِ م َ ]</font></b> (اِخ ) نام امیر لیتوانی از سال <span class=\"hlight\" dir=\"rtl\">١٣١٥</span> تا <span class=\"hlight\" dir=\"rtl\">١٣٣٧</span> م .<br /></font></div>'),
(287927, 'ژدین', '<span class=\"hlight\">ژدین .</span> <font color=\"DarkGreen\"><b>[ ژِ دُ ]</font></b> (اِخ ) نیکلا. نام کشیش و نویسنده ٔ فرانسوی . مولد ارلئان بسال <span class=\"hlight\" dir=\"rtl\">١٦٦٧</span> و وفات بسال <span class=\"hlight\" dir=\"rtl\">١٧٤٤</span> م .<br /></font></div>'),
(287928, 'ژر', '<span class=\"hlight\">ژر.</span> <font color=\"DarkGreen\"><b>[ ژِ ]</font></b> (اِخ ) از قلل جبال پیرنه نزدیک کوههای اوبن (پیرنه ٔ سفلی )، به ارتفاع <span class=\"hlight\" dir=\"rtl\">٢٦١٢</span> گز.<br /></font></div>'),
(287929, 'ژرا', '<span class=\"hlight\">ژرا.</span> <font color=\"DarkGreen\"><b>[ ژُ ]</font></b> (اِخ ) نام قسمت جنوب غربی فلات سویس که میان دریاچه های لمان و نُشاتل واقع است .<br /></font></div>'),
(287930, 'ژرا', '<span class=\"hlight\">ژرا.</span> <font color=\"DarkGreen\"><b>[ ژِ ]</font></b> (اِخ ) نام شهری به آلمان دارای <span class=\"hlight\" dir=\"rtl\">٤٢٢٠٧</span> تن سکنه، بر کنار رود الستربلان کرسی ناحیه ٔ باس تر .<br /></font></div>'),
(287931, 'ژرا', '<span class=\"hlight\">ژرا.</span> <font color=\"DarkGreen\"><b>[ ژِ ]</font></b> (اِخ ) نام ناحیتی کوچک از حبشه بین هارار و سرزمین اوگادن . رودی که از سومالی گذشته و به دریای هند میریزد نیز همین نام دارد.<br /></font></div>'),
(287932, 'ژرار', '<span class=\"hlight\">ژرار.</span> <font color=\"DarkGreen\"><b>[ ژِ ]</font></b> (اِخ ) میشل . نام سیاستمداری از مردم فرانسه . مولد سن مارتَن (<span class=\"hlight\" dir=\"rtl\">١٧٣٧</span> - <span class=\"hlight\" dir=\"rtl\">١٨١٥</span> م .). او را پِرژرار می نامیدند. وی از طبقه ٔ برزگران بود و در فرانسه نمایندگی مجلس مبعوثان داشت .<br /></font></div>'),
(287933, 'ژرار', '<span class=\"hlight\">ژرار.</span> <font color=\"DarkGreen\"><b>[ ژِ ]</font></b> (اِخ ) لوبارون فرانسوا. نام مصور و رسّام تاریخ فرانسه . متولد در رُم بسال <span class=\"hlight\" dir=\"rtl\">١٧٧٠</span> و متوفی در پاریس بسال <span class=\"hlight\" dir=\"rtl\">١٨٣٧</span> م . نویسنده ٔکتاب «جنگ اُسترلیتز» .<br /></font></div>'),
(287934, 'ژرار', '<span class=\"hlight\">ژرار.</span> <font color=\"DarkGreen\"><b>[ ژِ ]</font></b> (اِخ ) (قدیس ) نام رُهبان صومعه ٔ برنی متولد در قلمرو نامور (<span class=\"hlight\" dir=\"rtl\">٨٩٠</span> - <span class=\"hlight\" dir=\"rtl\">٩٥٩</span> م .). ذکران وی سوم اُکتبر است .<br /></font></div>'),
(287935, 'ژرار', '<span class=\"hlight\">ژرار.</span> <font color=\"DarkGreen\"><b>[ ژِ ]</font></b> (اِخ ) (قدیس ) نام اسقف شُناد در هنگری، متوفی بسال <span class=\"hlight\" dir=\"rtl\">١٠٤٧</span> م . مولد وی در ایالت ونیز و ذکران او <span class=\"hlight\" dir=\"rtl\">٢٤</span> سپتامبر است .<br /></font></div>'),
(287936, 'ژرار', '<span class=\"hlight\">ژرار.</span> <font color=\"DarkGreen\"><b>[ ژِ ]</font></b> (اِخ ) (قدیس ) نام اسقف تول متولد در کلنی بسال <span class=\"hlight\" dir=\"rtl\">٩٣٥</span> م . ذکران وی روز <span class=\"hlight\" dir=\"rtl\">٢٣</span> آوریل است .<br /></font></div>'),
(287937, 'ژرار', '<span class=\"hlight\">ژرار.</span> <font color=\"DarkGreen\"><b>[ ژِ ]</font></b> (اِخ ) شارل فردریک . نام شیمی دان فرانسوی متولد در استراسبورگ بسال <span class=\"hlight\" dir=\"rtl\">١٨١٦</span> و متوفی بسال <span class=\"hlight\" dir=\"rtl\">١٨٥٦</span> م .<br /></font></div>'),
(287938, 'ژرار', '<span class=\"hlight\">ژرار.</span> <font color=\"DarkGreen\"><b>[ ژِ ]</font></b> (اِخ ) سسیل ژول بازیل . نام صاحب منصبی فرانسوی، مولد پینیان بسال <span class=\"hlight\" dir=\"rtl\">١٨١٧</span> و وفات به افریقا بسال <span class=\"hlight\" dir=\"rtl\">١٨٦٤</span> م . شهرت وی در شکار شیر بوده است، بدینجهت او را شیرکش نامند.<br /></font></div>'),
(287939, 'ژرار', '<span class=\"hlight\">ژرار.</span> <font color=\"DarkGreen\"><b>[ ژِ ]</font></b> (اِخ ) (لوبین ئورو) نام یکی از قدیسین مسیحی . مولد بسال <span class=\"hlight\" dir=\"rtl\">١٠٤٠</span> ووفات در حدود سال <span class=\"hlight\" dir=\"rtl\">١١٢١</span> م . ذکران وی نهم ژوئن است .<br /></font></div>'),
(287940, 'ژرار', '<span class=\"hlight\">ژرار.</span> <font color=\"DarkGreen\"><b>[ ژِ ]</font></b> (اِخ ) پیر اُگوست فلوران . نام عالم حقوق و مورخ بلژیکی . مولد بروکسل بسال <span class=\"hlight\" dir=\"rtl\">١٨٠٠</span> و وفات در ایکسل بسال <span class=\"hlight\" dir=\"rtl\">١٨٨٢</span> م .<br /></font></div>'),
(287941, 'ژرار', '<span class=\"hlight\">ژرار.</span> <font color=\"DarkGreen\"><b>[ ژِ ]</font></b> (اِخ ) بالتازار. نام متعصبی دینی که گیوم درانژ را بسال <span class=\"hlight\" dir=\"rtl\">١٥٨٤</span> م . به قتل رسانید.<br /></font></div>'),
(287942, 'ژرار', '<span class=\"hlight\">ژرار.</span> <font color=\"DarkGreen\"><b>[ ژِ ]</font></b> (اِخ ) آلکساندر. نام صاحب منصب و جهانگرد انگلیسی . متولد و متوفی به آبردین (<span class=\"hlight\" dir=\"rtl\">١٧٩٢</span> - <span class=\"hlight\" dir=\"rtl\">١٨٤٠</span> م .). وی را در مغولستان و چین و تبت جنوبی کشفیاتی است .<br /></font></div>'),
(287943, 'ژرار', '<span class=\"hlight\">ژرار.</span> <font color=\"DarkGreen\"><b>[ ژِ ]</font></b> (اِخ ) نام یکی از مارشالهای فرانسوی . مولد دامویله بسال <span class=\"hlight\" dir=\"rtl\">١٧٧٣</span> و وفات به پاریس در <span class=\"hlight\" dir=\"rtl\">١٨٥٢</span> م . وی معاصر ناپلئون بناپارت و از سرداران او بود.<br /></font></div>'),
(287944, 'ژرار', '<span class=\"hlight\">ژرار.</span> <font color=\"DarkGreen\"><b>[ ژِ ]</font></b> (اِخ ) نام نخستین دوکی که امارت لورن را بسال <span class=\"hlight\" dir=\"rtl\">١٠٤٨</span> م . به ارث برد (<span class=\"hlight\" dir=\"rtl\">١٠٢٤</span> - <span class=\"hlight\" dir=\"rtl\">١٠٧٠</span> م .).<br /></font></div>'),
(287945, 'ژرار', '<span class=\"hlight\">ژرار.</span> <font color=\"DarkGreen\"><b>[ ژِ ]</font></b> (اِخ ) یا ژِرارا. نام شهری به فلسطین باستان . بدانجا ابراهیم پیغمبر فرمان یافت که فرزند خویش را قربان کند. رجوع به جرار شود.<br /></font></div>'),
(287946, 'ژرار دسابیونتا', '<span class=\"hlight\">ژرار دسابیونتا.</span> <font color=\"DarkGreen\"><b>[ ژِ دُ ساب ْ بی ُ ن ِت ْتا ]</font></b> (اِخ ) نام منجم و طبیب ایتالیائی در قرن سیزده میلادی . مولد سابیونتا.<br /></font></div>'),
(287947, 'ژرار دنروال', '<span class=\"hlight\">ژرار دنروال .</span> <font color=\"DarkGreen\"><b>[ ژِ دُ ن ِرْ ]</font></b> (اِخ ) نام ادیب فرانسوی . مولد پاریس بسال <span class=\"hlight\" dir=\"rtl\">١٨٠٨</span> و وفات بسال <span class=\"hlight\" dir=\"rtl\">١٨٥٥</span> م . به همانجا. وی را ژرار لابرونی نیز گویند. او را آثار و تحقیقات و تتبعاتی در ادبیات فرانسه است .<br /></font></div>'),
(287948, 'ژرار دکرمون', '<span class=\"hlight\">ژرار دکرمون .</span> <font color=\"DarkGreen\"><b>[ ژِ دُ رِ مُن ْ ]</font></b> (اِخ ) نام مترجم ایتالیائی . مولد کرمون (لُمباردی ) بسال <span class=\"hlight\" dir=\"rtl\">١١١٤</span> و وفات بسال <span class=\"hlight\" dir=\"rtl\">١١٨٧</span> م . وی برای آموختن زبان عرب و علوم عربیه به طلیطله رفت و پس از تبحّردر آن زبان المجسطی بطلمیوس و بعض کتب فارابی را بزبان لاتین ترجمه کرد. و از خود نیز تألیفاتی دارد.<br /></font></div>'),
(287949, 'ژرارمه', '<span class=\"hlight\">ژرارمه .</span> <font color=\"DarkGreen\"><b>[ ژِ م ِ ]</font></b> (اِخ ) نام کرسی بخش وُژ از ولایت سن دیه دارای <span class=\"hlight\" dir=\"rtl\">٨٨١١</span> تن سکنه و کارخانه ٔ پنیرسازی . و راه آهن از آن گذرد. و دریاچه ٔ زیبای ژرارمه بدانجاست .<br /></font></div>'),
(287950, 'ژراس', '<span class=\"hlight\">ژراس .</span> <font color=\"DarkGreen\"><b>[ ژِ ]</font></b> (اِخ ) نام شهری به ایتالیا نزدیک دریای ایونی، دارای <span class=\"hlight\" dir=\"rtl\">٩٣٢٠</span> تن سکنه .<br /></font></div>'),
(287951, 'ژراغن', '<span class=\"hlight\">ژراغن .</span> <font color=\"DarkGreen\"><b>[ ژَ غ َ ]</font></b> (اِ) ریگستان . (آنندراج ) <span class=\"hlight\">:</span> <br />زمینی ژراغن بسختی چو سنگ <br />نه آرامگاه و نه آب و گیا.<br /> <font color=\"Red\">بهرامی (از فرهنگ شعوری ).</font><br />این بیت در لغت نامه ٔ اسدی بشاهد لغت زراغن (با زاء یک نقطه ) آمده است به همین معنی . رجوع به زراغن شود.<br /></font></div>'),
(287952, 'ژراغنگ', '<span class=\"hlight\">ژراغنگ .</span> <font color=\"DarkGreen\"><b>[ ژَ غ َ ]</font></b> (اِ) زمینی پر از سنگ چخماق . <BR><font color=\"Blue\">◄</font> جاها از صدمه ٔ باران ترکیده . (آنندراج ). این صورت و دو معنی آن ظاهراً مجعول است .<br /></font></div>'),
(287953, 'ژراغنگ', '<span class=\"hlight\">ژراغنگ .</span> <font color=\"DarkGreen\"><b>[ ژَ غ َ ]</font></b> (اِ) زمین ریگناک . (آنندراج ) <span class=\"hlight\">:</span> <br />زمین ژراغنگ و راه درازش <br />همه سنگلاخ و همه شوره یکسر.<br /> <font color=\"Red\">عسجدی (از فرهنگ شعوری ).</font><br />این بیت را اسدی در لغت نامه بشاهد لغت زراغنگ (با زاء یک نقطه ) آورده است . رجوع به زراغنگ شود.<br /></font></div>'),
(287954, 'ژرام', '<span class=\"hlight\">ژرام .</span> <font color=\"DarkGreen\"><b>[ ژُ ]</font></b> (اِخ ) نام پسر آحاب از زوجه ٔ وی ایزابل . او از سال <span class=\"hlight\" dir=\"rtl\">٨٥٣</span> تا <span class=\"hlight\" dir=\"rtl\">٨٤٢</span> ق .م . بر اسرائیل شهریاری داشت . رجوع به یهورام شود.<br /></font></div>'),
(287955, 'ژرام', '<span class=\"hlight\">ژرام .</span> <font color=\"DarkGreen\"><b>[ ژُ ]</font></b> (اِخ )نام پسر بزرگ و خلیفه ٔ یهوشافاط. وی از سال <span class=\"hlight\" dir=\"rtl\">٨٥٠</span> - <span class=\"hlight\" dir=\"rtl\">٨٤٢</span> ق .م . مدت هشت سال سلطنت کرد و عتلیا دختر عموی شهریار اسرائیل را به زنی گرفت . رجوع به یهورام شود.<br /></font></div>'),
(287956, 'ژراندو', '<span class=\"hlight\">ژراندو.</span> <font color=\"DarkGreen\"><b>[ ژِ دُ ]</font></b> (اِخ ) ژزف ماری بارن دُ. نام عالم و فیلسوف فرانسوی پیرو طریقه ٔ کندیاک مولد لیون و وفات به پاریس (<span class=\"hlight\" dir=\"rtl\">١٧٧٢</span> - <span class=\"hlight\" dir=\"rtl\">١٨٤٢</span> م .).<br /></font></div>'),
(287957, 'ژربر', '<span class=\"hlight\">ژربر.</span> <font color=\"DarkGreen\"><b>[ ژِ ب ِ ]</font></b> (اِخ ) مارتن . بارن دوهرنو پرنس آبّه دُسنت بلز . دانشمند موسیقی شناس آلمانی . مولد هرب و وفات به سنت بلز (<span class=\"hlight\" dir=\"rtl\">١٧٢٠</span>-<span class=\"hlight\" dir=\"rtl\">١٧٩٣</span> م .).<br /></font></div>'),
(287958, 'ژربر', '<span class=\"hlight\">ژربر.</span> <font color=\"DarkGreen\"><b>[ ژِ ب ِ ]</font></b> (اِخ ) اِرنست لودویگ . دانشمند موسیقی شناس آلمانی متولد و متوفی به سوندرشوزن (<span class=\"hlight\" dir=\"rtl\">١٧٤٦</span> - <span class=\"hlight\" dir=\"rtl\">١٨١٩</span> م .).<br /></font></div>'),
(287959, 'ژربرن', '<span class=\"hlight\">ژربرن .</span> <font color=\"DarkGreen\"><b>[ ژِ ب ِ رُ ]</font></b> (اِخ ) گابریل . عالم فرانسوی . مولد سنت کاله (من ) بسال <span class=\"hlight\" dir=\"rtl\">١٦٢٨</span> و وفات در سنت دنی بسال <span class=\"hlight\" dir=\"rtl\">١٧١١</span> م .<br /></font></div>'),
(287960, 'ژربرژ', '<span class=\"hlight\">ژربرژ.</span> <font color=\"DarkGreen\"><b>[ ژِ ب ِ ]</font></b> (اِخ ) نام ملکه ٔ فرانسه . مولد حدود سال <span class=\"hlight\" dir=\"rtl\">٩١٣</span> و وفات <span class=\"hlight\" dir=\"rtl\">٩٦٩</span> م . خواهر اتون اول پادشاه آلمان . وی در سال <span class=\"hlight\" dir=\"rtl\">٩٣٩</span> بعقد ازدواج لوئی چهارم درآمد.<br /></font></div>'),
(287961, 'ژربرژ', '<span class=\"hlight\">ژربرژ.</span> <font color=\"DarkGreen\"><b>[ ژِ ب ِ ]</font></b> (اِخ ) نام ملکه ٔ استرازی، بورگونی و پرُونس، زوجه ٔ کارلمان برادر شارلمانی . مولد حدود سال <span class=\"hlight\" dir=\"rtl\">٧٥٠</span> و وفات بعد از <span class=\"hlight\" dir=\"rtl\">٧٧٤</span> م .<br /></font></div>'),
(287962, 'ژربه', '<span class=\"hlight\">ژربه .</span> <font color=\"DarkGreen\"><b>[ ژِ ب ِ ]</font></b> (اِخ ) فیلیپ اُلمپ . کشیش و نویسنده ٔ فرانسوی . اسقف پرپینیان (<span class=\"hlight\" dir=\"rtl\">١٧٩٨</span> - <span class=\"hlight\" dir=\"rtl\">١٨٦٤</span> م .).<br /></font></div>'),
(287963, 'ژربه ویله', '<span class=\"hlight\">ژربه ویله .</span> <font color=\"DarkGreen\"><b>[ ژِ ب ِ ل ِ ]</font></b> (اِخ ) نام کرسی بخش مورت -اِ-موزل از ولایت لونه ویل دارای راه آهن و <span class=\"hlight\" dir=\"rtl\">١٥٩٦</span> تن سکنه .<br /></font></div>'),
(287964, 'ژربوام', '<span class=\"hlight\">ژربوام .</span> <font color=\"DarkGreen\"><b>[ ژِ رُ ]</font></b> (اِخ ) نام پسر ناباط. اولین پادشاه اسباط عشره . وی از سال <span class=\"hlight\" dir=\"rtl\">٩٣١</span> تا <span class=\"hlight\" dir=\"rtl\">٩٠٩</span> ق .م . سلطنت کرد و از سبط افرائیم بود. رجوع به یربعام شود.<br /></font></div>'),
(287965, 'ژربیه دژن', '<span class=\"hlight\">ژربیه دژن .</span> <font color=\"DarkGreen\"><b>[ ژِ ی ِ دُ ژُ ]</font></b> (اِخ ) نام قله ٔ ویواره در جنوب مزانک . رود لوآر در پای آن جاری و ارتفاع آن <span class=\"hlight\" dir=\"rtl\">١٥٥٤</span> متر است .<br /></font></div>'),
(287966, 'ژربیون', '<span class=\"hlight\">ژربیون .</span> <font color=\"DarkGreen\"><b>[ ژِ بی یُن ْ ]</font></b> (اِخ ) ژان فرانسوا. نام کشیش و مبلغ مسیحی از آباء یسوعیین به چین . مولد سال <span class=\"hlight\" dir=\"rtl\">١٦٥٤</span> و وفات در پکن بسال <span class=\"hlight\" dir=\"rtl\">١٧٠٧</span> م .<br /></font></div>'),
(287967, 'ژرترود', '<span class=\"hlight\">ژرترود.</span> <font color=\"DarkGreen\"><b>[ ژِ ]</font></b> (اِخ ) (قدیسه ) نام راهبه ٔ نیول در برابان . دختر پپن دُلاندن . ذکران وی <span class=\"hlight\" dir=\"rtl\">١٧</span> مارس است .<br /></font></div>'),
(287968, 'ژرترویدن برگ', '<span class=\"hlight\">ژرترویدن برگ .</span> <font color=\"DarkGreen\"><b>[ ژِ دِم ْ ب ِ ]</font></b> (اِخ ) نام شهری به هلند، دارای <span class=\"hlight\" dir=\"rtl\">١٩٨٠</span> تن سکنه .<br /></font></div>'),
(287969, 'ژرد', '<span class=\"hlight\">ژرد.</span> <font color=\"DarkGreen\"><b>[ ژَ ]</font></b> (اِمص ) بسیار خوردن . پرخوری . (برهان ). بسیارخوری . (آنندراج ). صاحب غیاث اللغات گوید: ظاهراً لغت ژرد مشترک است به زبان عربی و فارسی، مگر تفاوت اینقدر باشد که در عربی به زای عربی و در فارسی به زای فارسی است .<br /></font></div>'),
(287970, 'ژردان', '<span class=\"hlight\">ژردان .</span> <font color=\"DarkGreen\"><b>[ ژُ ]</font></b> (اِخ ) کامیل . سیاستمدار فرانسوی . مولد لیون (<span class=\"hlight\" dir=\"rtl\">١٧٧١</span> - <span class=\"hlight\" dir=\"rtl\">١٨٢١</span> م .).<br /></font></div>'),
(287971, 'ژردانس', '<span class=\"hlight\">ژردانس .</span> <font color=\"DarkGreen\"><b>[ ژُ ن ِ ]</font></b> (اِخ ) نام مورخ گتی در قرن ششم میلادی .<br /></font></div>'),
(287972, 'ژرز', '<span class=\"hlight\">ژرز.</span> <font color=\"DarkGreen\"><b>[ ژِ رِ ]</font></b> (اِخ ) نام شهری به اسپانیا (در ایالت کادیکس )، دارای <span class=\"hlight\" dir=\"rtl\">٦٥٠٠٠</span> تن سکنه .<br /></font></div>'),
(287973, 'ژرس', '<span class=\"hlight\">ژرس .</span> <font color=\"DarkGreen\"><b>[ ژُ رِ ]</font></b> (اِخ ) ژان لئون . پسرعم ژُرس امیرالبحر فرانسوی .مولد کاستره بسال <span class=\"hlight\" dir=\"rtl\">١٨٥٩</span> ومقتول بسال <span class=\"hlight\" dir=\"rtl\">١٩١٤</span> م . در پاریس . وی از سیاستمداران و ناطقین و از سران حزب سوسیالیست فرانسه بشمار است .<br /></font></div>'),
(287974, 'ژرس', '<span class=\"hlight\">ژرس .</span> <font color=\"DarkGreen\"><b>[ ژُ رِ ]</font></b> (اِخ ) بنژامن . نام امیرالبحر فرانسوی . مولد پاریس بسال <span class=\"hlight\" dir=\"rtl\">١٨٢٣</span> و وفات بسال <span class=\"hlight\" dir=\"rtl\">١٨٨٩</span> م .<br /></font></div>'),
(287975, 'ژرس', '<span class=\"hlight\">ژرس .</span> <font color=\"DarkGreen\"><b>[ ژِ ]</font></b> (اِخ ) نام ایالتی به فرانسه متشکل از قسمتی از گاسکنی قدیم، دارای سه ایالت و <span class=\"hlight\" dir=\"rtl\">٢٩</span> ولایت و <span class=\"hlight\" dir=\"rtl\">٤٦٦</span> دهستان و <span class=\"hlight\" dir=\"rtl\">١٩١١٣٤</span> تن سکنه . این ناحیه بنام رودی که از آنجا گذرد موسوم گشته است .<br /></font></div>'),
(287976, 'ژرس', '<span class=\"hlight\">ژرس .</span> <font color=\"DarkGreen\"><b>[ ژِ ]</font></b> (اِخ ) نام رودخانه ای بطول <span class=\"hlight\" dir=\"rtl\">١٧٨</span> کیلومتر به فرانسه که از فلات لانمزان سرچشمه گیرد و از ایالت ژرس گذرد و به رود کارون پیوندد.<br /></font></div>'),
(287977, 'ژرسدرف', '<span class=\"hlight\">ژرسدرف .</span> <font color=\"DarkGreen\"><b>[ ژِ دُ ]</font></b> (اِخ ) نام دو محل به آلمان (در قلمرو ساکس ) سرحد بوهم : ژرسدرف قدیم، دارای <span class=\"hlight\" dir=\"rtl\">٣٩٦٦</span> تن سکنه ؛ و ژرسدرف نو، دارای <span class=\"hlight\" dir=\"rtl\">٤٩٧٢</span> تن سکنه .<br /></font></div>'),
(287978, 'ژرسن', '<span class=\"hlight\">ژرسن .</span> <font color=\"DarkGreen\"><b>[ ژِ س ُ ]</font></b> (اِخ ) ژان شارلیه . نام عالم کلامی فرانسوی . مولد در قریه ٔ ژرسن شامپانی بسال <span class=\"hlight\" dir=\"rtl\">١٣٦٢</span> و وفات در لیون بسال <span class=\"hlight\" dir=\"rtl\">١٤٢٨</span> م . او را ژان دُژرسن نیز گویند.<br /></font></div>'),
(287979, 'ژرسو', '<span class=\"hlight\">ژرسو.</span> <font color=\"DarkGreen\"><b>[ ژِ س َ ]</font></b> (اِخ ) نام قصبه ای به سویس (در کانتون شویتز) دارای <span class=\"hlight\" dir=\"rtl\">١٨١٧</span> تن سکنه .<br /></font></div>'),
(287980, 'ژرسی', '<span class=\"hlight\">ژرسی .</span> <font color=\"DarkGreen\"><b>[ ژِ ]</font></b> (اِخ ) نام بزرگترین جزیره ٔ آنگلونرماند، دارای <span class=\"hlight\" dir=\"rtl\">٥٢٠٠٠</span> تن سکنه و کرسی آن سنت هلیه است .<br /></font></div>'),
(287981, 'ژرسی سیتی', '<span class=\"hlight\">ژرسی سیتی .</span> <font color=\"DarkGreen\"><b>[ ژِ ]</font></b> (اِخ ) نام شهری به اتازونی (در نیوجِرسی ) بر کنار هودسن و روبروی نیویورک، دارای <span class=\"hlight\" dir=\"rtl\">٣٢٥٠٠٠</span> تن سکنه .<br /></font></div>'),
(287982, 'ژرف', '<span class=\"hlight\">ژرف .</span> <font color=\"DarkGreen\"><b>[ ژَ ]</font></b> (ص )عمیق است مطلقاً خواه دریا باشد و خواه چاه و خواه رودخانه و حوض و امثال آن . (برهان ). دورتک . دوراندرون . نُغُل . (حاشیه ٔ فرهنگ اسدی نخجوانی ). گود. بعیدةالقعر. قعیر. چال . دور. (فرهنگ اسدی ). دورفرود. سخت گود. بغایت عمیق . دوراندر بود چون مغاکی و چاهی . (لغت نامه ٔ اسدی ) <span class=\"hlight\">:</span> <br />چو آمد بنزدیک آن ژرف چاه <br />یکایک نگون شد سر و تخت شاه .<br /> <font color=\"Red\">فردوسی .</font><br />گهی چاه ژرف و گهی بندگی <br />به ذل و به خواری سرافکندگی .<br /> <font color=\"Red\">فردوسی .</font><br />که بیچاره بیژن در آن ژرف چاه <br />نبیند شب و روز و خورشید و ماه .<br /> <font color=\"Red\">فردوسی .</font><br />کسی کو بره برکند ژرف چاه <br />سزد گر کند خویشتن را نگاه .<br /> <font color=\"Red\">فردوسی .</font><br />بر آن رای واژونه دیو نژند<br />یکی ژرف چاهی بره بر بکند.<br /> <font color=\"Red\">فردوسی .</font><br />پس ابلیس واژونه این ژرف چاه <br />به خاشاک پوشید و بسپرد راه .<br /> <font color=\"Red\">فردوسی .</font><br />وزان پس بپرسید فرخنده شاه <br />از آن ژرف دریا و تاریک چاه .<br /> <font color=\"Red\">فردوسی .</font><br />یکی ژرف دریاست بن ناپدید<br />در گنج رازش ندارد کلید.<br /> <font color=\"Red\">فردوسی .</font><br />تو نشنیده ای داستان پلنگ <br />بدان ژرف دریا که زد با نهنگ .<br /> <font color=\"Red\">فردوسی .</font><br />ز شهر برهمن به جائی رسید<br />یکی بیکران ژرف دریا بدید.<br /> <font color=\"Red\">فردوسی .</font><br />سوی ژرف دریا همی راندند<br />جهان آفرین را همی خواندند.<br /> <font color=\"Red\">فردوسی .</font><br />چو چشمه بر ژرف دریا بری <br />به دیوانگی ماند این داوری .<br /> <font color=\"Red\">فردوسی .</font><br />ز پستی بیامد به کوهی رسید<br />یکی بیکران ژرف دریا بدید.<br /> <font color=\"Red\">فردوسی .</font><br />بباید گذشتن به دریای ژرف <br />اگر خوش بود روز اگر باد و برف .<br /> <font color=\"Red\">فردوسی .</font><br />سپهدار چون پیش لشکر کشید<br />یکی ژرف دریای بی بن بدید.<br /> <font color=\"Red\">فردوسی .</font><br />که از مرغ آن کشته نشناختند<br />به گرداب ژرف اندر انداختند.<br /> <font color=\"Red\">فردوسی .</font><br />بویژه دلیری چو من روز جنگ <br />که از ژرف دریا برآرم نهنگ .<br /> <font color=\"Red\">فردوسی .</font><br />چو بگذشت از آن آب جائی رسید<br />که آمد یکی ژرف دریا پدید.<br /> <font color=\"Red\">فردوسی .</font><br />سوی ژرف دریا بیامد به جنگ <br />که بر خشک بر بود ره بادرنگ .<br /> <font color=\"Red\">فردوسی .</font><br />فریدون چو بشنید شد خشمناک <br />از آن ژرف دریا نیامدش باک .<br /> <font color=\"Red\">فردوسی .</font><br />اگر سلم در ژرف دریا شود<br />وگر بر فلک چون ثریا شود<br />به چنگ آرمش سر ببرّم ز تن <br />بسازم ورا کام شیران کفن .<br /> <font color=\"Red\">فردوسی .</font><br />به جائی یکی ژرف دریا بدید<br />همی کوه بایست پیشش برید.<br /> <font color=\"Red\">فردوسی .</font><br />به دریای ژرف اندر انداختش <br />چنان چون شنیدش دگر ساختش .<br /> <font color=\"Red\">فردوسی .</font><br />چنین تا بنزدیکی ژرف رود<br />رسیدند با جوشن و درع و خود.<br /> <font color=\"Red\">فردوسی .</font><br />چنین تا بیامد یکی ژرف رود<br />سپه شد پراکنده بی تاروپود.<br /> <font color=\"Red\">فردوسی .</font><br />دشمن از شمشیر او ایمن نباشد ور بود<br />در حصاری گرد او از ژرف دریا پارگین .<br /> <font color=\"Red\">فرخی .</font><br />آنکه اندر ژرف دریا راه برده روز و شب <br />بر امید سود از این معبر بدان معبرشود.<br /> <font color=\"Red\">فرخی .</font><br />بگذرانیدی سپاه از روی دریا بی قیاس <br />ژرف دریا باشد اندر جنب آن هر یک قلیل .<br /> <font color=\"Red\">فرخی .</font><br />چونان که گر خواهی در بادیه <br />سازی از او ژرف چهی را رسن .<br /> <font color=\"Red\">فرخی .</font><br />تکاوری که به یک شربت آب ماند راست <br />به دستش اندر دریای ژرف پهناور.<br /> <font color=\"Red\">منشوری .</font><br />گمان بردی از سهم آن ژرف رود<br />که آمد مجرّه ز گردون فرود.<br /> <font color=\"Red\">اسدی .</font><br />یکی چاه تاریک ژرف است آز<br />بنش ناپدید و سرش پهن باز.<br /> <font color=\"Red\">اسدی .</font><br />درخشنده شمعی است این جان پاک <br />فتاده در این ژرف جای مغاک .<br /> <font color=\"Red\">اسدی .</font><br />جهان ژرف چاهی است پر بیم و آز<br />از او کوش تا تن کشی بر فراز.<br /> <font color=\"Red\">اسدی .</font><br />به دریای ژرف آنکه جوید صدف <br />ببایدش جان برنهادن به کف .<br /> <font color=\"Red\">اسدی .</font><br />وگرنه بدان سر نداند رسید<br />در این ژرف دریاشود ناپدید.<br /> <font color=\"Red\">اسدی .</font><br />چو از دامن ژرف دریای قار<br />سپیده برآمد چو سیمین بخار.<br /> <font color=\"Red\">اسدی .</font><br />دست خدای گیر و از این ژرف چه برآی <br />گر با هزار جور و جفا و مظالمی .<br /> <font color=\"Red\">ناصرخسرو.</font><br />بر سایش ما را ز جنبش آمد<br />ای پور در این زیر ژرف دریا.<br /> <font color=\"Red\">ناصرخسرو.</font><br />هر روز به مذهبی دگر باشی <br />گه در چه ژرف و گاه بر بامی <br />گر ناصبیت برد عمر باشی <br />ور شیعی خواندت علی نامی .<br /> <font color=\"Red\">ناصرخسرو.</font><br />خرد پرّ جان است اگر نشکنیش <br />بدو جانت زین ژرف چه برپرد.<br /> <font color=\"Red\">ناصرخسرو.</font><br />آبی است جهان تیره و بس ژرف بدو در<br />زنهار که تیره نکنی جان مصفا.<br /> <font color=\"Red\">ناصرخسرو.</font><br />یکی دریای ژرف است اینکه هرگز<br />نرستست از هلاکش یک سفینه .<br /> <font color=\"Red\">ناصرخسرو.</font><br />چون بغم معده درافتاده ای <br />معده ترا ژرف چه بیژن است .<br /> <font color=\"Red\">ناصرخسرو.</font><br />ای بحر نبوده چون دلت ژرف <br />ای ابر نبوده چون کفت راد.<br /> <font color=\"Red\">مسعودسعد.</font><br />یکی آنکه جویها ژرف نبود... و دیگر آنکه جویها <font color=\"DarkGreen\"><b>[ درشمشیر ]</font></b> ژرف باشد. (نوروزنامه ). غلامانش چاهی ژرف کندند. (مجمل التواریخ والقصص ). <br />فرخا اقبال یاری کو در این دریای ژرف <br />ترک جان گفت و سر آن نفس حیوان برگرفت .<br /> <font color=\"Red\">عطار.</font><br />علم در علم است این دریای ژرف <br />من چنین جاهل کجا خواهم رسید.<br /> <font color=\"Red\">عطار.</font><br />کشتی هرکس از این دریای ژرف <br />هیچ کس را جست تا اکنون جهد.<br /> <font color=\"Red\">عطار.</font><br />شه از بازی آن طلسم شگرف <br />گراینده شد سوی دریای ژرف .<br /> <font color=\"Red\">نظامی .</font><br />چون برآیند از تک دریای ژرف <br />کشف گردد صاحب درّ شگرف .<br /> <font color=\"Red\">مولوی .</font><br />این همه جوها ز دریائی است ژرف <br />جزء را بگذار و بر کل دار طرف .<br /> <font color=\"Red\">مولوی .</font><br />صدهزاران ماهی از دریای ژرف <br />در دهان هر یکی درّی شگرف .<br /> <font color=\"Red\">مولوی .</font><br />هرآنچ آفریدی در این جوی ژرف <br />نهفتی در آن کیمیای شگرف .<br /> <font color=\"Red\">امیرخسرو.</font><br />بحر لجی ؛ دریای ژرف . (دهار). جمةالماء؛ جای ژرف از آب . جوائف النفس ؛ درون ژرف قرارگاه روح .(منتهی الارب ). تعمیق ؛ ژرف گردانیدن . تعمق ؛ ژرف شدن .(مقدمة الادب ). قعارة؛ ژرف شدن چاه . دورتک گردیدن چاه . عماقة؛ ژرف شدن . دورتک و دراز گردیدن . (منتهی الارب ). اِقعار؛ ژرف کردن . اِعماق ؛ ژرف کردن . (تاج المصادر). <BR><font color=\"Blue\">◄</font> بسیار. بی نهایت <span class=\"hlight\">:</span> <br />زین عصا تا آن عصا فرقی است ژرف <br />زین عمل تا آن عمل راهی شگرف .<br /> <font color=\"Red\">مولوی .</font><br />زین حسن تا آن حسن فرقی است ژرف .<br /> <font color=\"Red\">مولوی .</font><br />زانکه درویشان و رای گنج و مال <br />روزیی دارند ژرف از ذوالجلال .<br /> <font color=\"Red\">مولوی .</font><br /> <BR><font color=\"Blue\">◄</font> مهم ّ. مشکل <span class=\"hlight\">:</span> <br />بدل گفت پیران که ژرف است کار<br />ز توران شدن پیش آن شهریار.<br /> <font color=\"Red\">فردوسی .</font><br />جاهل نرسد در سخن ژرف تو آری <br />کف بر سر بحر آید و دردانه به پایاب .<br /> <font color=\"Red\">خاقانی .</font><br /> <BR><font color=\"Blue\">◄</font> بزرگ . عظیم . کبیر <span class=\"hlight\">:</span> <br />اگر پیل ژرف است و گر گرگ و شیر<br />قراری کند چون شکم گشت سیر.<br /> <font color=\"Red\">؟</font><br /> <BR><font color=\"Blue\">◄</font> دور <span class=\"hlight\">:</span> <br />کدام است مرد پژوهنده راز<br />که پیماید این ژرف راه دراز.<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> (اِ) عمق . گودی . قعر <span class=\"hlight\">:</span> <br />ز ژرف زمین تا به چرخ بلند<br />ز خورشید تا تیره خاک نژند.<br /> <font color=\"Red\">فردوسی .</font><br />به سنگ و به گچ باید از ژرف آب <br />برآورد تا چشمه ٔ آفتاب .<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(287983, 'ژرف اندیش', '<span class=\"hlight\">ژرف اندیش .</span> <font color=\"DarkGreen\"><b>[ ژَ اَ ]</font></b> (نف مرکب )نعت فاعلی از ژرف اندیشیدن . متعمق . دقیق . ژرف بین .<br /></font></div>'),
(287984, 'ژرف اندیشی', '<span class=\"hlight\">ژرف اندیشی .</span> <font color=\"DarkGreen\"><b>[ ژَ اَ ]</font></b> (حامص مرکب ) تعمق . دقت . غوررسی .<br /></font></div>'),
(287985, 'ژرف بین', '<span class=\"hlight\">ژرف بین .</span> <font color=\"DarkGreen\"><b>[ ژَ ]</font></b> (نف مرکب ) متعمق . باریک بین . غوررس . عمیق . نافذالنظر. تیزچشم . تیزبین . ژرف اندیش . ژرف نگاه . ژرف نگر <span class=\"hlight\">:</span> <br />چه بیند بدین اندرون ژرف بین <br />چه گوئی تو ای فیلسوف اندر این .<br /> <font color=\"Red\">ابوشکور.</font><br /> <br />یکی ژرف بین است شاه یمن <br />که چون او نباشد به هر انجمن .<br /> <font color=\"Red\">فردوسی .</font><br />ز هر کشوری مردم ژرف بین <br />که استاد یابی بدین برگزین .<br /> <font color=\"Red\">فردوسی .</font><br />چونیکو ببیند دل ژرف بین <br />در این نیست جز حکم جان آفرین .<br /><font color=\"Red\">فردوسی .</font><br />یکی چاره آورد از دل بجای <br />که بد ژرف بین او به تدبیر و رای .<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(287986, 'ژرف بینی', '<span class=\"hlight\">ژرف بینی .</span> <font color=\"DarkGreen\"><b>[ ژَ]</font></b> (حامص مرکب ) تعمق . باریک بینی . غوررسی . ژرف اندیشی .ژرف دررفتن در چیزی . تعمق کردن و غوررسی در امری .<br /></font></div>'),
(287987, 'ژرف دیدن', '<span class=\"hlight\">ژرف دیدن .</span> <font color=\"DarkGreen\"><b>[ ژَ دی دَ]</font></b> (مص مرکب ) به تعمق نگریستن . به عمق دیدن . تعمق .<br /></font></div>'),
(287988, 'ژرف نگاه', '<span class=\"hlight\">ژرف نگاه .</span> <font color=\"DarkGreen\"><b>[ ژَ ن ِ ]</font></b> (ص مرکب ) باریک بین . (آنندراج ). غوررس . نظرعمیق کننده . ژرف بین . به تعمق نگرنده . ژرف نگر.<br /></font></div>'),
(287989, 'ژرف نگاه کردن', '<span class=\"hlight\">ژرف نگاه کردن .</span> <font color=\"DarkGreen\"><b>[ ژَ ن ِ ک َ دَ ]</font></b> (مص مرکب ) نظر عمیق کردن . ژرف بینی . ژرف نگریستن . غوررسی کردن . باریک بینی <span class=\"hlight\">:</span> <br />پرستنده باشی و جویند راه <br />به فرمانها ژرف کردن نگاه .<br /> <font color=\"Red\">فردوسی .</font><br />چو در کارتان ژرف کردم نگاه <br />ببندد همی بر خرد دیو راه .<br /> <font color=\"Red\">فردوسی .</font><br />به بخشایش امید و ترس از گناه <br />به فرمانها ژرف کردن نگاه .<br /> <font color=\"Red\">فردوسی .</font><br />ز هول رزمگهش خانیان ترکستان <br />اگر کنند به کوه و به دشت ژرف نگاه <br />به کوه مرد نماید به چشمشان نخجیر<br />به دشت پیل نماید به چشمشان روباه .<br /> <font color=\"Red\">فرخی .</font><br />زلف مشکین تو زان عارض تابنده چو ماه <br />به سر چاه زنخدان تو آید گه گاه <br />از پی آنکه یکی بسته بدو رسته شود<br />گرد میگردد و در چاه کند ژرف نگاه .<br /><font color=\"Red\">فرخی .</font><br /></font></div>'),
(287990, 'ژرف نگر', '<span class=\"hlight\">ژرف نگر.</span> <font color=\"DarkGreen\"><b>[ ژَ ن ِ گ َ ]</font></b> (نف مرکب ) متعمق . باریک بین <span class=\"hlight\">:</span> مجرب، ژرف نگر؛ رازدار. (التفهیم ).<br /></font></div>'),
(287991, 'ژرف نگری', '<span class=\"hlight\">ژرف نگری .</span> <font color=\"DarkGreen\"><b>[ ژَ ن ِ گ َ ]</font></b> (حامص مرکب ) تعمق . باریک بینی . ژرف بینی . ژرف اندیشی . غوررسی .<br /></font></div>'),
(287992, 'ژرف نگریستن', '<span class=\"hlight\">ژرف نگریستن .</span> <font color=\"DarkGreen\"><b>[ ژَ ن ِ گ َ ت َ ]</font></b> (مص مرکب ) تعمق کردن . دقت کردن . بتعمق نگاه کردن . ژرف نگری . ژرف بینی . دقیق شدن در کاری <span class=\"hlight\">:</span> <br />بگفتم همه گفتنی سربسر<br />تو ژرف اندر این پندنامه نگر.<br /> <font color=\"Red\">دقیقی .</font><br />اگر داد بیند بر این کار ما<br />یکی بنگرد ژرف سالار ما.<br /> <font color=\"Red\">فردوسی .</font><br />ولیکن بدین رای هشیار من <br />یکی بنگرد ژرف سالار من .<br /> <font color=\"Red\">فردوسی .</font><br />برمز این مرا گفت آن شکرین لب <br />که ای شاعر اندر سخن ژرف بنگر.<br /> <font color=\"Red\">فرخی .</font><br />زی هر گلی که ژرف بدو در تو بنگری <br />گوئی که زر دارد یک پاره در میان .<br /> <font color=\"Red\">منوچهری .</font><br />دعوی کنند گرچه براهیم زاده ایم <br />چون ژرف بنگری همه شاگرد آزرند.<br /> <font color=\"Red\">ناصرخسرو.</font><br />در اینها به چشم دلت ژرف بنگر<br />که این را به چشم سرت دید نتوان .<br /><font color=\"Red\">ناصرخسرو.</font><br /></font></div>'),
(287993, 'ژرف یاب', '<span class=\"hlight\">ژرف یاب .</span> <font color=\"DarkGreen\"><b>[ ژَ ]</font></b> (نف مرکب ) آنکه اندازه گیرد عمق چیزی را. <BR><font color=\"Blue\">◄</font> متعمق . دقیق .دقیق النظر. باریک بین . با فراست و بصیر <span class=\"hlight\">:</span> <br />چراغ جهان یوسف ژرف یاب <br />شتابید هم در زمان سوی آب .<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><br />چنین داد جبریل فرخ جواب <br />به پیغمبر تازی ژرف یاب .<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><br />جدا کرد پس یوسف ژرف یاب <br />ز پیش زلیخا بشب جامه خواب .<br /><font color=\"Red\">شمسی (یوسف و زلیخا).</font><br /></font></div>'),
(287994, 'ژرف یابی', '<span class=\"hlight\">ژرف یابی .</span> <font color=\"DarkGreen\"><b>[ ژَ ]</font></b> (حامص مرکب ) اندازه گیری عمق چیزی . <BR><font color=\"Blue\">◄</font> تعمق .<br /></font></div>'),
(287995, 'ژرفا', '<span class=\"hlight\">ژرفا.</span><font color=\"DarkGreen\"><b>[ ژَ ]</font></b> (اِ) عمق . (برهان ). قعر. گودی . یکی از سه بُعد جسم، مقابل درازا و پهنا <span class=\"hlight\">:</span> بعدهای جایگاه چه چیزند؟ سه گونه اند: یکی درازا و دیگر پهنا و سه دیگر ژرفا. (التفهیم ). <BR><font color=\"Blue\">◄</font> غور. <BR><font color=\"Blue\">◄</font> عمیق بودن . (برهان ).<br /></font></div>'),
(287996, 'ژرفایابی', '<span class=\"hlight\">ژرفایابی .</span> <font color=\"DarkGreen\"><b>[ ژَ ]</font></b> (حامص مرکب ) سنجیدن گودی چیزی . عمق یابی . تحقیق عمق . غوررسی .<br /></font></div>'),
(287997, 'ژرفنا', '<span class=\"hlight\">ژرفنا.</span> <font color=\"DarkGreen\"><b>[ ژَ]</font></b> (اِ مرکب ) ژرفنای . ژرفا. ژرفای . ژرفی . جای ژرف .<br /></font></div>'),
(287998, 'ژرفنای', '<span class=\"hlight\">ژرفنای .</span> <font color=\"DarkGreen\"><b>[ ژَ ]</font></b> (اِ مرکب ) ژرفنا. رجوع به ژرفنا شود.<br /></font></div>'),
(287999, 'ژرفی', '<span class=\"hlight\">ژرفی .</span> <font color=\"DarkGreen\"><b>[ ژَ ]</font></b> (ص نسبی ) منسوب به ژرف . <BR><font color=\"Blue\">◄</font> (حامص، اِ) عمق . گودی . غور. یکی از ابعاد سه گانه مقابل درازی و پهنی . (برهان ). ژرفا <span class=\"hlight\">:</span> به روستای ارغان چاهی آب است ژرفی آن همه ٔ جهان نتواند دانست . (حدود العالم ).<br />اگر خون آن کشتگان را ز خاک <br />بژرفی برد رای یزدان پاک <br />همانا که دریای قلزم شود<br />که لشکر بخون اندرون گم شود.<br /> <font color=\"Red\">فردوسی .</font><br />بدان دادگر کو سپهر آفرید<br />بلندی و ژرفی و مهر آفرید.<br /> <font color=\"Red\">فردوسی .</font><br />بسوی باز شدن سوی او چنان تازند<br />چو سوی ژرفی خاشاکها بر آب روان .<br /> <font color=\"Red\">فرخی .</font><br />همانجا یکی سهمگین چاه بود<br />که ژرفیش صد شاه رش راه بود.<br /> <font color=\"Red\">اسدی (گرشاسب نامه ).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">بژرفی </span> ؛ با کمال دقت . با تأمل . با تعمّق <span class=\"hlight\">:</span> <br />بژرفی نگه دار هنگام را<br />بروز و بشب گاه آرام را.<br /> <font color=\"Red\">فردوسی .</font><br />پژوهش فزای و بترس ازکمین <br />سخن هرچه باشد بژرفی ببین .<br /> <font color=\"Red\">فردوسی .</font><br />همه رازها بر تو باید گشاد<br />بژرفی ببین تا چه آیدت یاد.<br /> <font color=\"Red\">فردوسی .</font><br />سپه ران بیاری سالار خویش <br />بژرفی نگه دار پیکار خویش .<br /> <font color=\"Red\">فردوسی .</font><br />برهنه دگرباره بگذارشان <br />بژرفی نگه دار بازارشان .<br /> <font color=\"Red\">فردوسی .</font><br />وزان پس بدو گفت رو کار خویش <br />بژرفی نگه دار و مگریز بیش .<br /> <font color=\"Red\">فردوسی .</font><br />بژرفی نگه دار گفتار من <br />مبادا که خوار آیدت کار من .<br /> <font color=\"Red\">فردوسی .</font><br />بژرفی بدین خواب من گوش دار<br />گزارش کن این را و هم هوش دار .<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">بژرفی نگه کردن </span> ؛ به تعمق نگریستن . بژرفی دیدن در. تعمق در آن . دقت در آن <span class=\"hlight\">:</span> <br />بژرفی نگه کن که با یزدگرد<br />چه کرد این برافراخته هفت گرد.<br /> <font color=\"Red\">فردوسی .</font><br />نهفته همه رازها بازجست <br />بژرفی نگه کرد کار از نخست .<br /> <font color=\"Red\">فردوسی .</font><br />بژرفی نگه کن سراپای اوی <br />همان کوشش و دانش و رای اوی .<br /> <font color=\"Red\">فردوسی .</font><br />پرستنده باشی و جوینده راه <br />بژرفی به فرمانش کردن نگاه .<br /> <font color=\"Red\">فردوسی .</font><br />به لشکر بترسان بداندیش را<br />بژرفی نگه کن پس و پیش را.<br /> <font color=\"Red\">فردوسی .</font><br />بژرفی نگه کن چنان هم که هست <br />به گفتار و دیدارو جای نشست .<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(288000, 'ژرفین', '<span class=\"hlight\">ژرفین .</span> <font color=\"DarkGreen\"><b>[ ژُ ]</font></b> (اِ) زرفین . (شعوری ). رجوع به زرفین شود.<br /></font></div>'),
(288001, 'ژرم', '<span class=\"hlight\">ژرم .</span> <font color=\"DarkGreen\"><b>[ ژِ رُ ]</font></b> (اِخ ) (قدیس ) اب و دستور کلیسای لاتینی . مولد استریدُنا در حدود سال <span class=\"hlight\" dir=\"rtl\">٣٣١</span> و وفات به بیت اللحم در <span class=\"hlight\" dir=\"rtl\">٤٢٠</span> م . وی تورات سبعینی یونانی را با تورات عبری مطالعه و موازنه و به زبان لاتین ترجمه کرد. ذکران او سی ام سپتامبر است .<br /></font></div>'),
(288002, 'ژرم', '<span class=\"hlight\">ژرم .</span> <font color=\"DarkGreen\"><b>[ ژِ رُ ]</font></b> (اِخ ) ژرم کلاپکا. نام نویسنده ٔ فکاهی انگلیسی . وی بسال <span class=\"hlight\" dir=\"rtl\">١٨٥٩</span> در والسال متولد شد و در <span class=\"hlight\" dir=\"rtl\">١٩٢٧</span> م . به نورتهامپتون درگذشت .<br /></font></div>'),
(288003, 'ژرم', '<span class=\"hlight\">ژرم .</span> <font color=\"DarkGreen\"><b>[ ژِ رُ ]</font></b> (اِخ ) ژان لئون . نام نقاش و پیکرساز فرانسوی . مولد بسال <span class=\"hlight\" dir=\"rtl\">١٨٢٤</span> در وسول و وفات در پاریس بسال <span class=\"hlight\" dir=\"rtl\">١٩٠٤</span> م .<br /></font></div>'),
(288004, 'ژرم امیلیانی', '<span class=\"hlight\">ژرم امیلیانی .</span> <font color=\"DarkGreen\"><b>[ ژِ رُ اِ ]</font></b> (اِخ ) (قدیس ) از قدّیسان مسیحی . مولد در حدود سال <span class=\"hlight\" dir=\"rtl\">١٤٨١</span> و وفات بسال <span class=\"hlight\" dir=\"rtl\">١٥٣٧</span> م . ذکران وی بیستم ژوئیه است .<br /></font></div>'),
(288005, 'ژرم دمراوی', '<span class=\"hlight\">ژرم دمراوی .</span> <font color=\"DarkGreen\"><b>[ ژِ رُ دُ م ُ ]</font></b> (اِخ ) نام راهب و عالم موسیقی . مولد مُراوی در قرن هجدهم میلادی .<br /></font></div>'),
(288006, 'ژرم دپراگ', '<span class=\"hlight\">ژرم دپراگ .</span> <font color=\"DarkGreen\"><b>[ ژِ رُ دُ پْرا <span class=\"hlight\" dir=\"rtl\">/</span> پ ِ ]</font></b> (اِخ ) نام شاگرد ژان هوس مولد در پراگ حدود سال <span class=\"hlight\" dir=\"rtl\">١٣٧٤</span> م . وی را بسال <span class=\"hlight\" dir=\"rtl\">١٤١٦</span> م . در کنستانس به تهمت الحاد زنده سوختند و او با کمال شهامت و مردانگی جان داد.<br /></font></div>'),
(288007, 'ژرمانی', '<span class=\"hlight\">ژرمانی .</span> <font color=\"DarkGreen\"><b>[ ژِ ]</font></b> (اِخ ) نام قسمت بزرگی از اروپای قدیم و کشور آلمان کنونی . رجوع به آلمان شود. رومیان مملکتی را که در شرق رن تا ویستول و در شمال دانوب تا دریای بالتیک واقع بود ژرمانی مینامیدند. امروز از منطقه ٔ مذکور دولتهای هلند، آلمان، دانمارک، چکسلواکی، لهستان و رومانی تشکیل یافته است . ژرمن ها به گلواها شباهت داشتند. تاسیت میگوید: «چشمهای آبی و خشمناک و موهای قرمز و قد بلند دارند». طوایف مذکور تا دیر زمانی چادرنشین بودند و در قرن چهارم اغلب آنها در یک جا بسر برده و به زراعت زمین میپرداختند. اراضی مال تمام قبیله بود و هر سال آن را بین خانواده های مختلف تقسیم میکردند. در مملکت ژرمانی شهر وجود نداشت، فقط قصباتی یافت میشد که از کلبه های گرد یا مربع تشکیل گشته بود و هر یک باغ کوچکی داشت که دیوارهای کوتاه بر آن احاطه میکرد.<br />ملل عمده ٔ ژرمن : هرگاه کسی از مصب رود رن شروع میکرد و در ساحل آن پیش میرفت اول به فرانک ها برمیخورد که به دو دسته تقسیم میشدند: یکی فرقه ٔ سالین که قسمتی از خاک بلژیک را متصرف بود، و دیگری طایفه ٔ ری پوئر که در دنباله ٔ رودخانه تا شهر مایانس منزل داشت . در کنار رودخانه ٔ سن که شعبه ای است از رن، بورگندها و واندال ها سکنی گرفته و در جنوب آن در مقابل آلزاس آلامانها رحل اقامت افکنده بودند. در طول رود دانوب قبیله ٔ مارکمان که اخیراً سوئو معروف بود سکنی داشت . بعض قبایل واندالها در مجارستان فعلی بودند و بالاخره در کنار دانوب سفلی و ساحل شمال دریای سیاه ویزیگت ها و اُسترگت ها مقیم بودند. در داخله ٔ ژرمانی مهمترین طوایف لمباردها بودند و انگل ها و ساکسن ها سواحل بحر شمال را از دانمارک تا رن در تصرف داشتند. (ترجمه ٔ تاریخ رم آلبر ماله ص <span class=\"hlight\" dir=\"rtl\">٣٣٤</span>).<br /></font></div>'),
(288008, 'ژرمانیا', '<span class=\"hlight\">ژرمانیا.</span> <font color=\"DarkGreen\"><b>[ ژِ ]</font></b> (اِخ ) نام ستاره ای است که جز بکمک تلسکوپ دیده نمیشود و آن را لوتر بسال <span class=\"hlight\" dir=\"rtl\">١٨٨٤</span> م . کشف کرد.<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(288009, 'ژرمانیه', '<span class=\"hlight\">ژرمانیه .</span> <font color=\"DarkGreen\"><b>[ ژِ ی َ ]</font></b> (اِخ ) نام کشور ژرمنها. رجوع به ژرمانیا و آلمان شود.<br /></font></div>'),
(288010, 'ژرمانیکوس', '<span class=\"hlight\">ژرمانیکوس .</span> <font color=\"DarkGreen\"><b>[ ژِ ]</font></b> (اِخ ) نام سردار رومی از خاندان اگوست، پسر بزرگ دروزوس برادر تیبریوس قیصر روم، معاصر اردوان سوم اشکانی و پدر آگری پین و پدربزرگ نرون . وی بسال <span class=\"hlight\" dir=\"rtl\">١٨</span> م . بنابه فرمان عموی خود قیصر روم به فرمانفرمائی کل آسیای رومی (از داردانل تا فرات ) گماشته شد و چون پیش ازآن بجهت شورش ژرمن ها به کشور ایشان لشکر کشیده و پیروز گردیده بود ژرمانیکوس یعنی فاتح ژرمن ها لقب یافته بود. بنابه روایت مورخین رومی، وی مردی دلیر و مؤدب و سربازی باتقوی و محبوب القلوب بود و رفتاری نجیبانه داشت . ولی تیبریوس باطناً با او مخالف بود و در سال <span class=\"hlight\" dir=\"rtl\">١٩</span> م . پیزون والی سوریه را مأمور کشتن او کرد ووی او را مسموم ساخت . (ایران باستان ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٢٣٩٤</span>).<br /></font></div>'),
(288011, 'ژرمن', '<span class=\"hlight\">ژرمن .</span> <font color=\"DarkGreen\"><b>[ ژِ م َ ]</font></b> (اِخ ) هانری . نام سیاستمدار ومتخصص در امور مالی فرانسوی . مولد لیون بسال <span class=\"hlight\" dir=\"rtl\">١٨٢٤</span> ووفات در پاریس بسال <span class=\"hlight\" dir=\"rtl\">١٩٠٥</span> م . او را آثاری چند است .<br /></font></div>'),
(288012, 'ژرمن', '<span class=\"hlight\">ژرمن .</span> <font color=\"DarkGreen\"><b>[ ژِ م َ]</font></b> (اِخ ) میشل . از مردم فرانسه . بِنه دیکتن سنت مور و عالم به خطوط قدیمه . مولدبسال <span class=\"hlight\" dir=\"rtl\">١٦٤٥</span> در پرون و وفات بسال <span class=\"hlight\" dir=\"rtl\">١٦٩٤</span> م . در پاریس .<br /></font></div>'),
(288013, 'ژرمن', '<span class=\"hlight\">ژرمن .</span> <font color=\"DarkGreen\"><b>[ ژِ م َ ]</font></b> (اِخ ) (قدیس ) او را ژرمن کوزَن گویند. وی در پیبراک نزدیکی تولوز بسال <span class=\"hlight\" dir=\"rtl\">١٥٧٩</span> م . متولد شد و بسال <span class=\"hlight\" dir=\"rtl\">١٦٠١</span> در همانجا درگذشت . مقبره ٔ او زیارتگاه مردم است .<br /></font></div>'),
(288014, 'ژرمن', '<span class=\"hlight\">ژرمن .</span> <font color=\"DarkGreen\"><b>[ ژِ م َ ]</font></b> (اِخ ) (قدیس ) نام اسقف پاریس . مولد در نزدیکی اُتُن بسال <span class=\"hlight\" dir=\"rtl\">٤٩٦</span> و وفات در پاریس بسال <span class=\"hlight\" dir=\"rtl\">٥٧٦</span> م . ذکران وی روز <span class=\"hlight\" dir=\"rtl\">٢٨</span> ماه مه است .<br /></font></div>'),
(288015, 'ژرمن', '<span class=\"hlight\">ژرمن .</span> <font color=\"DarkGreen\"><b>[ ژِ م َ ]</font></b> (اِخ ) (قدیس ) نام اسقف اکسر و متولد در همان شهر در حدود سال <span class=\"hlight\" dir=\"rtl\">٣٩٠</span> و متوفی در راوِن بسال <span class=\"hlight\" dir=\"rtl\">٤٤٨</span> م . ذکران او روز <span class=\"hlight\" dir=\"rtl\">٣١</span> ژوئیه است .<br /></font></div>'),
(288016, 'ژرمن', '<span class=\"hlight\">ژرمن .</span> <font color=\"DarkGreen\"><b>[ ژِ م َ ]</font></b> (اِخ ) سوفی . نام ریاضی دان فرانسوی . مولد پاریس بسال <span class=\"hlight\" dir=\"rtl\">١٧٧٦</span> و وفات در همانجا بسال <span class=\"hlight\" dir=\"rtl\">١٨٣١</span> م .<br /></font></div>'),
(288017, 'ژرمن', '<span class=\"hlight\">ژرمن .</span> <font color=\"DarkGreen\"><b>[ ژِ م َ ]</font></b> (اِخ ) پیر دوّم . نام زرگر معروف فرانسوی (<span class=\"hlight\" dir=\"rtl\">١٧٢٢</span>-<span class=\"hlight\" dir=\"rtl\">١٧٩٧</span> م .). وی را بسبب اقامت در رُم رومی گویند. رسالتی در اصول فن زرگری دارد.<br /></font></div>'),
(288018, 'ژرمن', '<span class=\"hlight\">ژرمن .</span> <font color=\"DarkGreen\"><b>[ ژِ م َ ]</font></b> (اِخ ) پیر ژرمن اول . نام زرگر معروف فرانسوی (<span class=\"hlight\" dir=\"rtl\">١٦٤٧</span>-<span class=\"hlight\" dir=\"rtl\">١٦٨٤</span> م .).<br /></font></div>'),
(288019, 'ژرمن', '<span class=\"hlight\">ژرمن .</span> <font color=\"DarkGreen\"><b>[ ژِ م َ ]</font></b> (اِخ ) الکساندر شارل .نام مورخ فرانسوی . مولد بسال <span class=\"hlight\" dir=\"rtl\">١٨٠٩</span> در پاریس و وفات بسال <span class=\"hlight\" dir=\"rtl\">١٨٨٧</span> م . در مونت پلیه . او را آثار بسیاری است .<br /></font></div>'),
(288020, 'ژرمن', '<span class=\"hlight\">ژرمن .</span> <font color=\"DarkGreen\"><b>[ ژِ م َ ]</font></b> (اِخ ) اگوست ژان . نام کنت ِ مونت فرت و سیاستمدار فرانسوی . مولد پاریس بسال <span class=\"hlight\" dir=\"rtl\">١٧٨٦</span> و وفات در همانجا بسال <span class=\"hlight\" dir=\"rtl\">١٨٢١</span> م .<br /></font></div>'),
(288021, 'ژرمن', '<span class=\"hlight\">ژرمن .</span> <font color=\"DarkGreen\"><b>[ ژِ م َ ]</font></b> (اِخ ) اگوست . نام مورخ و رمان و نمایشنامه نویس فرانسوی . مولد پاریس بسال <span class=\"hlight\" dir=\"rtl\">١٨٦٢</span> و وفات در همانجا بسال <span class=\"hlight\" dir=\"rtl\">١٩١٥</span> م .<br /></font></div>'),
(288022, 'ژرمن', '<span class=\"hlight\">ژرمن .</span> <font color=\"DarkGreen\"><b>[ ژِ م َ ]</font></b> (اِخ ) نامی که به ساکنین ژرمانی یا آلمان اطلاق می شود. این قوم چنانکه از اخلاق و زبان و صورت ظاهر آنان پیداست از نژاد آریائی هندواروپائی هستند که در حدود قرن هفتم یا ششم پیش از میلاد بنابه روایتی از آسیا مهاجرت کرده و از طریق دره ٔ دانوب به اروپا راه یافته اند و آنان یکی از شعب هشتگانه ٔ ملل هندواروپائی بشمار می روند. نام ژرمن شامل آلمان های غربی و شرقی اروپا و انگلوساکسونها و اسکاندیناویها نیزمی شود. دین قدیم آنان پرستش مظاهر طبیعت بود و در نظام اجتماعی ایشان هر فردی آزادی تام و تمام داشت .<br /></font></div>'),
(288023, 'ژرمن دپره', '<span class=\"hlight\">ژرمن دپره .</span> <font color=\"DarkGreen\"><b>[ ژِ م َ دِ رِ ]</font></b> (اِخ ) (اِگلیز سن ...) نام یکی از کلیساهای مشهور و بسیار قدیم پاریس که تاکنون برپاست . این کلیسا را شیلدبر اول بسال <span class=\"hlight\" dir=\"rtl\">٥٥٨</span> م . بنا کرده است . بنای خارجی آن که بطرز رومی و گتی می باشد معرف فن معماری در قرن یازدهم میلادی است .<br /></font></div>'),
(288024, 'ژرمن دپره', '<span class=\"hlight\">ژرمن دپره .</span> <font color=\"DarkGreen\"><b>[ ژِ م َ دِ رِ ]</font></b> (اِخ ) (فوار دُسن ...) یکی از قدیمترین و مشهورترین نقاط پاریس . در آغاز هر سال میلادی و پانزده روز بعد از عید پاک (فصح ) این بازار گشاده شود و مدت آن سه هفته کشد.<br /></font></div>'),
(288025, 'ژرمن لوکسروآ', '<span class=\"hlight\">ژرمن لوکسروآ.</span> <font color=\"DarkGreen\"><b>[ ژِ م َ لُک ْ س ِ ]</font></b> (اِخ ) (کلیسای مقدس ) نام کلیسائی قدیمی در پاریس مقابل لوور. اساس ساختمان آن در قرن ششم میلادی گذارده شده است .<br /></font></div>'),
(288026, 'ژرمنی', '<span class=\"hlight\">ژرمنی .</span> <font color=\"DarkGreen\"><b>[ ژِ م َ ]</font></b> (ص نسبی ) منسوب به ژرمن . رجوع به ژرمن شود.<br /></font></div>'),
(288027, 'ژرمه', '<span class=\"hlight\">ژرمه .</span> <font color=\"DarkGreen\"><b>[ ژِ م ِ ]</font></b> (اِخ ) (قدیس ) یا ژِرمار. نام یکی ازقدّیسین بووِزی مولد سال <span class=\"hlight\" dir=\"rtl\">٦١٠</span> و وفات بسال <span class=\"hlight\" dir=\"rtl\">٦٥٨</span> م . ذکران وی <span class=\"hlight\" dir=\"rtl\">٢٨</span> سپتامبر است .<br /></font></div>'),
(288028, 'ژرمی', '<span class=\"hlight\">ژرمی .</span> <font color=\"DarkGreen\"><b>[ ژِ رِ ]</font></b> (اِخ ) یکی از چهار پیغمبر اسرائیل و دومین پیغمبر اعظم عهد عتیق . مولد حدود سال <span class=\"hlight\" dir=\"rtl\">٦٥٠</span>و وفات در حدود سال <span class=\"hlight\" dir=\"rtl\">٥٩٠</span> ق .م . رجوع به اَرمیا شود.<br /></font></div>'),
(288029, 'ژرن', '<span class=\"hlight\">ژرن .</span> <font color=\"DarkGreen\"><b>[ ژِ رُ ]</font></b> (اِخ ) (سابقاً: باروک ) نام قصبه ای به مجمعالجزایر فیلیپین (در جزیره ٔ لوسَن )، دارای <span class=\"hlight\" dir=\"rtl\">٧٨٠٥</span> تن سکنه .<br /></font></div>'),
(288030, 'ژرن', '<span class=\"hlight\">ژرن .</span> <font color=\"DarkGreen\"><b>[ ژِ رُ ]</font></b> (اِخ ) نام شهری به اسپانیا در کاتالونی، دارای <span class=\"hlight\" dir=\"rtl\">١٨٠٠٠</span> تن سکنه و آنجا کرسی ایالت باشد.<br /></font></div>'),
(288031, 'ژرنه', '<span class=\"hlight\">ژرنه .</span> <font color=\"DarkGreen\"><b>[ ژِ ن ِ ]</font></b> (اِخ ) دِزیره . نام فیزیک دان فرانسوی . مولد والنسین (<span class=\"hlight\" dir=\"rtl\">١٨٣٤</span> - <span class=\"hlight\" dir=\"rtl\">١٩١٠</span> م .). وی را در غلیان و تبلور و قوه ٔ حرکت وضعیه مطالعاتی است .<br /></font></div>'),
(288032, 'ژره گی ای آگیلار', '<span class=\"hlight\">ژره گی ای آگیلار.</span> <font color=\"DarkGreen\"><b>[ ژُ رِ ]</font></b> (اِخ ) نام شاعر و نقاش اسپانیائی . مولد سویل بسال <span class=\"hlight\" dir=\"rtl\">١٥٧٠</span> و وفات بسال <span class=\"hlight\" dir=\"rtl\">١٦٤٠</span> م .<br /></font></div>'),
(288033, 'ژره گیبری', '<span class=\"hlight\">ژره گیبری .</span> <font color=\"DarkGreen\"><b>[ ژُ رِ ب ِ ]</font></b> (اِخ ) ژان برنارد. نام فلاح فرانسوی . مولد بایون و وفات به پاریس (<span class=\"hlight\" dir=\"rtl\">١٨١٥</span> - <span class=\"hlight\" dir=\"rtl\">١٨٨٧</span> م .).<br /></font></div>'),
(288034, 'ژرو', '<span class=\"hlight\">ژرو.</span> <font color=\"DarkGreen\"><b>[ ژِ رُ ]</font></b> (اِخ ) نام مرزبان آلمانی به مرز شرقی . وی میان سالهای <span class=\"hlight\" dir=\"rtl\">٩٠٠</span> - <span class=\"hlight\" dir=\"rtl\">٩٦٥</span> م . میزیست و از قهرمانان روزگار خود بود.<br /></font></div>'),
(288035, 'ژروزالم', '<span class=\"hlight\">ژروزالم .</span> <font color=\"DarkGreen\"><b>[ ژِ ل ِ ]</font></b> (اِخ ) ژان فردریک گیوم .عالم کلامی پرتستانی مذهب از مردم آلمان . مولد بسال <span class=\"hlight\" dir=\"rtl\">١٧٠٩</span> در اسنابروک و وفات بسال <span class=\"hlight\" dir=\"rtl\">١٧٨٩</span> م . در برونسویک .<br /></font></div>'),
(288036, 'ژروزالم', '<span class=\"hlight\">ژروزالم .</span> <font color=\"DarkGreen\"><b>[ ژِ ل ِ ]</font></b> (اِخ )الیز. نام زنی ادیبه از مردم آلمان . نام مستعار الیز ویداکوویخ . او بسال <span class=\"hlight\" dir=\"rtl\">١٨٧٧</span> م . در وین متولد شد و در بوئنوسایرس اقامت داشت .<br /></font></div>'),
(288037, 'ژروزالم', '<span class=\"hlight\">ژروزالم .</span> <font color=\"DarkGreen\"><b>[ ژِ ل ِ ]</font></b> (اِخ ) اورشلیم . رجوع به اورشلیم شود.<br /></font></div>'),
(288038, 'ژروزالم دلیوره', '<span class=\"hlight\">ژروزالم دلیوره .</span> <font color=\"DarkGreen\"><b>[ ژِ ل ِ دِ وْ رِ ]</font></b> (اِخ ) نام منظومه ای حماسی که آن را لوتاس در بیست قطعه سروده است (<span class=\"hlight\" dir=\"rtl\">١٥٧٥</span> م .).<br /></font></div>'),
(288039, 'ژروزز', '<span class=\"hlight\">ژروزز.</span> <font color=\"DarkGreen\"><b>[ ژِ زِ ]</font></b> (اِخ ) ژان باتیست فرانسوا. نام ادیب فرانسوی . مولد ریمس بسال <span class=\"hlight\" dir=\"rtl\">١٧٦٤</span> و وفات بسال <span class=\"hlight\" dir=\"rtl\">١٨٣٠</span> م .<br /></font></div>'),
(288040, 'ژروه', '<span class=\"hlight\">ژروه .</span> <font color=\"DarkGreen\"><b>[ ژِرْ وِ ]</font></b> (اِخ ) (سن ...) نام کلیسائی به پاریس بدانسوی هتل دوویل . این کلیسا از قرن ششم میلادی برپاست و به «ژروه » و «پروته » دو برادر شهید اهداء شده است .<br /></font></div>'),
(288041, 'ژروه', '<span class=\"hlight\">ژروه .</span> <font color=\"DarkGreen\"><b>[ ژِرْ وِ ]</font></b> (اِخ ) شارل هوبر. نام ترانه ساز فرانسوی . مولد پاریس بسال <span class=\"hlight\" dir=\"rtl\">١٦٧١</span> و وفات در همانجا بسال <span class=\"hlight\" dir=\"rtl\">١٧٤٤</span> م .<br /></font></div>'),
(288042, 'ژروه', '<span class=\"hlight\">ژروه .</span> <font color=\"DarkGreen\"><b>[ ژِرْ وِ ]</font></b> (اِخ ) پل . نام طبیعی دان فرانسوی . مولد و وفات در پاریس (<span class=\"hlight\" dir=\"rtl\">١٨١٦</span>-<span class=\"hlight\" dir=\"rtl\">١٨٧٩</span> م .).<br /></font></div>'),
(288043, 'ژروه', '<span class=\"hlight\">ژروه .</span> <font color=\"DarkGreen\"><b>[ ژِرْ وِ ]</font></b> (اِخ ) آلفرد آلبرت . نام امیرالبحر فرانسوی . مولد بسال <span class=\"hlight\" dir=\"rtl\">١٨٣٧</span> در پروونس و وفات بسال <span class=\"hlight\" dir=\"rtl\">١٩٢١</span> م .<br /></font></div>'),
(288044, 'ژروه دکانتوربری', '<span class=\"hlight\">ژروه دکانتوربری .</span> <font color=\"DarkGreen\"><b>[ ژِرْ وِ دُ تُرْ ب ِ ]</font></b> (اِخ ) نام راهب و مورخ انگلیسی . مولد حدود سال <span class=\"hlight\" dir=\"rtl\">١١٤١</span> و وفات در حدود سال <span class=\"hlight\" dir=\"rtl\">١٢١٠</span> م .<br /></font></div>'),
(288045, 'ژروه و پروته', '<span class=\"hlight\">ژروه و پروته .</span> <font color=\"DarkGreen\"><b>[ ژِرْ وِ وَ پْرُ <span class=\"hlight\" dir=\"rtl\">/</span> پ ُ رُ ت ِ ]</font></b> (اِخ ) نام دو برادر مسیحی که در زمان امپراطوری نِرُن در شهر میلان به شهادت رسیدند. ذکرانشان <span class=\"hlight\" dir=\"rtl\">١٩</span> ژوئن است و کلیسای سن ژروه بدیشان اهداء شده است .<br /></font></div>'),
(288046, 'ژروکس', '<span class=\"hlight\">ژروکس .</span> <font color=\"DarkGreen\"><b>[ژِرْ وِ ]</font></b> (اِخ ) هانری . نام نقاش فرانسوی استاد در ترسیم موضوعات تاریخی . مولد پاریس بسال <span class=\"hlight\" dir=\"rtl\">١٨٥٢</span> و وفات در همانجا بسال <span class=\"hlight\" dir=\"rtl\">١٩٢٩</span> م .<br /></font></div>'),
(288047, 'ژروینوس', '<span class=\"hlight\">ژروینوس .</span> <font color=\"DarkGreen\"><b>[ ژِرْ ]</font></b> (اِخ ) ژُرژ گدفری .نام تاریخ دان و سیاستمدار آلمانی . مولد دارمستاد بسال <span class=\"hlight\" dir=\"rtl\">١٨٠٥</span> و وفات بسال <span class=\"hlight\" dir=\"rtl\">١٨٧١</span> م . وی مؤلف تاریخی است درحوادث قرن نوزدهم، پس از عهدنامه ٔ وین تا <span class=\"hlight\" dir=\"rtl\">١٨٣١</span> م .<br /></font></div>'),
(288048, 'ژرپوز', '<span class=\"hlight\">ژرپوز.</span> <font color=\"DarkGreen\"><b>[ ژَ ]</font></b> (اِ) کلاکموش . موش دشتی . موش صحرائی . موش دوپا. یربوع .<br /></font></div>'),
(288049, 'ژرژ', '<span class=\"hlight\">ژرژ.</span> <font color=\"DarkGreen\"><b>[ ژُ ]</font></b> (اِخ ) یگُر ولادیمیرُویچ ملقب به دُل گوروکی یا درازدست . امیر شهر کیف و امیر اعظم روسیه . وی بسال <span class=\"hlight\" dir=\"rtl\">١١٥٧</span> م . پس از آغاز بنای مسکو درگذشت .<br /></font></div>'),
(288050, 'ژرژ', '<span class=\"hlight\">ژرژ.</span> <font color=\"DarkGreen\"><b>[ ژُ ]</font></b> (اِخ ) هانری . نویسنده و سیاستمدار امریکائی . مولد بسال <span class=\"hlight\" dir=\"rtl\">١٨٣٩</span> در فیلادلفیا و وفات در نیویورک بسال <span class=\"hlight\" dir=\"rtl\">١٨٩٩</span> م .<br /></font></div>'),
(288051, 'ژرژ', '<span class=\"hlight\">ژرژ.</span> <font color=\"DarkGreen\"><b>[ ژُ ]</font></b> (اِخ ) ملقب به متاتسمیندل . یکی از قدیسات ارمنی . وی به تیالت (در گرجستان ) در حدود سال <span class=\"hlight\" dir=\"rtl\">١٠١٤</span> م . متولد شد و بسال <span class=\"hlight\" dir=\"rtl\">١٠٧٢</span> درگذشت .<br /></font></div>'),
(288052, 'ژرژ', '<span class=\"hlight\">ژرژ.</span> <font color=\"DarkGreen\"><b>[ ژُ ]</font></b> (اِخ ) مادموازل مارگریت ژزفین ویمر. هنرپیشه ٔ فرانسوی . مولد بایو بسال <span class=\"hlight\" dir=\"rtl\">١٧٨٧</span> و وفات بسال <span class=\"hlight\" dir=\"rtl\">١٨٦٧</span> م .<br /></font></div>'),
(288053, 'ژرژ', '<span class=\"hlight\">ژرژ.</span><font color=\"DarkGreen\"><b>[ ژُ ]</font></b> (اِخ ) (گیورگیس ) رجوع به مهران گشنسب شود.<br /></font></div>'),
(288054, 'ژرژ', '<span class=\"hlight\">ژرژ.</span> <font color=\"DarkGreen\"><b>[ ژُ ]</font></b>(اِخ ) (قدّیس ) نام مردی مروّج دین مسیح . اسقف وُلای . عصر زندگی و احوال وی مبهم است، برخی او را از مردم قرن اول و گروهی قرن چهارم میلادی دانسته اند. ذکران او روز دهم نوامبر است .<br /></font></div>'),
(288055, 'ژرژ', '<span class=\"hlight\">ژرژ.</span> <font color=\"DarkGreen\"><b>[ ژُ ]</font></b> (اِخ ) (قدّیس ) نام امیر کاپادوکیه . او بسال <span class=\"hlight\" dir=\"rtl\">٣٠٣</span> م . بفرمان دیوکلسین کشته شد. وی بالخصوص مورد افتخار و تقدیس انگلیسیان و مردم روسیه و ذکران او روز <span class=\"hlight\" dir=\"rtl\">٢٣</span> آوریل است .<br /></font></div>'),
(288056, 'ژرژ', '<span class=\"hlight\">ژرژ.</span> <font color=\"DarkGreen\"><b>[ ژُ ]</font></b> (اِخ ) داوید للوید. سیاستمدار انگلیسی . مولد بسال <span class=\"hlight\" dir=\"rtl\">١٨٦٣</span> م . در منچستر. وی رئیس حزب آزادی خواهان و نخست وزیر کابینه ٔ ائتلافی از <span class=\"hlight\" dir=\"rtl\">١٩١٦</span> تا <span class=\"hlight\" dir=\"rtl\">١٩٢٢</span> بود.<br /></font></div>'),
(288057, 'ژرژ', '<span class=\"hlight\">ژرژ.</span> <font color=\"DarkGreen\"><b>[ ژُ ]</font></b>(اِخ ) (نشان قدیس ...) نام نشان روسیه . آن را کاترین دوم ملکه ٔ روسیه به منظور سپاسداری از ابراز لیاقت بسال <span class=\"hlight\" dir=\"rtl\">١٧٦٩</span> م . باب کرد. روبان این نشان را هفت راه، چهار زرد و سه سیاه است .<br /></font></div>'),
(288058, 'ژرژ', '<span class=\"hlight\">ژرژ.</span> <font color=\"DarkGreen\"><b>[ ژُ ]</font></b> (اِخ ) نام دوک ِ ساکس . او را باربو گفتندی (<span class=\"hlight\" dir=\"rtl\">١٤٧١</span>-<span class=\"hlight\" dir=\"rtl\">١٥٣٩</span> م .).<br /></font></div>'),
(288059, 'ژرژ', '<span class=\"hlight\">ژرژ.</span> <font color=\"DarkGreen\"><b>[ ژُ ]</font></b> (اِخ ) نام ناحیتی به افریقای جنوبی از مستعمرات انگلیس، دارای <span class=\"hlight\" dir=\"rtl\">١٠٠٩٥</span> تن سکنه .<br /></font></div>'),
(288060, 'ژرژ اسکولاریوس', '<span class=\"hlight\">ژرژ اسکولاریوس .</span> <font color=\"DarkGreen\"><b>[ ژُ اِ ک ُ یُس ْ ]</font></b> (اِخ ) نام یکی از نوع پروران (هومانیست ها) بیزانسی در قرن پانزدهم میلادی . وفات بین سالهای <span class=\"hlight\" dir=\"rtl\">١٤٦٨</span> و <span class=\"hlight\" dir=\"rtl\">١٤٦٤</span> م .<br /></font></div>'),
(288061, 'ژرژ اول', '<span class=\"hlight\">ژرژ اول .</span> <font color=\"DarkGreen\"><b>[ ژُ ژِ اَوْ وَ ]</font></b> (اِخ ) (جُرج اول ) نام امیر منتخب (الکتور) هانور و پادشاه انگلیس و سرسلسله ٔ خاندان هانور که تاکنون در انگلستان پادشاهی دارند. مولداُسنابروک بسال <span class=\"hlight\" dir=\"rtl\">١٦٦٠</span> و وفات بسال <span class=\"hlight\" dir=\"rtl\">١٧٢٧</span> م . وی بسال <span class=\"hlight\" dir=\"rtl\">١٧١٤</span> به شاهی نشسته است .<br /></font></div>'),
(288062, 'ژرژ اول', '<span class=\"hlight\">ژرژ اول .</span> <font color=\"DarkGreen\"><b>[ ژُ ژِ اَوْ وَ ]</font></b> (اِخ ) پادشاه یونان پسر کریستیان نهم پادشاه دانمارک .وی بسال <span class=\"hlight\" dir=\"rtl\">١٨٤٥</span> در کپنهاگ متولد شد و در سال <span class=\"hlight\" dir=\"rtl\">١٨٦٣</span> تاجگذاری کرد و بسال <span class=\"hlight\" dir=\"rtl\">١٩١٣</span> م . در سالونیک به قتل رسید.<br /></font></div>'),
(288063, 'ژرژ داندن', '<span class=\"hlight\">ژرژ داندن .</span> <font color=\"DarkGreen\"><b>[ ژُدَ ]</font></b> (اِخ ) نام پیسی فکاهی (کمدی ) به نثر در سه پرده از آثار مولیر که در سال <span class=\"hlight\" dir=\"rtl\">١٦٦٨</span> م . نوشته شده است .<br /></font></div>'),
(288064, 'ژرژ دانیل ویچ', '<span class=\"hlight\">ژرژ دانیل ویچ .</span> <font color=\"DarkGreen\"><b>[ ژُ ل ُ ]</font></b> (اِخ ) نام امیر روسیه (<span class=\"hlight\" dir=\"rtl\">١٣١٩</span> - <span class=\"hlight\" dir=\"rtl\">١٣٢٥</span> م .) پسر کوچک آلکساندر نوْسکی . مولد سال <span class=\"hlight\" dir=\"rtl\">١٢٨١</span> م .<br /></font></div>'),
(288065, 'ژرژ دتربیزند', '<span class=\"hlight\">ژرژ دتربیزند.</span> <font color=\"DarkGreen\"><b>[ ژُ دُ رِ زُ ]</font></b> (اِخ ) نام هومانیست بیزانسی در قرن پانزدهم میلادی . وی بسال <span class=\"hlight\" dir=\"rtl\">١٣٩٦</span> م . متولد شد و بسال <span class=\"hlight\" dir=\"rtl\">١٤٨٦</span> در رُم درگذشت . از آثار مترجم این مرد المجسطی بطلمیوس و فن خطابه ٔ ارسطو است .<br /></font></div>'),
(288066, 'ژرژ ددانمارک', '<span class=\"hlight\">ژرژ ددانمارک .</span> <font color=\"DarkGreen\"><b>[ ژُ دُ ن ِ ]</font></b> (اِخ ) نام شاهزاده ٔ دانمارکی . مولد سال <span class=\"hlight\" dir=\"rtl\">١٦٥٣</span> درکپنهاگ و وفات بسال <span class=\"hlight\" dir=\"rtl\">١٧٠٨</span> م . در کنسینگتن . پسر فردریک سوّم پادشاه دانمارک .<br /></font></div>'),
(288067, 'ژرژ دشیپر', '<span class=\"hlight\">ژرژ دشیپر.</span> <font color=\"DarkGreen\"><b>[ ژُ دُ ]</font></b> (اِخ ) نام جغرافیادان بیزانسی در اوائل قرن هفتم میلادی مؤلف تاریخ عمومی امپراطوری روم .<br /></font></div>'),
(288068, 'ژرژ دلاادیسه', '<span class=\"hlight\">ژرژ دلاادیسه .</span> <font color=\"DarkGreen\"><b>[ ژُ دُ اُ س ِ ]</font></b> (اِخ ) نام یکی از مبدعان در دین مسیح در قرن چهارم میلادی . وی روزگاری اُسقف لااُدیسه بوده است، از اینرو او را بدان شهر نسبت داده اند.<br /></font></div>'),
(288069, 'ژرژ دنیکمدی', '<span class=\"hlight\">ژرژ دنیکمدی .</span> <font color=\"DarkGreen\"><b>[ ژُ دُ ک ُ م ِ ]</font></b> (اِخ ) نام اسقف الاساقفه ٔ نیقوسه . متوفی در حدود سال <span class=\"hlight\" dir=\"rtl\">٨٩٠</span> م . وی قبل از نیقوسه اسقف الاساقفه ٔ سن سوفی قسطنطنیه بوده است .<br /></font></div>'),
(288070, 'ژرژ دوم', '<span class=\"hlight\">ژرژ دوم .</span> <font color=\"DarkGreen\"><b>[ ژُ ژِ دُوْ وُ ]</font></b> (اِخ ) وسولودویچ . نام امیر ولادیمیرو سوزدال و امیر روسیه . مولد میان سالهای <span class=\"hlight\" dir=\"rtl\">١١٨٧</span> و <span class=\"hlight\" dir=\"rtl\">١١٨٩</span> و وفات بسال <span class=\"hlight\" dir=\"rtl\">١٢٣٨</span> م .<br /></font></div>'),
(288071, 'ژرژ دوم', '<span class=\"hlight\">ژرژ دوم .</span> <font color=\"DarkGreen\"><b>[ ژُ ژِ دُوْ وُ ]</font></b> (اِخ ) (جرج دوم ) پادشاه انگلیس فرزند ژرژ اول . وی بسال <span class=\"hlight\" dir=\"rtl\">١٦٨٣</span> در هانور متولد شد و بسال <span class=\"hlight\" dir=\"rtl\">١٧٦٠</span> م . در کنسینگتن درگذشت .<br /></font></div>'),
(288072, 'ژرژ دوم', '<span class=\"hlight\">ژرژ دوم .</span> <font color=\"DarkGreen\"><b>[ ژُ ژِ دُوْ وُ ]</font></b> (اِخ ) نام پادشاه یونان . پسر بزرگ کنستانتین شاه یونان و ملکه ٔسوفی شاهزاده ٔ پروس . مولد سال <span class=\"hlight\" dir=\"rtl\">١٨٩٠</span> م . در تاتوئی .<br /></font></div>'),
(288073, 'ژرژ سوم', '<span class=\"hlight\">ژرژ سوم .</span> <font color=\"DarkGreen\"><b>[ ژُ ژِ س ِوْ وُ ]</font></b> (اِخ ) (جُرج سوم ) پادشاه انگلیس . مولد لندن بسال <span class=\"hlight\" dir=\"rtl\">١٧٣٨</span> و وفات در ویندسر بسال <span class=\"hlight\" dir=\"rtl\">١٨٢٠</span> م . پسر فردریک امیر گال . در زمان وی مستعمره ٔ آمریکا از تصرف انگلیس خارج گشت .<br /></font></div>'),
(288074, 'ژرژ ششم', '<span class=\"hlight\">ژرژ ششم .</span> <font color=\"DarkGreen\"><b>[ ژُ ژِ ش ِ ش ُ ]</font></b> (اِخ ) (جرج ششم )نام پادشاه انگلیس پسر دوم ژرژ پنجم . وی بسال <span class=\"hlight\" dir=\"rtl\">١٨٩٥</span> م . در ساندرینگهام متولد شد و بسال <span class=\"hlight\" dir=\"rtl\">١٩٣٦</span> پس از استعفای برادر مهتر خود ادواردهشتم به سلطنت نشست و اینک نیز شاه انگلستان است .<br /></font></div>'),
(288075, 'ژرژ لوسینسل', '<span class=\"hlight\">ژرژ لوسینسل .</span> <font color=\"DarkGreen\"><b>[ ژُ ل ُ س ِ ]</font></b> (اِخ ) نام مورخ بیزانسی در نیمه ٔ دوم قرن هشتم میلادی . وی را تاریخی است که از خلقت جهان آغازمیشود و به مرگ دیوکلسین (<span class=\"hlight\" dir=\"rtl\">٢٨٤</span> م .) خاتمه میپذیرد.<br /></font></div>'),
(288076, 'ژرژ لوموان', '<span class=\"hlight\">ژرژ لوموان .</span> <font color=\"DarkGreen\"><b>[ ژُ ل ُ ]</font></b>(اِخ ) غالباً او را ژرژ هامارتل یا پِشُر گفته اند. نام مورخ بیزانسی در قرن نهم میلادی . وی در اواخر سلطنت میشل سوم (<span class=\"hlight\" dir=\"rtl\">٨٤٢</span>-<span class=\"hlight\" dir=\"rtl\">٨٦٧</span> م .) میزیست . او را تاریخی عمومی است واز خلقت جهان آغاز کرده و به مرگ تئوفیل (<span class=\"hlight\" dir=\"rtl\">٨٤٢</span> م .) پایان داده است .<br /></font></div>'),
(288077, 'ژرژ پنجم', '<span class=\"hlight\">ژرژپنجم .</span> <font color=\"DarkGreen\"><b>[ ژُ ژِ پ َ ج ُ ]</font></b> (اِخ ) (جرج پنجم ) پادشاه انگلیس پسر ادوارد هفتم . وی بسال <span class=\"hlight\" dir=\"rtl\">١٨٦٥</span> م . در لندن تولد یافت و بسال <span class=\"hlight\" dir=\"rtl\">١٩١٠</span> به پادشاهی نشست و بسال <span class=\"hlight\" dir=\"rtl\">١٩١٧</span>سلسله ٔ خود را ویندسور نامید و بسال <span class=\"hlight\" dir=\"rtl\">١٩٣٦</span> درگذشت .<br /></font></div>'),
(288078, 'ژرژ پیزیدس', '<span class=\"hlight\">ژرژ پیزیدس .</span> <font color=\"DarkGreen\"><b>[ ژُ دِ ]</font></b> (اِخ ) نام شاعر کلامی و فلسفی بیزانسی در قرن هفتم میلادی معاصر هرقل امپراطور رُم . وی جنگهای این سلطان را با ایران و آوارها بنظم آورده است .<br /></font></div>'),
(288079, 'ژرژ چهارم', '<span class=\"hlight\">ژرژ چهارم .</span> <font color=\"DarkGreen\"><b>[ ژُ ژِچ َ رُ ]</font></b> (اِخ ) (جرج چهارم ) نام پادشاه انگلستان پسربزرگ ژرژ سوم . وی بسال <span class=\"hlight\" dir=\"rtl\">١٧٦٢</span> م . در لندن تولد یافت وبسال <span class=\"hlight\" dir=\"rtl\">١٨٣٠</span> در ویندسور درگذشت و در <span class=\"hlight\" dir=\"rtl\">١٨١٠</span> نایب السلطنه ٔ انگلستان شد و در <span class=\"hlight\" dir=\"rtl\">١٨٢٠</span> به شاهی نشست . به عهد او کشور ایرلند استقلال یافت .<br /></font></div>'),
(288080, 'ژرژتون', '<span class=\"hlight\">ژرژتون .</span> <font color=\"DarkGreen\"><b>[ ژُ ت َ ]</font></b>(اِخ ) جرج تون . یا سن ژرژ. پایتخت جزیره ٔ گرناد، یکی از جزایر آنتیل کوچک، دارای قریب <span class=\"hlight\" dir=\"rtl\">٥٠٠٠</span> تن سکنه . آنجا مقر حکومت انگلیس است .<br /></font></div>'),
(288081, 'ژرژتون', '<span class=\"hlight\">ژرژتون .</span> <font color=\"DarkGreen\"><b>[ژُ ت َ ]</font></b> (اِخ ) جرج تون . نام شهری به اتازونی (در کارولین جنوبی ) کرسی بخش ژرژتون، دارای <span class=\"hlight\" dir=\"rtl\">٤٣١٠</span> تن سکنه .<br /></font></div>'),
(288082, 'ژرژتون', '<span class=\"hlight\">ژرژتون .</span> <font color=\"DarkGreen\"><b>[ ژُ ت َ ]</font></b> (اِخ ) جرج تون . نام شهری به ممالک متحده ٔ امریکا (در ایالت کلمبیا) کنار رود پتوماک، دارای <span class=\"hlight\" dir=\"rtl\">١٧٠٠٠</span> تن سکنه .<br /></font></div>'),
(288083, 'ژرژتون', '<span class=\"hlight\">ژرژتون .</span> <font color=\"DarkGreen\"><b>[ ژُ ت َ ]</font></b> (اِخ ) جرج تون . نام شهری به اتازونی (در کنتوکی ) کرسی ناحیه ٔ اسکوت، دارای <span class=\"hlight\" dir=\"rtl\">٣٥٧٠</span> تن سکنه .<br /></font></div>'),
(288084, 'ژرژتون', '<span class=\"hlight\">ژرژتون .</span> <font color=\"DarkGreen\"><b>[ ژُ ت َ ]</font></b> (اِخ ) نام کرسی گویان انگلیس، دارای <span class=\"hlight\" dir=\"rtl\">٥٣٠٠٠</span> تن سکنه .<br /></font></div>'),
(288085, 'ژرژتون', '<span class=\"hlight\">ژرژتون .</span> <font color=\"DarkGreen\"><b>[ ژُ ت َ ]</font></b> (اِخ ) جرج تون . نام قصبه ای به اتازونی (در کلرادو) قلمرو کلرکریک واقع در پنجاه کیلومتری دانور. و بدانجا معادن نقره بسیار باشد.<br /></font></div>'),
(288086, 'ژرژل', '<span class=\"hlight\">ژرژل .</span><font color=\"DarkGreen\"><b>[ ژُ ژِ ]</font></b> (اِخ ) آبه ژان فرانسوا. سیاستمدار فرانسوی متولد و متوفی در برویر(وُژ) (<span class=\"hlight\" dir=\"rtl\">١٧٣١</span>-<span class=\"hlight\" dir=\"rtl\">١٨١٣</span> م .).<br /></font></div>'),
(288087, 'ژرژی', '<span class=\"hlight\">ژرژی .</span> <font color=\"DarkGreen\"><b>[ ژُ ]</font></b> (اِخ ) (تلفظ انگلیسی : جُرجیا) نام یکی از کشورهای ممالک متحده ٔامریکا دارای <span class=\"hlight\" dir=\"rtl\">٢٩٠٠٠٠٠</span> تن سکنه . کرسی آن آتلانتاست .<br /></font></div>'),
(288088, 'ژرگوی', '<span class=\"hlight\">ژرگوی .</span> <font color=\"DarkGreen\"><b>[ ژِ گ ُ وی ]</font></b> (اِخ ) نام شهری به کشور گل قدیم واقع در شش کیلومتری جنوب کلرمون فرّان . مردم این شهر بسال <span class=\"hlight\" dir=\"rtl\">٥٣</span> ق .م . درمقابل لشکر سزار سردار روم دفاع دلیرانه ای کردند.<br /></font></div>'),
(288089, 'ژری ویل', '<span class=\"hlight\">ژری ویل .</span> <font color=\"DarkGreen\"><b>[ ژِ ]</font></b> (اِخ ) نام دهستانی مختلط در الجزیره جزء ناحیه ٔ آئین سفرا در جنوب ایالت اوران، دارای <span class=\"hlight\" dir=\"rtl\">٥٤٨٤٣</span> تن سکنه .<br /></font></div>'),
(288090, 'ژریون', '<span class=\"hlight\">ژریون .</span> <font color=\"DarkGreen\"><b>[ ژِ یُن ْ ]</font></b> (اِخ ) نام غولی در اساطیر یونان دارای سه سر و سه تن و سه پا. وی به دست هرکول به قتل رسید.<br /></font></div>'),
(288091, 'ژریکل', '<span class=\"hlight\">ژریکل .</span> <font color=\"DarkGreen\"><b>[ ژِ ک ُ ]</font></b> (اِخ ) ژان لوئی آندره تئودر. نام نقاش فرانسوی . مولد او در روئن سال <span class=\"hlight\" dir=\"rtl\">١٧٩١</span> و وفات در پاریس بسال <span class=\"hlight\" dir=\"rtl\">١٨٢٤</span> م .<br /></font></div>'),
(288092, 'ژریکو', '<span class=\"hlight\">ژریکو.</span> <font color=\"DarkGreen\"><b>[ ژِ ک ُ ]</font></b> (اِخ ) نام شهری قدیمی به فلسطین در <span class=\"hlight\" dir=\"rtl\">٢٣</span>کیلومتری اورشلیم .<br /></font></div>'),
(288093, 'ژزابل', '<span class=\"hlight\">ژزابل .</span> <font color=\"DarkGreen\"><b>[ ژِ ب ِ ]</font></b> (اِخ )نام زن آحاب پادشاه اسرائیل . رجوع به ایزابل شود.<br /></font></div>'),
(288094, 'ژزافات', '<span class=\"hlight\">ژزافات .</span> <font color=\"DarkGreen\"><b>[ ژُ ]</font></b> (اِخ ) نام رودباری است . رجوع به وادی یهوشافاط شود.<br /></font></div>'),
(288095, 'ژزف', '<span class=\"hlight\">ژزف .</span> <font color=\"DarkGreen\"><b>[ ژُ زِ ]</font></b> (اِخ ) نام جاثلیقی بعهد خسرواول، انوشیروان . (ایران در زمان ساسانیان ص <span class=\"hlight\" dir=\"rtl\">٢٩٩</span>).<br /></font></div>'),
(288096, 'ژزف', '<span class=\"hlight\">ژزف .</span> <font color=\"DarkGreen\"><b>[ ژُ زِ ]</font></b> (اِخ ) یوسف . رجوع به یوسف پسر یعقوب پیغمبر شود.<br /></font></div>'),
(288097, 'ژزف', '<span class=\"hlight\">ژزف .</span> <font color=\"DarkGreen\"><b>[ ژُ زِ ]</font></b> (اِخ ) لوروآ. رجوع به بناپارت شود.<br /></font></div>'),
(288098, 'ژزف', '<span class=\"hlight\">ژزف .</span> <font color=\"DarkGreen\"><b>[ ژُ زِ ]</font></b> (اِخ ) فردریک اِرنست ژرژ شارل . نام دوک ِ «ساکس -آلتنبورگ ». مولد بسال <span class=\"hlight\" dir=\"rtl\">١٧٨٩</span> و وفات در آلتنبورگ بسال <span class=\"hlight\" dir=\"rtl\">١٨٦٨</span> م .<br /></font></div>'),
(288099, 'ژزف', '<span class=\"hlight\">ژزف .</span> <font color=\"DarkGreen\"><b>[ ژُ زِ ]</font></b> (اِخ ) فرانسوا لوکلرک دوترامبلی، مشهور به لوپر. نام راهب و سیاستمدار فرانسوی ملقب به امینانس گریز پسر بزرگ ژان دوترامبلی . مولد سال <span class=\"hlight\" dir=\"rtl\">١٥٧٧</span> در پاریس و وفات بسال <span class=\"hlight\" dir=\"rtl\">١٦٣٨</span> م .<br /></font></div>'),
(288100, 'ژزف', '<span class=\"hlight\">ژزف .</span> <font color=\"DarkGreen\"><b>[ ژُ زِ ]</font></b> (اِخ ) شارل لوئی . نام آرشیدوک و زبانشناس مجارستانی . مولد بسال <span class=\"hlight\" dir=\"rtl\">١٨٣٣</span> و وفات بسال <span class=\"hlight\" dir=\"rtl\">١٩٠٥</span> م . در فیوم .<br /></font></div>'),
(288101, 'ژزف', '<span class=\"hlight\">ژزف .</span> <font color=\"DarkGreen\"><b>[ ژُ زِ ]</font></b> (اِخ ) نام آرشیدوک اتریش . مولد بسال <span class=\"hlight\" dir=\"rtl\">١٨٧٢</span> م . وی در جنگ بین المللی نخستین شرکت داشته است .<br /></font></div>'),
(288102, 'ژزف', '<span class=\"hlight\">ژزف .</span> <font color=\"DarkGreen\"><b>[ ژُ زِ ]</font></b> (اِخ ) نام رئیس سرخ پوستان قبیله ٔ هندیان «نزپرسه » مولد بسال <span class=\"hlight\" dir=\"rtl\">١٨٣١</span> و وفات در واشنگتن بسال <span class=\"hlight\" dir=\"rtl\">١٩٠٤</span> م . او را ناپلئون هندیان می گفتند.<br /></font></div>'),
(288103, 'ژزف', '<span class=\"hlight\">ژزف .</span> <font color=\"DarkGreen\"><b>[ ژُ زِ]</font></b> (اِخ ) آرشیدوک و پالاتن ِ اتریش پسر لئوپلد دوّم . مولد فلورانس بسال <span class=\"hlight\" dir=\"rtl\">١٧٧٦</span> و وفات در پست بسال <span class=\"hlight\" dir=\"rtl\">١٨٧٢</span> م .<br /></font></div>'),
(288104, 'ژزف اول', '<span class=\"hlight\">ژزف اول .</span> <font color=\"DarkGreen\"><b>[ ژُ زِ ف ِ اَوْ وَ ]</font></b> (اِخ ) پادشاه پرتقال از <span class=\"hlight\" dir=\"rtl\">١٧٥٠</span> تا <span class=\"hlight\" dir=\"rtl\">١٧٧٧</span> م . پسر ژان پنجم و ماری آن دتریش . مولد بسال <span class=\"hlight\" dir=\"rtl\">١٧١٥</span> در لشبونة و هم بدانجا نیز وفات کرده است .<br /></font></div>'),
(288105, 'ژزف اول', '<span class=\"hlight\">ژزف اول .</span> <font color=\"DarkGreen\"><b>[ ژُ زِ ف ِ اَوْ وَ ]</font></b> (اِخ ) امپراطور آلمان پسر بزرگ لئوپلد اول . مولد وین بسال <span class=\"hlight\" dir=\"rtl\">١٦٧٨</span> و وفات در همانجا بسال <span class=\"hlight\" dir=\"rtl\">١٧١١</span> م . سلطنت وی از سال <span class=\"hlight\" dir=\"rtl\">١٧٠٥</span> تا <span class=\"hlight\" dir=\"rtl\">١٧١١</span> بوده است .<br /></font></div>'),
(288106, 'ژزف اوپتن', '<span class=\"hlight\">ژزف اوپتن .</span> <font color=\"DarkGreen\"><b>[ ژُ زِ ت ُ ]</font></b> (اِخ ) نام خاورشناس معاصر مدیر موزه ٔ متروپولیتن . وی از ایرانشناسان و کاوش کنندگان پرسپلیس (تخت جمشید) است و اکتشافات بسیاری در آثار تاریخی آنجا کرده و برخی از تحقیقات خود را در آن باب انتشار داده است . (فرهنگ خاورشناسان ص <span class=\"hlight\" dir=\"rtl\">١٩٠</span>).<br /></font></div>'),
(288107, 'ژزف برینگاس', '<span class=\"hlight\">ژزف برینگاس .</span> <font color=\"DarkGreen\"><b>[ ژُ زِ بْری <span class=\"hlight\" dir=\"rtl\">/</span> ب ِ ]</font></b> (اِخ ) نام سیاستمدار بیزانسی در مائه ٔ دهم میلادی از معتمدین قسطنطین هفتم . وفات بسال <span class=\"hlight\" dir=\"rtl\">٩٧١</span> م .<br /></font></div>'),
(288108, 'ژزف دوم', '<span class=\"hlight\">ژزف دوم .</span> <font color=\"DarkGreen\"><b>[ ژُ زِ ف ِ دُوْ وُ ]</font></b> (اِخ ) نام امپراطور آلمان پسر بزرگ فرانسوای اول و ماری ترز. مولد و وفات در وین (<span class=\"hlight\" dir=\"rtl\">١٧٤١</span>-<span class=\"hlight\" dir=\"rtl\">١٧٩٠</span> م .).وی از سال <span class=\"hlight\" dir=\"rtl\">١٧٦٥</span> تا <span class=\"hlight\" dir=\"rtl\">١٧٩٠</span> در آلمان سلطنت کرده است .<br /></font></div>'),
(288109, 'ژزف دوناکسس', '<span class=\"hlight\">ژزف دوناکسس .</span> <font color=\"DarkGreen\"><b>[ ژُ زِ دُ س ُ ]</font></b> (اِخ ) سیاستمدار پرتقالی . مولد اوائل قرن شانزدهم میلادی در پرتقال و وفات بسال <span class=\"hlight\" dir=\"rtl\">١٥٧٩</span> م . در قسطنطنیه .<br /></font></div>'),
(288110, 'ژزف فردینان', '<span class=\"hlight\">ژزف فردینان .</span> <font color=\"DarkGreen\"><b>[ ژُ زِ ف ِ ]</font></b> (اِخ ) نام آرشیدوک اطریش . مولد سالزبورگ بسال <span class=\"hlight\" dir=\"rtl\">١٨٧٢</span> م . وی در جنگ بین المللی نخستین شرکت داشته است .<br /></font></div>'),
(288111, 'ژزف فلاویوس', '<span class=\"hlight\">ژزف فلاویوس .</span> <font color=\"DarkGreen\"><b>[ ژُ زِ فْلا <span class=\"hlight\" dir=\"rtl\">/</span> ف ِ ]</font></b> (اِخ ) نام مورخ یهود. مولد بسال <span class=\"hlight\" dir=\"rtl\">٣٠٧</span> م . وی پس از تبحر در عبری و یونانی برای دفاع بعض روحانیون یهود به روم رفت و سپس در موقع جنگ وسپاسیان سردار روم با یهود تسلیم شد. چون پیش بینی کرد که وسپاسیان و پسر او تیتوس به امپراطوری روم خواهند رسید و چنین شد مورد توجه دو امپراطور مزبور گردید. تیتوس پس از تسخیر بیت المقدس تمام کتب مذهبی یهودرا به اختیار او گذاشت و او سنوات آخر عمر خود را در دربار روم گذرانید و کتبی راجع به تاریخ یهود و خراب شدن اورشلیم نوشت . کتابهای او از اینقرار است : <span class=\"hlight\" dir=\"rtl\">١</span>-هفت کتاب راجع به وقایعی که دنباله ٔ آن جنگهای رومیان با یهود و خراب شدن بیت المقدس است . <span class=\"hlight\" dir=\"rtl\">٢</span>- کتاب دیگر که حاوی بیست فصل و راجع به عهد عتیق یهود است . این کتاب را چنانکه خود فلاویوس گوید با این مقصود نوشته که یونانیان با تاریخ یهود آشنا شوند و رومیان بدانند که ملت او گذشته های طولانی داشته اند و چیزهائی که نویسندگان رومی راجع به این ملت منتشر می کنند صحیح نیست . در این تألیف تا فصل هفتم کتاب یازدهم نوشته های او موافق توراة است . بعد از سلطنت کورش بزرگ تاریخ یهود را دنبال کرده و وقایع دوره ٔ بطالسه و سلوکیها را به تفصیل شرح داده و سپس فروتر شده و به دوره ٔ رومیان رسیده است . <span class=\"hlight\" dir=\"rtl\">٣</span>- کتابهائی نیز در شرح احوال خود نوشته که در واقع دنباله ٔ کتاب مذکور است . <span class=\"hlight\" dir=\"rtl\">٤</span>- کتابی در قدمت ملت یهود. و این کتاب در واقع امر برای دفاع از ملت مزبور تألیف شده است . توضیح آنکه آپیون یکی از نحویّون اسکندرانی را یونانیان به روم فرستاده بودند و او در نزد کالی گولا امپراطور روم از یهود بدگوئی کرده و گفته بود که آنان امپراطور مزبور را خدا نمی دانند. در این کتاب فلاویوس از تاریخ نویسی یهودیان ودیگر مورخین مشرق زمین دفاع کرده گوید که آنان بهتر از مورخین یونانی از عهده برآمده اند، سپس از مان تُن مورّخ مصری و سایر مورّخینی که نوشته اند مسقطالرأس یهودیان مصر است انتقاد و پس از آن در مقابل آپیون از ملت یهود و موسی و قانونگذاری او دفاع کرده است . <span class=\"hlight\" dir=\"rtl\">٥</span>- کتابی هم به دست آمده موسوم به حکومت عقل که بعض محققین آن را به فلاویوس نسبت می دهند. مصنف این کتاب می خواسته است فلسفه ٔ یونانی را با نوشته های توراة وفق دهد. اهمیت نوشته های این مورخ از اینجا مشاهده می شود که نویسندگان معتبر کلیسای (مسیحی ) مانند تئوفیل وکلمان اسکندرانی و اسویوس و غیره به او استناد کرده اند. انشاء آن چنانکه گویند فصیح و روشن است، ولی مورّخ مذکور همه جا بیطرفانه قضاوت نکرده و راجع به رومیان بیان او متملقانه است و جاهائی هم که از خود دفاع کرده قلم او تابع احساسات شخصی شده است . (ایران باستان ج <span class=\"hlight\" dir=\"rtl\">١</span> صص <span class=\"hlight\" dir=\"rtl\">٨٠</span> - <span class=\"hlight\" dir=\"rtl\">٨١</span>).<br /></font></div>'),
(288112, 'ژزفو باربارو', '<span class=\"hlight\">ژزفو باربارو.</span> <font color=\"DarkGreen\"><b>[ ژُ زِ ]</font></b> (اِخ ) نام یکی از سفراء و فرستادگان کشور ونیس به دربار اُوزون حسن پادشاه آق قوینلو. (ترجمه ٔ تاریخ ادبیات برون ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٧</span> و ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٤٣٥</span>).<br /></font></div>'),
(288113, 'ژزفین', '<span class=\"hlight\">ژزفین .</span> <font color=\"DarkGreen\"><b>[ ژُ زِ ]</font></b> (اِخ ) ماری ژُزف رُز تاشه دولاپاژری . نام امپراطریس فرانسه . مولد مارتینیک بسال <span class=\"hlight\" dir=\"rtl\">١٧٦٣</span> و وفات در مالمزن بسال <span class=\"hlight\" dir=\"rtl\">١٨١٤</span> م . وی در <span class=\"hlight\" dir=\"rtl\">١٧٧٩</span> به زوجیت ویکنت آلکساندر بوهارنه درآمد و پس از مرگ وی با ژنرال بناپارت در <span class=\"hlight\" dir=\"rtl\">١٧٩٦</span> ازدواج کرد و در سال <span class=\"hlight\" dir=\"rtl\">١٨٠٤</span> به امپراطریسی فرانسه رسید. ناپلئون او را در <span class=\"hlight\" dir=\"rtl\">١٨٠٩</span> طلاق گفت و وی در <span class=\"hlight\" dir=\"rtl\">١٨١٤</span> درگذشت .<br /></font></div>'),
(288114, 'ژزپن', '<span class=\"hlight\">ژزپن .</span> <font color=\"DarkGreen\"><b>[ ژُ زِ پ َ ]</font></b> (اِخ ) نام نقاش ایتالیائی . مولد آرپینو ازقلمرو ناپل بسال <span class=\"hlight\" dir=\"rtl\">١٥٦٠</span> و وفات در رُم بسال <span class=\"hlight\" dir=\"rtl\">١٦٤٠</span> م .<br /></font></div>'),
(288115, 'ژست', '<span class=\"hlight\">ژست .</span> <font color=\"DarkGreen\"><b>[ ژِ ]</font></b> (فرانسوی، اِ) حرکت و جنبش تن عموماً و دست خصوصاً گاه سخن گفتن و اشاره . حالت و حرکت یا حرکات خاص که به دست یا سر یا تن دهند.<br /></font></div>'),
(288116, 'ژسلن', '<span class=\"hlight\">ژسلن .</span> <font color=\"DarkGreen\"><b>[ ژُ س ِ ل َ ]</font></b> (اِخ ) نام کرسی بخش مُرْبیهان از ولایت پُن تیوی، دارای <span class=\"hlight\" dir=\"rtl\">٢٠٩٩</span> تن سکنه .<br /></font></div>'),
(288117, 'ژسن', '<span class=\"hlight\">ژسن .</span> <font color=\"DarkGreen\"><b>[ ژِ س ِ ]</font></b> (اِخ ) نام سرزمینی به مصر سفلی . آنجا تا زمان اِکسود اقامتگاه اسرائیلیان بود.<br /></font></div>'),
(288118, 'ژسنه', '<span class=\"hlight\">ژسنه .</span> <font color=\"DarkGreen\"><b>[ ژِ ن ِ ]</font></b> (اِخ ) ماتیا. نام زبان شناس آلمانی . مولد روت بسال <span class=\"hlight\" dir=\"rtl\">١٦٩١</span> و وفات بسال <span class=\"hlight\" dir=\"rtl\">١٧٦١</span> م .<br /></font></div>'),
(288119, 'ژسنه', '<span class=\"hlight\">ژسنه .</span> <font color=\"DarkGreen\"><b>[ ژِ ن ِ ]</font></b> (اِخ ) کنراد. نام طبیعی دان و فیلسوف سویسی . مولد سال <span class=\"hlight\" dir=\"rtl\">١٥١٦</span> در زوریخ و وفات بسال <span class=\"hlight\" dir=\"rtl\">١٥٦٥</span> م .<br /></font></div>'),
(288120, 'ژسنه', '<span class=\"hlight\">ژسنه .</span> <font color=\"DarkGreen\"><b>[ ژِ ن ِ ]</font></b> (اِخ ) سالمون . نام شاعر و دورنماساز سویسی . مولد و وفات به زوریخ (<span class=\"hlight\" dir=\"rtl\">١٧٣٠</span>-<span class=\"hlight\" dir=\"rtl\">١٧٨٨</span> م .).<br /></font></div>'),
(288121, 'ژغار', '<span class=\"hlight\">ژغار.</span> <font color=\"DarkGreen\"><b>[ ژَ ]</font></b> (اِ) سختی . (برهان ). مقابل سستی . استحکام . درشتی . صلابت . <BR><font color=\"Blue\">◄</font> سختی و محنت . (آنندراج ). <BR><font color=\"Blue\">◄</font> گیاهی که بدان جامه رنگ کنند. (برهان ). زغار. (آنندراج ). رجوع به زغار شود. <BR><font color=\"Blue\">◄</font> غازه . (آنندراج ). <BR><font color=\"Blue\">◄</font> زنگ و چرک فلزات <span class=\"hlight\">:</span> <br />توشان زیر زمین فرسوده کردی <br />زمین داده مر ایشان را ژغارا.<br /> <font color=\"Red\">رودکی .</font><br />این بیت در لغت نامه ٔ اسدی شاهد برای زغار با زاء موحده آمده است بمعنی نم و تری و زنگ و صداء و تبدیل ژ به ز در فارسی مطرد است و ظاهراً این بیت از قصیده ای است از رودکی که مطلعش این است :<br />درنگ آر ای سپهر چرخ وارا<br />کیاخن ترت باید کرد کارا.<br /> <BR><font color=\"Blue\">◄</font> نعره و فریاد و بانگ سهمناک و آواز بلند که آن را کوکا نیز گویند. (جهانگیری ). بانگ تیز و سخت . غوغا. رجوع به زغار شود <span class=\"hlight\">:</span> <br />به یکی زخم تپانچه که بدان روی کریه <br />بزدم جنگ چه سازی چه کنی بانگ <font color=\"DarkGreen\"><b>[ و ]</font></b> ژغار .<br /> <font color=\"Red\">بوالمثل .</font><br />در شاهد یکانه که در لغت نامه ٔ اسدی و صحاح الفرس آمده در هر دو جا «... چه کنی بانگ ژغار» آورده اند بطریق اضافه ٔ بانگ به ژغار نه بطور عطف . احتمال قوی می دهم که چون بیت فوق در مزاح و هجوی گفته شده ژغار صورتی از شکال و شغال باشد نه بمعنی بانگ سخت، مگر شواهد دیگری آن را تأیید کند. و در بیت ذیل نیز ژغار ظاهراً بمعنی نم و تری و آهار آمده است <span class=\"hlight\">:</span> <br />به ایر ماند چون پی نهاد و نعره گشاد<br />بود زکام درخش از ژغار تندر او.<br /><font color=\"Red\">امیر معزی (در صفت اسب ).</font><br /></font></div>'),
(288122, 'ژغاره', '<span class=\"hlight\">ژغاره .</span> <font color=\"DarkGreen\"><b>[ ژَ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (اِ) نان ارزن . (برهان ) <span class=\"hlight\">:</span> <br />رفیقان من با می و ناز و نعمت <br />منم آرزومند یک تا ژغاره .<br /> <font color=\"Red\">ابوشکور.</font><br />گروهی از من امید سورمی دارند<br />مرا تحیّر نان ژغاره قیرینش . <br /> <font color=\"Red\">سوزنی (از جهانگیری ).</font><br /><BR><font color=\"Blue\">◄</font> سرخی و غازه که زنان بر روی مالند. <BR><font color=\"Blue\">◄</font> ناف حیوانات عموماً و ناف گاو خصوصاً. <BR><font color=\"Blue\">◄</font> فریاد و فغان . (برهان ). رجوع به ژغاله شود.<br /></font></div>'),
(288123, 'ژغاله', '<span class=\"hlight\">ژغاله .</span> <font color=\"DarkGreen\"><b>[ ژَ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ل ِ ]</font></b> (اِ)نان ارزن . (برهان ). رجوع به ژغاره شود <span class=\"hlight\">:</span> <br />رفیقان من با می و ناز و نعمت <br />منم آرزومند یک تا ژغاله .<br /> <font color=\"Red\">ابوشکور (از فرهنگ شعوری ).</font><br /><BR><font color=\"Blue\">◄</font> ناف حیوانات . <BR><font color=\"Blue\">◄</font> سرخی زنان . (برهان ). سرخی و غازه که زنان بر روی مالند. سرخاب .<br /></font></div>'),
(288124, 'ژغاو', '<span class=\"hlight\">ژغاو.</span> <font color=\"DarkGreen\"><b>[ ژَ ]</font></b> (اِ) زن فاحشه و قحبه . <BR><font color=\"Blue\">◄</font> قحبه خانه . (برهان ).<br /></font></div>'),
(288125, 'ژغند', '<span class=\"hlight\">ژغند.</span> <font color=\"DarkGreen\"><b>[ ژَ غ َ ]</font></b> (اِ) بانگ تند بود که ددی چون یوز و پلنگ برزند و گویند بانگی سهمگین و بیم زده نیز باشد. (لغت نامه ٔ اسدی ). بانگ یوز. (نسخه ای از لغت نامه ٔ اسدی ). بانگ تند بود که ددی بزند بزودی در روی جانوران چون یوز و پلنگ . (نسخه ای از لغت نامه ٔ اسدی ). بانگ ددان . هرّا. بانگ مخصوص یوز. (صحاح الفرس ). آواز بلند و مهیب و سهمناک باشد که سباع و بهایم بوقت گرفتار شدن در دام کنند. (برهان ) <span class=\"hlight\">:</span> <br />کرد روبه یوزواری یک ژغند <br />خویشتن را زان میان بیرون فکند .<br /> <font color=\"Red\">رودکی (سندبادنامه ٔ منظوم ).</font><br /><BR><font color=\"Blue\">◄</font> آواز گردباد. <BR><font color=\"Blue\">◄</font> سختی . صلابت . مقابل سستی .<br /></font></div>'),
(288126, 'ژغنگ', '<span class=\"hlight\">ژغنگ .</span> <font color=\"DarkGreen\"><b>[ ژَ غ َ ]</font></b> (اِ) فواق . سکسکه <span class=\"hlight\">:</span> <br />مرا رفیقی پرسید کاین غریو ز چیست <br />جواب دادم کز غرو نیست هست ژغنگ .<br /> <font color=\"Red\">شاکر بخاری .</font><br /> <br />و بعید نیست که کلمه مرکب از «ز»مخفف «از» و غنگ باشد. اسدی در لغت نامه بیت فوق را بشاهد لغت زغنگ (به زاء یک نقطه ) آورده است . رجوع به زغنگ شود. <BR><font color=\"Blue\">◄</font> آروغ .<br /></font></div>'),
(288127, 'ژغژغ', '<span class=\"hlight\">ژغژغ .</span> <font color=\"DarkGreen\"><b>[ ژَ ژَ ]</font></b> (اِ صوت ) آوازی که در محل چیزی خوردن و جاویدن و خائیدن چیزی از دهان ... از دندانها برآید. <BR><font color=\"Blue\">◄</font> صدای بهم خوردن دندانها بسبب بسیاری سرماو کثرت قهر و غضب . (برهان ). دندان غرچه <span class=\"hlight\">:</span> <br />ژغژغ دندان او دل می شکست <br />جان شیران سیه میشد ز دست .<br /> <font color=\"Red\">مولوی .</font><br /> <BR><font color=\"Blue\">◄</font> صدا و آواز برهم خوردن گردکان و بادام و امثال آنها وقتی که در جوال یا جائی دیگر بریزند و برهم خورد. (برهان ) <span class=\"hlight\">:</span> <br />گر دهد خود کی دهد آن پرحیل <br />جوز پوسیده ست و گفتار دغل <br />ژغژغ آن مغز و عقلت را برد<br />صدهزاران عقل را یک نشمرد.<br /> <font color=\"Red\">مولوی .</font><br />گرنه خوش آوازی مغزی بود<br />ژغژغ آواز قشری که شنود.<br /> <font color=\"Red\">مولوی .</font><br />ژغژغ آن زان تحمل می کنی <br />تا که خاموشانه بر مغزی زنی .<br /> <font color=\"Red\">مولوی .</font><br />چون بادامها را در کف جمع کنی و بجنبانی بانگی و ژغژغی می کند. (بهاءالدین ولد).<br /></font></div>'),
(288128, 'ژف', '<span class=\"hlight\">ژف .</span> <font color=\"DarkGreen\"><b>[ژَ ]</font></b> (ص ) تر. برابر خشک . (برهان ). ضد خشک . نمناک .<br /></font></div>'),
(288129, 'ژفت', '<span class=\"hlight\">ژفت .</span> <font color=\"DarkGreen\"><b>[ ژُ ]</font></b> (ص ) بخیل و ممسک <span class=\"hlight\">:</span> <br />با او چگونه گشت زبان ژفت یا جواد<br />با او چگونه رفت فلک نرم یا درشت .<br /><font color=\"Red\">؟ (از شعوری ).</font><br /></font></div>'),
(288130, 'ژفت', '<span class=\"hlight\">ژفت .</span> <font color=\"DarkGreen\"><b>[ ژَ ]</font></b> (ص ) تناور. (آنندراج ). فربه . <BR><font color=\"Blue\">◄</font> لاغر. (آنندراج ). نحیف (از لغات اضداد است ) <span class=\"hlight\">:</span> <br />برو بزیر رکابش چو اسب تازی چست <br />مباش در ره حکمش چو گاو کاهل ژفت .<br /><font color=\"Red\">؟ (از شعوری ).</font><br /></font></div>'),
(288131, 'ژفته', '<span class=\"hlight\">ژفته .</span> <font color=\"DarkGreen\"><b>[ ژِ ت ِ ]</font></b> (اِخ ) نام یکی از قضات بنی اسرائیل در قرن دوازدهم قبل از میلاد.<br /></font></div>'),
(288132, 'ژفر', '<span class=\"hlight\">ژفر.</span> <font color=\"DarkGreen\"><b>[ ژُ ]</font></b> (اِخ ) ژُزف ژاک سِزِر. مارشال فرانسوی . مولد بسال <span class=\"hlight\" dir=\"rtl\">١٨٥٢</span> در ریوزالت و وفات بسال <span class=\"hlight\" dir=\"rtl\">١٩٣١</span> م . وی در تُنکن و ماداگاسکار و سودان تحصیل شهرت کرد و از سال <span class=\"hlight\" dir=\"rtl\">١٩١٤</span> تا <span class=\"hlight\" dir=\"rtl\">١٩١٦</span> سپهبد سپاه فرانسه و فاتح نبرد اول مارن (سپتامبر <span class=\"hlight\" dir=\"rtl\">١٩١٤</span>) بود.<br /></font></div>'),
(288133, 'ژفرسن', '<span class=\"hlight\">ژفرسن .</span> <font color=\"DarkGreen\"><b>[ ژِ ف ِ س ُ ]</font></b> (اِخ ) جفرسن . تُماس . نام سومین رئیس جمهور ممالک متحده ٔ آمریکای شمالی . مولد شادوِل بسال <span class=\"hlight\" dir=\"rtl\">١٧٤٣</span> و وفات در مُنتی سلو بسال <span class=\"hlight\" dir=\"rtl\">١٨٢٦</span> م . وی یکی از مؤسسین حزب دموکرات آمریکاست . رجوع به جفرسُن شود.<br /></font></div>'),
(288134, 'ژفرسن باراک', '<span class=\"hlight\">ژفرسن باراک .</span> <font color=\"DarkGreen\"><b>[ ژِ ف ِ س ُ ]</font></b>(اِخ ) یا ژِفِرسن لِکازِرن . نام شهری به اتازونی درایالت میسوری ناحیه ٔ سن لوئی، دارای <span class=\"hlight\" dir=\"rtl\">٩٠٠٠</span> تن سکنه .<br /></font></div>'),
(288135, 'ژفرسن سیتی', '<span class=\"hlight\">ژفرسن سیتی .</span> <font color=\"DarkGreen\"><b>[ ژِ ف ِ س ُ ]</font></b> (اِخ ) نام شهری به اتازونی، کرسی ایالت میسوری، دارای <span class=\"hlight\" dir=\"rtl\">٦٧٤٢</span> تن سکنه . رجوع به جفرسن سیتی شود.<br /></font></div>'),
(288136, 'ژفرسن ویل', '<span class=\"hlight\">ژفرسن ویل .</span> <font color=\"DarkGreen\"><b>[ژِ ف ِ س ُ ]</font></b> (اِخ ) نام شهری به اتازونی، در ایندیانا، دارای <span class=\"hlight\" dir=\"rtl\">١٠٦٦٠</span> تن سکنه .<br /></font></div>'),
(288137, 'ژفرن', '<span class=\"hlight\">ژفرن .</span> <font color=\"DarkGreen\"><b>[ ژُ رَ ]</font></b> (اِخ ) مادموازل ماری ترز. نام زنی با ذکاء و هوشی وافر. مولد پاریس بسال <span class=\"hlight\" dir=\"rtl\">١٦٩٩</span> و وفات بسال <span class=\"hlight\" dir=\"rtl\">١٧٧٧</span> م . خانه ٔ او مجمع فیلسوفان وقت بود.<br /></font></div>'),
(288138, 'ژفره', '<span class=\"hlight\">ژفره .</span> <font color=\"DarkGreen\"><b>[ ژُ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (اِ) پیرامن دهان . (برهان ). صاحب آنندراج گوید: پیرامن دهان، در برهان آورده وظن آن است که زفر یعنی دهان را زفره خوانده باشد.<br /></font></div>'),
(288139, 'ژفره', '<span class=\"hlight\">ژفره .</span> <font color=\"DarkGreen\"><b>[ ژَ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (اِ) غلبه در قمار و لعب و بازی . (این لغت در فرهنگ ناظم الاطباء آمده است و در کتب لغتی که در دسترس ما بود دیده نشد).<br /></font></div>'),
(288140, 'ژفروای اول', '<span class=\"hlight\">ژفروای اول .</span> <font color=\"DarkGreen\"><b>[ ژُ ی ِ اَوْ وَ ]</font></b> (اِخ ) دوک ِ آنژو از سال <span class=\"hlight\" dir=\"rtl\">٩٥٨</span> تا <span class=\"hlight\" dir=\"rtl\">٩٨٧</span> م .<br /></font></div>'),
(288141, 'ژفروای اول', '<span class=\"hlight\">ژفروای اول .</span> <font color=\"DarkGreen\"><b>[ ژُی ِ اَوْ وَ ]</font></b> (اِخ ) دوک ِبرتانی از سال <span class=\"hlight\" dir=\"rtl\">٩٩٢</span> تا <span class=\"hlight\" dir=\"rtl\">١٠٠٨</span> م . متوفی بسال <span class=\"hlight\" dir=\"rtl\">١٠٠٨</span> م .<br /></font></div>'),
(288142, 'ژفروای دوم', '<span class=\"hlight\">ژفروای دوم .</span> <font color=\"DarkGreen\"><b>[ ژُ ی ِ دُوْ وُ ]</font></b> (اِخ ) سومین پسر هانری دوّم پادشاه انگلیس . مولد بسال <span class=\"hlight\" dir=\"rtl\">١١٥٨</span> م . دوک برتانی از سال <span class=\"hlight\" dir=\"rtl\">١١٧٨</span> تا <span class=\"hlight\" dir=\"rtl\">١١٨٦</span> م .<br /></font></div>'),
(288143, 'ژفروای دوم', '<span class=\"hlight\">ژفروای دوم .</span> <font color=\"DarkGreen\"><b>[ ژُ ی ِ دُوْ وُ ]</font></b> (اِخ )مارتل . وی از سال <span class=\"hlight\" dir=\"rtl\">١٠٤٠</span> تا <span class=\"hlight\" dir=\"rtl\">١٠٦٠</span> م . دوک ِ آنژو بود.<br /></font></div>'),
(288144, 'ژفروای سوم', '<span class=\"hlight\">ژفروای سوم .</span> <font color=\"DarkGreen\"><b>[ ژُ ی ِس ِوْ وُ ]</font></b> (اِخ ) کنت آنژو از سال <span class=\"hlight\" dir=\"rtl\">١٠٦٠</span> تا <span class=\"hlight\" dir=\"rtl\">١٠٦٨</span> م .<br /></font></div>'),
(288145, 'ژفروای چهارم', '<span class=\"hlight\">ژفروای چهارم .</span> <font color=\"DarkGreen\"><b>[ ژُ ی ِ چ َ رُ ]</font></b> (اِخ ) ملقب به پلانتاژنه از سال <span class=\"hlight\" dir=\"rtl\">١١٢٩</span> تا <span class=\"hlight\" dir=\"rtl\">١١٥١</span> م . دوک ِ آنژو و بسال <span class=\"hlight\" dir=\"rtl\">١١٤٤</span> دوک ِ نُرماندی . وی داماد هانری اول و پدر هانری دوم پادشاه انگلستان است .<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(288146, 'ژفری', '<span class=\"hlight\">ژفری .</span> <font color=\"DarkGreen\"><b>[ ژُ رُ ]</font></b> (اِخ ) ژولین لوئی . نام نقاد شهیر فرانسه . متولد بسال <span class=\"hlight\" dir=\"rtl\">١٧٤٣</span> در رن و متوفی بسال <span class=\"hlight\" dir=\"rtl\">١٨١٤</span> م .<br /></font></div>'),
(288147, 'ژفری', '<span class=\"hlight\">ژفری .</span> <font color=\"DarkGreen\"><b>[ ژُ رُ ]</font></b> (اِخ ) ژان ماری میشل . نام هنرپیشه ٔ فرانسوی . متولد بسال <span class=\"hlight\" dir=\"rtl\">١٨١٣</span> و متوفی به پاریس بسال <span class=\"hlight\" dir=\"rtl\">١٨٨٣</span> م .<br /></font></div>'),
(288148, 'ژفری', '<span class=\"hlight\">ژفری .</span> <font color=\"DarkGreen\"><b>[ ژِ رُ ]</font></b> (اِخ ) اتین فرانسوا. نام پزشک و شیمی دان فرانسوی . متولد بسال <span class=\"hlight\" dir=\"rtl\">١٦٧٢</span> در پاریس و متوفی بسال <span class=\"hlight\" dir=\"rtl\">١٧٣١</span> م .<br /></font></div>'),
(288149, 'ژفری', '<span class=\"hlight\">ژفری .</span> <font color=\"DarkGreen\"><b>[ ژِ رُ ]</font></b> (اِخ ) ماتیو اگوست . مورّخ فرانسوی . مولد پاریس بسال <span class=\"hlight\" dir=\"rtl\">١٨٢٠</span> و وفات در بی اِور بسال <span class=\"hlight\" dir=\"rtl\">١٨٩٥</span> م .<br /></font></div>'),
(288150, 'ژفری', '<span class=\"hlight\">ژفری .</span> <font color=\"DarkGreen\"><b>[ ژِرُ ]</font></b> (اِخ ) گوستاو. نام ادیب و نقاد فرانسوی . مولد بسال <span class=\"hlight\" dir=\"rtl\">١٨٥٥</span> م . در پاریس .<br /></font></div>'),
(288151, 'ژفری', '<span class=\"hlight\">ژفری .</span> <font color=\"DarkGreen\"><b>[ ژِ ]</font></b> (اِخ ) ژرژ لرد. نام شانسلیه ٔ انگلستان در زمان سلطنت شارل دوم و ژاک دوم . مولد بسال <span class=\"hlight\" dir=\"rtl\">١٦٤٨</span> در آکتن و وفات بسال <span class=\"hlight\" dir=\"rtl\">١٦٨٩</span> م . در حومه ٔ لندن .<br /></font></div>'),
(288152, 'ژفری', '<span class=\"hlight\">ژفری .</span> <font color=\"DarkGreen\"><b>[ ژِ رُ ]</font></b> (اِخ ) اِدمُن امه فلورانتن . هنرپیشه ٔ درام و نقاش فرانسوی . مولد مگنله (اوآز) بسال <span class=\"hlight\" dir=\"rtl\">١٨٠٤</span> و وفات در سن پیر-له -نمور بسال <span class=\"hlight\" dir=\"rtl\">١٨٩٥</span> م .<br /></font></div>'),
(288153, 'ژفری دلانگلی', '<span class=\"hlight\">ژفری دلانگلی .</span> <font color=\"DarkGreen\"><b>[ ژُ رُ دُ ]</font></b> (اِخ ) نام سفیرانگلیس به دربار غازان خان ایلخان مغول . (ترجمه ٔ ادبیات ایران تألیف برون ج <span class=\"hlight\" dir=\"rtl\">٣</span>، از سعدی تا جامی ص <span class=\"hlight\" dir=\"rtl\">٤٦</span>).<br /></font></div>'),
(288154, 'ژفری سن هیلر', '<span class=\"hlight\">ژفری سن هیلر.</span> <font color=\"DarkGreen\"><b>[ ژُ رُ س َ ل ِ ]</font></b> (اِخ ) اتین . نام طبیعی دان فرانسوی . متولد در اتامپ بسال <span class=\"hlight\" dir=\"rtl\">١٧٧٢</span> و متوفی به پاریس بسال <span class=\"hlight\" dir=\"rtl\">١٨٤٤</span> م . وی در بیست ویک سالگی به استادی حیوان شناسی موزئوم منصوب شد و نخستین کرسی این فن را در فرانسه افتتاح کرد. او در سفر مصر همراه بناپارت بود. پسر وی ایزی دور (<span class=\"hlight\" dir=\"rtl\">١٨٠٥</span>-<span class=\"hlight\" dir=\"rtl\">١٨٦١</span> م .)نیز کارهای علمی و تتبعات پدر را ادامه داده است .<br /></font></div>'),
(288155, 'ژفک', '<span class=\"hlight\">ژفک .</span> <font color=\"DarkGreen\"><b>[ ژَ ]</font></b> (اِ) چرک کنجهای چشم است خواه تر باشد خواه خشک و در عربی رمص چرک خشک و غمص چرک تر را گویند. (برهان ). رمص . غمص . پیخ . پیخال ِ چشم . خِم . (زمخشری ). خیم . (فرهنگ اسدی نخجوانی ). قی (در چشم ). کیغ. کیخ . اشک ستبرگشته و رنگ گردانیده در گوشه ٔ چشم و بر مژه . ژفک آب . (آنندراج ). ژفکاب <span class=\"hlight\">:</span> <br />چشم و مژگان ز ژفک گندیده <br />عنکبوتی به گوه غلطیده .<br /><font color=\"Red\">طیان .</font><br /></font></div>'),
(288156, 'ژفکاب', '<span class=\"hlight\">ژفکاب .</span> <font color=\"DarkGreen\"><b>[ ژَ ]</font></b> (اِ مرکب ) آب و چرکی که در گوشه ٔ چشم جمع شده باشد خواه تر باشد خواه خشک . (برهان ). پیخ . قی (در چشم ). رمص . غمص . ژفک . رجوع به ژفک شود.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ژفکاب از چشم پاک کردن </span> ؛ شوخ از چشم ستردن و زدودن آن .<br /></font></div>'),
(288157, 'ژفکر', '<span class=\"hlight\">ژفکر.</span> <font color=\"DarkGreen\"><b>[ ژَ ک َ ]</font></b> (ص )شکیبا. (فرهنگ رشیدی ) .<br /></font></div>'),
(288158, 'ژفکناک', '<span class=\"hlight\">ژفکناک .</span> <font color=\"DarkGreen\"><b>[ژَ ]</font></b> (ص مرکب ) چشمی خِم ناک . قی گرفته . چشم قی آلود.<br /></font></div>'),
(288159, 'ژفکیدن', '<span class=\"hlight\">ژفکیدن .</span> <font color=\"DarkGreen\"><b>[ ژَ دَ ]</font></b> (مص ) خیم گرفتن چشم .<br /></font></div>'),
(288160, 'ژفکیده', '<span class=\"hlight\">ژفکیده .</span> <font color=\"DarkGreen\"><b>[ ژَ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف <span class=\"hlight\" dir=\"rtl\">/</span> نف ) قی آلود. خِم ناک (چشم ).<br /></font></div>'),
(288161, 'ژفگاب', '<span class=\"hlight\">ژفگاب .</span> <font color=\"DarkGreen\"><b>[ ژَ ]</font></b> (اِ مرکب ) ژفکاب . رجوع به ژفکاب شود.<br /></font></div>'),
(288162, 'ژفگن', '<span class=\"hlight\">ژفگن .</span> <font color=\"DarkGreen\"><b>[ ژَ گ ِ ]</font></b> (ص نسبی ) خِم ناک . قی آلود <span class=\"hlight\">:</span> غمیصا بایستاد بر فراق سهیل می گریست تا چشمش ژفگن شد. (تفسیر ابوالفتوح ج <span class=\"hlight\" dir=\"rtl\">٥</span> ص <span class=\"hlight\" dir=\"rtl\">١٨٨</span>). عین ٌ اغمص ؛ چشمی ژفگن . غمص ؛ ژفگن شدن . (تاج المصادر بیهقی ).<br /></font></div>'),
(288163, 'ژفگین', '<span class=\"hlight\">ژفگین .</span> <font color=\"DarkGreen\"><b>[ ژَ ]</font></b> (ص نسبی ) قی آلود. خِم ناک . ژفگن : عین ٌ اغمص ؛ چشمی ژفگین .<br /></font></div>'),
(288164, 'ژفیدن', '<span class=\"hlight\">ژفیدن .</span> <font color=\"DarkGreen\"><b>[ ژَ دَ ]</font></b> (مص ) تر شدن و خیسیدن، بعربی ترشف گویند. (برهان ).<br /></font></div>'),
(288165, 'ژفیده', '<span class=\"hlight\">ژفیده .</span> <font color=\"DarkGreen\"><b>[ ژَ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ]</font></b> (ن مف <span class=\"hlight\" dir=\"rtl\">/</span> نف ) ترشده و خیسیده . (برهان ). به آب ترشده (به زای تازی نیز گفته اند یعنی زفیده ) <span class=\"hlight\">:</span> <br />از آن دم که دیده رخت را ندیده <br />شده جمله گیتی ز اشکم ژفیده .<br /> <font color=\"Red\">روحی شارستانی (از جهانگیری ).</font><br /> <br /></font></div>'),
(288166, 'ژلا', '<span class=\"hlight\">ژلا.</span> <font color=\"DarkGreen\"><b>[ ژِ ]</font></b> (اِخ ) نام شهری یونانی نشین در جنوب سیسیل قدیم مستعمره ٔ رُدِس . آنجا به دست آمیلکار تسخیر و غارت گردید.<br /></font></div>'),
(288167, 'ژلاتین', '<span class=\"hlight\">ژلاتین .</span> <font color=\"DarkGreen\"><b>[ ژِ ]</font></b> (فرانسوی، اِ) اصل آن به زبان لاتین ژلاسیو به معنی انجماد و یخ بستن است و آن ماده ای است شبیه به لرزانک میوه که از الیاف نسوج حیوانات گرفته میشود و برای ساختن چسب ها بکار میرود و در چاپ نیز بکار است .<br /></font></div>'),
(288168, 'ژلاتینی شکل', '<span class=\"hlight\">ژلاتینی شکل .</span> <font color=\"DarkGreen\"><b>[ ژِ ش َ <span class=\"hlight\" dir=\"rtl\">/</span> ش ِ ]</font></b> (ص مرکب ) چیزی که شکل و طبیعت ژلاتین دارد. رجوع به ژلاتین شود.<br /></font></div>'),
(288169, 'ژلاز اول', '<span class=\"hlight\">ژلاز اول .</span> <font color=\"DarkGreen\"><b>[ ژِ زِ اَوْ وَ ]</font></b> (اِخ ) (قدیس ) پاپ رُم از سال <span class=\"hlight\" dir=\"rtl\">٤٩٢</span> تا <span class=\"hlight\" dir=\"rtl\">٤٩٦</span> م .<br /></font></div>'),
(288170, 'ژلاز دوم', '<span class=\"hlight\">ژلاز دوم .</span> <font color=\"DarkGreen\"><b>[ ژِ زِ دُوْ وُ ]</font></b> (اِخ ) پاپ رم از سال <span class=\"hlight\" dir=\"rtl\">١١١٨</span> تا <span class=\"hlight\" dir=\"rtl\">١١١٩</span> م .<br /></font></div>'),
(288171, 'ژلاشیش دبوزیم', '<span class=\"hlight\">ژلاشیش دبوزیم .</span> <font color=\"DarkGreen\"><b>[ ژِ دُ ]</font></b> (اِخ ) ژُزف بارون دُ. نام ژنرال اتریشی . مولد سال <span class=\"hlight\" dir=\"rtl\">١٨٠١</span> در پترواراد (اسلاوُنی ) و وفات بسال <span class=\"hlight\" dir=\"rtl\">١٨٥٩</span> م . در اگرام .<br /></font></div>'),
(288172, 'ژلاطین', '<span class=\"hlight\">ژلاطین .</span> <font color=\"DarkGreen\"><b>[ ژِ ]</font></b> (فرانسوی، اِ) رجوع به ژلاتین شود.<br /></font></div>'),
(288173, 'ژلس', '<span class=\"hlight\">ژلس .</span> <font color=\"DarkGreen\"><b>[ ژِ ل ُ ]</font></b> (اِخ ) نام دهستانی در پیرنه ٔ سفلی ولایت پو، دارای <span class=\"hlight\" dir=\"rtl\">١٧٢٠</span> تن سکنه . محصول عمده ٔ آن شراب است .<br /></font></div>'),
(288174, 'ژلن', '<span class=\"hlight\">ژلن .</span> <font color=\"DarkGreen\"><b>[ ژِ ل ُ ]</font></b> (اِخ ) نام مردم سارماتی از اقوام اروپای قدیم . رجوع به سارماتی شود.<br /></font></div>'),
(288175, 'ژلن', '<span class=\"hlight\">ژلن .</span> <font color=\"DarkGreen\"><b>[ ژِ ل ُ ]</font></b> (اِخ ) نام جبار ژِلا و سیراکوز از <span class=\"hlight\" dir=\"rtl\">٤٩٠</span> تا <span class=\"hlight\" dir=\"rtl\">٤٧٨</span> ق .م . وی بر کارتاژیها در هیمر ظفر یافت .<br /></font></div>'),
(288176, 'ژله', '<span class=\"hlight\">ژله .</span> <font color=\"DarkGreen\"><b>[ ژِ ل ِ ]</font></b> (اِخ ) کلود. رجوع به لورن شود.<br /></font></div>'),
(288177, 'ژله', '<span class=\"hlight\">ژله .</span> <font color=\"DarkGreen\"><b>[ ژِ ل ِ ]</font></b> (فرانسوی، اِ) لرزانک . رجوع به لرزانک شود.<br /></font></div>'),
(288178, 'ژلگاوا', '<span class=\"hlight\">ژلگاوا.</span> <font color=\"DarkGreen\"><b>[ ژِ ]</font></b> (اِخ ) نام کنونی شهر میتو در لتونی، پایتخت قدیم کورلاند روسیه، دارای <span class=\"hlight\" dir=\"rtl\">٢٨٠٠٠</span> تن سکنه .<br /></font></div>'),
(288179, 'ژلیمر', '<span class=\"hlight\">ژلیمر.</span> <font color=\"DarkGreen\"><b>[ ژِ م ِ ]</font></b>(اِخ ) نام آخرین پادشاه واندالهای آفریقا. وی پس ازدو سال سلطنت به دست بِلیزر در <span class=\"hlight\" dir=\"rtl\">٥٣٤</span> م . مغلوب گشت .<br /></font></div>'),
(288180, 'ژلیه', '<span class=\"hlight\">ژلیه .</span> <font color=\"DarkGreen\"><b>[ ژُ ی ِ ]</font></b> (اِخ ) نام شهری در اتازونی (ایلی نوآ) بر کنار رود پلنز دارای <span class=\"hlight\" dir=\"rtl\">٢٣٣٦٥</span> تن سکنه .<br /></font></div>'),
(288181, 'ژلیوت', '<span class=\"hlight\">ژلیوت .</span> <font color=\"DarkGreen\"><b>[ ژِ یُت ْ ]</font></b> (اِخ ) پیر. نام خُنیاگر یعنی آوازه خوان فرانسوی . مولد لاسوب و وفات در اِستل (<span class=\"hlight\" dir=\"rtl\">١٧١٣</span> - <span class=\"hlight\" dir=\"rtl\">١٧٩٧</span> م .).<br /></font></div>'),
(288182, 'ژلیکو', '<span class=\"hlight\">ژلیکو.</span> <font color=\"DarkGreen\"><b>[ ژِ ک ُ ]</font></b> (اِخ ) ژُن . نام امیرالبحر انگلیسی . مولد سوتامپتن بسال <span class=\"hlight\" dir=\"rtl\">١٨٥٩</span> و وفات بسال <span class=\"hlight\" dir=\"rtl\">١٩٣٥</span> م . وی فرمانده سفاین بریتانیا در جنگ دریائی ژوتلاند (<span class=\"hlight\" dir=\"rtl\">١٩١٦</span>) بود.<br /></font></div>'),
(288183, 'ژم', '<span class=\"hlight\">ژم .</span> <font color=\"DarkGreen\"><b>[ ژَ ]</font></b> (اِ) قابله . (آنندراج ). ماما. ماماچه . <BR><font color=\"Blue\">◄</font> دایه . (آنندراج ). در جای دیگر دیده نشد. <BR><font color=\"Blue\">◄</font> در بعض نسخ شاهنامه، کلمه ٔ زم در ابیات ذیل به تصحیف ژم شده است <span class=\"hlight\">:</span> <br />ز انبوه پیلان و شیران ژم <br />گذرهای جیحون پر از باد و دم .<br />به اشکش بفرمود <font color=\"DarkGreen\"><b>[ کیخسرو ]</font></b> تا سوی ژم <br />برد لشکر و پیل وگنج و درم .<br /> <font color=\"Red\">فردوسی .</font><br />رجوع به زم شود.<br /></font></div>'),
(288184, 'ژماروغ', '<span class=\"hlight\">ژماروغ .</span> <font color=\"DarkGreen\"><b>[ ژَ ]</font></b> (اِ) زماروغ . سماروغ . سماروخ . گیاهی است سفیدکه در برشکال از جاهای نمناک روید. (آنندراج ). قارچ . کَم ْء. چمه . رجوع به زماروغ و سماروغ شود . و ظاهراً سماروغ طملان ِ ترکی و دنبلان و کشنج فارسی باشد.<br /></font></div>'),
(288185, 'ژمه لی', '<span class=\"hlight\">ژمه لی .</span> <font color=\"DarkGreen\"><b>[ ژُ م ِ ]</font></b> (اِخ ) نیکلا. نام ترانه ساز ایتالیائی ملقب به «گلوک دلیتالی » . مولد بسال <span class=\"hlight\" dir=\"rtl\">١٧١٤</span> در آورسا و وفات بسال <span class=\"hlight\" dir=\"rtl\">١٧٧٤</span> م .<br /></font></div>'),
(288186, 'ژموزاک', '<span class=\"hlight\">ژموزاک .</span> <font color=\"DarkGreen\"><b>[ ژِ م ُ ]</font></b> (اِخ ) نام کرسی بخش شارانت -اَنْفِریور از شهرستان سَنت، دارای راه آهن و <span class=\"hlight\" dir=\"rtl\">٢٣٧٨</span> تن سکنه .<br /></font></div>'),
(288187, 'ژمینی', '<span class=\"hlight\">ژمینی .</span> <font color=\"DarkGreen\"><b>[ ژُ ]</font></b> (اِخ ) هانری . نام ژنرالی رئیس ارکان حرب مارشال نی . مولد پایرن بسال <span class=\"hlight\" dir=\"rtl\">١٧٧٩</span> و وفات در پاریس بسال <span class=\"hlight\" dir=\"rtl\">١٨٦٩</span> م .<br /></font></div>'),
(288188, 'ژمیه', '<span class=\"hlight\">ژمیه .</span> <font color=\"DarkGreen\"><b>[ ژِ ی ِ ]</font></b> (اِخ ) فیرمن . نام بازیگر و هنرپیشه ٔ فرانسوی . مولد اُبرویه بسال <span class=\"hlight\" dir=\"rtl\">١٨٦٩</span> و وفات بسال <span class=\"hlight\" dir=\"rtl\">١٩٣٣</span> م .<br /></font></div>'),
(288189, 'ژن', '<span class=\"hlight\">ژن .</span><font color=\"DarkGreen\"><b>[ ژُ ]</font></b> (اِخ ) نام کرسی بخش لاند از ولایت مُن -دو-مارسان، دارای <span class=\"hlight\" dir=\"rtl\">٦٠٨</span> تن سکنه .<br /></font></div>'),
(288190, 'ژن', '<span class=\"hlight\">ژن .</span> <font color=\"DarkGreen\"><b>[ ژِ ]</font></b> (اِخ ) (ایتالیایی : جِنُوا ) نام شهری در ایطالیا پایتخت لیگوری، بندری بر ساحل خلیج ژِن از فروع دریای مدیترانه، دارای <span class=\"hlight\" dir=\"rtl\">٦٣٠٠٠٠</span> تن سکنه و آن شهری باشکوه و دارای قصور عالیه و موزه های پرنفایس و بندری تجارتی است و بدانجا کارخانه های صنعتی و کشتی سازی و نساجی و فلزکاری هست و شراب و ابریشم وروغن صادرات آن است . این شهر را در قرون وسطی لیگورها و ژن ها بنا کردند و پایتخت کشور جمهوری ژن که مردم آن در تجارت با مردم «ونیز» رقابت میکردند گردید. این بندر در <span class=\"hlight\" dir=\"rtl\">١٦٨٤</span> م . بفرمان لوئی چهاردهم پادشاه فرانسه بمباران شد و بسال <span class=\"hlight\" dir=\"rtl\">١٧٩٨</span> پایتخت جمهوری لیگورین گردید و در سال <span class=\"hlight\" dir=\"rtl\">١٨٠٥</span> به امپراطوری فرانسه ملحق گشت .<br /></font></div>'),
(288191, 'ژن', '<span class=\"hlight\">ژن .</span> <font color=\"DarkGreen\"><b>[ ژَ ]</font></b> (ص ) زشت . بدهیئت . (آنندراج ). در زبان پهلوی زشت باشد. (فرهنگ شعوری ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٥١</span>). فرومایه . دون . (ظاهراً از مجعولات شعوری است ).<br /></font></div>'),
(288192, 'ژن خان', '<span class=\"hlight\">ژن خان .</span> <font color=\"DarkGreen\"><b>[ ژَ ]</font></b> (اِخ ) تولی خان . (دیوان رودکی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٨٧</span>).<br /></font></div>'),
(288193, 'ژناتان', '<span class=\"hlight\">ژناتان .</span> <font color=\"DarkGreen\"><b>[ ژُ ]</font></b> (اِ) نبز، یعنی لقب استهزائی که به مردم اتازونی داده اند. سام . رجوع به سام شود.<br /></font></div>'),
(288194, 'ژناترپین', '<span class=\"hlight\">ژناترپین .</span> <font color=\"DarkGreen\"><b>[ ژِ رُ ]</font></b> (فرانسوی، اِ) نام داروئی که در طب بکار است . دانشمندانی چون ماکس، یولونوسکی و نیتزبرگ به کشف ژنالکالوئیدها موفق شدند. این داروها تمامی خواص آلکالوئیدها را دارا هستند ولی سمیت آنها بسیار کمتر است . ژناتروپین تمام خواص آتروپین را داشته و بخوبی تحمل میشود.مقدار استعمال آن نیم تا شش میلی گرم است . این دارو را بصورت محلول و حب از راه معده و بصورت محلول قابل تزریق زیرجلدی بکار میبرند. (درمانشناسی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٤٠</span>).<br /></font></div>'),
(288195, 'ژناپ', '<span class=\"hlight\">ژناپ .</span> <font color=\"DarkGreen\"><b>[ ژِ ]</font></b> (اِخ ) نام شهری در بلژیک بر ساحل چپ رود دیل، دارای <span class=\"hlight\" dir=\"rtl\">١٨٨٦</span> تن سکنه .<br /></font></div>'),
(288196, 'ژنبر', '<span class=\"hlight\">ژنبر.</span> <font color=\"DarkGreen\"><b>[ ژَم ْ ب َ ]</font></b> (اِ) سبدی که بدان خس و خاشاک و خاکروبه بردارند. (آنندراج ). رجوع به زنبر شود.<br /></font></div>'),
(288197, 'ژند', '<span class=\"hlight\">ژند.</span> <font color=\"DarkGreen\"><b>[ ژَ ]</font></b> (اِخ ) مخفف ژنده رزم <span class=\"hlight\">:</span> <br />به شایسته کاری برون رفت ژند<br />گوی دید برسان سرو بلند.<br /> <font color=\"Red\">فردوسی .</font><br />ز فتراک زین برگشایم کمند<br />بخواهم از ایرانیان کین ژند.<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(288198, 'ژند', '<span class=\"hlight\">ژند.</span> <font color=\"DarkGreen\"><b>[ ژَ ]</font></b> (ص، اِ) پاره .کهنه . (برهان ). جامه ٔ مندرس . خرقه . (برهان ). ژنده . دلق . مطلق کهنه و پاره . رکو. فلرز. (فرهنگ رشیدی ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ژندژند</span> ؛ پاره پاره <span class=\"hlight\">:</span> <br />از بهرمن نوند همی سوخت روزگار<br />اکنون مرا بر آتش غم سوخت چون نوند<br />هم خامه ٔ مآثر من کرده ریزریز<br />هم جامه ٔ مفاخر من کرده ژندژند.<br /> <font color=\"Red\">شهاب الدین بغدادی (از جهانگیری ).</font><br /><BR><font color=\"Blue\">◄</font> (اِ) آتش زنه . چخماق . (برهان ). زند. <BR><font color=\"Blue\">◄</font> نفیر . (صحاح الفرس ). <BR><font color=\"Blue\">◄</font> (ص ) بزرگ و عظیم همچون ژندپیل . (آنندراج ). بزرگ و مهیب . (جهانگیری ). <BR><font color=\"Blue\">◄</font> (اِخ ) نام کتاب زردشت که به زند اشتهاردارد. (برهان ). صاحب آنندراج گوید: کتاب زردشت ... وهمانا که فقره به فقره و پاره به پاره و سوره به سوره بوده همانا که این نام یافته است . رجوع به زند شود. <br /></font></div>'),
(288199, 'ژند و است', '<span class=\"hlight\">ژند و است .</span> <font color=\"DarkGreen\"><b>[ژَ دُ اُ ]</font></b> (اِخ ) زند و اُست . زند و استا. زند و اوستا. اوستا کتاب مقدس زرتشتیان و ژند یا زند شرح آن است . رجوع به هر یک از این دو کلمه شود <span class=\"hlight\">:</span> <br />یکی ژند و است آر با برسمت <br />بزمزم یکی پاسخی پرسمت .<br /> <font color=\"Red\">فردوسی .</font><br />برآمد همی گرد مرد و بجست <br />یکی موبدی دید با ژندو است .<br /> <font color=\"Red\">فردوسی .</font><br />پدرْم آن خردمندمهران ستاد<br />به پیری بسی چیز دارد بیاد<br />به کنجی نشسته ست با ژندو است <br />از امید گیتی شده پیر و سست .<br /> <font color=\"Red\">فردوسی .</font><br />به آن آب روشن سر و تن بشست <br />همی خواند اندر نهان ژند و است .<br /> <font color=\"Red\">فردوسی .</font><br />که دین مسیحا ندارد درست <br />ره گبرگی ورزد و ژند و است .<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(288200, 'ژند و استا', '<span class=\"hlight\">ژند و استا.</span> <font color=\"DarkGreen\"><b>[ ژَ دُ اُ ]</font></b> (اِخ ) ژند و اُست . اوستا نام کتاب مقدس زرتشتیان و ژند یا زند شرح آن است . رجوع به هریک از این دو کلمه و «ژند و اُست » شود <span class=\"hlight\">:</span> <br />به فرهنگیان ده مرا از نخست <br />چو آموختم ژند و استا درست .<br /> <font color=\"Red\">فردوسی .</font><br />بجائی که دانست آتشکده است <br />دگر ژند و استا و جشن سده است .<br /> <font color=\"Red\">فردوسی .</font><br />بیاراید این آتش زردهشت <br />بگیرد همی ژند و استا به مشت .<br /> <font color=\"Red\">فردوسی .</font><br />یکی کودکی مهتر اندر برش <br />پژوهنده ٔ ژند و استا سرش .<br /> <font color=\"Red\">فردوسی .</font><br />اگر نیستی اندر استا و ژند<br />فرستاده را زینهار از گزند.<br /> <font color=\"Red\">فردوسی .</font><br />بیامد بیاورد <font color=\"DarkGreen\"><b>[ تباک ]</font></b> استا و ژند<br />چنین گفت کز کردگار بلند<br />بریده ست بی مایه جان تباک <br />اگر دل ندارد سوی شاه پاک .<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(288201, 'ژندباف', '<span class=\"hlight\">ژندباف .</span> <font color=\"DarkGreen\"><b>[ ژَ ]</font></b> (اِ مرکب ) زندباف . صاحب آنندراج گوید: بمعنی بلبل و قمری و مثل آن و صاحب جهانگیری و مؤید به زای عربی نوشته و کسی وجه تسمیه ٔ این بیان نکرده و شاید که چون پرهای بلبل و قمری و فاخته و کبک و کبوتر و دراج چندان خوش رنگ و لطیف نباشد ژندباف میگفته باشند. رجوع به زندباف شود -انتهی . و این گفته بر اساسی نیست .<br /></font></div>'),
(288202, 'ژندرود', '<span class=\"hlight\">ژندرود.</span> <font color=\"DarkGreen\"><b>[ ژَ ]</font></b> (اِخ ) زاینده رود. زنده رود اصفهان . (آنندراج ).<br /></font></div>'),
(288203, 'ژنده', '<span class=\"hlight\">ژنده .</span> <font color=\"DarkGreen\"><b>[ ژَ دَ ]</font></b> (اِخ ) مخفف ژنده رزم . رجوع به ژنده رزم و ژند شود <span class=\"hlight\">:</span> <br />زمانی همی بود سهراب دیر<br />نیامد بنزدیک او ژنده شیر.<br /> <font color=\"Red\">فردوسی .</font><br />چو بشنید سهراب برجست زود<br />بیامد بر ژنده برسان دود.<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(288204, 'ژنده', '<span class=\"hlight\">ژنده .</span> <font color=\"DarkGreen\"><b>[ ژَ <span class=\"hlight\" dir=\"rtl\">/</span> ژِ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ص، اِ) پاره . پاره پاره . ژند. کهنه . لته . دلق . رُکو. خرقه . جامه ٔ دریده وکهن گشته . مندرس . جامه ٔ پاره پاره . کهن . (حاشیه ٔ لغت نامه ٔ اسدی ). خَلَق . خَلَق شده . فرسوده . مستعمل . پینه دار. دریده و کهن گشته و خَلَق باشد و آن جامه ای باشد که قلندران پوشند از لباس نکنده کرده . (نسخه ای از لغت نامه ٔ اسدی ). خُلقان . پاره های جامه ٔ کهنه که از راه چینند و آن شخص را نیز ژنده چین و کهنه چین گویند. (فرهنگ رشیدی ) <span class=\"hlight\">:</span> <br />این سَلَب من بین در ماه دی <br />ژنده چو تشلیخ در کیسیان . <br /> <font color=\"Red\">ابوالعباس (از صحاح الفرس ).</font><br />چو گل گرچه او ژنده پیراهن است <br />ولی بوی او از دگر گلشن است .<br /> <font color=\"Red\">منجیک (از شعوری ).</font><br />تا پای نهند بر سر حرّان <br />با کون فراخ گنده و ژنده .<br /> <font color=\"Red\">عسجدی .</font><br /> <br />گر کسی دیبا پوشد تو چرا نازی <br />چون خود اندر سَلَب ژنده ٔ خلقانی .<br /> <font color=\"Red\">ناصرخسرو.</font><br />مردمان بر تو بخندند ای برادر بی گمان <br />چون پلاس و ژنده را سازی به دیبا آستر.<br /> <font color=\"Red\">ناصرخسرو.</font><br />دید وقتی یکی پراکنده <br />زنده ای زیر جامه ٔ ژنده .<br /> <font color=\"Red\">سنائی .</font><br />سیه گلیم خری ژنده جل و پشماکند<br />که ژندگیش نه درپی پذیرد و نه رفو.<br /> <font color=\"Red\">سوزنی .</font><br />زو دلم چون مرقع صوفی است <br />پاره بر پاره ژنده بر ژنده .<br /><font color=\"Red\">سوزنی .</font><br />جز به نظم سخن کجا یابی <br />آگهی از درست و ژنده ٔ من .<br /> <font color=\"Red\">سوزنی (از جهانگیری ).</font><br />آسمان را بجای دلق کبود<br />ژنده ای تازه تر ندوخته اند.<br /> <font color=\"Red\">خاقانی .</font><br />یا دلم ده باز تا چند از بلا<br />یا نه یاری ژنده کفشی ده مرا.<br /> <font color=\"Red\">عطار (از رشیدی ).</font><br />نقل است که روزی بر لب دجله نشسته بود و خرقه ٔ ژنده ٔ خود پاره میدوخت، سوزنش در دریا افتاد. کسی از او پرسید که ملکی چنان از دست بدادی چه یافتی ؟ اشاره کرد به دریا که سوزنم بازدهید. هزار ماهی از دریا برآمد هر یکی سوزنی زرّین به دهان گرفته . (تذکرةالاولیاء). <br />چونکه بازش کرد آن که میگریخت <br />صدهزارش ژنده اندر ره بریخت .<br /> <font color=\"Red\">مولوی .</font><br />یک فقیهی ژنده ها برچیده بود<br />در عمامه ٔ خویش درپیچیده بود.<br /> <font color=\"Red\">مولوی .</font><br />زان عمامه ٔ زفت نابایست او<br />ماند یک گز ژنده اندر دست او.<br /> <font color=\"Red\">مولوی .</font><br />ظاهر درویشی جامه ٔ ژنده است و موی سترده . (گلستان ).<br />مزن طعنه ای خواجه بر ژنده ام <br />که من هم خدا را یکی بنده ام .<br /> <font color=\"Red\">سعدی (بوستان ).</font><br />نه سلطان خریدار هر بنده ای ست <br />نه در زیر هر ژنده ای زنده ای ست .<br /> <font color=\"Red\">سعدی (بوستان ).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ژنده شدن </span> ؛ پاره و کهنه و مندرس گشتن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ژنده کردن </span> ؛ محکم کاری نکردن . بد کار کردن : سفسف العمل ؛ بد کرد کار را و محکم نکرد آن را (لم یحکمه ) و ژنده کردش . (زمخشری ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /> <span class=\"hlight\">ژنده باش گنده مباش </span> . رجوع به کتاب امثال و حکم دهخدا شود.<br /> <BR><font color=\"Blue\">◄</font> (ص ) کلمه ٔ ژنده در بیت ذیل معلوم نیست در چه معنی استعمال شده است، شاید: پیر <span class=\"hlight\">:</span> <br />سر ژنده ٔ زال چون برف گشت <br />ز خون یلان خاک شنگرف گشت .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> مُتکبر. <BR><font color=\"Blue\">◄</font> زنده . عظیم . بزرگ . (برهان ). شگرف . مهیب . (برهان ). مُنکر. کلان . ضخم . رجوع به قندفیل و گنده پیر شود.این کلمه در معنی اخیر غالباً در صفت پیل آمده است و گاه در صفت برخی از درندگان مانند گرگ و شیر <span class=\"hlight\">:</span> <br />از سهم و از سیاست نادرگزار تو<br />بر گرگ ژنده پوست بدرّد سگ شبان .<br /> <font color=\"Red\">سوزنی .</font><br />و نیز رجوع به ژنده پیل شود.<br /></font></div>'),
(288205, 'ژنده رزم', '<span class=\"hlight\">ژنده رزم .</span> <font color=\"DarkGreen\"><b>[ ژَ دَ رَ ]</font></b> (اِخ ) ژند. ژنده . نام خالوی سهراب پسر شاه سمنگان از پهلوانان تورانی . او به یک مشت رستم کشته شد. فردوسی داستان وی را در شاهنامه چنین آورده است :<br />بدانگه که سهراب آهنگ جنگ <br />نمود و گه رفتن آمدش تنگ <br />همی خواند پس مادرش ژنده رزم <br />که او دیده بد پهلوان گاه بزم <br />بد او پور شاه سمنگان زمین <br />همان خال سهراب باآفرین <br />بدو گفت کای گرد روشن روان <br />فرستمت همراه این نوجوان <br />که چون نامور سوی ایران رسد<br />بنزدیک شاه دلیران رسد<br />چو تنگ اندرآید سپه روز کین <br />پدر را نمائی به پور گزین ...<br />چو خورشید گشت از جهان ناپدید<br />شب تیره بر روز لشکر کشید<br />تهمتن بیامد بنزدیک شاه <br />میان بسته ٔ رزم و دل کینه خواه <br />که دستور باشد مرا تاجور<br />کزایدر شوم بی کلاه و کمر<br />ببینم که این نو جهاندار کیست <br />بزرگان کدامند و سالار کیست <br />بدو گفت کاوس کین کار تست <br />که روشن روان بادی و تندرست ...<br />تهمتن یکی جامه ٔ ترکوار<br />بپوشید و آمد نهان تا حصار<br />بیامد چو نزدیکی دژ رسید<br />خروشیدن و بانگ ترکان شنید<br />بدان دژ درون رفت مرد دلیر<br />چنان چون سوی آهوان نره شیر<br />یکایک سران را نگه کرد و دید<br />ز شادی رخانش چو گل بشکفید<br />چو سهراب را دید بر تخت بزم <br />نشسته به یک دست او ژنده رزم <br />به دیگر چو هومان سوار دلیر<br />دگر بارمان نامبردار شیر<br />تو گفتی همه تخت سهراب بود<br />بسان یکی سرو شاداب بود...<br />ز گردان به گرد اندرش صد دلیر<br />جوان و سرافراز چون نره شیر<br />پرستار پنجاه با دست بند<br />به پیش دل افروز تخت بلند...<br />همی بود رستم بدانجا ز دور<br />نشسته نگه کرد مردان تور<br />به شایسته کاری برون رفت ژند<br />گوی دید برسان سرو بلند<br />بدان لشکر اندر چنو کس نبود<br />بسودش بتندی و پرسید زود<br />چه مردی بدو گفت با من بگوی <br />سوی روشنی آی و بنمای روی <br />تهمتن یکی مشت بر گردنش <br />بزد تیز و برشد روان از تنش <br />بدان جایگه خشک شد ژنده رزم <br />سرآمد بر او روز پیکار و بزم <br />زمانی همی بود سهراب دیر<br />نیامد بنزدیک او ژنده شیر<br />نگه کرد سهراب تا ژنده رزم <br />کجا شد که جایش تهی شد زبزم <br />برفتند و دیدندش افکنده خوار<br />برآسوده از بزم و از کارزار<br />به سهراب گفتند شد ژنده رزم <br />سرآمد بر او کار پیکار و بزم <br />چو بشنید سهراب برجست زود<br />بیامد بر ژنده برسان دود<br />ابا چاکر و شمعو خنیاگران <br />بیامد ورا دید مرده چنان <br />شگفت آمدش سخت و خیره بماند<br />دلیران و گندآوران را بخواند<br />بدیشان چنین گفت سهراب شیر<br />که ای بخردان و ردان دلیر<br />یک امشب شما را نباید غنود<br />همه شب سر نیزه باید بسود<br />که گرگ اندرآمد میان رمه <br />سگ و مرد را دید در دمدمه <br />ربود از دلیران یکی گوسفند<br />بزاری وخواریش چونین فکند<br />اگر یار باشد جهان آفرین <br />چو نعل سمندم بساید زمین <br />ز فتراک زین برگشایم کمند<br />بخواهم از ایرانیان کین ژند...<br />که گر گم شد از تخت من ژنده رزم <br />نیاید همی سیر جانم ز بزم ...<br /></font></div>'),
(288206, 'ژنده شیر', '<span class=\"hlight\">ژنده شیر.</span> <font color=\"DarkGreen\"><b>[ ژَ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (اِ مرکب ) شیر بزرگ . شیر کلان . شیر خشمناک . رجوع به ژنده شود <span class=\"hlight\">:</span> <br />زمانی همی بود سهراب دیر<br />نیامد بنزدیک او ژنده شیر.<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(288207, 'ژنده فروش', '<span class=\"hlight\">ژنده فروش .</span> <font color=\"DarkGreen\"><b>[ ژَ <span class=\"hlight\" dir=\"rtl\">/</span> ژِ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ف ُ ]</font></b> (نف مرکب ) کهنه فروش . نجّاد. (زمخشری ).<br /></font></div>'),
(288208, 'ژنده پوش', '<span class=\"hlight\">ژنده پوش .</span> <font color=\"DarkGreen\"><b>[ ژَ <span class=\"hlight\" dir=\"rtl\">/</span> ژِ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (نف مرکب ) کهنه پوش . خرقه پوش . مُتَحشف <span class=\"hlight\">:</span> <br />ز فرمان سر آزاده و ژنده پوش <br />ز آواز بیغاره آسوده گوش .<br /> <font color=\"Red\">فردوسی .</font><br />با عقل پای کوب که پیری است ژنده پوش <br />بر فقر دست کش که عروسی است خوش لقا.<br /> <font color=\"Red\">خاقانی .</font><br />پس بگفتی تاکنون بودی خدیو<br />بنده گردی ژنده پوشی را بریو.<br /> <font color=\"Red\">مولوی .</font><br />ز ویرانه ٔ عارفی ژنده پوش <br />یکی را نباح سگ آمد به گوش .<br /> <font color=\"Red\">سعدی (بوستان ).</font><br />چندان بمان که جامه ٔ ازرق کند قبول <br />بخت جوانت از فلک پیر ژنده پوش .<br /> <font color=\"Red\">حافظ.</font><br />قانعی ژنده پوش ناگاهی <br />درمی یافت در سر راهی .<br /><font color=\"Red\">مکتبی .</font><br /></font></div>'),
(288209, 'ژنده پیل', '<span class=\"hlight\">ژنده پیل .</span> <font color=\"DarkGreen\"><b>[ ژَ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (اِ مرکب ) پیل بزرگ . فیل بزرگ . فیل کلان . فیل مست و خشمگین . معرب آن زندفیل است . (از تاج العروس ). کلثوم <span class=\"hlight\">:</span> <br />رده برکشیده سپاهش دو میل <br />به دست چپش هفتصد ژنده پیل .<br /> <font color=\"Red\">فردوسی .</font><br />گرازان سواران دمان و دنان <br />به دندان زمین ژنده پیلان کنان .<br /> <font color=\"Red\">فردوسی .</font><br />خروشیدن کوس با کرّنای <br />همان ژنده پیلان و هندی درای .<br /> <font color=\"Red\">فردوسی .</font><br />یکی پهلوان است گرد و دلیر<br />به تن ژنده پیل و به دل نرّه شیر.<br /> <font color=\"Red\">فردوسی .</font><br />یکی ژنده پیلی بیاراستند<br />بر او تخت زرین بپیراستند.<br /> <font color=\"Red\">فردوسی .</font><br />مبارز چو شیروی درنده شیر<br />چو شاپور یل ژنده پیل دلیر.<br /> <font color=\"Red\">فردوسی .</font><br />بدل گفت پیکار با ژنده پیل <br />چو غوطه است خوردن به دریای نیل .<br /> <font color=\"Red\">فردوسی .</font><br />نبرد کسی جوید اندر جهان <br />که او ژنده پیل اندرآرد ز جان .<br /> <font color=\"Red\">فردوسی .</font><br />پس لشکرش هفت صد ژنده پیل <br />خدای جهان یاور و جبرئیل .<br /> <font color=\"Red\">فردوسی .</font><br />ز لشکرگه پهلوان بر دو میل <br />کشیده دورویه رده ژنده پیل .<br /> <font color=\"Red\">فردوسی .</font><br />بزیر اندرش باره ٔ گامزن <br />یکی ژنده پیل است گوئی بتن .<br /> <font color=\"Red\">فردوسی .</font><br />به پیش سپاه اندرون پیل و شیر<br />پس ژنده پیلان یلان دلیر.<br /> <font color=\"Red\">فردوسی .</font><br />سوی سام نیرم نهادند روی <br />ابا ژنده پیلان پرخاشجوی .<br /> <font color=\"Red\">فردوسی .</font><br />به رزم اندرون ژنده پیل بلاست <br />به بزم اندرون آسمان وفاست .<br /> <font color=\"Red\">فردوسی .</font><br />به یک دست بربسته شیر و پلنگ <br />به دست دگر ژنده پیلان جنگ .<br /> <font color=\"Red\">فردوسی .</font><br />ابا کوس و با ژنده پیلان مست <br />همان گرزه ٔ گاوپیکر به دست .<br /> <font color=\"Red\">فردوسی .</font><br />همی رفت شاه از بر ژنده پیل <br />بر آن تخت پیروزه برسان نیل .<br /> <font color=\"Red\">فردوسی .</font><br />به تن ژنده پیل و به جان جبرئیل <br />به کف ابر بهمن به دل رود نیل .<br /> <font color=\"Red\">فردوسی .</font><br />همی رفت تازان سوی ژنده پیل <br />خروشنده مانند دریای نیل .<br /> <font color=\"Red\">فردوسی .</font><br />وزان ژنده پیلان هندی چهار<br />همه جامه و فرش کردند بار.<br /> <font color=\"Red\">فردوسی .</font><br />سه دیگر فرستادن تخت عاج <br />بر این ژنده پیلان و پیروزه تاج .<br /> <font color=\"Red\">فردوسی .</font><br />مرا خیره گشتی سر از فرّ شاه <br />وزان ژنده پیلان و چندین سپاه .<br /> <font color=\"Red\">فردوسی .</font><br />یکی تخت بر کوهه ٔ ژنده پیل <br />ز پیروزه تابان بکردار نیل .<br /> <font color=\"Red\">فردوسی .</font><br />به گرد اندرش ژنده پیلان دویست <br />تو گفتی به گیتی جز او شاه نیست .<br /> <font color=\"Red\">فردوسی .</font><br />ز هاماوران بود صد ژنده پیل <br />یکی لشکری ساخته تا دو میل .<br /> <font color=\"Red\">فردوسی .</font><br />تهمتن بپوشید ببر بیان <br />نشست از برژنده پیل دمان .<br /> <font color=\"Red\">فردوسی .</font><br />تو گفتی هر زمانی ژنده پیلی <br />بلرزاند ز رنج پشگان تن .<br /> <font color=\"Red\">منوچهری .</font><br />بارکش چون گاومیش و حمله بر چون نره شیر<br />گامزن چون ژنده پیل و بانگ زن چون کرگدن .<br /> <font color=\"Red\">منوچهری .</font><br />از ننگ آنکه شاهان باشند بر ستوران <br />بر پشت ژنده پیلان این شه کند سواری .<br /> <font color=\"Red\">منوچهری .</font><br />پر خوری ژنده پیل باشی تو<br />کم خوری جبرئیل باشی تو.<br /> <font color=\"Red\">سنائی .</font><br /> <BR><font color=\"Blue\">◄</font> کنایه از پهلوان بسیار نیرومند و دلیر <span class=\"hlight\">:</span> <br />بگفتا دریغ از چنین ژنده پیل <br />که بودی خروشان چو دریای نیل .<br /> <font color=\"Red\">فردوسی .</font><br />تن ژنده پیل اندرآمد به خاک <br />جهان گشت از این درد ما را خباک .<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(288210, 'ژنده چین', '<span class=\"hlight\">ژنده چین .</span> <font color=\"DarkGreen\"><b>[ ژَ <span class=\"hlight\" dir=\"rtl\">/</span> ژِدَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (نف مرکب ) آنکه پاره های جامه ٔ کهنه از راهها و کوچه ها چیند. (رشیدی ). رجوع به کهنه چین شود.<br /></font></div>'),
(288211, 'ژندژند', '<span class=\"hlight\">ژندژند.</span> <font color=\"DarkGreen\"><b>[ ژَ ژَ ]</font></b>(ص مرکب ) پاره پاره . (برهان ). قطعه قطعه <span class=\"hlight\">:</span> <br />هم خامه ٔ مآثر من کرده ریزریز<br />هم جامه ٔ مفاخر من کرده ژندژند.<br /> <font color=\"Red\">شهاب الدین بغدادی (از جهانگیری ).</font><br />رجوع به ژند شود.<br /></font></div>'),
(288212, 'ژندگی', '<span class=\"hlight\">ژندگی .</span> <font color=\"DarkGreen\"><b>[ ژَ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (حامص ) حالت و چگونگی ژند و ژنده . پارگی . کهنگی . (غیاث ). رثاثت <span class=\"hlight\">:</span> <br />سیه گلیم خری ژنده جل و پشماکند<br />که ژندگیش نه درپی پذیرد و نه رفو.<br /><font color=\"Red\">سوزنی .</font><br /></font></div>'),
(288213, 'ژنر', '<span class=\"hlight\">ژنر.</span><font color=\"DarkGreen\"><b>[ ژِ ن ِ ]</font></b> (اِخ ) جِنِر. ادوارد. نام طبیب معروف انگلیسی مخترع واکسن . مولد ووفات در برکلی از ناحیه ٔ گلوسستر (<span class=\"hlight\" dir=\"rtl\">١٧٤٩</span>-<span class=\"hlight\" dir=\"rtl\">١٨٢٣</span> م .).<br /></font></div>'),
(288214, 'ژنرال', '<span class=\"hlight\">ژنرال .</span> <font color=\"DarkGreen\"><b>[ ژِ ن ِ ]</font></b> (فرانسوی، اِ) یکی از درجات نظامی . سرتیپ .<br /></font></div>'),
(288215, 'ژنرال قنسول', '<span class=\"hlight\">ژنرال قنسول .</span> <font color=\"DarkGreen\"><b>[ ژِ ن ِ ق ُ ]</font></b> (فرانسوی، اِ مرکب ) یا ژنرال کنسول . سرکنسول و کارپرداز اول . آنکه تعهد امور ابناء کشور خویش را در مملکت بیگانه کند.<br /></font></div>'),
(288216, 'ژنرال گاردان', '<span class=\"hlight\">ژنرال گاردان .</span> <font color=\"DarkGreen\"><b>[ ژِ ن ِ ]</font></b> (اِخ ) رجوع به گاردان شود.<br /></font></div>'),
(288217, 'ژنرالیف', '<span class=\"hlight\">ژنرالیف .</span> <font color=\"DarkGreen\"><b>[ ژِ ن ِ ]</font></b> (اِخ ) نام قصر پادشاهان مغاربه نزدیکی الحمراء واقع در غرناطه و آن نمونه ٔ بارزی ازفن معماری عرب و دارای باغهای دلکش و باشکوه است .<br /></font></div>'),
(288218, 'ژنز', '<span class=\"hlight\">ژنز.</span> <font color=\"DarkGreen\"><b>[ ژُ ]</font></b> (اِخ ) جُنز. ویلیام . نام مستشرق هندشناس انگلیسی . مولد لندن بسال <span class=\"hlight\" dir=\"rtl\">١٧٤٦</span> و وفات در کلکته بسال <span class=\"hlight\" dir=\"rtl\">١٧٩٤</span> م .<br /></font></div>'),
(288219, 'ژنز', '<span class=\"hlight\">ژنز.</span> <font color=\"DarkGreen\"><b>[ ژُ ]</font></b> (اِخ ) جُنز. ژان پل . نام ملاح و دریاداری از مردم اکس . مولد کیرک بان بسال <span class=\"hlight\" dir=\"rtl\">١٧٤٧</span> و وفات در پاریس بسال <span class=\"hlight\" dir=\"rtl\">١٧٩٢</span> م . وی در جنگ استقلال امریکا سمت امیرالبحری سفاین آن کشور را داشت .<br /></font></div>'),
(288220, 'ژنز', '<span class=\"hlight\">ژنز.</span> <font color=\"DarkGreen\"><b>[ ژُ ]</font></b> (اِخ ) جُنز. اینیگو. نام معماری انگلیسی . مولد سال <span class=\"hlight\" dir=\"rtl\">١٥٧٣</span> در اسمیت فیلد و وفات بسال <span class=\"hlight\" dir=\"rtl\">١٦٥٢</span> م . وی ملقب به «لوپالادیو آنگله » و اصلاً اسپانیولی است .<br /></font></div>'),
(288221, 'ژنزارت', '<span class=\"hlight\">ژنزارت .</span> <font color=\"DarkGreen\"><b>[ ژِ ن ِ رِ ]</font></b> (اِخ ) نام دریاچه ای است به فلسطین . رجوع به تیبریاد شود.<br /></font></div>'),
(288222, 'ژنزاک', '<span class=\"hlight\">ژنزاک .</span> <font color=\"DarkGreen\"><b>[ ژُ ]</font></b> (اِخ ) نام کرسی ولایت شارانت سفلی، دارای راه آهن و <span class=\"hlight\" dir=\"rtl\">٣١٤٢</span> تن سکنه . محصولات عمده ٔ آنجا شراب و عرق و احجار ساختمانی است .<br /></font></div>'),
(288223, 'ژنس', '<span class=\"hlight\">ژنس .</span> <font color=\"DarkGreen\"><b>[ ژِ ]</font></b> (اِخ ) (قدیس ) نام اسقف کلرمن . وی در حدود سالهای <span class=\"hlight\" dir=\"rtl\">٦٠٠</span> تا <span class=\"hlight\" dir=\"rtl\">٦٦٢</span> م . می زیسته و ذکران او سوم ژوئن است .<br /></font></div>'),
(288224, 'ژنسریک', '<span class=\"hlight\">ژنسریک .</span> <font color=\"DarkGreen\"><b>[ ژِ س ِ ]</font></b> (اِخ ) نام پادشاهی از واندالها فاتح افریقا و مؤسس سلطنت وسیعی در آنجا و مخرّب یونان و روم . (<span class=\"hlight\" dir=\"rtl\">٤٢٨</span>-<span class=\"hlight\" dir=\"rtl\">٤٧٧</span> م .).<br /></font></div>'),
(288225, 'ژنسن', '<span class=\"hlight\">ژنسن .</span> <font color=\"DarkGreen\"><b>[ ژُ س ُ ]</font></b> (اِخ ) جانسن . سموئل . نام نویسنده و نقّاد انگلیسی متولد در لیشفیلد و متوفی در لندن (<span class=\"hlight\" dir=\"rtl\">١٧٠٩</span>-<span class=\"hlight\" dir=\"rtl\">١٧٨٤</span> م .). مؤلف کتاب تذکره ٔ زندگانی شعرای انگلیس .<br /></font></div>'),
(288226, 'ژنسن', '<span class=\"hlight\">ژنسن .</span> <font color=\"DarkGreen\"><b>[ ژُ س ُ ]</font></b> (اِخ ) جانسن . بنژامن . نام یکی از بهترین شعرای درام نویس انگلیس . مولد وِستمینستر بسال <span class=\"hlight\" dir=\"rtl\">١٥٧٢</span> یا <span class=\"hlight\" dir=\"rtl\">١٥٧٣</span>و وفات بسال <span class=\"hlight\" dir=\"rtl\">١٦٣٧</span> م . وی را بِن ژنسن نیز میگفتند.<br /></font></div>'),
(288227, 'ژنسن', '<span class=\"hlight\">ژنسن .</span> <font color=\"DarkGreen\"><b>[ ژُ س ُ ]</font></b> (اِخ ) جانسن . اندریو. نام رئیس جمهوری اتازونی در سال <span class=\"hlight\" dir=\"rtl\">١٨٦٥</span> م . وی پس از کشته شدن لینکلن به مقام ریاست جمهور رسید (<span class=\"hlight\" dir=\"rtl\">١٨٠٨</span>-<span class=\"hlight\" dir=\"rtl\">١٨٧٥</span> م .).<br /></font></div>'),
(288228, 'ژنسیر', '<span class=\"hlight\">ژنسیر.</span> <font color=\"DarkGreen\"><b>[ ژُ ی ِ ]</font></b> (اِخ ) رسینیل دوژنسیر. نام ترانه سازی از اهالی فرانسه . مولد پاریس بسال <span class=\"hlight\" dir=\"rtl\">١٨٣٩</span> و وفات بسال <span class=\"hlight\" dir=\"rtl\">١٩٠٣</span> م .<br /></font></div>'),
(288229, 'ژنلهاک', '<span class=\"hlight\">ژنلهاک .</span> <font color=\"DarkGreen\"><b>[ ژِ ن ُ ]</font></b> (اِخ ) نام کرسی بخش گارد از ولایت آلِس نزدیک گارُدِنت، دارای راه آهن و <span class=\"hlight\" dir=\"rtl\">١٠٠٩</span> تن سکنه .<br /></font></div>'),
(288230, 'ژنن', '<span class=\"hlight\">ژنن .</span> <font color=\"DarkGreen\"><b>[ ژِ ن ُ ]</font></b> (اِخ ) فرانسوا. نام عالم فرانسوی متولد در آمین بسال <span class=\"hlight\" dir=\"rtl\">١٨٠٣</span> و متوفی بسال <span class=\"hlight\" dir=\"rtl\">١٨٥٦</span> م .<br /></font></div>'),
(288231, 'ژنه', '<span class=\"hlight\">ژنه .</span> <font color=\"DarkGreen\"><b>[ ژِ ن ِ ]</font></b> (اِخ ) (قدیس ) نام آرتیست و ممثل رومی معاصر دیوکلسین امپراطور روم . او در سال <span class=\"hlight\" dir=\"rtl\">٢٨٦</span> یا <span class=\"hlight\" dir=\"rtl\">٣٠٣</span> م . به جرم نصرانیت به شهادت رسید. وی قهرمان تراژدی «رُترو» است و ذکران او <span class=\"hlight\" dir=\"rtl\">٢٦</span> اوت است .<br /></font></div>'),
(288232, 'ژنه', '<span class=\"hlight\">ژنه .</span> <font color=\"DarkGreen\"><b>[ ژَ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ) نیش سوزن . <BR><font color=\"Blue\">◄</font> نیش جانوران گزنده مانند زنبور و پشه و امثال آن . (برهان ). صاحب آنندراج گوید تبدیل زنه است .<br /></font></div>'),
(288233, 'ژنو', '<span class=\"hlight\">ژنو.</span> <font color=\"DarkGreen\"><b>[ ژِ ن ِوْ ]</font></b> (اِخ ) (دریاچه ٔ...) نام دیگر دریاچه ٔ لِمان در جنوب غربی سوئیس شمال آلپ های ساووآ و به زیبائی منظر شهره است . این دریاچه قریب <span class=\"hlight\" dir=\"rtl\">٣٧٥</span> متر از سطح دریا ارتفاع دارد و طول آن هفتاد کیلومتر و عرضش دوازده کیلومتر و عمق ژرفترین جای آن <span class=\"hlight\" dir=\"rtl\">٣٣٠</span> متر است .<br /></font></div>'),
(288234, 'ژنو', '<span class=\"hlight\">ژنو.</span> <font color=\"DarkGreen\"><b>[ ژِ ن ِوْ ]</font></b> (اِخ ) نام شهری در سویس و کرسی بخشی به همین نام بر کنار دریاچه ٔ لِمان، دارای <span class=\"hlight\" dir=\"rtl\">١٣٥٠٠٠</span> تن سکنه . این شهر را دانشگاهی است که کالوَن بنا نهاده و نیز در آنجا مؤسسات بزرگی از قبیل موزه و کتابخانه ٔ عمومی و کارخانه های ساعت سازی و صنایع ظریفه و شیمیائی وجود دارد. شهر ژنو از جهت صفا و جودت هوا گردشگاه ملل خارجی است . جامعه ٔ ملل سابقاً در این شهر تشکیل میشد. کانتون ژنو را قریب <span class=\"hlight\" dir=\"rtl\">١٨٠٠٠٠</span> تن سکنه است .<br /></font></div>'),
(288235, 'ژنود', '<span class=\"hlight\">ژنود.</span> <font color=\"DarkGreen\"><b>[ ژِ ]</font></b> (اِخ ) آبه آنتوان اُژِن . نام عالم کاتولیک فرانسوی . مولد مُنتلیمار بسال <span class=\"hlight\" dir=\"rtl\">١٧٩٢</span> و وفات در جزایر هیر بسال <span class=\"hlight\" dir=\"rtl\">١٨٤٩</span> م .<br /></font></div>'),
(288236, 'ژنور', '<span class=\"hlight\">ژنور.</span><font color=\"DarkGreen\"><b>[ ژِ ن ِوْرْ ]</font></b> (اِخ ) نام گردنه ای است در آلپهای کوتین مابین بریانسن و سوز، دارای <span class=\"hlight\" dir=\"rtl\">١٨٦٠</span> متر ارتفاع .<br /></font></div>'),
(288237, 'ژنوسکوپولامین', '<span class=\"hlight\">ژنوسکوپولامین .</span> <font color=\"DarkGreen\"><b>[ ژِ نُس ْ ک ُ پ ُ ]</font></b> (فرانسوی، اِ) یا اینوکسیداسکوپولامین از ژنالکالوئیدهاست . سمیت آن از اسکوپولامین کمتر و اثر آن کاملاً مشابه است . مقدار استعمال آن روزی یک تا سه میلی گرم از حبهای نیم میلی گرمی محلولات خوراکی که هر بیست قطره ٔ آن برابر یک میلی گرم است و آمپولهای نیم تا یک میلی گرمی . (درمانشناسی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٤٨</span>).<br /></font></div>'),
(288238, 'ژنوی یو', '<span class=\"hlight\">ژنوی یو.</span> <font color=\"DarkGreen\"><b>[ ژِ ن ِ وی ی ِوْ ]</font></b> (اِخ ) (آبِی ْ دوسنت ...) این بنا در سال <span class=\"hlight\" dir=\"rtl\">٥٠٨</span> م . بوسیله ٔ کلویس بر روی تپه ای در پاریس (محل کنونی مدرسه ٔ هانری چهارم ) تأسیس شد. جمعیت شانوای سنت ژنوی یو که بنام ژِن ُوِفَن نیز خوانده میشود در سال <span class=\"hlight\" dir=\"rtl\">١٦٣٤</span> م . به دست کاردینال لارشفوکو به شکل دیگر درآمد. کتابخانه ٔ ژِن ُوِفَن ها در <span class=\"hlight\" dir=\"rtl\">١٧٩١</span> بسته شد و سپس بصورت کتابخانه ٔ عمومی سنت ژنوی یو درآمد.<br /></font></div>'),
(288239, 'ژنوی یو', '<span class=\"hlight\">ژنوی یو.</span> <font color=\"DarkGreen\"><b>[ ژِ ن ِ وی ی ِوْ ]</font></b> (اِخ ) نام قدیسه ٔ متولد در نانتر بسال <span class=\"hlight\" dir=\"rtl\">٤٢٠</span> و متوفی در پاریس بسال <span class=\"hlight\" dir=\"rtl\">٥١٢</span> م . ذکران وی سوم ژانویه است . او با آتیلای خونخوار معروف معاصر بود وسکنه ٔ پاریس را امیدوار ساخت که از خطر هجوم وی مصون خواهند ماند و از قضا این پیش بینی به صحت پیوست .<br /></font></div>'),
(288240, 'ژنک', '<span class=\"hlight\">ژنک .</span> <font color=\"DarkGreen\"><b>[ ژُ ]</font></b> (فرانسوی، اِ) نامی است اصلاً چینی و مستعمل در زبان فرانسه بمعنی کشتی مخصوص بادبان داری که برای حمل و نقل های تجارتی یا امور نظامی و جنگی در شرق اقصی بکار میرود و تا حدود <span class=\"hlight\" dir=\"rtl\">٤٠٠</span> تن ظرفیت دارد. ژاپنی ها این نوع کشتی را در کشنشین بکار میبرند. جُنْگ . رجوع به جُنْگ شود.<br /></font></div>'),
(288241, 'ژنکپینگ', '<span class=\"hlight\">ژنکپینگ .</span> <font color=\"DarkGreen\"><b>[ ژُ ک ُ ]</font></b> (اِخ ) نام شهری در سوئد بر کنار وِتِر، دارای <span class=\"hlight\" dir=\"rtl\">٣٠٠٠٠</span> تن سکنه . آنجا مرکز کارخانه های کبریت سازی است .<br /></font></div>'),
(288242, 'ژنگ', '<span class=\"hlight\">ژنگ .</span> <font color=\"DarkGreen\"><b>[ ژَ ]</font></b> (اِخ ) کتاب مانی نقاش و آن مشتمل بوده بر تصویرات و نقشهائی که اختراع اوست . (برهان ). ارژنگ . کتاب منسوب به مانی و ظاهراً ژنگ مخفف این کلمه باشد <span class=\"hlight\">:</span> <br />آن صحن چمن که از دم دی <br />گفتی دم گرگ یا پلنگ است <br />اکنون ز بهار مانوی طبع<br />پر نقش و نگار همچو ژنگ است .<br /> <font color=\"Red\">(منسوب به رودکی از جهانگیری ).</font><br /> <BR><font color=\"Blue\">◄</font> (اِ) چین و شکنجی که بر روی و اندام مردم پدید آید از پیری . (برهان ). آژنگ . و ظاهراً ژنگ بدین معنی مخفف این کلمه است . <BR><font color=\"Blue\">◄</font> قطره ٔ باران . (جهانگیری ) (برهان ). و به این معنی در بعض فرهنگهابا اول مکسور و یاء معروف مرقوم است . <BR><font color=\"Blue\">◄</font> صاحب آنندراج گوید: بمعنی جلاجل نیز هست لیکن در نسخه ٔ لسان الشعرا که نزد کاتب است نیست اما زنگ با زای تازی بمعنی جلاجل آمده است <span class=\"hlight\">:</span> <br />سواران و پیلان بدر بر بپای <br />خروشیدن ژنگ و هندی درای .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> زنگ . زنگار. زنگی که در فلزات بر اثر رطوبت و غیره پیدا شود. رجوع به ژنگار شود <span class=\"hlight\">:</span> <br />به می بر پراکند مشک و گلاب <br />شد آن طشت بی ژنگ چون آفتاب .<br /> <font color=\"Red\">فردوسی .</font><br />مدارید کردار او بس شگفت <br />که روشن دلش ژنگ آهن گرفت .<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(288243, 'ژنگ کیند', '<span class=\"hlight\">ژنگ کیند.</span> <font color=\"DarkGreen\"><b>[ ژُ ]</font></b> (اِخ ) ژهان بارتلد. نام نقاش و گراوورساز هلندی، متولد در لاتروپ بسال <span class=\"hlight\" dir=\"rtl\">١٨١٩</span> و متوفی بسال <span class=\"hlight\" dir=\"rtl\">١٨٩١</span> م .<br /></font></div>'),
(288244, 'ژنگا', '<span class=\"hlight\">ژنگا.</span> <font color=\"DarkGreen\"><b>[ ژُ ]</font></b> (اِ) سُم شکافته ٔ آهو و گاو و امثال آن . (آنندراج از انجمن آرا) .<br /></font></div>'),
(288245, 'ژنگار', '<span class=\"hlight\">ژنگار.</span> <font color=\"DarkGreen\"><b>[ ژَ ]</font></b> (اِ) زنجار. زنگار. زنگ . ژنگ . زنگی که در فلزات از اثر رطوبت و غیره پیدا شود. بعض فرهنگها ژنگار یا زنگار را بخصوص به رنگ سبز که بر فلز نشیند اطلاق کرده اند <span class=\"hlight\">:</span> <br />بشستن بدین بِه و آب پاک <br />وز او دور شد گرد و ژنگار و خاک .<br /> <font color=\"Red\">فردوسی .</font><br />«هرگاه که صیقل بر آنجای نهی و صیقل زنی البته آن ژنگار از وی زائل گرداند... لاجرم سزای آن را ژنگار طبع و ختم بر آنجا نهاد». (کتاب المعارف ).<br /></font></div>'),
(288246, 'ژنگارزده', '<span class=\"hlight\">ژنگارزده .</span> <font color=\"DarkGreen\"><b>[ ژَ زَ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف مرکب ) زنگارخورده . ژنگارگرفته . ژنگ زده . ژنگ بسته . زنگ خورده . ژنگ خورده . زنگ زده . زنگ گرفته .<br /></font></div>'),
(288247, 'ژنگاری', '<span class=\"hlight\">ژنگاری .</span> <font color=\"DarkGreen\"><b>[ ژَ ]</font></b> (ص نسبی ) زنگاری . برنگ زنگار. زنگ زده .<br /></font></div>'),
(288248, 'ژنگدان', '<span class=\"hlight\">ژنگدان .</span> <font color=\"DarkGreen\"><b>[ ژَ ]</font></b> (اِ) زنگدان . زنگ . زنگله . جلاجل . ژنگدن . (برهان ). زنگوله . زنگهای کوچک اطراف دورویه .<br /></font></div>'),
(288249, 'ژنگدن', '<span class=\"hlight\">ژنگدن .</span> <font color=\"DarkGreen\"><b>[ ژَ دَ ]</font></b> (اِ) ژنگدان . رجوع به ژنگدان شود.<br /></font></div>'),
(288250, 'ژنگله', '<span class=\"hlight\">ژنگله .</span> <font color=\"DarkGreen\"><b>[ ژَ گ ُ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ل ِ ]</font></b> (اِ) سُمی که شکافته باشد همچون سُم آهو و گاو و گوسفند و امثال آن . (برهان ). ظِلف . (مهذب الاسماء). زنگله . کفشک . (التفهیم ).<br /></font></div>'),
(288251, 'ژنگلیچه', '<span class=\"hlight\">ژنگلیچه .</span> <font color=\"DarkGreen\"><b>[ ژَ گ ُ چ َ <span class=\"hlight\" dir=\"rtl\">/</span> چ ِ ]</font></b> (اِ مصغر) نوعی از جلاجل که دهانش فراخ باشد. (آنندراج ). زنگوله ٔ دهان گشاده .<br /></font></div>'),
(288252, 'ژنگه', '<span class=\"hlight\">ژنگه .</span> <font color=\"DarkGreen\"><b>[ ژَ گ َ <span class=\"hlight\" dir=\"rtl\">/</span> گ ِ ]</font></b> (اِ) آفتی که به غله رسد و آن چنان باشد که خوشه ٔ غله از دانه خالی گردد و زرد شود. (برهان ). زنگ .<br /></font></div>'),
(288253, 'ژنگوی', '<span class=\"hlight\">ژنگوی .</span> <font color=\"DarkGreen\"><b>[ ژَ ]</font></b> (اِخ ) نام یکی از بزرگان چین <span class=\"hlight\">:</span> <br />به چین اندرون بودحسنوی نام <br />دگر سرکشی بود ژنگوی نام .<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(288254, 'ژنی', '<span class=\"hlight\">ژنی .</span> <font color=\"DarkGreen\"><b>[ ژِ ]</font></b> (فرانسوی، ص ) داهیه . نابغه . داهی .<br /></font></div>'),
(288255, 'ژنی دزار', '<span class=\"hlight\">ژنی دزار.</span> <font color=\"DarkGreen\"><b>[ ژِ دِ ]</font></b> (اِخ ) (لو...) نام حجاری خفته رسته ای از آنتونن مِرسیه که اینک در موزه ٔ لوور است .<br /></font></div>'),
(288256, 'ژنیان', '<span class=\"hlight\">ژنیان .</span> <font color=\"DarkGreen\"><b>[ ژِ ]</font></b> (اِخ ) (خانه ٔ... یا خان ...) نام منزلی و دهی است نزدیک به شیراز. (آنندراج ) (انجمن آرا).<br /></font></div>'),
(288257, 'ژنیان', '<span class=\"hlight\">ژنیان .</span> <font color=\"DarkGreen\"><b>[ ژِن ْ ]</font></b> (اِ) نانخواه و آن تخمی باشد که بر روی خمیر نان ریزند. (برهان ). همان زنیان است به زای تازی که نانخواه باشد. (آنندراج ).<br /></font></div>'),
(288258, 'ژنیوس', '<span class=\"hlight\">ژنیوس .</span> <font color=\"DarkGreen\"><b>[ ژِ ]</font></b> (اِخ ) نام یکی از خدایان شهر ازمیرنا. رجوع به ازمیرنا شود. (ترجمه ٔ تمدن قدیم فوستل دُکولانژ ص <span class=\"hlight\" dir=\"rtl\">٤٨١</span>).<br /></font></div>'),
(288259, 'ژه', '<span class=\"hlight\">ژه .</span> <font color=\"DarkGreen\"><b>[ ژَ ]</font></b> (اِخ ) ظاهراً نام شکارگاه و جایگاهی بوده است در نزدیکی غزنین که بدانجای به نخجیر رفتندی <span class=\"hlight\">:</span> امیر گفت ما به شکار ژه خواهیم رفت و روزی بیست کار گیرد. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٢٦٠</span>). پس از نماز سوی ژه رفت به شکار با عدتی و آلتی تمام و خواجه ٔ بزرگ و عارض و صاحب دیوان رسالت به غزنین ماندند. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٢٦٠</span>). امیر از شکار ژه به باغ صدهزار بازآمد. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٢٦٣</span>). شانزدهم شعبان امیر رضی اﷲ عنه به شکار ژه رفت و پیش یک هفته کسان رفته بودند فرازآوردن حشر را از بهر نخجیر و شکاری سخت نیکو رفت و امیر به باغ محمودی بازآمد. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٤١٨</span>). پنجم شوال امیر به شکار ژه رفت با خاصگان لشکر و ندیمان و مطربان . (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٥٠٩</span>).<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(288260, 'ژه', '<span class=\"hlight\">ژه .</span> <font color=\"DarkGreen\"><b>[ ژَ <span class=\"hlight\" dir=\"rtl\">/</span> ژِ ]</font></b> (پسوند) علامت تصغیر است مانند چه و «زه » در: نایژه، و دریاژه <span class=\"hlight\">:</span> هفتم دریاژه کاندر حد سروشنه است که از چهار رود پیوندد که از بتمان گشاید اندر میان کوههاست از او رودی بگشاید که آب سمرقند و بخارا و سغد از آنجاست مقدار چهار فرسنگ اندر چهار فرسنگ . (حدود العالم ص <span class=\"hlight\" dir=\"rtl\">١١</span>).<br /></font></div>'),
(288261, 'ژه هو', '<span class=\"hlight\">ژه هو.</span> <font color=\"DarkGreen\"><b>[ ژِ ]</font></b> (اِخ ) نام ایالتی از ایالات چین به مساحت صد و نود و سه هزار کیلومتر مربع، دارای سه ملیون و پنجاه و پنج هزار تن سکنه . کرسی آن چن ده است .<br /></font></div>'),
(288262, 'ژهان سن', '<span class=\"hlight\">ژهان سن .</span> <font color=\"DarkGreen\"><b>[ ژُ س ِ ]</font></b> (اِخ ) نام یکی از خاورشناسان . وی ناشر قسمتی از آثار نویسندگان اسلامی است و کتاب «بغیة المستفید» ابن ربیع شیبانی را که در احوال بنی طاهر و غیره تألیف شده به چاپ رسانیده و این نسخه را با مقدمه و تعلیقات از نسخه ٔخطی ناقص کتابخانه ٔ کپنهاگ به لاتین نقل کرده است .<br /></font></div>'),
(288263, 'ژهانسبورگ', '<span class=\"hlight\">ژهانسبورگ .</span> <font color=\"DarkGreen\"><b>[ ژُ ن ِ ]</font></b> (اِخ ) نام شهری در افریقای جنوبی، دارای <span class=\"hlight\" dir=\"rtl\">٣١٠٠٠٠</span> تن سکنه .<br /></font></div>'),
(288264, 'ژهانو', '<span class=\"hlight\">ژهانو.</span> <font color=\"DarkGreen\"><b>[ ژُ ن ُ ]</font></b> (اِخ ) آلفرد. نام نقاش فرانسوی، متولد در اُفن باخ (هس ) بسال <span class=\"hlight\" dir=\"rtl\">١٨٠٠</span> و متوفی بسال <span class=\"hlight\" dir=\"rtl\">١٨٣٧</span> م .<br /></font></div>'),
(288265, 'ژهانو', '<span class=\"hlight\">ژهانو.</span> <font color=\"DarkGreen\"><b>[ ژُ ن ُ ]</font></b> (اِخ ) تونی . برادر آلفرد، متولد در افن باخ . او نیز مصور بود (<span class=\"hlight\" dir=\"rtl\">١٨٠٣</span> - <span class=\"hlight\" dir=\"rtl\">١٨٥٢</span> م .).<br /></font></div>'),
(288266, 'ژهو', '<span class=\"hlight\">ژهو.</span><font color=\"DarkGreen\"><b>[ ژِ ]</font></b> (اِخ ) (کمپانیی دو) نام گروهی از آدمکشان سلطنت طلب . اینان بعد از نُهم ترمیدور از دسته ٔ مخالف خود جمهوری خواهان با کمال شقاوت انتقام میکشیدند.<br /></font></div>'),
(288267, 'ژهو', '<span class=\"hlight\">ژهو.</span> <font color=\"DarkGreen\"><b>[ ژِ ]</font></b> (اِخ ) نام پادشاهی از بنی اسرائیل از <span class=\"hlight\" dir=\"rtl\">٨٦٤</span> تا <span class=\"hlight\" dir=\"rtl\">٨١٩</span> ق .م .<br /></font></div>'),
(288268, 'ژو', '<span class=\"hlight\">ژو.</span> <font color=\"DarkGreen\"><b>[ ژُوْ ]</font></b> (اِخ ) پُل . نام مورخ ایتالیائی . مولد کُم (<span class=\"hlight\" dir=\"rtl\">١٤٨٣</span>-<span class=\"hlight\" dir=\"rtl\">١٥٥٢</span> م .).<br /></font></div>'),
(288269, 'ژو', '<span class=\"hlight\">ژو.</span> (اِخ ) نام قلعه ٔ دوب در مرز فرانسه و سویس در چهارکیلومتری پونتارلیه .<br /></font></div>'),
(288270, 'ژو', '<span class=\"hlight\">ژو.</span> <font color=\"DarkGreen\"><b>[ ژَ <span class=\"hlight\" dir=\"rtl\">/</span>ژُو ]</font></b> (اِ) دریا بود. (لغت نامه ٔ اسدی ) <span class=\"hlight\">:</span> <br />مرد ملاح تیز اندک رو <br />راند بر باد کشتی اندر ژو.<br /><font color=\"Red\">عنصری .</font><br /></font></div>'),
(288271, 'ژوآن', '<span class=\"hlight\">ژوآن .</span> (اِخ ) نام خلیجی در جنوب غربی ایالت آلپ ماری تیم . ناپلئون اول در بازگشت خود از جزیره ٔ اِلب در این خلیج از کشتی پیاده شد.<br /></font></div>'),
(288272, 'ژوآن دتریش', '<span class=\"hlight\">ژوآن دتریش .</span> <font color=\"DarkGreen\"><b>[ دُ ]</font></b> (اِخ ) نام پسر غیرقانونی فیلیپ چهارم پادشاه اسپانی، متولد در مادرید بسال <span class=\"hlight\" dir=\"rtl\">١٦٢٩</span> و متوفی بسال <span class=\"hlight\" dir=\"rtl\">١٦٧٩</span> م . وی وزیر شارل دوم بود.<br /></font></div>'),
(288273, 'ژوآن دتریش', '<span class=\"hlight\">ژوآن دتریش .</span> <font color=\"DarkGreen\"><b>[ دُ ]</font></b> (اِخ ) نام پسر صلبی شارل کن متولد در راتیسبن و متوفی به نامور (<span class=\"hlight\" dir=\"rtl\">١٥٤٧</span>-<span class=\"hlight\" dir=\"rtl\">١٥٧٨</span> م .). وی حاکم هلند بود.<br /></font></div>'),
(288274, 'ژوآن فرنانده', '<span class=\"hlight\">ژوآن فرنانده .</span> <font color=\"DarkGreen\"><b>[ ف ِدِ ]</font></b> (اِخ ) نام جزیره ای در اقیانوس کبیر در مغرب شیلی، دارای <span class=\"hlight\" dir=\"rtl\">٣٠٠</span> تن سکنه .<br /></font></div>'),
(288275, 'ژوآن له پن', '<span class=\"hlight\">ژوآن له پن .</span> <font color=\"DarkGreen\"><b>[ ل ِ پ َ ]</font></b> (اِخ ) نام محلی از آلپهای ماری تیم (واقع در کمون آنتیب )، دارای راه آهن و یکهزار تن سکنه .<br /></font></div>'),
(288276, 'ژوآن ژوآن', '<span class=\"hlight\">ژوآن ژوآن .</span> (اِخ ) نام طایفه ای از ترکان آسیای مرکزی در قرن ششم هجری . (دیوان رودکی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٧٩</span>).<br /></font></div>'),
(288277, 'ژوآنویل', '<span class=\"hlight\">ژوآنویل .</span> <font color=\"DarkGreen\"><b>[ آن ْ ]</font></b> (اِخ ) فرانسوا دوک دُرلئان پرنس دو. نام ملاح فرانسوی و سومین پسر لوئی فیلیپ پادشاه فرانسه . متولد در نویی بسال <span class=\"hlight\" dir=\"rtl\">١٨١٨</span> و متوفی در پاریس بسال <span class=\"hlight\" dir=\"rtl\">١٩٠٠</span> م .<br /></font></div>'),
(288278, 'ژوآنویل', '<span class=\"hlight\">ژوآنویل .</span> <font color=\"DarkGreen\"><b>[ آن ْ ]</font></b> (اِخ ) ژان دو. نام مورّخ فرانسوی و مشاور سن لوئی . متولد در ژوآنویل (هت مارن ) بسال <span class=\"hlight\" dir=\"rtl\">١٢٢٤</span> و متوفی بسال <span class=\"hlight\" dir=\"rtl\">١٣١٧</span> م . نوشته های او راجع به تاریخ زندگی سن لوئی و جنگهای صلیبی از مدارک و منابع گرانبها بشمار میرود.<br /></font></div>'),
(288279, 'ژوآنویل', '<span class=\"hlight\">ژوآنویل .</span> <font color=\"DarkGreen\"><b>[ آن ْ ]</font></b> (اِخ ) نام کرسی بخش هُت -مارن، دارای <span class=\"hlight\" dir=\"rtl\">٣٦٦٢</span> تن سکنه .<br /></font></div>'),
(288280, 'ژوآنویل لوپن', '<span class=\"hlight\">ژوآنویل لوپن .</span> <font color=\"DarkGreen\"><b>[ آن ْ ل ُ پ ُ ]</font></b> (اِخ ) نام کمونی از ایالت «سِن » ولایت سو، کنار رود لامارن، دارای <span class=\"hlight\" dir=\"rtl\">١٣٤٢٥</span> تن سکنه .<br /></font></div>'),
(288281, 'ژوآنیی', '<span class=\"hlight\">ژوآنیی .</span> <font color=\"DarkGreen\"><b>[ آن ْ ]</font></b> (اِخ ) نام کرسی بخش یُن، واقع در <span class=\"hlight\" dir=\"rtl\">٢٥</span>کیلومتری شمال غربی اُکسر، دارای راه آهن و <span class=\"hlight\" dir=\"rtl\">٦٦٧١</span> تن سکنه .<br /></font></div>'),
(288282, 'ژوارز', '<span class=\"hlight\">ژوارز.</span> <font color=\"DarkGreen\"><b>[ رِ ]</font></b> (اِخ ) بِنیتو. نام رئیس جمهور مکزیک . مولد سان پابلوگلاتائو در سال <span class=\"hlight\" dir=\"rtl\">١٨٠٦</span> و وفات به مکزیکو در سال <span class=\"hlight\" dir=\"rtl\">١٨٧٢</span> م .<br /></font></div>'),
(288283, 'ژواغار', '<span class=\"hlight\">ژواغار.</span> <font color=\"DarkGreen\"><b>[ ژَ ]</font></b> (اِخ ) نام مُغی است . (لغت نامه ٔ اسدی ). نام مغی می فروش است . نام یکی از بت پرستان بوده است . (برهان ) <span class=\"hlight\">:</span> <br />گفتا که یکی مشکی است نی مشک تبتی <br />کاین مشک حشونقبی است از خم ژواغار .<br /> <font color=\"Red\">ابوالعباس .</font><br />رجوع به خشوفغن شود. و اینکه بعض لغت نامه ها و شمس فخری کلمه را معنی مطلق مغ و غیره داده اند غلط است <span class=\"hlight\">:</span><br />ز یُمن اهتمام او در اسلام <br />عجب نبودز ایمان ژواغار.<br /><font color=\"Red\">شمس فخری (از جهانگیری ).</font><br /></font></div>'),
(288284, 'ژواله', '<span class=\"hlight\">ژواله .</span> <font color=\"DarkGreen\"><b>[ ژَ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ل ِ ]</font></b> (اِ) گلوله . مهره . غالوک . زواله . رجوع به زواله شود.<br /></font></div>'),
(288285, 'ژواه', '<span class=\"hlight\">ژواه .</span> <font color=\"DarkGreen\"><b>[ ژِ ]</font></b> (اِ) زواه . رجوع به زواه شود.<br /></font></div>'),
(288286, 'ژوایوز', '<span class=\"hlight\">ژوایوز.</span> <font color=\"DarkGreen\"><b>[ یُزْ ]</font></b> (اِخ ) هانری دو. نام مارشال فرانسوی . برادر ژوایوز (آن دوک دو) (<span class=\"hlight\" dir=\"rtl\">١٥٦٧</span>-<span class=\"hlight\" dir=\"rtl\">١٦٠٨</span> م .).<br /></font></div>'),
(288287, 'ژوایوز', '<span class=\"hlight\">ژوایوز.</span> <font color=\"DarkGreen\"><b>[ یُزْ ]</font></b> (اِخ ) فرانسوا دو. نام کاردینال فرانسوی . برادر ژوایوز (آن دوک دو) (<span class=\"hlight\" dir=\"rtl\">١٥٦٢</span>-<span class=\"hlight\" dir=\"rtl\">١٦١٥</span> م .).<br /></font></div>'),
(288288, 'ژوایوز', '<span class=\"hlight\">ژوایوز.</span> <font color=\"DarkGreen\"><b>[ یُزْ ]</font></b> (اِخ ) آن دوک دو. نام ندیم هانری سوم و دریاسالار فرانسه . متولد بسال <span class=\"hlight\" dir=\"rtl\">١٥٦١</span> و مقتول در جنگ کوترا بسال <span class=\"hlight\" dir=\"rtl\">١٥٨٧</span> م .<br /></font></div>'),
(288289, 'ژوبای اول', '<span class=\"hlight\">ژوبای اول .</span><font color=\"DarkGreen\"><b>[ ی ِ اَوْ وَ ]</font></b> (اِخ ) نام پادشاه نومیدی از قسمت پمپه . متوفی بسال <span class=\"hlight\" dir=\"rtl\">٤٢</span> ق .م .<br /></font></div>'),
(288290, 'ژوبای دوم', '<span class=\"hlight\">ژوبای دوم .</span> <font color=\"DarkGreen\"><b>[ ی ِ دُوْ وُ ]</font></b> (اِخ )نام پسر ژوبای اول و پادشاه مریتانی . متوفی بسال <span class=\"hlight\" dir=\"rtl\">١٨</span>م . وی را بزبان یونانی تصانیفی در باب تاریخ است .<br /></font></div>'),
(288291, 'ژوبر', '<span class=\"hlight\">ژوبر.</span> <font color=\"DarkGreen\"><b>[ب ِ ]</font></b> (اِخ ) ژُزف . نام دانشمند علم الاخلاق فرانسوی . متولد در مُن ْتینیاک بسال <span class=\"hlight\" dir=\"rtl\">١٧٥٤</span> و متوفی بسال <span class=\"hlight\" dir=\"rtl\">١٨٢٤</span> م .<br /></font></div>'),
(288292, 'ژوبر', '<span class=\"hlight\">ژوبر.</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) پیتروس ژاکوبوس . نام ژنرالی از مردم ترانسواآلی . متولد در کانگو (ناتال ) بسال <span class=\"hlight\" dir=\"rtl\">١٨٣١</span> و متوفی بسال <span class=\"hlight\" dir=\"rtl\">١٩٠٠</span> م . وی بواسطه ٔ جنگهای <span class=\"hlight\" dir=\"rtl\">١٨٨١</span> و <span class=\"hlight\" dir=\"rtl\">١٨٩٩</span> خود علیه انگلیس مشهور است .<br /></font></div>'),
(288293, 'ژوبر', '<span class=\"hlight\">ژوبر.</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) بارتلمی . نام ژنرال فرانسوی متولد به پُن -دُ-وُ مقتول در جنگ نُوی (<span class=\"hlight\" dir=\"rtl\">١٧٦٩</span> - <span class=\"hlight\" dir=\"rtl\">١٧٩٩</span> م .).<br /></font></div>'),
(288294, 'ژوبین', '<span class=\"hlight\">ژوبین .</span> (اِ) زوبین . ژوپین . رجوع به هر دو کلمه شود.<br /></font></div>'),
(288295, 'ژوبین زن', '<span class=\"hlight\">ژوبین زن .</span> <font color=\"DarkGreen\"><b>[ زَ ]</font></b> (نف مرکب ) رجوع به ژوپین زن شود.<br /></font></div>'),
(288296, 'ژوبین ور', '<span class=\"hlight\">ژوبین ور.</span> <font color=\"DarkGreen\"><b>[ وَ ]</font></b> (ص مرکب ) رجوع به ژوپین وَر شود.<br /></font></div>'),
(288297, 'ژوبین کش', '<span class=\"hlight\">ژوبین کش .</span> <font color=\"DarkGreen\"><b>[ ک َ <span class=\"hlight\" dir=\"rtl\">/</span> ک ِ ]</font></b> (نف مرکب ) رجوع به ژوپین کش شود.<br /></font></div>'),
(288298, 'ژوتلند', '<span class=\"hlight\">ژوتلند.</span> <font color=\"DarkGreen\"><b>[ ل َ ]</font></b> (اِخ ) نام جزیره ای از جزایر دانمارک در شمال شلسویک، دارای <span class=\"hlight\" dir=\"rtl\">١٥٠٠٠٠٠</span> تن سکنه . ویبورگ، آالبورگ، آارهوس، راندرس، هورسنس از شهرهای آن است .<br /></font></div>'),
(288299, 'ژوتورن', '<span class=\"hlight\">ژوتورن .</span> (اِخ ) نام الهه ٔ رومی نگهبان آبها و معشوقه ٔ ژوپیتر. چشمه ای در کنار فروم (رُم ) بنام او خوانده شده است .<br /></font></div>'),
(288300, 'ژوده', '<span class=\"hlight\">ژوده .</span> <font color=\"DarkGreen\"><b>[ دِ ]</font></b> (اِخ ) نام ناحیتی از فلسطین . رجوع به یهودیه شود.<br /></font></div>'),
(288301, 'ژودیت دباویر', '<span class=\"hlight\">ژودیت دباویر.</span> <font color=\"DarkGreen\"><b>[ دُ ی ِ ]</font></b> (اِخ ) نام دومین زن لوئی لودِبُنِر و مادر شارل لوشوْ وفات در تور بسال <span class=\"hlight\" dir=\"rtl\">٨٤٣</span> م .<br /></font></div>'),
(288302, 'ژودیک', '<span class=\"hlight\">ژودیک .</span> (اِخ ) آنّا. نام زنی از هنرپیشگان فرانسه و بازیگر اُپرِت . مولد سومور بسال <span class=\"hlight\" dir=\"rtl\">١٨٥٠</span> و وفات بسال <span class=\"hlight\" dir=\"rtl\">١٩١١</span> م .<br /></font></div>'),
(288303, 'ژورا', '<span class=\"hlight\">ژورا.</span> (اِخ ) نام سلسله ٔ جبالی بین فرانسه و سویس بطول <span class=\"hlight\" dir=\"rtl\">٣٠٠</span> کیلومتر.<br /></font></div>'),
(288304, 'ژورا', '<span class=\"hlight\">ژورا.</span> (اِخ ) نام یکی از ایالات فرانسه، دارای سه ولایت و <span class=\"hlight\" dir=\"rtl\">٣٢</span> بخش و <span class=\"hlight\" dir=\"rtl\">٥٨٥</span> دهستان و <span class=\"hlight\" dir=\"rtl\">٢٢٠٨٠٠</span> تن سکنه .<br /></font></div>'),
(288305, 'ژورا', '<span class=\"hlight\">ژورا.</span> <font color=\"DarkGreen\"><b>[ ژُ ]</font></b> (اِخ ) اتین . نام نقاش فرانسوی . مولد وِرْمانتون بسال <span class=\"hlight\" dir=\"rtl\">١٦٩٩</span> و وفات بسال <span class=\"hlight\" dir=\"rtl\">١٧٨٩</span> م .<br /></font></div>'),
(288306, 'ژورانسن', '<span class=\"hlight\">ژورانسن .</span> <font color=\"DarkGreen\"><b>[ س ُ ]</font></b> (اِخ ) نام کُمونی در پیرنه ٔ سفلی ازشهرستان پو، دارای <span class=\"hlight\" dir=\"rtl\">٤٠٢٩</span> تن سکنه و شراب های معروف .<br /></font></div>'),
(288307, 'ژوردان', '<span class=\"hlight\">ژوردان .</span> (اِخ ) ژان باتیست . نام مارشال فرانسوی، فاتح فلوروس بسال <span class=\"hlight\" dir=\"rtl\">١٧٩٤</span> م . متولد در لیموژ بسال <span class=\"hlight\" dir=\"rtl\">١٧٦٢</span> و متوفی در پاریس بسال <span class=\"hlight\" dir=\"rtl\">١٨٣٣</span> م .<br /></font></div>'),
(288308, 'ژوردان', '<span class=\"hlight\">ژوردان .</span> (اِخ ) نام مترجم یکی از نمایشنامه های فارسی و شرح آن چنین است که : در <span class=\"hlight\" dir=\"rtl\">١٢٩١</span> هَ . ق .<span class=\"hlight\" dir=\"rtl\">/</span> <span class=\"hlight\" dir=\"rtl\">١٨٧٤</span> م . در تهران هفت بازی فارسی در یک مجلد چاپ سنگی شد و با یک مقدمه در فوائد تعلیمی نمایش بقلم میرزا جعفر قراچه داغی انتشار یافت . این بازیها را میرزا فتحعلی دربندی بدواً به ترکی آذربایجانی نوشته ودر حدود سال <span class=\"hlight\" dir=\"rtl\">١٨٦١</span> م . در تفلیس چاپ کرده بود. پنج فقره از این نمایشها را با حواشی و ترجمه و نت های بسیار مجدداً در اروپا به طبع رسانیدند. (یکی از این فقرات را) مسیو ژوردان با ترجمه و نُت و غیره (ناشر، ا.وارموند، وین -لیپزیک <span class=\"hlight\" dir=\"rtl\">١٨٨٩</span>) ترجمه کرد و منتشر ساخت .(تاریخ ادبیات ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span> ترجمه ٔ رشید یاسمی ص <span class=\"hlight\" dir=\"rtl\">٣١٠</span>).<br /></font></div>'),
(288309, 'ژوردان', '<span class=\"hlight\">ژوردان .</span> (اِخ ) ماتیو ژوو. نام یکی از قسی ترین تروریست های پرونس . متولد در سن ژوست بسال <span class=\"hlight\" dir=\"rtl\">١٧٤٩</span> م . وی بسال <span class=\"hlight\" dir=\"rtl\">١٧٩٤</span> در پاریس به دار آویخته شد. او را «ژوردان کوپ تِت » نیز گویند.<br /></font></div>'),
(288310, 'ژوردن', '<span class=\"hlight\">ژوردن .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (اِخ ) شارل بِرشیله . نام فیلسوف فرانسوی متولد در پاریس بسال <span class=\"hlight\" dir=\"rtl\">١٨١٧</span> و متوفی بسال <span class=\"hlight\" dir=\"rtl\">١٨٨٦</span> م .<br /></font></div>'),
(288311, 'ژورنال', '<span class=\"hlight\">ژورنال .</span> (فرانسوی، اِ) روزنامه و در زبان فارسی غالباً به مجلاتی که در آن صور متنوع و اشکال مختلف البسه رسم شده و در خیاطی بکار است اطلاق می شود.<br /></font></div>'),
(288312, 'ژورک', '<span class=\"hlight\">ژورک .</span> <font color=\"DarkGreen\"><b>[ ژَ <span class=\"hlight\" dir=\"rtl\">/</span> ژُورَ ]</font></b> (اِ) پرنده ای است سرخ رنگ به بزرگی گنجشک و بعضی گویند پرنده ای است که سر و گردن او سرخ میباشد و او را سرخاب گویند. (برهان ). پرنده ای است سرخ فام به مقدار گنجشکی . (جهانگیری ). ژولک . سُرخاب <span class=\"hlight\">:</span> <br />شارک چو مؤذن به سحر حلق گشوده <br />وان ژورک و آن صعوه از آن داده اذان را.<br /> <font color=\"Red\">سنائی (از آنندراج ).</font><br />رجوع به ژوژک شود.<br /></font></div>'),
(288313, 'ژوری شامبرتن', '<span class=\"hlight\">ژوری شامبرتن .</span> <font color=\"DarkGreen\"><b>[ ژِوْ ب ِ ت َ ]</font></b> (اِخ ) نام کرسی بخش در ایالت «کت دُر» از ولایت دیژُن واقع در دامنه ٔ کت دُر، دارای راه آهن و <span class=\"hlight\" dir=\"rtl\">١٥١٨</span> تن سکنه و شرابهای مشهور.<br /></font></div>'),
(288314, 'ژورین دلاگراویر', '<span class=\"hlight\">ژورین دلاگراویر.</span> <font color=\"DarkGreen\"><b>[ ی َ دُ ی ِ ]</font></b> (اِخ ) ژان پیر اِدمُن . نام ملاح و نویسنده ٔ فرانسوی متولد در برست بسال <span class=\"hlight\" dir=\"rtl\">١٨١٢</span> و متوفی در پاریس بسال <span class=\"hlight\" dir=\"rtl\">١٨٩٢</span> م . وی را تألیفاتی مشهور در تاریخ و فن بحرپیمائی است .<br /></font></div>'),
(288315, 'ژوریو', '<span class=\"hlight\">ژوریو.</span> <font color=\"DarkGreen\"><b>[ ی ُ ]</font></b> (اِخ ) پیر. نام عالم کلامی پرتستانی از مردم فرانسه متولددر مِر بسال <span class=\"hlight\" dir=\"rtl\">١٦٣٧</span> و متوفی در رتردام بسال <span class=\"hlight\" dir=\"rtl\">١٧١٣</span> م .<br /></font></div>'),
(288316, 'ژوزنکور', '<span class=\"hlight\">ژوزنکور.</span> <font color=\"DarkGreen\"><b>[ زِ ن ِ ]</font></b> (اِخ ) نام کرسی بخش در ایالت هت -مارْن از ولایت شُمُن، دارای <span class=\"hlight\" dir=\"rtl\">٢١٩</span> تن سکنه .<br /></font></div>'),
(288317, 'ژوست', '<span class=\"hlight\">ژوست .</span> (اِخ ) نام خانواده ٔ حجاران بومی حوالی فلورانس . آنها پس از جنگهای ایتالیا به تورن آمدند. ژان و آنتوان ژوست مشهورترین افراد آنانند که مقبره ٔ لوئی دوازدهم را در سن -دنیس حجاری کردند. آنان را لِه بتی نیز گویند.<br /></font></div>'),
(288318, 'ژوست', '<span class=\"hlight\">ژوست .</span> (اِخ ) (قدیس ) نام یکی از شهدای اسپانیا درحدود قرن چهارم میلادی . ذکران او روز ششم اوت است .<br /></font></div>'),
(288319, 'ژوستن', '<span class=\"hlight\">ژوستن .</span> <font color=\"DarkGreen\"><b>[ ت َ ]</font></b> (اِخ ) (قدیس ) نام نویسنده ٔ رساله ٔ دفاع از دین مسیحی . وی بسال <span class=\"hlight\" dir=\"rtl\">١٦٥</span> م . به شهادت رسید. ذکران او سیزدهم آوریل است .<br /></font></div>'),
(288320, 'ژوستن', '<span class=\"hlight\">ژوستن .</span> <font color=\"DarkGreen\"><b>[ ت َ ]</font></b> (اِخ ) نام مورخ لاتینی در قرن دوم میلادی . زمان زندگانی این مورخ درست معلوم نیست و تصور میکنند که در زمان آنتونن ها بخصوص آنتونن لوپیو (مقدس ) زندگانی میکرده است (یعنی تقریباً بین <span class=\"hlight\" dir=\"rtl\">١٣٨</span> و <span class=\"hlight\" dir=\"rtl\">١٦١</span> م .). با وجود این راجع به زمان او بعضی تا قرن چهارم میلادی . پائین می آیند. اسم او هم درست معلوم نیست ولی غالباً او را به زبان لاطین یوستی نوس می نامند. ژوستن در واقع مورخ مستقلی نیست . وی کتابهای تروگ پمپه (رجوع به این نام شود) را خلاصه کرده و چیزی از خود بر آن نیفزوده است . تروگ پمپه تاریخی در باب عالم نوشته بوده که <span class=\"hlight\" dir=\"rtl\">٤٤</span> کتاب از آن گم شده است و فقط از خلاصه های ژوستن معلوم میشودکه تروگ پمپه از ادوار گذشته ٔ کدام ملل یاد کرده است . بنابراین از فهرست ژوستن نه فقط بطور خلاصه به نوشته های تروگ پمپه پی می بریم بلکه درمی یابیم که مورخ مزبور از کدام یک از مورخین قدیم استفاده کرده است . باید دانست که نویسندگان قرون بعد درباره ٔ خلاصه کنندگان خوشبین نبوده اند زیرا عقیده داشتند که آنان پس از خلاصه کردن کتابها اصل کتب را معدوم میکردند. این تهمت را هم بعضی به ژوستن زده و گفته اند که وی اصل کتاب تروگ پمپه را در آتش انداخته و سوخته است . ولی چنین بنظر می آید که ژوستن چنین اتهامی را پیش بینی کرده بوده است زیرا در مقدمه و چند جای کتاب خود از تروگ پمپه و کتب او سخن میراند. مثلاً در مقدمه گوید: «چنانکه بعض رومیان تاریخ روم را به زبان یونانی نوشته اند تروگ پمپه میخواست که تاریخ یونان و سایر ملل را به زبان لاطین بنویسد... و من کتابهای او را گلچین کرده دسته ٔ گلی ترتیب داده ام ...». اختلافاتی که در نوشته های ژوستن و سایر مورخین راجع به وقایع زمان اسکندر دیده میشود از تروگ پمپه است و نیز این نکته که ژوستن افسانه ها را حقایقی دانسته نیز از مورخ مذکور ناشی شده است . کلیه ٔ ترتیب نوشته های ژوستن و نقائص آن از کتب اصل است، از جمله اینکه بعض وقایع مهم را به سکوت گذرانیده و حال آنکه از مطالبی که چندان اهمیت نداشته مشروحاً سخن رانده است . اسلوب انشاء ژوستن را رویهمرفته بد نمیدانند و بعض جاها نیز عالی است، گرچه نمیتوان دانست که این طرز انشاء از خود اوست یا از تروگ پمپه اقتباس شده است . در خاتمه باید گفت که هرچند نوشته های ژوستن سواد مختصری است از کتب تروگ پمپه با وجود آن سواد مزبور با نقائصی که دارد سواد پرده ٔ نقاشی بزرگی است . عده ٔ کتابهای ژوستن به عده ٔ کتابهای تروگ پمپه <span class=\"hlight\" dir=\"rtl\">٤٤</span> کتاب است . و جایهای بسیاری از کتب او با تاریخ ایران قدیم ارتباط دارد. (ایران باستان ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٨٧</span>).<br /></font></div>'),
(288321, 'ژوستن اول', '<span class=\"hlight\">ژوستن اول .</span> <font color=\"DarkGreen\"><b>[ ت َ ن ِ اَوْ وَ ]</font></b> (اِخ ) نام امپراطور روم شرقی از <span class=\"hlight\" dir=\"rtl\">٥١٨</span> تا <span class=\"hlight\" dir=\"rtl\">٥٢٧</span> م . وی عموی ژوستی نین و اصلش از ایلیری است .<br /></font></div>'),
(288322, 'ژوستن دوم', '<span class=\"hlight\">ژوستن دوم .</span> <font color=\"DarkGreen\"><b>[ ت َ ن ِ دُوْ وُ ]</font></b> (اِخ ) نام امپراطور روم شرقی از <span class=\"hlight\" dir=\"rtl\">٥٦٥</span> تا <span class=\"hlight\" dir=\"rtl\">٥٧٨</span> م . برادرزاده و جانشین ژوستی نین .<br /></font></div>'),
(288323, 'ژوستن ماک کارتی', '<span class=\"hlight\">ژوستن ماک کارتی .</span> <font color=\"DarkGreen\"><b>[ ت َ ]</font></b> (اِخ ) نام یکی از مترجمین غزلیات حافظ.<br /></font></div>'),
(288324, 'ژوستی نیانوس', '<span class=\"hlight\">ژوستی نیانوس .</span> (اِخ ) یا ژوستی نین . نام امپراطور روم شرقی متولد در <span class=\"hlight\" dir=\"rtl\">٤٨٤</span> م . وی پس از استعفای ژوستی نوس از <span class=\"hlight\" dir=\"rtl\">٥٢٧</span> تا <span class=\"hlight\" dir=\"rtl\">٥٦٥</span> م . حکمرانی کرد و چندین بار در زمان سلطنت قباد و انوشیروان با دولت ایران بجنگید، لیکن با وجود داشتن سردار قابلی مانند بلیزاریوس هر بارشکست یافت (<span class=\"hlight\" dir=\"rtl\">٥٢٨</span> - <span class=\"hlight\" dir=\"rtl\">٥٣٢</span> م .) و مبالغی به دولت ایران غرامت جنگ پرداخت . در افریقا نیز با واندالها جنگ کردو ژلیمر شاه آنان را اسیر کرد. همچنین با استروگتهائی که ایطالیا را در تصرف داشتند به جنگ پرداخت و برایشان غالب آمد. و قسمتی از سواحل شرقی اسپانیول رانیز از ویزیگتها بگرفت . در زمان ژوستی نیانوس انتخاب کنسولها موقوف شد و قوانین قضائی روم ساده و مدوّن گشت . مجموعه ٔ قوانینی که در زمان وی جمعآوری و تدوین شده به مجموعه ٔ قوانین ژوستی نیانوس معروف است . ابنیه ٔ عظیم و رفیعی در روم از جمله سنت سوفی در قسطنطنیه منسوب به اوست . (تمدن قدیم فوستل دوکولانژ ص <span class=\"hlight\" dir=\"rtl\">٤٨١</span>).<br /></font></div>'),
(288325, 'ژوستی نین اول', '<span class=\"hlight\">ژوستی نین اول .</span> <font color=\"DarkGreen\"><b>[نی َ ن ِ اَوْ وَ ]</font></b> (اِخ ) رجوع به ژوستی نیانوس شود.<br /></font></div>'),
(288326, 'ژوستی نین دوم', '<span class=\"hlight\">ژوستی نین دوم .</span> <font color=\"DarkGreen\"><b>[ نی َ ن ِ دُوْ وُ ]</font></b> (اِخ ) نام امپراطور روم شرقی . وی در سال <span class=\"hlight\" dir=\"rtl\">٦٨٥</span> م . به تخت نشست ودر سال <span class=\"hlight\" dir=\"rtl\">٦٩٥</span> به دست لئونس از سلطنت خلع و بسال <span class=\"hlight\" dir=\"rtl\">٧٠٥</span> دوباره پادشاه شد و سرانجام در <span class=\"hlight\" dir=\"rtl\">٧١١</span> م . به قتل رسید.<br /></font></div>'),
(288327, 'ژوستین', '<span class=\"hlight\">ژوستین .</span> (اِخ ) نام قدیسه ای متولد در انطاکیه . وی در حدود سال <span class=\"hlight\" dir=\"rtl\">٣٠٤</span> م . در نیکومدی به شهادت رسید. ذکران او هفتم اُکتبر است .<br /></font></div>'),
(288328, 'ژوستین', '<span class=\"hlight\">ژوستین .</span> (اِخ ) نام قدیسه ای از مردم پارو. وی در زمان دیوکلسین بسال <span class=\"hlight\" dir=\"rtl\">٣٠٤</span> م . به شهادت رسید. ذکران او بیست وششم سپتامبر است .<br /></font></div>'),
(288329, 'ژوستین', '<span class=\"hlight\">ژوستین .</span> (اِخ ) نام امپراطریس رومی زوجه ٔ والنتین اول، متوفی بسال <span class=\"hlight\" dir=\"rtl\">٣٨٨</span> م .<br /></font></div>'),
(288330, 'ژوسه', '<span class=\"hlight\">ژوسه .</span> <font color=\"DarkGreen\"><b>[ س ِ ]</font></b> (اِخ ) نام کرسی بخش در ایالت «هت -سائون » از ولایت وِسول، دارای راه آهن و قریب <span class=\"hlight\" dir=\"rtl\">٢٥٦٤</span> تن سکنه .<br /></font></div>'),
(288331, 'ژوسیو', '<span class=\"hlight\">ژوسیو.</span> <font color=\"DarkGreen\"><b>[ ی ُ ]</font></b> (اِخ ) آدریان . پسر آنتوان دوژوسیو، متولد در پاریس بسال <span class=\"hlight\" dir=\"rtl\">١٧٩٧</span> و متوفی بسال <span class=\"hlight\" dir=\"rtl\">١٨٥٣</span> م .<br /></font></div>'),
(288332, 'ژوسیو', '<span class=\"hlight\">ژوسیو.</span> <font color=\"DarkGreen\"><b>[ ی ُ ]</font></b> (اِخ ) آنتوان لوران . برادرزاده ٔ آنتوان دوژوسیو نیز از نبات شناسان معروف است، متولد در لیون بسال <span class=\"hlight\" dir=\"rtl\">١٧٤٨</span> و متوفی بسال <span class=\"hlight\" dir=\"rtl\">١٨٣٦</span> م .<br /></font></div>'),
(288333, 'ژوسیو', '<span class=\"hlight\">ژوسیو.</span> <font color=\"DarkGreen\"><b>[ ی ُ ]</font></b> (اِخ ) ژزف . برادر آنتوان دوژوسیو نیز از نبات شناسان فرانسه است، متولد در لیون به سال <span class=\"hlight\" dir=\"rtl\">١٧٠٤</span> و متوفی به سال <span class=\"hlight\" dir=\"rtl\">١٧٧٩</span> م .<br /></font></div>'),
(288334, 'ژوسیو', '<span class=\"hlight\">ژوسیو.</span> <font color=\"DarkGreen\"><b>[ ی ُ ]</font></b> (اِخ ) برنارد. برادر عالم مزبور نیز از نبات شناسان معروف فرانسه است، متولد در لیون و متوفی در پاریس (<span class=\"hlight\" dir=\"rtl\">١٦٩٩</span>-<span class=\"hlight\" dir=\"rtl\">١٧٧٧</span> م .).<br /></font></div>'),
(288335, 'ژوسیو', '<span class=\"hlight\">ژوسیو.</span> <font color=\"DarkGreen\"><b>[ ی ُ ]</font></b> (اِخ ) آنتوان دو. نام عالم گیاه شناس فرانسوی متولد در لیون بسال <span class=\"hlight\" dir=\"rtl\">١٦٨٦</span> و متوفی بسال <span class=\"hlight\" dir=\"rtl\">١٧٥٨</span> م .<br /></font></div>'),
(288336, 'ژوش', '<span class=\"hlight\">ژوش .</span> (اِخ ) زوش . سمعانی گوید: قریه ای از قراء بخاراست و گمان میکنم نزدیک نور باشد. (الانساب سمعانی ورق <span class=\"hlight\" dir=\"rtl\">٢٨١</span>).<br /></font></div>'),
(288337, 'ژوش', '<span class=\"hlight\">ژوش .</span> (ص ) تند و تیز و سخت و زودخشم بود <span class=\"hlight\">:</span> <br />کردمت بانگ ای مه سیمین <br />ژوش خواندم ترا که هستی ژوش .<br /> <font color=\"Red\">رودکی (از لغت نامه ٔ اوبهی ).</font><br />زوش . رجوع به زوش شود.<br /></font></div>'),
(288338, 'ژوشت', '<span class=\"hlight\">ژوشت .</span> (اِخ ) نام رُستاقی از رساتیق سیستان . «و آن (با واو مجهول ) شاید همان چشت باشدکه از نواحی زرنگ است و در تاریخ هرات و حواشی بیهقی ضبط شده است و بلاذری در فتوح البلدان آن را زوشت ضبط کرده است و گوید: از کرکویه بسوی زرنج رفت و از هندمند عبور کرد و از وادی نوق گذشته به زوشت رفت بر سه میلی زرنج . (بلاذری چ قاهره ص <span class=\"hlight\" dir=\"rtl\">٤٠١</span>). اصطخری و یاقوت آن را نیاورده اند». (از حاشیه ٔ تاریخ سیستان ص <span class=\"hlight\" dir=\"rtl\">٢٨</span>).<br /></font></div>'),
(288339, 'ژوشی', '<span class=\"hlight\">ژوشی .</span> (ص نسبی ) زوشی . منسوب به ژوش، از قراء بخارا. (سمعانی ورق <span class=\"hlight\" dir=\"rtl\">٢٨١</span>).<br /></font></div>'),
(288340, 'ژوفری', '<span class=\"hlight\">ژوفری .</span> <font color=\"DarkGreen\"><b>[ رُ ]</font></b> (اِخ ) تئودور. نام فیلسوف فرانسوی متولد در پُنتت (دوب ) بسال <span class=\"hlight\" dir=\"rtl\">١٧٩٦</span> و متوفی در پاریس بسال <span class=\"hlight\" dir=\"rtl\">١٨٤٢</span> م .<br /></font></div>'),
(288341, 'ژوفری دابانس', '<span class=\"hlight\">ژوفری دابانس .</span> <font color=\"DarkGreen\"><b>[ رُ ]</font></b> (اِخ ) کلود فرانسوا، مارکی دو. نام مخترع کشتی بخار متولد در رُش -سور-رُنیون (هُت -مارن ) بسال <span class=\"hlight\" dir=\"rtl\">١٧٥١</span> و متوفی بسال <span class=\"hlight\" dir=\"rtl\">١٨٣٢</span> م .<br /></font></div>'),
(288342, 'ژوفلورو', '<span class=\"hlight\">ژوفلورو.</span> <font color=\"DarkGreen\"><b>[ ژُف ْ ل ُ رُ ]</font></b> (اِخ ) نام آکادمی تولوز موزّع جوائز اشعار در هر سال . این آکادمی را تروبادورها در <span class=\"hlight\" dir=\"rtl\">١٣٢٣</span> م . تأسیس کردند و آن را کلژ دُلاگ ِ سیانس نامیدند و چون در آنجا به بهترین اشعاری که در لهجه ٔ لانگ دک یعنی لهجه های جنوبی فرانسه سروده میشد جوایزی از گلهای متنوع زرّین و سیمین داده میشد از اینرو بدانجا نام ژوفلورو دادند.<br /></font></div>'),
(288343, 'ژول', '<span class=\"hlight\">ژول .</span> (اِخ ) جِیمز پرِسْکُت . نام فیزیک دان انگلیسی، متولد در سالفرد (<span class=\"hlight\" dir=\"rtl\">١٨١٨</span>-<span class=\"hlight\" dir=\"rtl\">١٨٨٩</span> م .).<br /></font></div>'),
(288344, 'ژول', '<span class=\"hlight\">ژول .</span> (فرانسوی، اِ) واحد عمل الکتریکی است و آن عملی است که یک کولن با اختلاف سطح یک ولت انجام میدهد.<br /></font></div>'),
(288345, 'ژول', '<span class=\"hlight\">ژول .</span> (ص ) پریشان و درهم . (جهانگیری ). پریشان و درهم و آن را ژولیده گویند و ژولیدن مصدر آن است . (آنندراج ). <BR><font color=\"Blue\">◄</font> (اِ) چین و شکنج و ناهمواری . (برهان ).<br /></font></div>'),
(288346, 'ژول اول', '<span class=\"hlight\">ژول اول .</span> <font color=\"DarkGreen\"><b>[ ل ِ اَوْ وَ ]</font></b> (اِخ ) (قدیس ) پاپ مسیحی از <span class=\"hlight\" dir=\"rtl\">٣٣٧</span> تا <span class=\"hlight\" dir=\"rtl\">٣٥٢</span> م . ذکران وی دوازدهم آوریل است .<br /></font></div>'),
(288347, 'ژول دوم', '<span class=\"hlight\">ژول دوم .</span> <font color=\"DarkGreen\"><b>[ ل ِ دُوْ وُ ]</font></b> (اِخ ) ژولین دولا رُوِر. پاپ مسیحی از <span class=\"hlight\" dir=\"rtl\">١٥٠٣</span> تا <span class=\"hlight\" dir=\"rtl\">١٥١٣</span> م . متولد در حوالی ساون بسال <span class=\"hlight\" dir=\"rtl\">١٤٤٣</span> و متوفی در رم بسال <span class=\"hlight\" dir=\"rtl\">١٥١٣</span> م . وی قدرت سیاسی پاپها را در ایتالیا که از دست رفته بود از نو زنده کرد.<br /></font></div>'),
(288348, 'ژول سزار', '<span class=\"hlight\">ژول سزار.</span> <font color=\"DarkGreen\"><b>[ س ِ ]</font></b> (اِخ ) رجوع به سزار شود.<br /></font></div>'),
(288349, 'ژول سوم', '<span class=\"hlight\">ژول سوم .</span> <font color=\"DarkGreen\"><b>[ ل ِ س ِوْ وُ ]</font></b> (اِخ ) پاپ مسیحی از سال <span class=\"hlight\" dir=\"rtl\">١٥٥٠</span> تا <span class=\"hlight\" dir=\"rtl\">١٥٥٥</span> م .<br /></font></div>'),
(288350, 'ژول لابوم', '<span class=\"hlight\">ژول لابوم .</span> (اِخ ) خاورشناس معاصر، عالم به علوم و احکام اسلامی و باخبر از دقایق و رموز قرآن که فهرستی مفید برای قرآن کریم ترتیب داده و آیات قرآنی را بر حسب موضوعات مختلف تقسیم کرده و آن را در <span class=\"hlight\" dir=\"rtl\">١٨</span> فصل مبوب کرده است . وی این فهرست را به فرانسه نوشته و دانشمند معاصر مصری محمد فؤاد عبدالباقی آن را با اصل آیات از فرانسه به عربی گردانیده وتفصیل الاَّیات نام داده است . فصول کتاب بدینگونه است : تاریخ . محمد. تبلیغ. بنی اسرائیل . توراة. نصاری . ماوراء طبیعت . توحید. قرآن . دین . عقاید. عبادات . شریعت و قوانین . نظام اجتماعی . علوم و فنون .تجارت . علم تهذیب اخلاق . موفقیت و فیروزی . و تحت هر فصلی فروعی قرار داده که شماره ٔ آنها به <span class=\"hlight\" dir=\"rtl\">٣٥٠</span> فرع میرسد و تحت هر فرعی آیات نازله ٔ قرآنی و پهلوی هر آیه اسم سوره ای است که در آن آیه ٔ مذکور نازل شده است .<br /></font></div>'),
(288351, 'ژول مهل', '<span class=\"hlight\">ژول مهل .</span> <font color=\"DarkGreen\"><b>[ م ُ ]</font></b> (اِخ ) نام خاورشناس فرانسوی مترجم شاهنامه ٔ فردوسی به زبان فرانسه و طابعآن از سال <span class=\"hlight\" dir=\"rtl\">١٨٣٨</span> تا سال <span class=\"hlight\" dir=\"rtl\">١٨٧٨</span> م . رجوع به موهل شود.<br /></font></div>'),
(288352, 'ژول ورن', '<span class=\"hlight\">ژول ورن .</span> <font color=\"DarkGreen\"><b>[ وِ ]</font></b> (اِخ ) نام رمان نویس فرانسوی (<span class=\"hlight\" dir=\"rtl\">١٨٢٨</span>-<span class=\"hlight\" dir=\"rtl\">١٩٠٥</span> م .).<br /></font></div>'),
(288353, 'ژول گانتن', '<span class=\"hlight\">ژول گانتن .</span> <font color=\"DarkGreen\"><b>[ ت َ ]</font></b> (اِخ ) از خاورشناسان فرانسوی طابع تمام باب چهارم تاریخ گزیده در تاریخ سلاطین اسلامی ایران با اصل فارسی بضمیمه ٔ ترجمه ٔ فرانسوی در سال <span class=\"hlight\" dir=\"rtl\">١٩٠٣</span> م . در پاریس . (ترجمه ٔ ادبیات برون ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">١١٦</span>).<br /></font></div>'),
(288354, 'ژولاندن', '<span class=\"hlight\">ژولاندن .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (مص ) پریشان کردن .<br /></font></div>'),
(288355, 'ژولانیدن', '<span class=\"hlight\">ژولانیدن .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (مص ) پریشان کردن .<br /></font></div>'),
(288356, 'ژوله', '<span class=\"hlight\">ژوله .</span> <font color=\"DarkGreen\"><b>[ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ل ِ ]</font></b> (اِ) نام مرغی است که آن را چکاوک خوانند و به عربی قبره گویند. (برهان ). چکاوک . قبره . ابوالملیح .<br /></font></div>'),
(288357, 'ژولوس', '<span class=\"hlight\">ژولوس .</span> (اِخ ) نام سرسلسله ٔ خانواده ٔ ژول سزار (قیصر). (ترجمه ٔ تمدن قدیم فوستل دکولانژ ص <span class=\"hlight\" dir=\"rtl\">٤٨١</span>).<br /></font></div>'),
(288358, 'ژولپ', '<span class=\"hlight\">ژولپ .</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (اِ) ژولپ از کلمه ٔ عربی جُلاب (معرب از گلاب ) گرفته شده که مخلوطی از عسل و آب بوده است . امروز این نام را به پوسیونهائی مرکب از شربت و آب مقطر و یا به پوسیون های صاف و شفافی که دارای صمغ باشداطلاق میکنند. تمامی ژولپ ها از محصولات ماژیسترال هستند. معروفترین ژولپ ها که بعنوان حامل در پوسیونها بکار میروند عبارتند از: <span class=\"hlight\" dir=\"rtl\">١</span>- ژولپ ساده : شربت ساده <span class=\"hlight\" dir=\"rtl\">٣٠</span> گرم . آب بهارنارنج <span class=\"hlight\" dir=\"rtl\">٢٠</span> گرم . آب مقطر <span class=\"hlight\" dir=\"rtl\">١٠٠</span> گرم . <span class=\"hlight\" dir=\"rtl\">٢</span>- ژولپ صمغ: گرد صمغ عربی <span class=\"hlight\" dir=\"rtl\">١٠</span> گرم . شربت ساده <span class=\"hlight\" dir=\"rtl\">٣٠</span> گرم . آب بهارنارنج <span class=\"hlight\" dir=\"rtl\">١٠</span> گرم . آب مقطر <span class=\"hlight\" dir=\"rtl\">١٠٠</span> گرم . (درمانشناسی ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br /></font></div>'),
(288359, 'ژولک', '<span class=\"hlight\">ژولک .</span> <font color=\"DarkGreen\"><b>[ ل َ ]</font></b> (اِ) نام پرنده ای است سرخ رنگ . رجوع به ژورک شود.<br /></font></div>'),
(288360, 'ژولی', '<span class=\"hlight\">ژولی .</span> (اِخ ) نام یکی از قدیسات مسیحی . وی بسال <span class=\"hlight\" dir=\"rtl\">٤٣٩</span> م . به شهادت رسید. ذکرانش در <span class=\"hlight\" dir=\"rtl\">٢٢</span> مه است .<br /></font></div>'),
(288361, 'ژولی', '<span class=\"hlight\">ژولی .</span> (اِخ ) نام دختر امپراطور تیتوس و ماریکا فورنیلا. متولد در حدود سال <span class=\"hlight\" dir=\"rtl\">٦٥</span> م . وی زوجه ٔ فلاویوس سابینوس پسر کهتر وسپازیان بود.<br /></font></div>'),
(288362, 'ژولی', '<span class=\"hlight\">ژولی .</span> (اِخ ) نام دختر آگریپا و ژولی دختر اگوست که فوقاً شرح زندگانیش گذشت . متولد بسال <span class=\"hlight\" dir=\"rtl\">١٨</span> ق .م . و متوفی بسال <span class=\"hlight\" dir=\"rtl\">٢٨</span> م .<br /></font></div>'),
(288363, 'ژولی', '<span class=\"hlight\">ژولی .</span> (اِخ ) ژولیا لیویلا. نام جوانترین دختر آگریپین و ژرمانیکوس، متولد بسال <span class=\"hlight\" dir=\"rtl\">١٨</span> و متوفی بسال <span class=\"hlight\" dir=\"rtl\">٤٣</span> م .<br /></font></div>'),
(288364, 'ژولی', '<span class=\"hlight\">ژولی .</span> (اِخ ) نام دختر اگوست قیصر رُم، متولد بسال <span class=\"hlight\" dir=\"rtl\">٣٩</span> ق .م . و متوفی بسال <span class=\"hlight\" dir=\"rtl\">١٤</span> م . وی شهره به زیبائی و هوسرانی است و متوالیاً به زوجیت مارسلوس و آگریپا و تیبر درآمده است .<br /></font></div>'),
(288365, 'ژولی', '<span class=\"hlight\">ژولی .</span> (اِخ ) ژولیا. نام دختر ژول سزار و زن پمپه، متوفی بسال <span class=\"hlight\" dir=\"rtl\">٥٤</span> ق .م . رجوع به ژولیا شود.<br /></font></div>'),
(288366, 'ژولیا', '<span class=\"hlight\">ژولیا.</span> (اِخ ) (ژنس ) نام خانواده ٔ معتبری از رومیان . ژول سزار منسوب بدان است .<br /></font></div>'),
(288367, 'ژولیا', '<span class=\"hlight\">ژولیا.</span> (اِخ ) ادوار. نام ریاضی دان فرانسوی و عضو فرهنگستان علوم فرانسه . مولد سیدی -بل -آبه بسال <span class=\"hlight\" dir=\"rtl\">١٨٩٣</span> م .<br /></font></div>'),
(288368, 'ژولیا', '<span class=\"hlight\">ژولیا.</span> (اِخ ) ژولی . نام دختر قیصر (ژول سزار) و کورنلیا (رجوع به این دو اسم شود) و زن پمپه . وی چندی پدر و شوهر خویش را از مخالفت کردن با یکدیگر بازداشت . وفات بسال <span class=\"hlight\" dir=\"rtl\">٥٥</span> ق .م . (تمدن قدیم فوستل دکولانژ ص <span class=\"hlight\" dir=\"rtl\">٤٨١</span>).<br /></font></div>'),
(288369, 'ژولیا دمنا', '<span class=\"hlight\">ژولیا دمنا.</span> <font color=\"DarkGreen\"><b>[ دُ ]</font></b> (اِخ ) نام امپراطریس رومی زن سِپتیم سِوِر و مادر کاراکالا. متولد به اِمز از بلاد شام در حدود سال <span class=\"hlight\" dir=\"rtl\">١٥٨</span> و متوفی بسال <span class=\"hlight\" dir=\"rtl\">٢١٧</span> م .<br /></font></div>'),
(288370, 'ژولیا مامه آ', '<span class=\"hlight\">ژولیا مامه آ.</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (اِخ ) نام مادر آلکساندر سِوِر. این زن را به کیش مسیحی میلی وافر بود و در سال <span class=\"hlight\" dir=\"rtl\">٢٣٥</span> م . با پسرش به قتل رسید.<br /></font></div>'),
(288371, 'ژولیا مزا', '<span class=\"hlight\">ژولیا مزا.</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (اِخ ) نام خواهر زن امپراطور سپتیم سِوِر. متولد در اِمِز و متوفی در حدود سال <span class=\"hlight\" dir=\"rtl\">٢٢٥</span> م .<br /></font></div>'),
(288372, 'ژولیان', '<span class=\"hlight\">ژولیان .</span> (اِخ ) کامیل . نام مورخ فرانسوی مؤلف کتاب مهمی راجع به تاریخ سرزمین گل . مولد مارسی بسال <span class=\"hlight\" dir=\"rtl\">١٨٥٩</span> و وفات بسال <span class=\"hlight\" dir=\"rtl\">١٩٣٣</span> م .<br /></font></div>'),
(288373, 'ژولیانی', '<span class=\"hlight\">ژولیانی .</span> (ص نسبی، اِ) نام تقویم ژولین که ژول سزار در سال <span class=\"hlight\" dir=\"rtl\">٤٦</span> ق .م . آن را بر روی حساب سزیژن بنا نهاد. سال ژولیانی <span class=\"hlight\" dir=\"rtl\">٣٦٥</span> روز داشت (بجای <span class=\"hlight\" dir=\"rtl\">٣٦٥</span> روز و یک ربع) و هر چهار سال یک بار سال را <span class=\"hlight\" dir=\"rtl\">٣٦٦</span> روز حساب می کردند یعنی یک روز بعنوان کبیسه بدان می افزودند. این ترتیب تا اصلاح گریگوری که در سال <span class=\"hlight\" dir=\"rtl\">١٥٨٢</span> م . انجام گرفت برجای بود.<br /></font></div>'),
(288374, 'ژولیدن', '<span class=\"hlight\">ژولیدن .</span> <font color=\"DarkGreen\"><b>[ دَ]</font></b> (مص ) تند و درهم شدن و آن را جولیدن گویند. (جهانگیری ). درهم شدن و درهم رفتن و پریشان گردیدن . (برهان ). مختلط و مشوش گشتن . آشفته شدن . کالیدن . درهم کشیدن . درهم و پریشان شدن عموماً و پریشان شدن موی خصوصاً. (رشیدی ). کالیده و پریشان و پراکنده و وِژگال شدن موی . وِشکال شدن موی . <br /></font></div>'),
(288375, 'ژولیدنی', '<span class=\"hlight\">ژولیدنی .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (ص لیاقت ) درخور ژولیدن .<br /></font></div>'),
(288376, 'ژولیده', '<span class=\"hlight\">ژولیده .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف <span class=\"hlight\" dir=\"rtl\">/</span> نف ) درهم رفته . درهم شده . آمیخته . به دست مالیده . پریشان . و این معنی را بیشتر در زلف و کاکل استعمال کنند. (برهان ). خلاف خوارکرده (در موی ). گوریده . آشفته . بهم شوریده . کالیده : جغبوت ؛سخت ژولیده (در موی ). هدمل ؛ بسیارموی ژولیده سر. هِدَبّْل ؛ ژولیده موی که شانه نکند. شَعر مشعون ؛ موی پراکنده ٔ ژولیده . تَفَث ؛ چرکین و ژولیده گردیدن موی . شعثان الرأس ؛ ژولیده موی غبارآلوده سر. جُفول ؛ پراکنده شدن موها و ژولیده گردیدن . (منتهی الارب ) <span class=\"hlight\">:</span> <br />مانده گشتم ز پا و از دیده <br />شانه نو بود وموی ژولیده .<br /> <font color=\"Red\">سنائی .</font><br />تو نیز مه چهارده بنمای <br />بردار ز روی زلف ژولیده .<br /> <font color=\"Red\">سنائی .</font><br />نگارم دوش ژولیده درآمد<br />چو جان من بشولیده درآمد.<br /> <font color=\"Red\">عطار.</font><br />همی گفت ژولیده دستار و موی <br />کف دست شکرانه مالان به روی .<br /><font color=\"Red\">(بوستان ).</font><br /></font></div>'),
(288377, 'ژولیده بیان', '<span class=\"hlight\">ژولیده بیان .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ب َ ]</font></b> (ص مرکب ) آنکه بیان و گفتار او درهم و مشوش باشد. (آنندراج ).<br /></font></div>'),
(288378, 'ژولیده شدن', '<span class=\"hlight\">ژولیده شدن .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ش ُ دَ ]</font></b> (مص مرکب ) درهم و پریشان شدن . رجوع به ژولیدن شود.<br /></font></div>'),
(288379, 'ژولیده موی', '<span class=\"hlight\">ژولیده موی .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ص مرکب ) پریشان موی . آنکه موی و زلف آشفته و درهم دارد: اَشوع، اشعث ؛ مرد ژولیده موی . شَعْثاء؛ زن ژولیده موی . (منتهی الارب ). منتفش الشعر و منتفشةالشعر؛ ژولیده موی <span class=\"hlight\">:</span> <br />همی رفت ژولیده دستار و موی <br />کف دست شکرانه مالان به روی .<br /> <font color=\"Red\">سعدی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ژولیده موی شدن </span> ؛ پریشان موی شدن . زلف درهم شدن . شَعَث . (منتهی الارب ).<br /></font></div>'),
(288380, 'ژولیده کردن', '<span class=\"hlight\">ژولیده کردن .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ک َ دَ ]</font></b> (مص مرکب ) پراکنده کردن . پریشان کردن موی .<br /></font></div>'),
(288381, 'ژولیدگی', '<span class=\"hlight\">ژولیدگی .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (حامص ) حالت و چگونگی ژولیده . پریشانی . رجوع به پریشانی شود.<br /></font></div>'),
(288382, 'ژولیس', '<span class=\"hlight\">ژولیس .</span> (اِخ ) خاورشناس اواخر قرن شانزدهم میلادی . وی در ادبیات عرب براعتی حاصل و قصیده ٔ لامیةالعجم ابواسماعیل طغرائی را به زبان لاتین ترجمه کرد و در سال <span class=\"hlight\" dir=\"rtl\">١٧٠٧</span> م . به طبع رسانید.<br /></font></div>'),
(288383, 'ژولین', '<span class=\"hlight\">ژولین .</span> <font color=\"DarkGreen\"><b>[ ی َ ]</font></b> (اِخ ) (قدیس ) نام رئیس اسقفهای تُلد (طلیطله ) از <span class=\"hlight\" dir=\"rtl\">٦٨٠</span> تا <span class=\"hlight\" dir=\"rtl\">٦٩٠</span> م . متولد و متوفی در همان شهر (<span class=\"hlight\" dir=\"rtl\">٦٢٠</span>-<span class=\"hlight\" dir=\"rtl\">٦٩٠</span> م .). ذکران وی هشتم مارس است .<br /></font></div>'),
(288384, 'ژولین', '<span class=\"hlight\">ژولین .</span> <font color=\"DarkGreen\"><b>[ ی َ ]</font></b> (اِخ ) از قدیسین متولد به وین در دُفینه . وی بسال <span class=\"hlight\" dir=\"rtl\">٣٠٤</span> م . در بریود به شهادت رسید. کلیسای «سن ژولین لوپور» در پاریس بنام او و ذکرانش <span class=\"hlight\" dir=\"rtl\">٢٨</span> اوت است .<br /></font></div>'),
(288385, 'ژولین', '<span class=\"hlight\">ژولین .</span> <font color=\"DarkGreen\"><b>[ ی َ ]</font></b> (اِخ ) کنت . نام شخصیتی موهوم که گویند فرماندار آندالوزی بود. وی بر اثر حس کینه کشی در سال <span class=\"hlight\" dir=\"rtl\">٧١١</span> م . مدخل اسپانیا را به روی مُرها بگشود.<br /></font></div>'),
(288386, 'ژولین', '<span class=\"hlight\">ژولین .</span> <font color=\"DarkGreen\"><b>[ی َ ]</font></b> (اِخ ) پیر. نام حجار و مجسمه ساز فرانسوی حجّارمجسمه ٔ لابنیوز متولد در سن پولین (هُت لوآر) بسال <span class=\"hlight\" dir=\"rtl\">١٧٣١</span> و متوفی بسال <span class=\"hlight\" dir=\"rtl\">١٨٠٤</span> م .<br /></font></div>'),
(288387, 'ژولین', '<span class=\"hlight\">ژولین .</span> <font color=\"DarkGreen\"><b>[ ی َ ]</font></b> (اِخ ) استانیسلاس . نام چین شناس فرانسوی . مولد اورلئان بسال <span class=\"hlight\" dir=\"rtl\">١٧٩٩</span> و وفات در پاریس بسال <span class=\"hlight\" dir=\"rtl\">١٨٧٣</span> م .<br /></font></div>'),
(288388, 'ژولین لاپستات', '<span class=\"hlight\">ژولین لاپستات .</span> <font color=\"DarkGreen\"><b>[ ی َ پ ُ ]</font></b> (اِخ ) نام امپراطور روم از <span class=\"hlight\" dir=\"rtl\">٣٦١</span> تا <span class=\"hlight\" dir=\"rtl\">٣٦٣</span> م . متولد بسال <span class=\"hlight\" dir=\"rtl\">٣٣١</span> م . وی برادرزاده ٔ کنستانتن بود و چون نخست در حجر مسیحیت تربیت شده و سپس از آن دین خارج گردیده بود می خواست بت پرستی را بار دیگر در روم برقرار سازد، از اینرو او را لاپُستات یعنی مارق و مرتد لقب دادند. وی در جنگی که باشاپور دوم ساسانی کرد در بین النهرین به قتل رسید.<br /></font></div>'),
(288389, 'ژولین لسپیتالیه', '<span class=\"hlight\">ژولین لسپیتالیه .</span> <font color=\"DarkGreen\"><b>[ ی َ ل ُ تا ی ِ ]</font></b> (اِخ ) نام قدیسی مورد احترام مخصوصاً در اسپانیا و سیسیل (صقلیه ). از اوجز اساطیری در دست نیست . ذکران وی <span class=\"hlight\" dir=\"rtl\">٢٩</span> ژانویه است .<br /></font></div>'),
(288390, 'ژولیه', '<span class=\"hlight\">ژولیه .</span> <font color=\"DarkGreen\"><b>[ ی ِ ]</font></b> (اِخ ) شهری از پروس در ایالت رِنان . این شهر سابقاً کرسی دوک نشینی به همین نام بوده است و <span class=\"hlight\" dir=\"rtl\">٨٦٠٠</span> تن سکنه دارد.<br /></font></div>'),
(288391, 'ژولیوس لیپه', '<span class=\"hlight\">ژولیوس لیپه .</span> <font color=\"DarkGreen\"><b>[ پ ِ ]</font></b> (اِخ ) از خاورشناسان هلندی که در آثار اسلامی تتبع کرده و تاریخ الحکماء قفطی را با مقدمه ای که به آن نوشته بسال <span class=\"hlight\" dir=\"rtl\">١٩٠٣</span> م . در لیپزیک انتشار داده و نیز کتاب الفلک فرغانی و عجایب المقدور فی احوال تیمور ابن عربشاه را منتشر ساخته است .<br /></font></div>'),
(288392, 'ژولیوس ها', '<span class=\"hlight\">ژولیوس ها.</span> (اِخ ) نام اخلاف قیصر (ژول سزار). (ترجمه ٔ تمدن قدیم فوستل دکولانژ ص <span class=\"hlight\" dir=\"rtl\">٤٨١</span>).<br /></font></div>'),
(288393, 'ژومن', '<span class=\"hlight\">ژومن .</span> <font color=\"DarkGreen\"><b>[ ژُ م ُ ]</font></b> (اِخ ) نام دهستانی در بخش نُراز ولایت آوِسن کنار رود سامبر، دارای راه آهن تا مرز بلژیک و <span class=\"hlight\" dir=\"rtl\">٦٦٤٢</span> تن سکنه .<br /></font></div>'),
(288394, 'ژومه', '<span class=\"hlight\">ژومه .</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (اِخ ) نام بخشی از بلژیک به هِنو، دارای <span class=\"hlight\" dir=\"rtl\">٢٨٠٠٠</span> تن سکنه . آنجا محل استخراج فلزات و کارخانه های شیشه سازی است .<br /></font></div>'),
(288395, 'ژومو', '<span class=\"hlight\">ژومو.</span> <font color=\"DarkGreen\"><b>[ م ُ ]</font></b> (اِخ ) نام کرسی بخش در ایالت پوی -دو-دوم از ولایت ایسوار کنار آلیه، دارای <span class=\"hlight\" dir=\"rtl\">٨٢٤</span> تن سکنه .<br /></font></div>'),
(288396, 'ژومیده', '<span class=\"hlight\">ژومیده .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف ) کشت وزراعت آب زده . (برهان ). مزرعه و کشت زار آب داده شده .<br /></font></div>'),
(288397, 'ژومیلیاک لگراند', '<span class=\"hlight\">ژومیلیاک لگراند.</span> <font color=\"DarkGreen\"><b>[ ل ُ ]</font></b> (اِخ ) نام بخش در دُردُنی از ولایت نُنْتْرُن کنار ایسلنسانت، دارای <span class=\"hlight\" dir=\"rtl\">٢٤٦٤</span> تن سکنه .<br /></font></div>'),
(288398, 'ژومیژ', '<span class=\"hlight\">ژومیژ.</span> <font color=\"DarkGreen\"><b>[ ی ِ ]</font></b> (اِخ ) نام دهستان سِن ِ سفلی از ولایت روئن کنار سن، دارای <span class=\"hlight\" dir=\"rtl\">٨٧٠</span> تن سکنه . بدانجا خرابه های دیری است که بسال <span class=\"hlight\" dir=\"rtl\">٦٥٤</span> م . سن فیلبر یا فیلیبر بنا کرده است .<br /></font></div>'),
(288399, 'ژون', '<span class=\"hlight\">ژون .</span> <font color=\"DarkGreen\"><b>[ ژُ وَ ]</font></b> (اِخ ) نام یکی از نجبای کشور گل . وی بسال <span class=\"hlight\" dir=\"rtl\">٤١١</span> م . به امپراطوری و در سال <span class=\"hlight\" dir=\"rtl\">٤١٢</span> به قتل رسید.<br /></font></div>'),
(288400, 'ژون', '<span class=\"hlight\">ژون .</span> (اِخ ) نام سلسله ٔ بیست وسوم سلاطین چین . این سلسله مغول بوده اند و صد و نه سال سلطنت رانده اند.<br /></font></div>'),
(288401, 'ژون', '<span class=\"hlight\">ژون .</span> (اِ) بت . صنم . (برهان ). زون . رجوع به بت شود.<br /></font></div>'),
(288402, 'ژونت', '<span class=\"hlight\">ژونت .</span> (اِخ ) نام خاندان مشهوری از امپراطوران ونیزی در قرن شانزدهم میلادی . شعبه ٔ دوّمی از آنان در فلورانس و شعبه ٔ سوّمی در لیون بودند.<br /></font></div>'),
(288403, 'ژونن', '<span class=\"hlight\">ژونن .</span> <font color=\"DarkGreen\"><b>[ ن ُ ]</font></b> (اِخ ) نام سیاره ای تلسکوپی . این سیاره را در سال <span class=\"hlight\" dir=\"rtl\">١٨٠٤</span> م . هاردینگ کشف کرد و نام اساطیری ژونُن بدان داد.<br /></font></div>'),
(288404, 'ژونن', '<span class=\"hlight\">ژونن .</span> <font color=\"DarkGreen\"><b>[ ن ُ ]</font></b> (اِخ ) نام یکی از الهه های بزرگ روم و بنا به اساطیر قدیم دختر ساتورن و رِآ و زن ژوپیتر. وی را ملکه ٔ آسمان و الهه ٔ روشنی و زناشوئی می خواندند و از دیرباز با هرا الهه ٔیونانی یکی دانسته و بنام او معابدی بنا میکردند.<br /></font></div>'),
(288405, 'ژونن', '<span class=\"hlight\">ژونن .</span> <font color=\"DarkGreen\"><b>[ ن َ ]</font></b> (اِخ ) نام شهری در جمهوری آرژانتین در ایالت مندزا، دارای <span class=\"hlight\" dir=\"rtl\">٣٨٠٠٠</span> تن سکنه .<br /></font></div>'),
(288406, 'ژونن', '<span class=\"hlight\">ژونن .</span> <font color=\"DarkGreen\"><b>[ ن َ ]</font></b> (اِخ ) نام شهری در کشور پرو واقع در سلسله ٔ کوههای آند و مشرق لیما، دارای <span class=\"hlight\" dir=\"rtl\">٨٠٠٠</span> تن سکنه .<br /></font></div>'),
(288407, 'ژونو', '<span class=\"hlight\">ژونو.</span> <font color=\"DarkGreen\"><b>[ ن ُ ]</font></b> (اِخ ) آندُش . دوک دابرانتس ژنرال فرانسوی . مولد بوسی -ل ُ-گراند (کت -دُر) بسال <span class=\"hlight\" dir=\"rtl\">١٧٧١</span> م . وی در نبرد ایتالیا آجودان ناپلئون اول بود و با هیئت اعزامی به مصر رفت و لیسبن رادر <span class=\"hlight\" dir=\"rtl\">١٨٠٧</span> بگرفت و سرانجام در سال <span class=\"hlight\" dir=\"rtl\">١٨١٣</span> خود را کشت .<br /></font></div>'),
(288408, 'ژونی ویل', '<span class=\"hlight\">ژونی ویل .</span> (اِخ ) نام مرکز بخش در ایالت آردن از ولایت رِتِل، دارای <span class=\"hlight\" dir=\"rtl\">٧٨٠</span> تن سکنه .<br /></font></div>'),
(288409, 'ژوهیدن', '<span class=\"hlight\">ژوهیدن .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (مص ) چکیدن آب باشد از سقف خانه بسبب باران باریدن . (برهان ). چکه کردن طاق از باران .<br /></font></div>'),
(288410, 'ژوودان', '<span class=\"hlight\">ژوودان .</span> <font color=\"DarkGreen\"><b>[ ژِ وُ ]</font></b> (اِخ ) نام سرزمینی است باستانی از فرانسه در ایالت لالُزِر بین لامارگرید و لگوآل .<br /></font></div>'),
(288411, 'ژوونال', '<span class=\"hlight\">ژوونال .</span> <font color=\"DarkGreen\"><b>[ وِ ]</font></b> (اِخ ) نام شاعر هجاگوی لاتینی . مولد آکینوم در حدود سال <span class=\"hlight\" dir=\"rtl\">٤٢</span> و وفات بسال <span class=\"hlight\" dir=\"rtl\">١٢٥</span> م .<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(288412, 'ژوونال دزورسن', '<span class=\"hlight\">ژوونال دزورسن .</span> <font color=\"DarkGreen\"><b>[ وِ دِ س َ ]</font></b> (اِخ ) گیوم . نام برادر ژوونال دزورسن (ژان دوم ). وی در روزگار لوئی یازدهم مهردار فرانسه بود و در پاریس تولد و وفات یافت (<span class=\"hlight\" dir=\"rtl\">١٤٠٠</span>-<span class=\"hlight\" dir=\"rtl\">١٤٧٢</span> م .).<br /></font></div>'),
(288413, 'ژوونال دزورسن', '<span class=\"hlight\">ژوونال دزورسن .</span> <font color=\"DarkGreen\"><b>[ وِ دِ س َ ]</font></b> (اِخ ) ژان دوم . نام پسر ژان مذکور در فوق . قاضی و اسقف و مورخ فرانسوی متولد به پاریس در سال <span class=\"hlight\" dir=\"rtl\">١٣٨٨</span> و متوفی در سال <span class=\"hlight\" dir=\"rtl\">١٤٧٣</span> م . او را تاریخی است در باب شارل ششم . وی در دادرسی ژاندارک نیز تجدید نظر کرده است .<br /></font></div>'),
(288414, 'ژوونال دزورسن', '<span class=\"hlight\">ژوونال دزورسن .</span> <font color=\"DarkGreen\"><b>[ وِ دِ س َ ]</font></b> (اِخ ) ژان . نام قاضی فرانسوی متولد در تروی بسال <span class=\"hlight\" dir=\"rtl\">١٣٦٠</span> م . وی بسال <span class=\"hlight\" dir=\"rtl\">١٣٨٨</span> به منصب قضاوت بلدی پاریس رسید و در <span class=\"hlight\" dir=\"rtl\">١٤٠٨</span> نیابت سلطنت ناحیه ٔ ایزابو از باویر بدو محول شد. و در سال <span class=\"hlight\" dir=\"rtl\">١٤٣١</span> درگذشت .<br /></font></div>'),
(288415, 'ژوونالیس', '<span class=\"hlight\">ژوونالیس .</span> <font color=\"DarkGreen\"><b>[ وِ ]</font></b> (اِخ ) نام یکی از شعرای باستانی روم، متولد در حدود سال <span class=\"hlight\" dir=\"rtl\">٤٢</span> و متوفی در حدود سال <span class=\"hlight\" dir=\"rtl\">١٢٥</span> م . این شاعر غالباً در اشعار خویش نقائص اخلاقی مردم روم و قبایح اعمال بزرگان آن سرزمین را تشریح کرده است . (ترجمه ٔ تمدن قدیم فوستل دکولانژ ص <span class=\"hlight\" dir=\"rtl\">٤٨١</span>).<br /></font></div>'),
(288416, 'ژوونه', '<span class=\"hlight\">ژوونه .</span> <font color=\"DarkGreen\"><b>[ وِ ن ِ ]</font></b> (اِخ ) ژان . نام نقاش تاریخ فرانسه . متولد در روئن و متوفی به پاریس (<span class=\"hlight\" dir=\"rtl\">١٦٤٤</span> یا <span class=\"hlight\" dir=\"rtl\">١٦٤٧</span>-<span class=\"hlight\" dir=\"rtl\">١٧١٧</span> م .).<br /></font></div>'),
(288417, 'ژوویزی سورارژ', '<span class=\"hlight\">ژوویزی سورارژ.</span> <font color=\"DarkGreen\"><b>[ اُ ]</font></b> (اِخ ) نام دهستانی در «سِن -اِ-اواز» از شهرستان کربی، دارای راه آهن و <span class=\"hlight\" dir=\"rtl\">٨١٤٣</span> تن سکنه .<br /></font></div>'),
(288418, 'ژووینیی', '<span class=\"hlight\">ژووینیی .</span> <font color=\"DarkGreen\"><b>[ وین ْ ]</font></b> (اِخ ) نام کرسی بخش در ایالت مانش از ولایت آورانش، دارای <span class=\"hlight\" dir=\"rtl\">٦٥٠</span> تن سکنه .<br /></font></div>'),
(288419, 'ژووینیی سوزاندن', '<span class=\"hlight\">ژووینیی سوزاندن .</span> <font color=\"DarkGreen\"><b>[ وین ْ دِ ]</font></b> (اِخ ) نام کرسی بخش در ایالت «اُرن » از ولایت آرژانتان، دارای راه آهن و <span class=\"hlight\" dir=\"rtl\">٩١٧</span> تن سکنه .<br /></font></div>'),
(288420, 'ژوپی تر آمون', '<span class=\"hlight\">ژوپی تر آمون .</span> <font color=\"DarkGreen\"><b>[ ت ِ ]</font></b> (اِخ ) یکی از القاب اسکندر کبیر، و شرح آن چنین است : زمانی که اسکندر کبیر در مقدونیه بود خودرا پسر زئوس یا ژوپیتر که بنابر افسانه های قدیم یونان خدای خدایان بود می دانست . از اینرو بعدها که از مصر به معبد آمون رفت کاهن آنجا از راه چاپلوسی و تملق، او را ژوپی تر آمون خواند و از آن ببعد فکر پسر خدا بودن بقدری در مغز اسکندر قوت یافت که می خواست او را پسر خدا خطاب کنند. (ایران باستان ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٧٤٠</span>).<br /></font></div>'),
(288421, 'ژوپیتر', '<span class=\"hlight\">ژوپیتر.</span> <font color=\"DarkGreen\"><b>[ ت ِ ]</font></b> (اِخ ) مشتری . برجیس . سعد اکبر.<br /></font></div>'),
(288422, 'ژوپیتر', '<span class=\"hlight\">ژوپیتر.</span> <font color=\"DarkGreen\"><b>[ ت ِ ]</font></b> (اِخ ) ژوپیتر یا زئوس بنابر افسانه های یونان قدیم پسر کیوان است که یونانیان و رومیان او را پدر و خدای خدایان می پنداشتند. ژوپیتر نخست پدر را از آسمانها بزیر افکند، پس از آن دریاها و دوزخ را به برادران خود نپتونوس و پلوتو (رجوع به این دو نام شود) سپرده خود سلطنت آسمانها و زمین را اختیار کرد. زن ژوپیتر ژونو نام داشت و خواهر وی بود که از او وولکانوس و مارس (رجوع به این دو نام شود) بوجود آمدند. نویسندگان یونان و روم قدیم را درباره ٔ ژوپیتر افسانه ها و داستانهای بسیار است . (ترجمه ٔ تمدن قدیم فوستل دُکولانژ ص <span class=\"hlight\" dir=\"rtl\">٤٨١</span>).<br /></font></div>'),
(288423, 'ژوپیتر ا آنتیوپ', '<span class=\"hlight\">ژوپیتر ا آنتیوپ .</span> <font color=\"DarkGreen\"><b>[ ت ِ اِ یُپ ْ ]</font></b> (اِخ ) نام تصویر تیتان در موزه ٔ مونیخ . <BR><font color=\"Blue\">◄</font> نام همان تصویر در موزه ٔ لوور. <BR><font color=\"Blue\">◄</font> نام تصویری از آثار رافائل در رُم . <BR><font color=\"Blue\">◄</font> نام تصویری از آثار پوسن در تالار ملی .<br /></font></div>'),
(288424, 'ژوپیتر المپین', '<span class=\"hlight\">ژوپیتر المپین .</span> <font color=\"DarkGreen\"><b>[ ت ِ اُ ل َ ی ِ ]</font></b> (اِخ )نام مجسمه ای باستانی از شاهکارهای فیدیاس مجسمه ساز معروف یونانی که از عجایب سبعه ٔ عالم به شمار است .<br /></font></div>'),
(288425, 'ژوپین', '<span class=\"hlight\">ژوپین .</span> (اِ) حربه ای است که در قدیم بدان جنگ می کردند. (آنندراج ). صورتی از زوبین است . نصلان . نیزه ٔ کوتاه قد، و آن حربه ای بود که بجانب دشمن می افکندند. قسمی از نیزه ٔ کوچک که اهل هند آن را سیل (به یاء مجهول ) گویند. (غیاث ). نیزه ٔ کوچک که بر سر آن دو شاخه باشد. (غیاث ). ژوبین . زوبین . رجوع به زوبین شود. عَنَزَة. نیزه چه . مزراق . نیزه ٔخرد <span class=\"hlight\">:</span> آن دیالم از سر کوه تیر و ژوپین روان کردند و سنگ همی انداختند و مسلمانان بر سر کوه نتوانستند شدن بازگشتند. (بلعمی ترجمه ٔ تاریخ طبری ).<br />ز پنهان بدان شاهزاده سوار<br />بینداخت ژوپین زهرآب دار<br />گذاره شداز خسروی جوشنش <br />به خون تر شد آن شهریاری تنش .<br /> <font color=\"Red\">دقیقی .</font><br />همان تیز ژوپین زهرآبدار<br />که بر آهنین کوه آرد گذار.<br /> <font color=\"Red\">دقیقی (از شاهنامه ).</font><br />درفشیدن خشت و ژوپین ز گرد<br />چو آتش پس پرده ٔ لاجورد.<br /> <font color=\"Red\">فردوسی .</font><br />کنون خوردنت زخم ژوپین بود<br />تنت را کفن چنگ شاهین بود.<br /> <font color=\"Red\">فردوسی .</font><br />ز توران بسیجیده آمد دمان <br />به ژوپین گودرز بودش زمان .<br /> <font color=\"Red\">فردوسی .</font><br />چو شیر ژیان اندرآمد بسر<br />به ژوپین پولاد خسته جگر.<br /> <font color=\"Red\">فردوسی .</font><br />بینداخت ژوپین به پیران رسید<br />زره در برش سربسر بردرید.<br /> <font color=\"Red\">فردوسی .</font><br />بینداخت ژوپین بکردار تیر<br />برآمد به بازوی سالار پیر.<br /> <font color=\"Red\">فردوسی .</font><br />گرفته سپر پیش و ژوپین به دست <br />به بالا نهاده سر از جای پست .<br /> <font color=\"Red\">فردوسی .</font><br />به قلب اندرون شاه مکران بخست <br />به ژوپین و زان خستگی هم نرست .<br /> <font color=\"Red\">فردوسی .</font><br />درخشیدن تیغ و ژوپین و خشت <br />تو گفتی زمین بر هوا لاله کشت .<br /> <font color=\"Red\">فردوسی .</font><br />ز پیکان و از گرز و ژوپین و تیر<br />زمین شد بکردار دریای قیر.<br /> <font color=\"Red\">فردوسی .</font><br />دهید ار به گرز و به ژوپین دهید<br />سران را ز خون تاج بر سر نهید.<br /> <font color=\"Red\">فردوسی .</font><br />به ژوپین و خنجر به گرز و کمان <br />همی رزم جویند با بدگمان .<br /> <font color=\"Red\">فردوسی .</font><br />چنان دان که او سنگ و آهن خورد<br />همان تیر و ژوپین بر او نگذرد.<br /> <font color=\"Red\">فردوسی .</font><br />به نستیهن گرد و گلباد گفت <br />که ژوپین وخنجر بباید نهفت .<br /> <font color=\"Red\">فردوسی .</font><br />بفرمود تا تخت زرین نهند<br />به میدان پرخاش ژوپین نهند.<br /> <font color=\"Red\">فردوسی .</font><br />برآمد خروش ده و دار و گیر<br />چو باران ببارید ژوپین و تیر.<br /> <font color=\"Red\">فردوسی .</font><br />کمانهای چاچی و تیر خدنگ <br />سپرهای چینی و ژوپین جنگ .<br /> <font color=\"Red\">فردوسی .</font><br />یلان را به ژوپین و خنجرزنید<br />سر سرکشان را ز تن برکنید.<br /> <font color=\"Red\">فردوسی .</font><br />به ژوپین گراز و تذروان به باز<br />بگیریم یکسر بروز دراز.<br /> <font color=\"Red\">فردوسی .</font><br />پیاده شد از اسب ژوپین به دست <br />همی رفت پویان بکردار مست .<br /> <font color=\"Red\">فردوسی .</font><br />همه رزم را دل پر از کین کنیم <br />تن دشمنان جای ژوپین کنیم .<br /> <font color=\"Red\">فردوسی .</font><br />سپهدار توران برآراست جنگ <br />گرفتند کوپال و ژوپین بچنگ .<br /> <font color=\"Red\">فردوسی .</font><br />چو سی وسه جنگی ز تخم پشنگ <br />که ژوپین بدی سازشان روز جنگ .<br /> <font color=\"Red\">فردوسی .</font><br />ورا نام گستهم گژدهم خوان <br />نترسد ز ژوپین و از استخوان . <br /> <font color=\"Red\">فردوسی .</font><br />بر او تیر و ژوپین نیاید بکار<br />سزد گر پیاده کند کارزار.<br /> <font color=\"Red\">فردوسی .</font><br />به یارانش فرمود کاندرنهید<br />به تیر و به ژوپین و خنجر دهید.<br /> <font color=\"Red\">فردوسی .</font><br />هزار و صد و شصت خسروپرست <br />پیاده همی رفت ژوپین به دست .<br /> <font color=\"Red\">فردوسی .</font><br />برفتند شمشیر و ژوپین بکف <br />کشیده سپه برسه فرسنگ صف .<br /> <font color=\"Red\">فردوسی .</font><br />همه شب همی لشکر آراستند<br />همه تیغ و ژوپین بپیراستند.<br /> <font color=\"Red\">فردوسی .</font><br />درآورد بر چنگ ژوپین جنگ <br />بینداخت بر رستم تیزچنگ .<br /> <font color=\"Red\">فردوسی .</font><br />سواران به میدان بکردار گرد<br />به ژوپین گرفتند ننگ و نبرد.<br /> <font color=\"Red\">فردوسی .</font><br />دو رویه سپه برکشیدند صف <br />همه نیزه و تیغ و ژوپین بکف .<br /> <font color=\"Red\">فردوسی .</font><br />ز باران ژوپین و باران تیر<br />زمین شد ز خون چون یکی آبگیر.<br /> <font color=\"Red\">فردوسی .</font><br />ز بس تیر و ژوپین و نوک سنان <br />نداند کنون گو رکاب از عنان .<br /> <font color=\"Red\">فردوسی .</font><br />خروشی برآمد ز طلحندو گو<br />که از باد ژوپین من دور شو.<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(288426, 'ژوپین زن', '<span class=\"hlight\">ژوپین زن .</span> <font color=\"DarkGreen\"><b>[ زَ ]</font></b> (نف مرکب ) آنکه ژوپین افکند. نیزه زن . رجوع به زوبین زن شود <span class=\"hlight\">:</span> <br />سپه بود بر میمنه چل هزار<br />سواران ژوپین زن و نیزه دار.<br /> <font color=\"Red\">فردوسی .</font><br />راوت (؟) ژوپین زن خاراشکاف <br />پشت به پشت از پی روز مصاف .<br /><font color=\"Red\">امیرخسرو (از آنندراج ).</font><br /></font></div>'),
(288427, 'ژوپین ور', '<span class=\"hlight\">ژوپین ور.</span> <font color=\"DarkGreen\"><b>[ وَ ]</font></b> (ص مرکب ) حامل نیزه . سنان دار. نیزه دار.بردارنده ٔ زوبین . رجوع به زوبین ور شود <span class=\"hlight\">:</span> <br />چو دربان بدید آن سپاه گران <br />سپردار بسیار و ژوپین وران .<br /> <font color=\"Red\">فردوسی .</font><br />صفی برکشیدند پیش سوار<br />سپردار و ژوپین ور و نیزه دار.<br /> <font color=\"Red\">فردوسی .</font><br />پیاده سپردار ژوپین وران <br />شده انجمن لشکر بی کران .<br /> <font color=\"Red\">فردوسی .</font><br />همه دشت ژوپین ور و نیزه دار<br />به یک سو پیاده به یک سو سوار.<br /> <font color=\"Red\">فردوسی .</font><br />سپر برگرفتند ژوپین وران <br />بگشتند با خشتهای گران .<br /> <font color=\"Red\">فردوسی .</font><br />سپه بود بر میمنه چل هزار<br />سواران ژوپین ور نیزه دار.<br /> <font color=\"Red\">فردوسی .</font><br />برفتند آنگاه ژوپین وران <br />ابا جوشن و خشتهای گران .<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(288428, 'ژوپین کش', '<span class=\"hlight\">ژوپین کش .</span> <font color=\"DarkGreen\"><b>[ ک َ <span class=\"hlight\" dir=\"rtl\">/</span> ک ِ ]</font></b> (نف مرکب ) حامل زوبین . نیزه دار. رجوع به زوبین کش شود <span class=\"hlight\">:</span> <br />بیامد سپردار و ژوپین کشان <br />بجستند از آن تازیانه نشان .<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(288429, 'ژوژ', '<span class=\"hlight\">ژوژ.</span> (اِ) خارپشت . (لغت نامه ٔ اسدی در کلمه ٔ خارپشت ). خارپشت خُرد. جوجه تیغی . کوله . گوله . (برهان ). رجوع به خارپشت شود.<br /></font></div>'),
(288430, 'ژوژه', '<span class=\"hlight\">ژوژه .</span> <font color=\"DarkGreen\"><b>[ ژَ <span class=\"hlight\" dir=\"rtl\">/</span> ژِ ]</font></b> (اِ)ژوژ. کوله . خارپشت . (برهان ). رجوع به ژوژ و کوله شود. ژوژه که هیئت باستانی آن ژوژک است در تفسیر پهلوی (زند) کتاب وندیداد دوژک است که به ژوژک گردانیده شده و مراد از آن اطلاقی است که مردم زشت گفتار (بدزبان ) به ونگهاپر، سگ ترسو و بلندپوزه کرده اند. ژوژه یا «ژوژه خارپشت » که جانوری است دشمن مور و مار و ایرانیان کشتن آنها و همه ٔ جانوران زیان بخش (خرفستران ) رانیک میدانستند بسیار گرامی و ارجمند بوده است . در نامه ٔ پهلوی بندهش در فصل <span class=\"hlight\" dir=\"rtl\">١٤</span> فقره ٔ <span class=\"hlight\" dir=\"rtl\">١٩</span> دَه جنس سگ برشمرده شده و در میان آنها از ژوژه نیز نام برده است وگوید آن را خارپشت خوانند. در فصل <span class=\"hlight\" dir=\"rtl\">١٩</span> همین نامه در فقره ٔ <span class=\"hlight\" dir=\"rtl\">٢٩</span> آمده : ژوژه که خارپشت خوانند دشمن مور دانه کش است چنانکه گویند ژوژه در سوراخ مور که بشاشد هزار مور بکشد. در نامه ٔ دیگر پهلوی بنام شایست نشایست فصل <span class=\"hlight\" dir=\"rtl\">١</span> فقره ٔ <span class=\"hlight\" dir=\"rtl\">٣١</span> و فصل <span class=\"hlight\" dir=\"rtl\">١٢</span> فقره ٔ <span class=\"hlight\" dir=\"rtl\">٢٠</span> همین مطلب بندهش یاد شده است و نیز میگوید: و هرکه در سر راه خود ژوژه بیند باید برگیرد و به جائی برد که از آسیب برکنار باشد. (فرهنگ ایران باستان تألیف پورداود ص <span class=\"hlight\" dir=\"rtl\">٢١٣</span>).<br /></font></div>'),
(288431, 'ژوژک', '<span class=\"hlight\">ژوژک .</span> <font color=\"DarkGreen\"><b>[ ژَ ]</font></b> (اِ) در برخی از نسخ فرهنگ جهانگیری و بعض کتب لغت در معنی این کلمه آمده : بمعنی پرنده ٔ سرخ فام که بقدر گنجشک است و آن را سرخاب نیز گویند. بنابراین ظاهراً ژوژک همان ژورک است . رجوع به ژورک شود. <BR><font color=\"Blue\">◄</font> هیئت باستانی کلمه ٔ ژوژه . رجوع به ژوژه شود.<br /></font></div>'),
(288432, 'ژوکاست', '<span class=\"hlight\">ژوکاست .</span> <font color=\"DarkGreen\"><b>[ ژُ ]</font></b> (اِخ ) نام زن لائیوس پادشاه تِب و مادر اُدیپ در اساطیر یونانی . وی پس از کشته شدن شوهر خود لائیوس به دست اُدیپ، ندانسته به زوجیت قاتل شوی خویش که در حقیقت پسر خودش و لائیوس بود درآمد.<br /></font></div>'),
(288433, 'ژوکفسکی', '<span class=\"hlight\">ژوکفسکی .</span> <font color=\"DarkGreen\"><b>[ ک ُ ]</font></b> (اِخ ) واسیلی . نام شاعر روسی متولد در نزدیکی تولا بسال <span class=\"hlight\" dir=\"rtl\">١٧٨٣</span> و متوفی در بادِن -بادن بسال <span class=\"hlight\" dir=\"rtl\">١٨٥٢</span> م .<br /></font></div>'),
(288434, 'ژوکفسکی', '<span class=\"hlight\">ژوکفسکی .</span> <font color=\"DarkGreen\"><b>[ ک ُ ]</font></b> (اِخ ) والنتین . نام خاورشناس معروف روسی از شاگردان ویکتور رُزن . وی در امر مدفن فردوسی تتبعاتی کرده و آن را درحوالی مشهد طوس تمیز داده و محلی که آرامگاه فعلی فردوسی آنجا بنا شده ظاهراً همانجاست که این مستشرق یافته است . (فرهنگ خاورشناسان ص <span class=\"hlight\" dir=\"rtl\">١٩٠</span>). وی را مقاله ٔ بسیار نفیس بدیعی در ترجمه ٔ حال عمر خیام است . (چهارمقاله ٔ عروضی ص <span class=\"hlight\" dir=\"rtl\">٢١٢</span>). و هم تصنیفها (سرودها و اغانی ) فارسی را بنام «تصنیفهای فارسی » گرد آورده و به روسی ترجمه کرده و در سن پطرزبورغ در سال <span class=\"hlight\" dir=\"rtl\">١٩٠٢</span> م . بطبع رسانیده است . (ترجمه ٔ تاریخ ادبیات فارسی براون ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">١٤٧</span>). کشف المحجوب هجویری را نیز تصحیح و طبع کرده است .<br /></font></div>'),
(288435, 'ژوگن', '<span class=\"hlight\">ژوگن .</span> <font color=\"DarkGreen\"><b>[ گ ُ ]</font></b> (اِخ ) نام کرسی کانتن در ایالت کُت -دو-نُر از شهرستان دینان، دارای <span class=\"hlight\" dir=\"rtl\">٤٤٤</span> تن سکنه .<br /></font></div>'),
(288436, 'ژوگه', '<span class=\"hlight\">ژوگه .</span> <font color=\"DarkGreen\"><b>[ گ ِ ]</font></b> (اِخ ) نام صاحب کتاب شاهنشاهی مقدونی و بسط آداب و رسوم یونانی در مشرق . (ایران باستان ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢١٥٩</span>).<br /></font></div>'),
(288437, 'ژوگورتا', '<span class=\"hlight\">ژوگورتا.</span> (اِخ ) نام پادشاه نومیدی و برادرزاده ٔ می سیپا. متوفی به رُم . وی با رومیان به جنگ برخاست و مغلوب ماریوس شد (در حدود <span class=\"hlight\" dir=\"rtl\">١٥٤</span>-<span class=\"hlight\" dir=\"rtl\">١٠٥</span> ق .م .).<br /></font></div>'),
(288438, 'ژوی', '<span class=\"hlight\">ژوی .</span> (اِخ ) ویکتور ژزف اتین . نام درام نویس فرانسوی . مولدژوی -آن ژُزا و وفات به سن ژرمن آن لی (<span class=\"hlight\" dir=\"rtl\">١٧٦٤</span>-<span class=\"hlight\" dir=\"rtl\">١٨٤٦</span> م .).<br /></font></div>'),
(288439, 'ژویاک', '<span class=\"hlight\">ژویاک .</span> <font color=\"DarkGreen\"><b>[ ژوییا ]</font></b> (اِخ ) نام کرسی بخش در ایالت کُرز از ولایت بریو، دارای <span class=\"hlight\" dir=\"rtl\">١٨٣٣</span> تن سکنه .<br /></font></div>'),
(288440, 'ژوین', '<span class=\"hlight\">ژوین .</span> <font color=\"DarkGreen\"><b>[ ژُ وی َ ]</font></b> (اِخ ) فلاویوس کلودیوس ژُویانوس . نام یکی از امپراطوران روم (از <span class=\"hlight\" dir=\"rtl\">٣٦٣</span> تا <span class=\"hlight\" dir=\"rtl\">٣٦٤</span> م .)، مولد پانونی در حدود سال <span class=\"hlight\" dir=\"rtl\">٣٣١</span> و متوفی در سال <span class=\"hlight\" dir=\"rtl\">٣٦٤</span> م . وی را با شاپور دوم ساسانی عهدنامه ٔ ننگینی است .<br /></font></div>'),
(288441, 'ژوینبل', '<span class=\"hlight\">ژوینبل .</span> <font color=\"DarkGreen\"><b>[ ژویم ْ ب ُ ]</font></b> (اِخ ) ویلیام (<span class=\"hlight\" dir=\"rtl\">١٨٣٣</span> - <span class=\"hlight\" dir=\"rtl\">١٨٨٧</span> م .). نام فرزند تئودور گیوم ژوینبل . وی کتاب التنبیه فقه شافعی ابواسحاق شیرازی را با ترجمه ٔ لاتینی نشر داده و کتاب البلدان یعقوبی و رساله ٔ الجواز الدّینی منسوب به ابی لیث نصربن محمد سمرقندی را به طبع رسانیده است .<br /></font></div>'),
(288442, 'ژوینبل', '<span class=\"hlight\">ژوینبل .</span> <font color=\"DarkGreen\"><b>[ ژویم ْ ب ُ ]</font></b> (اِخ ) تئودور گیوم ژان . نام خاورشناسی از مردم هلند، متولد در رُتردام بسال <span class=\"hlight\" dir=\"rtl\">١٨٠٢</span> و متوفی بسال <span class=\"hlight\" dir=\"rtl\">١٨٦١</span> م . وی علاوه بر فن شرق شناسی مردی مذهبی و عالمی روحانی و در لغت عرب بارع و در علوم اسلامی متتبّع بود و تعلیم و تدریس زبان عربی را در دانشگاه لیدن بعهده داشت وقصاید متنبّی و شعرای معاصر او را که از مدیحه سرایان سیف الدوله ٔ حمدانی بودند با ترجمه ٔ لاتینی انتشار داد و کتاب مراصدالاطلاع و معجم البلدان یاقوت را بسال <span class=\"hlight\" dir=\"rtl\">١٨٥٩</span> م . در لیدن به طبع رسانید و کتاب «النجوم الزاهرة فی ملوک مصر و القاهرة» ابوالمحاسن تغری بردی و الخراج ابن آدم را طبع و درباره ٔ ابن سریح تتبع و هم درباب ابن قاسم عتیقی و کتاب المدونة تحقیق دارد. کتابی هم بنام هندلینگ در اصول فقه نوشته و معلوماتی مختصر از آراء شایعه با تعلیقات تاریخی نگاشته که دائرةالمعارف اسلام آن را جزء مصادر خود قرار داده است و نیز وی را رساله ای است بنام قواعد اسلامی که در آن قسمتی از عبادات و آداب مذهبی اسلامی را نگاشته و در موضوع حج تفصیل داده است .<br /></font></div>'),
(288443, 'ژپه', '<span class=\"hlight\">ژپه .</span> <font color=\"DarkGreen\"><b>[ ژُ پ ِ ]</font></b> (اِخ ) نام قدیم شهر یافا به فلسطین . رجوع به یافا شود.<br /></font></div>'),
(288444, 'ژپید', '<span class=\"hlight\">ژپید.</span> <font color=\"DarkGreen\"><b>[ ژِ ]</font></b> (اِخ ) نام طایفه ای از ژرمن که در داسی مستقر گردیده بودند و هم آنجا به تحریک ژوستی نین به دست لُمباردهادر قرن پنجم میلادی قتل عام شدند و از میان رفتند.<br /></font></div>'),
(288445, 'ژک', '<span class=\"hlight\">ژک .</span> <font color=\"DarkGreen\"><b>[ ژَ ]</font></b> (اِ) گردبرگرد دهن . (اوبهی ) <span class=\"hlight\">:</span> <br />ز برما <font color=\"DarkGreen\"><b>[ ز سرما؟ ]</font></b> ژک و پوز سگ بسته بود<br />بز و میش بر جای بربسته بود <font color=\"DarkGreen\"><b>[ کذا ]</font></b>.<br /> <font color=\"Red\">عسجدی .</font><br />شاید اصل دک باشد (دک و پوز).<br /></font></div>'),
(288446, 'ژک', '<span class=\"hlight\">ژک .</span> <font color=\"DarkGreen\"><b>[ ژَ <span class=\"hlight\" dir=\"rtl\">/</span> ژُ ]</font></b> (اِ) کسی بود که با خود همی دندد نرم نرم و خشم آلود گویند میژکد. (لغت نامه ٔ اسدی ). سخنی که از روی غضب وخشم در زیر لب گویند. کسی که با خود همی تندد. در شیراز و خراسان لُنْد گویند. (برهان ). سخنی بود که ازروی خشم و اعراض در زیر لب گویند و آن را دندنه نیزخوانند و ژکیدن مصدر آن است . (جهانگیری ). کسی بود که با خود می تندد و میگرید نرم نرم به تندی و خشم آلودگی گویند همی ژکد و سودائی مزاج بود که با خود گوید و گرید. زُک . لُند. لُندش ِ زیر لب . لُندلُند. غر و لُند. <BR><font color=\"Blue\">◄</font> (فعل امر) امر به ژکیدن . (برهان ).<br /></font></div>'),
(288447, 'ژکارندگی', '<span class=\"hlight\">ژکارندگی .</span> <font color=\"DarkGreen\"><b>[ ژَ رَ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (حامص ) ستیزه . لجاج . لج ّ.<br /></font></div>'),
(288448, 'ژکاره', '<span class=\"hlight\">ژکاره .</span> <font color=\"DarkGreen\"><b>[ ژَ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (ص ) لجوج . ستیهنده . کینه ور. گران . (لغت نامه ٔ اسدی ). ستیزه کار. خیره . ستیزنده . عنود. شوخ . شوخ چشم . شوخ دیده . چشم سفید. خیره چشم . یک دنده . یک پهلو. سمج . خودرای . رجوع به لجوج شود <span class=\"hlight\">:</span> <br />تا روز پدید آید آسایش یابم <br />زین علت مکروه و ستمکار و ژکاره .<br /> <font color=\"Red\">خسروانی .</font><br />ز خشم این کهن گرگ ژکاره <br />ندارم جز درت اندخسواره .<br /> <font color=\"Red\">لبیبی .</font><br />و در بیت ذیل اگر مصحف نباشد معنی غیر ستیهنده دارد <span class=\"hlight\">:</span> <br />مگر پروین ز دردم شد ژکاره <br />که گرد آمد بهم چندین ستاره .<br /><font color=\"Red\">فخرالدین اسعد (ویس و رامین ).</font><br /></font></div>'),
(288449, 'ژکاریدن', '<span class=\"hlight\">ژکاریدن .</span> <font color=\"DarkGreen\"><b>[ ژَ دَ ]</font></b> (مص ) لجاج کردن . ستهیدن .<br /></font></div>'),
(288450, 'ژکاسه', '<span class=\"hlight\">ژکاسه .</span> <font color=\"DarkGreen\"><b>[ ژُ س َ <span class=\"hlight\" dir=\"rtl\">/</span> س ِ ]</font></b> (اِ) قنفذ. خارپشت . (دهار). ژکاشه . اما این کلمه ظاهراً به این صورت تصحیف ریکاسه است .<br /></font></div>'),
(288451, 'ژکاشه', '<span class=\"hlight\">ژکاشه .</span> <font color=\"DarkGreen\"><b>[ ژُ ش َ <span class=\"hlight\" dir=\"rtl\">/</span> ش ِ ]</font></b> (اِ) قنفذ. خارپشت .خارپشت تیرانداز. جانوری است خزنده که به تازی قنفذ گویند و ژکاسه نیز گفته اند. (آنندراج ). اما کلمه ظاهراً تصحیف ریکاسه است .<br /></font></div>'),
(288452, 'ژکال', '<span class=\"hlight\">ژکال .</span> <font color=\"DarkGreen\"><b>[ ژُ ]</font></b> (اِ) زغال . فحم . انگشت . ژگال . صاحب برهان گوید این لغت گویند ارمنی است .<br /></font></div>'),
(288453, 'ژکان', '<span class=\"hlight\">ژکان .</span> <font color=\"DarkGreen\"><b>[ ژَ <span class=\"hlight\" dir=\"rtl\">/</span> ژُ ]</font></b> (نف ) در حال ژکیدن . آنکه ژکد. کسی که با خود دمدمه کند از دلتنگی . (لغت فرس ). آنکه با خود دَندد از خشم و نرم نرم گرید. (صحاح الفرس ). کسی که از درد و رنج با خود سخنی می گوید و می تندد. (اوبهی ). از خود رمیده و شخصی که از روی اعراض در زیر لب خود به خود آهسته سخن گوید و در صفاهان این نوع را لندیدن گویند. (فرهنگ خطی ) <span class=\"hlight\">:</span> <br />هشیوار از تخمه ٔ گیوکان <br />که بر درد و سختی نگردد ژکان .<br /> <font color=\"Red\">فردوسی .</font><br />برفتند از ایوان ژکان ودژم <br />دهان پر ز باد و روان پر ز غم .<br /> <font color=\"Red\">فردوسی .</font><br />بیامد فرخزاد آذرمکان <br />دژم روی با زیردستان ژکان .<br /> <font color=\"Red\">فردوسی .</font><br />چو دلو گران برنیامد ز چاه <br />بیامد ژکان زود شاپورشاه .<br /> <font color=\"Red\">فردوسی .</font><br />همی رفت رنجیده زو پهلوان <br />به ره بر بزرگان خروشان نوان <br />بیامد ژکان از بر شاه او<br />همه تیره دید اختر و گاه او.<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(288454, 'ژکاژ', '<span class=\"hlight\">ژکاژ.</span> <font color=\"DarkGreen\"><b>[ژَ ]</font></b> (اِ) نوعی از آهن میخ کوب . <BR><font color=\"Blue\">◄</font> کلنگ نوک تیز. <BR><font color=\"Blue\">◄</font> بیل نوک تیز. <BR><font color=\"Blue\">◄</font> آئینه ٔ کوچک . <BR><font color=\"Blue\">◄</font> تندی و تیزمزاجی . گردنکشی . تمرد. لج و عناد. (شعوری ) .<br /></font></div>'),
(288455, 'ژکر', '<span class=\"hlight\">ژکر.</span> <font color=\"DarkGreen\"><b>[ ژُ ک ِ ]</font></b> (فرانسوی، اِ) ورقی است از اوراق بازی قمار که صورت شیطانکی بر آن است و به فارسی آن را شوخ نامند.<br /></font></div>'),
(288456, 'ژکس', '<span class=\"hlight\">ژکس .</span> <font color=\"DarkGreen\"><b>[ ژَ ک َ ]</font></b> (صوت ) این لفظ در مقام معاذاﷲ گفته میشود. (برهان ). معاذاﷲ. العیاذباﷲ. پناه بر خدا. (ظاهراً این کلمه تصحیف پرگس و پرگست است ).<br /></font></div>'),
(288457, 'ژکفر', '<span class=\"hlight\">ژکفر.</span> <font color=\"DarkGreen\"><b>[ ژَ ف َ ]</font></b> (ص ) شکیبا. صبور. (برهان ). رجوع به ژفکر شود.<br /></font></div>'),
(288458, 'ژکفری', '<span class=\"hlight\">ژکفری .</span> <font color=\"DarkGreen\"><b>[ ژَ ف َ ]</font></b> (حامص ) شکیبائی . (برهان ). صبر. شکیب .<br /></font></div>'),
(288459, 'ژکنده', '<span class=\"hlight\">ژکنده .</span> <font color=\"DarkGreen\"><b>[ ژَ <span class=\"hlight\" dir=\"rtl\">/</span> ژُ ک َ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (نف ) کسی که همی ژکد و زیر لب از روی اِعراض سخن گوید. لندلندکننده . غرغرکننده . ژکان .<br /></font></div>'),
(288460, 'ژکندگی', '<span class=\"hlight\">ژکندگی .</span> <font color=\"DarkGreen\"><b>[ ژَ <span class=\"hlight\" dir=\"rtl\">/</span> ژُ ک َ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (حامص ) حالت و چگونگی ژکنده .<br /></font></div>'),
(288461, 'ژکه', '<span class=\"hlight\">ژکه .</span> <font color=\"DarkGreen\"><b>[ ژُ ک ِ ]</font></b> (فرانسوی، اِ) کلمه ای است انگلیسی و دخیل در زبان فرانسه و در فارسی بمعنی سوارکارو شخصی که حرفه اش تاختن اسبهای مخصوص مسابقه است .<br /></font></div>'),
(288462, 'ژکه کلوب', '<span class=\"hlight\">ژکه کلوب .</span> <font color=\"DarkGreen\"><b>[ ژُ ک ِ ک ُ ]</font></b> (فرانسوی، اِ مرکب ) کلمه ای است انگلیسی و دخیل در زبان فرانسه بمعنی کانون و محل اجتماع سوارکاران . و آن در آغاز جمعیتی بود که بسال <span class=\"hlight\" dir=\"rtl\">١٨٣٣</span> م . برای اصلاح نژاد اسب پدید آمد.<br /></font></div>'),
(288463, 'ژکور', '<span class=\"hlight\">ژکور.</span> <font color=\"DarkGreen\"><b>[ ژُ ]</font></b> (اِخ ) لوئی شوالیه دو. نام دانشمند فرانسوی و یکی از نویسندگان دائرةالمعارف . مولد پاریس بسال <span class=\"hlight\" dir=\"rtl\">١٧٠٤</span> و وفات بسال <span class=\"hlight\" dir=\"rtl\">١٧٧٩</span> م .<br /></font></div>'),
(288464, 'ژکور', '<span class=\"hlight\">ژکور.</span> <font color=\"DarkGreen\"><b>[ ژُ ]</font></b> (اِخ ) آرنه فرانسوا مارکی . نام سیاستمدار فرانسوی . مولد تورنان (سِن -اِ-مارن ) بسال <span class=\"hlight\" dir=\"rtl\">١٧٥٧</span> و وفات در پرسله (سن -اِ-مارن ) بسال <span class=\"hlight\" dir=\"rtl\">١٨٥٢</span> م .<br /></font></div>'),
(288465, 'ژکور', '<span class=\"hlight\">ژکور.</span> <font color=\"DarkGreen\"><b>[ ژَ ]</font></b> (ص ) زُفت و بخیل و دون بود. (لغت نامه ٔ اسدی ). سفله و دون همت باشد. (لغت نامه ٔ اسدی نسخه ٔ نخجوانی ) . ممسک . فرومایه .پست . خسیس . (برهان ). رجوع به زکور شود <span class=\"hlight\">:</span> <br />چرخ فلک هرگز پیدا نکرد <br />چون تو یکی سفله و دون و ژکور<br />خواجه ابوالقاسم از ننگ تو<br />برنکند سر به قیامت ز گور.<br /> <font color=\"Red\">رودکی .</font><br />زمانه مدح تو را جاودان همی دارد<br />از آنکه سخت عزیز است و اوست سخت ژکور.<br /> <font color=\"Red\">لامعی جرجانی .</font><br />اگر زرنگیرم نه زاهد خسیسم <br />وگر می ننوشم نه تائب ژکورم .<br /> <font color=\"Red\">سنائی .</font><br />بوهم هیچ حکیمی نبود از این حکمت <br />که سال سفله و زفت و بخیل و سخت ژکور (کذا).<br /> <font color=\"Red\">سوزنی (از جهانگیری ).</font><br /><BR><font color=\"Blue\">◄</font> دزد. (صحاح الفرس ) (برهان ). راهزن . قطاع الطریق . (برهان ). <BR><font color=\"Blue\">◄</font> پیچیده . <BR><font color=\"Blue\">◄</font> گرفته . (برهان ).<br /></font></div>'),
(288466, 'ژکیدن', '<span class=\"hlight\">ژکیدن .</span> <font color=\"DarkGreen\"><b>[ ژَ <span class=\"hlight\" dir=\"rtl\">/</span> ژُ دَ ]</font></b>(مص ) با خویشتن دمدمه کردن از دلتنگی . (لغت نامه ٔ اسدی ). در خود همی تندیدن وهمی گفتن نرم نرم به تندی و خشم آلودگی . (لغت نامه ٔ اسدی نسخه ٔ نخجوانی ). با خود همی دندیدن نرم نرم و خشم آلود. (لغت نامه ٔ اسدی ). آهسته سخن گفتن در زیر لب از روی خشم و قهر و غضب . (برهان ). کسی که با کسی همی تندد و همی دراید گویند همی ژکد. از درد یا غمی با خودسخن گفتن و تندیدن . با خود همی دندیدن و درائیدن . غرولند زدن . لندیدن . لندلند کردن . زکیدن <span class=\"hlight\">:</span> <br />ای طبع سازوارچه کردم ترا چه بود<br />با من همی نسازی و دایم همی ژکی .<br /> <font color=\"Red\">کسائی .</font><br />از او شاه ایران فراوان ژکید<br />برآشفت و از روزبه لب گزید.<br /> <font color=\"Red\">فردوسی .</font><br />همه ره ز دانا همی لب مکید<br />فرودآمد از اسب و چندی ژکید.<br /> <font color=\"Red\">فردوسی .</font><br />بگفت این و تیغ از میان برکشید<br />ز خون سیاوش فراوان ژکید.<br /> <font color=\"Red\">فردوسی .</font><br />سخن همه سخن غازی بود... و پدریان را نیک از آن درد می آمد و می ژکیدند تا آخر بیفکندندش . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٥٨</span>). و این قوم را سخت ناخوش می آمد وی را در درجه ای بدان بزرگی دیدن، چه خرد دیده بودند می ژکیدند و می گفتند. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">١٣٤</span>). ژکیدن و گفتار آن قوم به حاجب میرسانیدند و او میخندیدی و از آن باک نداشتی . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">١٣٤</span>). خواجه <font color=\"DarkGreen\"><b>[ احمد حسن ]</font></b> آغازید هم از اول به انتقام مشغول شدن و ژکیدن . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">١٥٥</span>). بوسهل زوزنی بر خشم خود طاقت نداشت برخاست نه تمام و بر خویشتن می ژکید. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">١٨١</span>). و یوسف چه دانست که دل و جگر معشوقش بر وی مشرفند به هر وقتی و بیشتر در شراب می ژکید و سخنان فراختر میگفت که این چه بود که همگان کردیم . (تاریخ بیهقی ).<br />ای پیشه کرده نوحه بدرد گذشته عمر<br />با خویشتن همیشه همیدون همی ژکی .<br /><font color=\"Red\">لؤلؤئی (از لغت نامه ٔ اسدی نسخه ٔ نخجوانی ).</font><br /></font></div>'),
(288467, 'ژگال', '<span class=\"hlight\">ژگال .</span> <font color=\"DarkGreen\"><b>[ ژُ ]</font></b> (اِ) زغال . ژکال . فحم . اَنگِشت .<br /></font></div>'),
(288468, 'ژگور', '<span class=\"hlight\">ژگور.</span> <font color=\"DarkGreen\"><b>[ ژَ ]</font></b> (ص ) زفت . بخیل . دون . زکور. رجوع به زکور شود.<br /></font></div>'),
(288469, 'ژگون', '<span class=\"hlight\">ژگون .</span> <font color=\"DarkGreen\"><b>[ ژِ ]</font></b> (اِخ ) نام کرسی بخش ژِر از ولایت اُش، دارای راه آهن و قریب <span class=\"hlight\" dir=\"rtl\">١٠٦٣</span> تن سکنه .<br /></font></div>'),
(288470, 'ژی', '<span class=\"hlight\">ژی .</span> (اِخ ) نام قریه ای است در اصفهان و در آنجا بنگ خوب حاصل میشود. (برهان ).<br /></font></div>'),
(288471, 'ژی', '<span class=\"hlight\">ژی .</span> (اِ) صورتی از زی و جی، ریشه ٔ زیستن و زندگی کردن . رجوع به زی و جی و زیستن شود.<br /></font></div>'),
(288472, 'ژی', '<span class=\"hlight\">ژی .</span> (اِ) نام زاء سه نقطه ٔ فارسی . رجوع به «ژ» شود.<br /></font></div>'),
(288473, 'ژی', '<span class=\"hlight\">ژی .</span> (اِ) آبگیر. آبدان . شَمَر. (لغت نامه ٔ اسدی ). جائی که آب در آن جمع شده باشد. (برهان ). غفچی . کوژی . تالاب . غدیر. اوشال . ژیر. آژیر. شاید این کلمه صورت دیگری از کلمه ٔ جوی باشد <span class=\"hlight\">:</span> <br />ای آنکه من از عشق تو اندر جگر خویش <br />آتشکده دارم صدو بر هر مژه ای ژی .<br /><font color=\"Red\">رودکی (از لغت نامه ٔ اسدی ).</font><br />می ستد باید بدین گه کاین زمین همچون ستی <br />آب چون مهتاب و بر ماهی چو زندان گشته ژی .<br /> <font color=\"Red\">ابوشکور.</font><br />بسی ژی در آن مرغزار و شکار<br />بیاسود خسرو در آن مرغزار.<br /> <font color=\"Red\">فردوسی .</font><br />رخ اعداش چو نی باد و سرش سبز چو سرو<br />سال عمرش بعدد باد فزون از الفی <br />ناصحش باد سرافراز چو در بستان سرو<br />حاسدش باد فرو گل شده چون نی در ژی .<br /> <font color=\"Red\">سوزنی (از آنندراج ).</font><br />در شبنم هوای درش قطره ای است چرخ <br />وز قطره ٔ سحاب کفش شبنمی است ژی .<br /><font color=\"Red\">سیف اسفرنگ (از جهانگیری ).</font><br /></font></div>'),
(288474, 'ژی تمیر', '<span class=\"hlight\">ژی تمیر.</span> <font color=\"DarkGreen\"><b>[ ت ُ ]</font></b> (اِخ ) نام شهری در شمال غربی اوکراین، دارای <span class=\"hlight\" dir=\"rtl\">٧٧٠٠٠</span> تن سکنه .<br /></font></div>'),
(288475, 'ژی ژیس', '<span class=\"hlight\">ژی ژیس .</span> (اِخ ) نام زنی که به دستور پروشات مادر اردشیر دوم استاتیرا زوجه ٔ او را مسموم کرد. شرح آن واقعه چنین است : پروشات که از دیرگاهی قصد کشتن استاتیرا زن اردشیر را داشت بالاخره به دسایس و حیل نیت خود را اجرا کرد. او زنی در خدمت خود داشت ژی ژیس نام که مورد اعتماد تام ملکه و بر وی بسیار مسلط بود و همین زن بقول «دی نُن » آلت اجرای خیال فاسد پروشات گردید. شرح قضیه موافق نوشته های «دی نن » و کتزیاس و پلوتارک (زندگانی اردشیر فصل <span class=\"hlight\" dir=\"rtl\">٢١</span>) با جزئی اختلاف چنین است : هر دو ملکه از چندی قبل آشتی کرده و ظاهراً نشان می دادند که منازعات و سؤظن های دیرینه را فراموش کرده اند ولی باطناً از یکدیگر بیمناک بودند و غذا را از یک ظرف و از همان خوراک می خوردند. بعد پلوتارک گوید: در پارس مرغی هست که فضله ندارد وروده هایش پر از چربی است بنابراین تصور می کنند که غذای این مرغ از باد و شبنم است . این مرغ را رین تاسیس نامند، ولی کتزیاس این مرغ را رین داوس نامیده چنین گوید: پروشات در سر میز یکی از این مرغها را برداشته با کاردی که یک طرف آن را مسموم کرده بود به دو نیم تقسیم کرد، نیمی را که مسموم نشده بود خود برداشت ونیم مسموم را به استاتیرا داد. دی نُن گوید ملان تاس نامی مرغ را بریده قسمت مسموم را به استاتیرا داد. بهرحال از درد شدید و تشنج هائی که بعد برای ملکه حاصل شد او یقین کرد که مسموم گشته است و بفاصله ٔ چند ساعت درگذشت . شاه هم سؤظن نسبت به پروشات حاصل کرد، زیرا درجه ٔ کینه و شقاوت او را خوب می دانست و برای اینکه در این باب حقیقت مطلب را بداند فرمود تمام خدمه وصاحب منصبان مادرش را توقیف و زجر کنند، ولی پروشات ژی ژیس را مدتها در منزل خود نگاه داشت و امتناع ورزید از اینکه او را به شاه تسلیم دارد، بالاخره این زن روزی اجازه گرفت به خانه اش برود و قراولان شاهی او راگرفتند و موافق قوانین پارسی که برای زهردهندگان مقرر است با زجر بکشتند، یعنی سرش را روی سنگ پهنی گذارده با سنگی دیگر چندان کوبیدند تا خرد شد و صورتش مسطح گردید. چنین است عقیده ٔ دی نن، ولی کتزیاس گوید که ژی ژیس آلت اجرای قصد پروشات نبود و فقط بر خلاف میل خود از قضیه اطلاع داشت . (ایران باستان ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٠٩٦</span>).<br /></font></div>'),
(288476, 'ژیان', '<span class=\"hlight\">ژیان .</span> (ص ) خشم آلود بود چون شیر و دد و دام و آنچه بدین ماند. (لغت نامه ٔ اسدی ). ددان تند را خوانند. سباع درنده ٔ جنگی . خشم آلود بود چون دد و پیل و اژدها و مانند اینها. تند (در ددان ). (نسخه ای از لغت نامه ٔ اسدی ). خشمین . خشمگین . خشم آلود. خشم آلوده . خشمناک . تند و خشمناک و قهرآلود و درنده را گویند از انسان و هر یک از حیوانات دیگر از چرنده و پرنده و درنده که در ایشان صفت غضب و خشمناکی باشد. (برهان ). خشمناک وتندخو و اطلاق این لفظ بر جمیع درندگان و طائر شکاری کنند و بعضی انسان را نیز داخل کرده اند. (غیاث ). <br />(در صفت اژدها)، اژدهای ژیان <span class=\"hlight\">:</span> <br />تهمتن بپوشید ببر بیان <br />نشست از بر اژدهای ژیان .<br /> <font color=\"Red\">فردوسی .</font><br />(در صفت ببر)، ببر ژیان :<br />در این بیشه زین بیش مگذار گام <br />که ببر ژیان دارد اندر کنام .<br /> <font color=\"Red\">اسدی (از دقائق الحقائق ) (از شعوری ).</font><br />(در صفت پلنگ )، پلنگ ژیان :<br />بسان پلنگ ژیان بد بع خوی <br />نکردی جز از جنگ هیچ آرزوی .<br /> <font color=\"Red\">فردوسی .</font><br />پلنگ ژیان گرچه باشد دلیر<br />نیارد شدن پیش چنگال شیر.<br /> <font color=\"Red\">فردوسی .</font><br />نباشد جز از راستی در میان <br />نباید بدن چون پلنگ ژیان .<br /> <font color=\"Red\">فردوسی .</font><br />از آن هرکه بستی یکی بر میان <br />نکردی پلنگ ژیانش زیان .<br /> <font color=\"Red\">اسدی (گرشاسب نامه ).</font><br />(در صفت پیل )، پیل ژیان :<br />ز پای اندرآمد نگون گشت طوس <br />تو گفتی ز پیل ژیان یافت کوس .<br /> <font color=\"Red\">فردوسی .</font><br />بیفکند گوری چو پیل ژیان <br />جدا کرد از او چرم و پای و میان .<br /> <font color=\"Red\">فردوسی .</font><br />برآورد خرطوم پیل ژیان <br />بدان تا به رستم رساند زیان .<br /> <font color=\"Red\">فردوسی .</font><br />درآمد بکردار پیل ژیان <br />به بازو کمان و کمر بر میان .<br /> <font color=\"Red\">فردوسی .</font><br />زدم بر زمینش چو پیل ژیان <br />که او را همه خرد شد استخوان .<br /> <font color=\"Red\">فردوسی .</font><br />از این دو هنرمند پیل ژیان <br />بباید ببندد به مردی میان .<br /> <font color=\"Red\">فردوسی .</font><br />بیفکند پیل ژیان را به خاک <br />نه شرم آمدش زان سپهبد نه باک .<br /> <font color=\"Red\">فردوسی .</font><br />فکندی بدان گرز پیل ژیان <br />که جاوید بادی تو ای پهلوان .<br /><font color=\"Red\">فردوسی .</font><br />تو گفتی دو پیلند هر دو ژیان <br />گشاده به کین دست و بسته میان .<br /> <font color=\"Red\">فردوسی .</font><br />چو پیل ژیان شاهزاده دو شاه <br />براندند هر دو ز قلب سپاه .<br /> <font color=\"Red\">فردوسی .</font><br />همی رفت بر سان شیر دمان <br />ابا لشکر گشن و پیل ژیان .<br /> <font color=\"Red\">فردوسی .</font><br />به بندی ببستش دو دست و میان <br />که نگشاید آن بند پیل ژیان .<br /> <font color=\"Red\">فردوسی .</font><br />که ساسان به پیل ژیان برنشست <br />گرفته یکی تیغ هندی به دست .<br /> <font color=\"Red\">فردوسی .</font><br />هزار پیل ژیان پیش کرد وز پس کرد<br />ولایتی چو بهشتی و باره ای چو بهار.<br /> <font color=\"Red\">فرخی .</font><br />نیامد گزندی به گرد دلیر<br />همانگه ز پیل ژیان جست زیر.<br /> <font color=\"Red\">اسدی (گرشاسب نامه ).</font><br />(در صفت دیو):<br />جهانی نظاره بدیدار گرگ <br />چه گرگ، آن ژیان نرّه دیو سترگ .<br /> <font color=\"Red\">فردوسی .</font><br />(در صفت شیر): کویر؛ شیر ژیان . (لغت نامه ٔ اسدی ):<br />چو خسرو چنان دید با اندیان <br />چنین گفت کای نره شیر ژیان <br />بر آن پیل بر تیرباران کنید<br />کمان را چو ابر بهاران کنید.<br /> <font color=\"Red\">فردوسی .</font><br />ز بیشه دو شیر ژیان آوریم <br />همه تاج را در میان آوریم .<br /> <font color=\"Red\">فردوسی .</font><br />ببندیم شیر ژیان بر دو سوی <br />کسی را که شاهی کند آرزوی .<br /> <font color=\"Red\">فردوسی .</font><br />سیاوش بیامد کمر بر میان <br />سخن گفت با من چو شیر ژیان .<br /> <font color=\"Red\">فردوسی .</font><br />کنون نزد او جنگ شیر ژیان <br />همان است و نخجیر و آهو همان .<br /> <font color=\"Red\">فردوسی .</font><br />هنر نزد ایرانیان است و بس <br />ندارند شیر ژیان را بکس .<br /> <font color=\"Red\">فردوسی .</font><br />ببستند گردان رومی میان <br />بر آن جنگ یکسر چو شیر ژیان .<br /> <font color=\"Red\">فردوسی .</font><br />شهنشاه ایران چو تنها بماند<br />چو شیر ژیان سوی لشکر براند.<br /> <font color=\"Red\">فردوسی .</font><br />بدینسان بود فر و برز کیان <br />به نخجیر آهنگ شیر ژیان .<br /> <font color=\"Red\">فردوسی .</font><br />دو شیر ژیان پیش آن بیشه دید<br />کمان را بزه کرد و اندرکشید.<br /> <font color=\"Red\">فردوسی .</font><br />کنون سال چون پانصد اندرگذشت <br />سر و تاج ساسانیان سرد گشت <br />کنون تخت و دیهیم را روز ماست <br />سر و کار با بخت پیروز ماست <br />چو بینیم چهر تو <font color=\"DarkGreen\"><b>[ چهر بهرام چوبینه ]</font></b> وبخت تو<br />سپاه و کلاه تو و تخت تو<br />برآریم سر کار ساسانیان <br />چو آهخته شیری که گردد ژیان .<br /> <font color=\"Red\">فردوسی .</font><br />پس پشت شاه اندر ایرانیان <br />دلیران و هریک چو شیر ژیان .<br /> <font color=\"Red\">فردوسی .</font><br />بران تا از این هر دو شیر ژیان <br />کرا پیشتر خواهد آمد زیان .<br /> <font color=\"Red\">فردوسی .</font><br />شما هر دو بر سان شیر ژیان <br />به کینه ببندید یکسر میان .<br /> <font color=\"Red\">فردوسی .</font><br />دو شیر ژیان چون دمور و گروی <br />که بودند گردان پرخاشجوی .<br /> <font color=\"Red\">فردوسی .</font><br />برخنه درآورد یکسر سپاه <br />چو شیرژیان رستم کینه خواه .<br /> <font color=\"Red\">فردوسی .</font><br />به کین سیاوش کمر بر میان <br />ببست و بیامد چو شیر ژیان .<br /> <font color=\"Red\">فردوسی .</font><br />به رزم ریزد، ریزد چه چیز، خون عدو<br />به صید گیرد، گیردچه چیز، شیر ژیان .<br /> <font color=\"Red\">فرخی .</font><br />از پشه عنا و الم پیل بزرگ است <br />وز مور فساد بچه ٔ شیر ژیان است .<br /> <font color=\"Red\">منوچهری .</font><br />بر آن چشمه کاسب من افشاند گرد<br />نیارد ژیان شیر از آن آب خورد.<br /> <font color=\"Red\">اسدی (گرشاسب نامه ).</font><br />چو شیر ژیان جست از افراز تخت <br />گرفتش گلوبند وبفشارد سخت .<br /> <font color=\"Red\">اسدی (گرشاسب نامه ).</font><br />این دهر باستیزه چو بستیزد<br />شیر ژیان به دام درآویزد.<br /> <font color=\"Red\">ناصرخسرو.</font><br />به انصاف او شاخ آهوبره <br />ز شیر ژیان برکند چنگ و ناب .<br /> <font color=\"Red\">سوزنی .</font><br />گوزنی بر ره شیر آشیان کرد<br />رسن در گردن شیر ژیان کرد.<br /> <font color=\"Red\">نظامی .</font><br />سگ کیست روباه نازورمند<br />که شیر ژیان را رساند گزند.<br /> <font color=\"Red\">نظامی .</font><br />یا دم الحیضی که از خرگوش ریخت <br />بر سر شیر ژیان خواهم فشاند.<br /> <font color=\"Red\">خاقانی .</font><br />زاده ٔ طبع منند اینان که خصمان منند<br />آری آری گربه است از عطسه ٔ شیر ژیان .<br /> <font color=\"Red\">خاقانی (از جهانگیری ).</font><br />در یک سر ناخن از دو دستش <br />صد شیر نر ژیان ببینم .<br /> <font color=\"Red\">خاقانی .</font><br />از صهیل اسب شیرآشوب او خرگوش وار<br />بس دم الحیضا که شیران ژیان افشانده اند.<br /> <font color=\"Red\">خاقانی .</font><br />گر سواران خنگ توسن در کمند افکنده اند<br />من کمند افکنده و شیر ژیان آورده ام .<br /> <font color=\"Red\">خاقانی .</font><br />مورچگان را چو بود اتفاق <br />شیر ژیان را بدرانند پوست .<br /> <font color=\"Red\">سعدی .</font><br />(در صفت عقاب )، عقاب ژیان :<br />همی تا نسوزد به آب اندر آذر<br />نگیرد عقاب ژیان را کبوتر<br />جهان گیر و کینه کش از بدسگالان <br />ملک باش و از نعمت ملک برخور.<br /> <font color=\"Red\">عنصری .</font><br />(در صفت غُرم )، غُرم ژیان :<br />که با آهوئی گفت غُرم ژیان <br />که گر دشت گردد همه پرنیان <br />ز دامی که پای من آزاد گشت <br />نپویم بدین سو ترا باددشت .<br /> <font color=\"Red\">فردوسی .</font><br />مرا گر بخواهی زشاه جهان <br />چو غُرم ژیان با تو آیم دمان .<br /> <font color=\"Red\">فردوسی .</font><br />بیاورد فرزند راچون نوند<br />چو غُرم ژیان سوی کوه بلند.<br /> <font color=\"Red\">فردوسی .</font><br />(در صفت گرگ )، گرگ ژیان :<br />پس آنگه درآمدچو گرگ ژیان <br />زریر سپهبد جهان پهلوان .<br /> <font color=\"Red\">دقیقی .</font><br />(در صفت گور)، گور ژیان :<br />کسی را که بگرفت از ایشان میان <br />چو شیری که یازد به گور ژیان .<br /> <font color=\"Red\">فردوسی .</font><br />همی مژده دادش که جنگی پلنگ <br />ز گور ژیان کرد کوتاه چنگ .<br /> <font color=\"Red\">فردوسی .</font><br />بیامد هم اندر زمان اردوان <br />بدیدارِ افکنده گور ژیان .<br /> <font color=\"Red\">فردوسی .</font><br />نبد شیر درنده را خوابگاه <br />نه گور ژیان یافت بر دشت راه .<br /> <font color=\"Red\">فردوسی .</font><br />گرفت اوبه تندی یکی را میان <br />چو شیری که یازد به گور ژیان .<br /> <font color=\"Red\">فردوسی .</font><br />یکی گور دید اندر آن مرغزار<br />کز آن خوب تر کس نبیند نگار<br />پس اندر همی راند بهرام نرم <br />بر او بارگی را نکرد ایچ گرم <br />در آن بیشه بد جای نخجیرگاه <br />به پیش اندر آمد یکی تنگ راه <br />زتنگی چو گور ژیان برگذشت <br />پدید آمد آنجای باغی بدشت .<br /> <font color=\"Red\">فردوسی .</font><br />بودم ژیان گور بدشت فساد و فسق <br />تازنده و مراغه گر و بارناپذیر.<br /> <font color=\"Red\">سوزنی .</font><br />جهد باد صبا بر کوهساران <br />چردگور ژیان در مرغزاران .<br /> <font color=\"Red\">؟</font><br />(در صفت گوزن )، گوزن ژیان :<br />بدان ایزدی فر و جاه کیان <br />ز نخجیر گور و گوزن ژیان <br />جدا کرد گاو و خر و گوسفند<br />بورز آورید آنچه بد سودمند.<br /> <font color=\"Red\">فردوسی .</font><br />(در صفت مرغ )، مرغ ژیان :<br />چو مرغ ژیان <font color=\"DarkGreen\"><b>[ سیمرغ ]</font></b> باشد آموزگار<br />چنین کام دل خواهد از روزگار.<br /> <font color=\"Red\">فردوسی .</font><br />(در صفت هزبر)، هزبر ژیان :<br />برفت از پس شاه غسانیان <br />سرافراز طایر هزبر ژیان .<br /> <font color=\"Red\">فردوسی .</font><br />بکوشید و اندر میان آورید<br />خروش هزبر ژیان آورید.<br /> <font color=\"Red\">فردوسی .</font><br />شکیبا و با هوش و رای و خرد<br />هزبر ژیان را بدام آورد .<br /> <font color=\"Red\">فردوسی .</font><br />زمین پر ز جوش و هوا پرخروش <br />هزبر ژیان را بدرید گوش .<br /> <font color=\"Red\">فردوسی .</font><br />بیامد <font color=\"DarkGreen\"><b>[ منوچهر ]</font></b> کنون چون هزبر ژیان <br />بکین پدر تنگ بسته میان .<br /> <font color=\"Red\">فردوسی .</font><br />بدو گفت شاه ای هزبر ژیان <br />از این آزمایش ندارم زیان .<br /> <font color=\"Red\">فردوسی .</font><br />به گرشاسب گفت ای هزبر ژیان <br />چه گوئی بدین جنگ بندی میان .<br /><font color=\"Red\">اسدی (گرشاسب نامه ).</font><br /></font></div>'),
(288477, 'ژیاکار', '<span class=\"hlight\">ژیاکار.</span> (اِخ ) نام خاورشناس عربی دان انگلیسی، مترجم کتاب حیوةالحیوان دمیری به انگلیسی و طابع آن از <span class=\"hlight\" dir=\"rtl\">١٩٠٦</span> تا <span class=\"hlight\" dir=\"rtl\">١٩٠٨</span> م . در بمبئی .<br /></font></div>'),
(288478, 'ژیبرال تار', '<span class=\"hlight\">ژیبرال تار.</span> (اِخ ) مصحف جبل الطارق . رجوع به جبل طارق شود.<br /></font></div>'),
(288479, 'ژیبن', '<span class=\"hlight\">ژیبن .</span> <font color=\"DarkGreen\"><b>[ ب ُ ]</font></b> (اِخ ) گیبن . ادوارد. نام مورّخ انگلیسی مؤلف «تاریخ انحطاط و سقوط امپراطوری روم ». متولد در پوتنی بسال <span class=\"hlight\" dir=\"rtl\">١٧٣٧</span> و متوفی در لندن بسال <span class=\"hlight\" dir=\"rtl\">١٧٩٤</span> م . و نیز او را کتابی است درباره ٔ اساس سلطنت عثمانی .<br /></font></div>'),
(288480, 'ژیتیون', '<span class=\"hlight\">ژیتیون .</span> <font color=\"DarkGreen\"><b>[ یُن ْ ]</font></b> (اِخ ) یا «ماراتونیزی ». نام بندری دریونان واقع در پِلوپونِز، دارای هفت هزار تن سکنه .<br /></font></div>'),
(288481, 'ژیر', '<span class=\"hlight\">ژیر.</span> (اِ) بمعنی آژیر است که آبگیر و تالاب و گوی باشد که آب باران و غیره در آن جمع شود. (برهان ). حوض . ژی . آبدان . شَمَر. آبگیر. برکه . غدیر. اوشال .<br /></font></div>'),
(288482, 'ژیرار', '<span class=\"hlight\">ژیرار.</span> (اِخ ) لابه گابریل . نام دستوردانی از مردم فرانسه، متولد در مونت فراند (پوی -دو-دوم ) (<span class=\"hlight\" dir=\"rtl\">١٦٧٧</span>-<span class=\"hlight\" dir=\"rtl\">١٧٤٨</span> م .).<br /></font></div>'),
(288483, 'ژیرار', '<span class=\"hlight\">ژیرار.</span> (اِخ ) (فیلیپ دو) نام یکی از مخترعین فرانسوی، متولد در لورمارن (ولکوز). وی به دعوت الکساندر اول امپراطور روسیه به لهستان رفت و نزدیک شهر ورشو کارخانه ٔ ریسندگی تأسیس کرد و مهندس نامی کارخانه های لهستان گردید (<span class=\"hlight\" dir=\"rtl\">١٧٧٥</span>-<span class=\"hlight\" dir=\"rtl\">١٨٤٥</span> م .).<br /></font></div>'),
(288484, 'ژیرار', '<span class=\"hlight\">ژیرار.</span> (اِخ ) ژان باتیست . او را در اصطلاح کلیسا لوپر گره گوار گویند. نام عالم علم تعلیم و تربیت سویسی، متولد در فریبورگ بسال <span class=\"hlight\" dir=\"rtl\">١٧٦٥</span> و متوفی بسال <span class=\"hlight\" dir=\"rtl\">١٨٥٠</span> م .<br /></font></div>'),
(288485, 'ژیرار داس وس', '<span class=\"hlight\">ژیرار داس وس .</span> <font color=\"DarkGreen\"><b>[ دُ اُ وُ ]</font></b> (اِخ ) نام خاورشناسی طابع کتاب التنازع و التخاصم بین بنی امیة و بنی هاشم با مقدمه ای به زبان آلمانی بسال <span class=\"hlight\" dir=\"rtl\">١٨٨٨</span> م . وی در تاریخ اسلامی مطالعه ٔ بسیار کرده و زبان عربی را نیز فراگرفته بوده است .<br /></font></div>'),
(288486, 'ژیرار دکریمن', '<span class=\"hlight\">ژیرار دکریمن .</span> <font color=\"DarkGreen\"><b>[ دُ م ُ ]</font></b> (اِخ ) نام دانشمندی دوستدار آثار اسلامی . وی در قرن هجدهم میلادی می زیسته و کتاب طب خلف بن عباس را به لاتینی ترجمه کرده است .<br /></font></div>'),
(288487, 'ژیراردن', '<span class=\"hlight\">ژیراردن .</span> <font color=\"DarkGreen\"><b>[ دُ ]</font></b> (اِخ ) فرانسوا. نام حجار و مجسمه ساز فرانسوی، متولد در ترُی و متوفی در پاریس (<span class=\"hlight\" dir=\"rtl\">١٦٢٨</span>-<span class=\"hlight\" dir=\"rtl\">١٧١٥</span> م .).<br /></font></div>'),
(288488, 'ژیراردن', '<span class=\"hlight\">ژیراردن .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (اِخ ) دلفین گی مادام امیل دو. زن ژیراردن مذکور در فوق، از نویسندگان فرانسه، متولد در اِکْس لاشاپل و متوفی در پاریس (<span class=\"hlight\" dir=\"rtl\">١٨٠٤</span>-<span class=\"hlight\" dir=\"rtl\">١٨٥٥</span> م .).<br /></font></div>'),
(288489, 'ژیراردن', '<span class=\"hlight\">ژیراردن .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (اِخ ) امیل دو. نام جریده نگار و سیاستمدار فرانسوی پسر الکساندر دوژیراردن، متولد و متوفی در پاریس (<span class=\"hlight\" dir=\"rtl\">١٨٠٦</span>-<span class=\"hlight\" dir=\"rtl\">١٨٨١</span> م .).<br /></font></div>'),
(288490, 'ژیردانو', '<span class=\"hlight\">ژیردانو.</span> <font color=\"DarkGreen\"><b>[ ی ُ ن ُ ]</font></b> (اِخ ) لوکا. نام نقاش ایطالیائی از اهالی ناپل . و او را ایل فاپرستو نامند. مولد و وفاتش به ناپل بود (<span class=\"hlight\" dir=\"rtl\">١٦٣٢</span>-<span class=\"hlight\" dir=\"rtl\">١٧٠٥</span> م .).<br /></font></div>'),
(288491, 'ژیردلن', '<span class=\"hlight\">ژیردلن .</span> <font color=\"DarkGreen\"><b>[ رُ دُ ل ِ ]</font></b> (اِخ ) لوئی گاسپار آمِدِه . نام قاضی و سیاستمدار فرانسوی، دارای عنوان پر دفرانس، متولد در ژکس (<span class=\"hlight\" dir=\"rtl\">١٧٨١</span>-<span class=\"hlight\" dir=\"rtl\">١٨٤٧</span> م .).<br /></font></div>'),
(288492, 'ژیرده تری یوزن', '<span class=\"hlight\">ژیرده تری یوزن .</span> <font color=\"DarkGreen\"><b>[ رُ دِ تْری <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ی ُ زُ ]</font></b> (اِخ ) رجوع به ژیرده دروسی شود.<br /></font></div>'),
(288493, 'ژیرده دروسی', '<span class=\"hlight\">ژیرده دروسی .</span> <font color=\"DarkGreen\"><b>[ رُ دِ دُ ]</font></b> (اِخ ) نام نقاش فرانسوی، متولد به مونتارژی و متوفی به پاریس (<span class=\"hlight\" dir=\"rtl\">١٧٦٧</span>-<span class=\"hlight\" dir=\"rtl\">١٨٢٤</span> م .). وی در پرده ای دعوت بقراط طبیب یونانی را به ایران از جانب اردشیر درازدست پادشاه هخامنشی تصویر کرده است . این تصویر نشان می دهد که فرستاده ٔ اردشیر مالی برای بقراط آورده است ووی آن را رد می کند. این پرده ٔ نقاشی اکنون در شعبه ٔطب دارالعلوم پاریس است . (ایران باستان ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٩٤٥</span>).<br /></font></div>'),
(288494, 'ژیرل دوویویه', '<span class=\"hlight\">ژیرل دوویویه .</span> <font color=\"DarkGreen\"><b>[ رُ وی وی ِ ]</font></b> (اِخ ) شارل پیر. نام عالم و دستورزبان دان فرانسوی، متولد در پاریس بسال <span class=\"hlight\" dir=\"rtl\">١٧٦٥</span> و متوفی بسال <span class=\"hlight\" dir=\"rtl\">١٨٣٢</span> م . او را کتابی است بنام دستور دستورهای زبان .<br /></font></div>'),
(288495, 'ژیرمانیی', '<span class=\"hlight\">ژیرمانیی .</span> <font color=\"DarkGreen\"><b>[ رُ مان ْ ]</font></b> (اِخ ) نام کرسی بخش در خطه ٔ بِلفُر کنار رود ساور، دارای <span class=\"hlight\" dir=\"rtl\">٣٧٣٤</span> تن سکنه و راه آهن و کارخانه ٔ پنبه ریسی .<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(288496, 'ژیرند', '<span class=\"hlight\">ژیرند.</span> <font color=\"DarkGreen\"><b>[ رُ ]</font></b> (اِخ ) نام ایالتی به فرانسه . این ایالت اساساً از سرزمین گوین تشکیل شده و دارای چهار شهرستان و پنجاه بخش و <span class=\"hlight\" dir=\"rtl\">٥٥٤</span> دهستان و <span class=\"hlight\" dir=\"rtl\">٨٥٢٧٦٨</span> تن سکنه و کرسی آن شهر بُردو است .<br /></font></div>'),
(288497, 'ژیرند', '<span class=\"hlight\">ژیرند.</span> <font color=\"DarkGreen\"><b>[ رُ ]</font></b> (اِخ ) نامی که به رود گارن پس از پیوستن به رود دُردُنی دهند.<br /></font></div>'),
(288498, 'ژیرندن', '<span class=\"hlight\">ژیرندن .</span> <font color=\"DarkGreen\"><b>[ رُ دَ ]</font></b> (اِخ ) نام حزب سیاسی مشهور در انقلاب <span class=\"hlight\" dir=\"rtl\">١٧٨٩</span> فرانسه .بریسوتن نیز گویند.<br /></font></div>'),
(288499, 'ژیره', '<span class=\"hlight\">ژیره .</span> <font color=\"DarkGreen\"><b>[ رِ ]</font></b> (اِخ ) نام دیهی از ناحیه ٔ شاپور فارس به عهد باستانی . (ترجمه ٔ ایران در زمان ساسانیان ص <span class=\"hlight\" dir=\"rtl\">٦٣</span>).<br /></font></div>'),
(288500, 'ژیره', '<span class=\"hlight\">ژیره .</span> <font color=\"DarkGreen\"><b>[ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (اِ) زیره . زیره است که به عربی کمون خوانند و بهترین آن کرمانی باشد. (برهان ). بلغت یونانی زیره را سنبوت گویند. (برهان ). کمون، معرب خامون کرمانی و فارسی و شامی و نبطی بود. (منتهی الارب ). زیره ٔ سیاه و زیره ٔ سبز از اقسام زیره است .<br /></font></div>'),
(288501, 'ژیرژه', '<span class=\"hlight\">ژیرژه .</span> <font color=\"DarkGreen\"><b>[ ژِ ]</font></b> (اِخ ) نام شهری در مصر علیا کنارنیل نزدیک شهر قدیم آبیدُس، دارای <span class=\"hlight\" dir=\"rtl\">١٩٩٠٠</span> تن سکنه .<br /></font></div>'),
(288502, 'ژیری', '<span class=\"hlight\">ژیری .</span> (اِخ ) آرتور. نام محقق فرانسوی، متولد در تره وو مؤلف کتابی در سیاست (<span class=\"hlight\" dir=\"rtl\">١٨٤٨</span>-<span class=\"hlight\" dir=\"rtl\">١٨٩٩</span> م .).<br /></font></div>'),
(288503, 'ژیزدره', '<span class=\"hlight\">ژیزدره .</span> <font color=\"DarkGreen\"><b>[ رَ ]</font></b> (اِخ )نام شهری در روسیه ٔ مرکزی (در قلمرو کالوگا) همنام رودی از آب راهه های رود اوکه، دارای <span class=\"hlight\" dir=\"rtl\">١٢٠٠٠</span> تن سکنه .<br /></font></div>'),
(288504, 'ژیزدره', '<span class=\"hlight\">ژیزدره .</span> <font color=\"DarkGreen\"><b>[ رَ ]</font></b> (اِخ ) نهری از آبراهه های رود «اوکه » واقع در ایالت کالوگای روسیه که از دوازده کیلومتری شمالی قصبه ٔ همنام خویش سرچشمه گیرد و نخست بجانب جنوب و سپس بسوی شمال شرقی جریان یابد و به رود اوکه ریزد. وسعت حوضه ٔ این رود <span class=\"hlight\" dir=\"rtl\">٨٧٢٩</span> کیلومتر مربع است و رودهای رژته ویتب و سرته بدو پیوندد و قابل سیر سفائن نیست . تنها در بعض قسمتهای آن قایق رانی ممکن است .<br /></font></div>'),
(288505, 'ژیزر', '<span class=\"hlight\">ژیزر.</span> <font color=\"DarkGreen\"><b>[ زُ ]</font></b> (اِخ ) نام کرسی بخش در اور از شهرستان آندِلی کنار رود لِپت، دارای راه آهن و <span class=\"hlight\" dir=\"rtl\">٥٨٦٨</span> تن سکنه .<br /></font></div>'),
(288506, 'ژیزل', '<span class=\"hlight\">ژیزل .</span> <font color=\"DarkGreen\"><b>[ زِ ]</font></b> (اِخ ) نام دختر شارل لوسمپل . مولد حدود سال <span class=\"hlight\" dir=\"rtl\">٩٠٨</span> م .<br /></font></div>'),
(288507, 'ژیزن', '<span class=\"hlight\">ژیزن .</span> <font color=\"DarkGreen\"><b>[ زِ ]</font></b> (اِخ ) پیر. نام نقاش فلاماندی . مولد آنورس (<span class=\"hlight\" dir=\"rtl\">١٨٣٦</span>-<span class=\"hlight\" dir=\"rtl\">١٩٠٠</span> م .).<br /></font></div>'),
(288508, 'ژیزه', '<span class=\"hlight\">ژیزه .</span> <font color=\"DarkGreen\"><b>[ زِ ]</font></b> (اِخ ) (در تداول مصریان : جیزه ).نام شهری در مصر به جنوب قاهره کنار نیل و نزدیک اهرام بزرگ و خرابه های مِمفیس، دارای <span class=\"hlight\" dir=\"rtl\">١٦٥٠٠</span> تن سکنه .<br /></font></div>'),
(288509, 'ژیسکن', '<span class=\"hlight\">ژیسکن .</span> <font color=\"DarkGreen\"><b>[ ک ُ ]</font></b> (اِخ ) نام سردار کارتاژی . وی بسال <span class=\"hlight\" dir=\"rtl\">٢٤١</span> ق .م . هنگام شورش و طغیان سربازان مزدور به قتل رسید.<br /></font></div>'),
(288510, 'ژیل', '<span class=\"hlight\">ژیل .</span> (اِخ ) ل . ا. گوسه دُگین . نام کاریکاتوریست فرانسوی . مولد پاریس و وفات در شارانتون (<span class=\"hlight\" dir=\"rtl\">١٨٤٠</span> - <span class=\"hlight\" dir=\"rtl\">١٨٨٥</span> م .). او را آندره نیز نامند.<br /></font></div>'),
(288511, 'ژیلا', '<span class=\"hlight\">ژیلا.</span> (اِخ ) نام رودی در اتازونی که در نووومکزیک و آریزونا جریان دارد و به رود کلرادو پیوندد.<br /></font></div>'),
(288512, 'ژیلبر', '<span class=\"hlight\">ژیلبر.</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) نیکلا ژزف لورن . نام شاعر فکاهی فرانسوی . مولد فن تنی -لو-شاتو (وُژ) . وی در هتل دیو (پاریس ) بر اثر سقوط از اسب درگذشت (<span class=\"hlight\" dir=\"rtl\">١٧٥١</span>-<span class=\"hlight\" dir=\"rtl\">١٧٨٠</span> م .). قطعات وداعیه ٔ او از زندگی مشهور است .<br /></font></div>'),
(288513, 'ژیلبر', '<span class=\"hlight\">ژیلبر.</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) (قدیس ) نام راهبی متولد در اُوِرنی در حدود سال <span class=\"hlight\" dir=\"rtl\">١٠٦٠</span> و متوفی بسال <span class=\"hlight\" dir=\"rtl\">١١٥٢</span> م . وی در جنگهای صلیبی همراه لوئی هفتم بود. ذکران او هفتم ژوئن است .<br /></font></div>'),
(288514, 'ژیلبر ا الیس', '<span class=\"hlight\">ژیلبر االیس .</span> <font color=\"DarkGreen\"><b>[ ب ِ اِ اِ ]</font></b> (اِخ ) (جزائر...) نام مجمعالجزایر کوچکی در پلینزی ازآن ِ انگلستان، دارای <span class=\"hlight\" dir=\"rtl\">٣٠٠٠٠</span> تن سکنه . محصول عمده ٔ آن فسفات و نارگیل است .<br /></font></div>'),
(288515, 'ژیلد', '<span class=\"hlight\">ژیلد.</span> (اِخ ) نام شرکتی است تعاونی که در قرون وسطی از بین اصناف و کارگران و تجار یا صناع تشکیل یافت .<br /></font></div>'),
(288516, 'ژیلداس', '<span class=\"hlight\">ژیلداس .</span> (اِخ ) (قدیس ) بنیانگذار صومعه ٔ سن ژیلداس در مُربیهان . وفات بسال <span class=\"hlight\" dir=\"rtl\">٥٦٥</span> م . ذکران وی <span class=\"hlight\" dir=\"rtl\">٢٩</span> ژانویه است .<br /></font></div>'),
(288517, 'ژیلدن', '<span class=\"hlight\">ژیلدن .</span> <font color=\"DarkGreen\"><b>[ دِ ]</font></b> (اِخ ) هوگو. نام منجم سوئدی . مولد هلسینگ فر (<span class=\"hlight\" dir=\"rtl\">١٨٤١</span>-<span class=\"hlight\" dir=\"rtl\">١٨٩٦</span> م .).<br /></font></div>'),
(288518, 'ژیله', '<span class=\"hlight\">ژیله .</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (اِخ ) لوئی . نام عالم تاریخ صنایع از مردم فرانسه و عضو آکادمی فرانسه . مولد پاریس بسال <span class=\"hlight\" dir=\"rtl\">١٨٧٦</span>.<br /></font></div>'),
(288519, 'ژیله', '<span class=\"hlight\">ژیله .</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (اِخ ) کلود کازیمیر. عالم گیاه شناس فرانسوی . مولد دُرمان و وفات در آلنس (<span class=\"hlight\" dir=\"rtl\">١٨٠٦</span>-<span class=\"hlight\" dir=\"rtl\">١٨٩٦</span> م .).<br /></font></div>'),
(288520, 'ژیلیپ', '<span class=\"hlight\">ژیلیپ .</span> (اِخ ) نام سردار اسپارتی در اواخر قرن پنجم قبل از میلاد. وی برابر شهر سیراکوز بر دو سردار آتنی بنام نیسیاس و دموستن ظفر یافت و سپاه آنان را منهزم ساخت (<span class=\"hlight\" dir=\"rtl\">٤١٣</span> ق .م .) و پس از تسخیر شهر آتن بفرمان لیزاندر مأمور حمل غنائم جنگ به اسپارت شد ولی به اتهام اختلاس قسمتی از آن اموال ناگزیر به جلای وطن گردید.<br /></font></div>'),
(288521, 'ژیلیکوه', '<span class=\"hlight\">ژیلیکوه .</span> (اِخ ) نام کوهی در مشرق ناحیه ٔ سرحدی ایران که از شمال به جنوب ممتد است . ارتفاع آن از <span class=\"hlight\" dir=\"rtl\">١٦٦٤</span>تا <span class=\"hlight\" dir=\"rtl\">٢٩٧٦</span> متر تغییر می کند و به زمستان بیشتر قلّه های آن را برف پوشد. (از جغرافیای طبیعی کیهان ص <span class=\"hlight\" dir=\"rtl\">٥٦</span>).<br /></font></div>'),
(288522, 'ژیمن', '<span class=\"hlight\">ژیمن .</span><font color=\"DarkGreen\"><b>[ م ُ ]</font></b> (اِخ ) نام کرسی بخش در ایالت ژرس از ولایت اُش، کنار رود ژیمن، دارای راه آهن و <span class=\"hlight\" dir=\"rtl\">٢٢١٨</span> تن سکنه .<br /></font></div>'),
(288523, 'ژیمن', '<span class=\"hlight\">ژیمن .</span> <font color=\"DarkGreen\"><b>[ م ُ ]</font></b> (اِخ ) نام شعبه ای از رود گارُن در فرانسه بطول <span class=\"hlight\" dir=\"rtl\">١٣٣</span> کیلومتر.<br /></font></div>'),
(288524, 'ژیمناستیک', '<span class=\"hlight\">ژیمناستیک .</span> (فرانسوی، اِ) ورزش بدنی با اسبابهای مختلف از قبیل پارالل و بارفیکس و دارحلقه و غیره .<br /></font></div>'),
(288525, 'ژیمنس', '<span class=\"hlight\">ژیمنس .</span> <font color=\"DarkGreen\"><b>[ م ِ ن ِ ]</font></b> (اِخ ) نام کاردینال و سیاستمدار اسپانیولی اسقف شهر تُلِد (طلیطله ). مولد ترلاگونا (<span class=\"hlight\" dir=\"rtl\">١٤٣٦</span> - <span class=\"hlight\" dir=\"rtl\">١٥١٧</span> م .). وی با آنکه سیاستمداری عظیم بود بزرگترین مفتش عقاید و از قاضیان خونخوار محکمه ٔ محنت عقاید مذهبی اسپانیا بشمار میرفت .<br /></font></div>'),
(288526, 'ژین', '<span class=\"hlight\">ژین .</span> <font color=\"DarkGreen\"><b>[ ی َ ]</font></b> (اِخ ) نام کرسی بخش در لواره از ولایت مونتارژی واقع در کنار رود لوار، دارای <span class=\"hlight\" dir=\"rtl\">٨٢٥٧</span> تن سکنه .<br /></font></div>'),
(288527, 'ژینسنه', '<span class=\"hlight\">ژینسنه .</span> <font color=\"DarkGreen\"><b>[ س ُ ن ِ ]</font></b> (اِخ ) آرماند. نام وکیلی از وکلای مجلس کنوانسیون از دسته ٔ ژیروندن . مولد بردو. وی در پاریس به دار آویخته شد (<span class=\"hlight\" dir=\"rtl\">١٧٥٨</span>-<span class=\"hlight\" dir=\"rtl\">١٧٩٣</span> م .).<br /></font></div>'),
(288528, 'ژینیاک', '<span class=\"hlight\">ژینیاک .</span> (اِخ ) نام کرسی بخش در ایالت «هِرُل » از ولایت مُنت پلیه، دارای راه آهن و <span class=\"hlight\" dir=\"rtl\">٢٥٨٧</span> تن سکنه .<br /></font></div>'),
(288529, 'ژیهلاوا', '<span class=\"hlight\">ژیهلاوا.</span> (اِخ ) نام شهری به چکسلواکی در «مُراوی »، دارای <span class=\"hlight\" dir=\"rtl\">٣٢٠٠٠</span> تن سکنه .<br /></font></div>'),
(288530, 'ژیور', '<span class=\"hlight\">ژیور.</span> <font color=\"DarkGreen\"><b>[ ژی وُ ]</font></b> (اِخ ) نام کرسی بخش در ایالت «رُن » از ولایت لیون، کنار رود رُن، دارای <span class=\"hlight\" dir=\"rtl\">١٤٦٨٧</span> تن سکنه .<br /></font></div>'),
(288531, 'ژیوری', '<span class=\"hlight\">ژیوری .</span> <font color=\"DarkGreen\"><b>[ وْ ]</font></b> (اِخ ) نام کرسی بخش در ایالت «سائون -اِ-لوآر» از ولایت شالن سورسائون، دارای راه آهن و <span class=\"hlight\" dir=\"rtl\">١٩٤٦</span> تن سکنه . محصول عمده ٔ آن شراب است .<br /></font></div>'),
(288532, 'ژیوه', '<span class=\"hlight\">ژیوه .</span> <font color=\"DarkGreen\"><b>[ ژی وَ <span class=\"hlight\" dir=\"rtl\">/</span> وِ ]</font></b> (اِ) جیوه . سیماب . معرب آن زیبق و بعربی فَرّار گویند. (برهان ).<br /></font></div>'),
(288533, 'ژیژ', '<span class=\"hlight\">ژیژ.</span> (ص، اِ) مردار. (جهانگیری ). پلشت . نجس . (برهان ). لاش . چرکین . در صحاح الفرس ژیژ و ریژ آمده و ناچار یکی تصحیف دیگری است . صاحب فرهنگ رشیدی آرد: ژیژ، ژیژا، ژاوژا، ژأوژا (هر چهار لغت ) مرادف جیز و جیژ است یعنی خارپشت .<br /></font></div>'),
(288534, 'ژیژاووس', '<span class=\"hlight\">ژیژاووس .</span> (اِخ ) نام خاورشناس عربی دان ایتالیائی . مؤلف چهار مجلد لغت عربی و لاتین است و آن را در میلان به طبع رسانیده است .<br /></font></div>'),
(288535, 'ژیک', '<span class=\"hlight\">ژیک .</span> (اِ) قطره ٔ باران . (برهان ). قطره باشد و در بعض فرهنگها بجای یای تحتانی نون مرقوم است .(جهانگیری ) (رشیدی ). ژنگ . <BR><font color=\"Blue\">◄</font> بمعنی خارپشت هم آمده است لیکن اشاره به حرکتش نشده . (برهان ).<br /></font></div>'),
(288536, 'ژیکاسه', '<span class=\"hlight\">ژیکاسه .</span> <font color=\"DarkGreen\"><b>[ س َ <span class=\"hlight\" dir=\"rtl\">/</span> س ِ ]</font></b> (اِ) خارپشت . (رشیدی ). رجوع به ریکاسه و ژکاسه و ژکاشه شود.<br /></font></div>'),
(288537, 'ژیکلر', '<span class=\"hlight\">ژیکلر.</span> <font color=\"DarkGreen\"><b>[ ل ُ ]</font></b> (فرانسوی، اِ) کلمه ای است فرانسوی از اصطلاحات هواپیمائی . بجای آن در فرهنگستان ایران لغت «سوخت پاش » وضع شده و آن آلتی است که بنزین را در موتورهواپیما پراکنده کند تا بتواند با هوا مخلوط شود.<br /></font></div>'),
(288538, 'ژیگ', '<span class=\"hlight\">ژیگ .</span> (اِ) ژیغ. قطره .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ژیگ ژیگ </span> ؛ ژیغژیغ.قطره قطره . (غیاث ).<br /></font></div>'),
(288539, 'ژیگس', '<span class=\"hlight\">ژیگس .</span> <font color=\"DarkGreen\"><b>[ گ ِ ]</font></b> (اِخ ) نام نیزه دار سادیارتس آخرین پادشاه لیدی از سلسله ٔ هرقلی ها. وی عاشق زن پادشاه شد و او را بکشت و بجایش نشست و دولت لیدی را نیروبخشید، مخصوصاً سواره نظامی تشکیل کرد که در تمام مشرق زمین معروف بود. پس از آن چون دید که قوی است بعض مستعمرات یونانی را در آسیای صغیر تابع کرد و با برخی دیگر قراردادهائی بست . هرودوت داستان عشق ژیگس و زن پادشاه را چنین روایت کرده است (کتاب اول بند <span class=\"hlight\" dir=\"rtl\">٨</span> - <span class=\"hlight\" dir=\"rtl\">١٢</span>): کاندولا آخرین پادشاه سلسله ٔ هرقلی ها زنی داشت که از حیث جمال بی نظیر بود و پادشاه بسیار او را دوست می داشت . کاندولا نیزه داری داشت موسوم به ژیگس که بسیار مورد اعتماد او بود. روزی پادشاه به او گفت من هرچه از زیبائی زن خود تعریف میکنم می بینم که تو باور نمی کنی، این است که می خواهم تو او را در خوابگاه وقتی که رختهای خود را کنده و می خواهد بخوابد ببینی . نیزه دار استیحاش کرد ولی کاندولا چندان اصرار ورزید تا سرانجام قرار شد پادشاه او را در خوابگاه مخفی بداردو او ملکه را برهنه ببیند. بعد چنین کرد و زن دریافت که این قضیه بی دخالت شوهرش ممکن نبوده است روی دهد و برای کشیدن انتقام چنین افتضاحی از شوهر خود، روز دیگر نیزه دار را خواست و به او گفت از دو راه یکی را باید انتخاب کنی، یا پادشاه را کشته ملک او و مرابه دست آری یا به امر من کشته شوی . ژیگس پس از اینکه دید ملکه در عزم خود راسخ است شق اول را قبول کرد و در پشت همان در پنهان شد و شبانه پادشاه را در خواب بکشت . بعد ملکه را گرفت و به تخت نشست و بانی سلسله ٔ مِرمِنادها گردید. معلوم است که هردوت قضیه را بشکل داستان شنیده و ضبط کرده است، اصل قضیه چنین بوده : ژیگس زن کاندولا را جلب کرده است، بعد پادشاه را کشته و به تخت او نشسته . (از ایران باستان ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٩٥</span>).<br /></font></div>'),
(288540, 'ژیگس', '<span class=\"hlight\">ژیگس .</span> <font color=\"DarkGreen\"><b>[ گ ِ ]</font></b> (اِخ ) نام پدر میرسوس سردارپارسی بعهد داریوش بزرگ . (ایران باستان ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٦٥١</span>).<br /></font></div>'),
(288541, 'ژیگو', '<span class=\"hlight\">ژیگو.</span> (اِخ ) ژان . نام نقاش وقایع تاریخی و مصور فرانسوی . مولد بزانسون و وفات در پاریس (<span class=\"hlight\" dir=\"rtl\">١٨٠٦</span> - <span class=\"hlight\" dir=\"rtl\">١٨٩٤</span> م .).<br /></font></div>'),
(288542, 'ژیگولت', '<span class=\"hlight\">ژیگولت .</span> <font color=\"DarkGreen\"><b>[ گ ُ ل ِ ]</font></b> (فرانسوی، ص، اِ) تأنیث ژیگولو. زن ِ خودآراکه پیوسته در لهو و لعب و مجالس رقص وقت بگذراند.<br /></font></div>'),
(288543, 'ژیگولو', '<span class=\"hlight\">ژیگولو.</span> <font color=\"DarkGreen\"><b>[ گ ُ ل ُ ]</font></b> (فرانسوی، ص، اِ) مرد خودآراکه پیوسته در لهو و لعب و مجالس رقص وقت بگذراند.<br /></font></div>');
